# GSE182018 AML cell line OCI-AML2 treated with homoharringtonine (HHT) ####
# Omacetaxine a.k.a. homoharringtonine (HHT), is a protein translation inhibitor which induces cell cycle arrest in G0/G1
# AML cell line OCI-AML2 (mutant RUNX1) treated with the protein translation inhibitor homoharringtonine (HHT) vs untreated control
# https://www.ncbi.nlm.nih.gov/geo/query/acc.cgi?acc=GSE182018
# Counts_GSE182018 <- read.delim("/Volumes/AC_HD_8TB/Exp.\ 277\ Analysis\ of\ Gibbs\ free\ energy\ in\ response\ to\ drug\ selection/Cross_validation_with_published_data/AML_OCI-AML2\ _omacetaxine_BCL2i_GSE182018/GSE182018_GEO_Submission_RawCounts_Aug2021.txt")
# Counts_GSE182018 <- Counts_GSE182018 %>% remove_rownames %>% column_to_rownames(var="X") # Convert first column into row names in data frame
# names(Counts_GSE182018)[1] <- "" # Remove the added X from the first column

# These are the raw counts downloaded from GREIN
Counts_GSE182018_GREIN <- read.delim("path_to/AML_OCI-AML2\ _omacetaxine_BCL2i_GSE182018/GREIN_raw_counts/GSE182018_TranscriptLevel_Raw_data\ .csv", sep = ",", header = T, stringsAsFactors = F)
Counts_GSE182018_GREIN <- Counts_GSE182018_GREIN %>% remove_rownames %>% column_to_rownames(var="X") # Convert first column into row names in data frame




# Access the Series Matrix
# Data_GSE182018 <- getGEO(GEO = "GSE182018")

# Load the object
Data_GSE182018 <- readRDS("path_to/GREIN_series_matrices_data/Data_GSE182018.rds")

# Extract the phenotypic/clinical data matrix from the series matrix
Expdata_GSE182018 <- Data_GSE182018[["GSE182018_series_matrix.txt.gz"]]@phenoData@data
Expdata_GSE182018 = Expdata_GSE182018[-c(1:6),] # Remove the samples that are not necessary for the analysis
colnames(Expdata_GSE182018)[colnames(Expdata_GSE182018) == "treatment:ch1"] <- "condition" # Rename the column to have an easier identifier for the conditions
Expdata_GSE182018$condition<-gsub(", 8hr","",as.character(Expdata_GSE182018$condition)) # Remove the last characters from the description of the conditions
Expdata_GSE182018$condition <- gsub('100 nM HHT', 'HHT', Expdata_GSE182018$condition) # Edit the name of the description in the conditions


# The order of the rows in Expdata_GSE182018 must be the same as the order of the columns in Counts_GSE182018
# Here below I show an example to reorder the rows names
# target <- c("DEX_1", "DEX_2", "DEX_3", "DEX_SH454_1", "DEX_SH454_2", "DEX_SH454_3", "No_Drug_1", "No_Drug_2", "No_Drug_3", "SH4_54_1", "SH4_54_2", "SH4_54_3")
# Expdata_GSE182018 <-  Expdata_GSE182018[match(target, Expdata_GSE182018$description), ]

# Data are converted and organized to the format required
Counts_GSE182018_GREIN <- as.matrix(Counts_GSE182018_GREIN)
Counts_GSE182018_GREIN <- Counts_GSE182018_GREIN[,-c(1:6)] # Remove the samples that are not necessary for the analysis

# Round counts down to the nearest integer
Counts_GSE182018_GREIN <- floor(Counts_GSE182018_GREIN)

# IMPORTANT:
# It is absolutely critical that the columns of the count matrix and the rows of the column data (information about samples) are in the same order.

# Replace the row names of Expdata_GSE182018 (sampleID) with the same sample name [title] of [Counts_GSE182018]. 
# This will help to match sample names in both matrices.
# The outcome should be TRUE
all(rownames(Expdata_GSE182018) %in% colnames(Counts_GSE182018_GREIN))
all(colnames(Counts_GSE182018_GREIN) %in% rownames(Expdata_GSE182018))

# With the count matrix, Counts_GSE182018_GREIN, and the sample information, Expdata_GSE182018, we can construct a DESeqDataSet:
dds_GSE182018 <- DESeqDataSetFromMatrix(countData = Counts_GSE182018_GREIN,
                              colData = Expdata_GSE182018,
                              design = ~ condition)
dds_GSE182018



# DATA QUALITY ASSESSMENT
# Before performing differential expression analysis, we perform data quality assessment by sample clustering and visualization
library("pheatmap")
# We log transform the counts
ntd <- normTransform(dds_GSE182018)
# Heatmap of the count matrix
select <- order(rowMeans(counts(dds_GSE182018,normalized=FALSE)),
                decreasing=TRUE)[1:20]
df <- as.data.frame(colData(dds_GSE182018)[,c("condition","type")])
pheatmap(assay(ntd)[select,], cluster_rows=FALSE, show_rownames=FALSE,
         cluster_cols=FALSE, annotation_col=df)



# Heatmap of the sample-to-sample distances
# A heatmap of this distance matrix gives us an overview over similarities and dissimilarities between samples
# Transform the values
vsd <- vst(dds_GSE182018, blind=FALSE)
# rld <- rlog(dds_GSE182018, blind=FALSE)
head(assay(vsd), 3)

# Apply the dist function to the transpose of the transformed count matrix to get sample-to-sample distances
sampleDists <- dist(t(assay(vsd)))

library("RColorBrewer")
sampleDistMatrix <- as.matrix(sampleDists)
rownames(sampleDistMatrix) <- paste(vsd$condition, vsd$type, sep="-")
colnames(sampleDistMatrix) <- NULL
colors <- colorRampPalette( rev(brewer.pal(9, "Blues")) )(255)
pheatmap(sampleDistMatrix,
         clustering_distance_rows=sampleDists,
         clustering_distance_cols=sampleDists,
         col=colors)

# Principal component plot of the samples
plotPCA(vsd, intgroup="condition")


# We perform a minimal pre-filtering to keep only rows that have at least 3 reads total
keep <- rowSums(counts(dds_GSE182018)) >= 3
dds_GSE182018 <- dds_GSE182018[keep,]
table(keep) # This shows how many transcripts have been removed after the filtering
nrow(dds_GSE182018) # to confirm the filtered transcripts



# To specify which level I want to compare against (e.g. which level represents the control group)
dds_GSE182018$condition <- relevel(dds_GSE182018$condition, ref = "Control")

# DIFFERENTIAL EXPRESSION ANALYSIS
dds_GSE182018 <- DESeq(dds_GSE182018) # The DESeq() function normalizes the read counts, estimates dispersions, and fits the linear model, all in one go

resultsNames(dds_GSE182018) # lists the coefficients
plotDispEsts(dds_GSE182018) # Plot the dispersions
# Each black dot in the plot represents the dispersion for one gene. The red line is fit to data (black bots),
# then the dispersions are squeezed toward the red line, resulting the final (blue) dispersion estimates. Usually,
# the dispersion is higest at the low counts and levels off at higher counts.


# Now test for differential expression between treatment conditions
res_GSE182018 <- results(dds_GSE182018)
res_GSE182018

# Get a summary of the results
# The summary gives the number of genes that are up and down regulated, the outlier genes, and genes removed due to low counts.
summary(res_GSE182018)

# Export results to CSV files
# write.csv(as.data.frame(res), file="Treated_vs_Controls.csv")

# Plot the log2 Fold Changes as function of expresson:
plotMA(res_GSE182018,alpha = 0.05)
abline(h=c(-2,2),col = "red")

# Transform the row names into a column
res_GSE182018_df <- data.frame(res_GSE182018)
res_GSE182018 <- tibble::rownames_to_column(res_GSE182018_df, "ensembl_transcript_id")



# Join the expression change values with the Table_ANNOTATED containing MFE values
MFE_GSE182018 <- dplyr::inner_join(Table_ANNOTATED, res_GSE182018, by="ensembl_transcript_id") %>%
  dplyr::filter(padj < 0.05) 


# Generate a scatter plot Log2_FC vs Normalized_MFE
library(ggplot2)
Plot_GSE182018 <- ggplot(MFE_GSE182018, aes(y=Normalized_MFE, x=log2FoldChange)) +
  geom_point(size=1.5, alpha=0.2)+
  theme_classic() +
  theme(legend.position="none") +
  geom_vline(xintercept = 0, size=0.3) +
  #xlim(-5.5,5.5) +
  theme(axis.title = element_text(size = 20)) +
  theme(plot.title = element_text(size = 15)) +
  labs(y="DGfold / nt (kcal/mol)",x="Log2_FC_expression",title="GSE182018_Log2_FC_adj.P<0.05")
print(Plot_GSE182018)



# Look at the mean log2_FC
MFE_GSE182018_UP <- dplyr::filter(MFE_GSE182018, log2FoldChange > 0)
Mean_MFE_GSE182018_UP <- mean(MFE_GSE182018_UP$Normalized_MFE, na.rm = TRUE)

MFE_GSE182018_DOWN <- dplyr::filter(MFE_GSE182018, log2FoldChange < 0)
Mean_MFE_GSE182018_DOWN <- mean(MFE_GSE182018_DOWN$Normalized_MFE, na.rm = TRUE)

TTEST_MFE_GSE182018_all_UP_vs_DOWN <- t.test(MFE_GSE182018_DOWN$Normalized_MFE, MFE_GSE182018_UP$Normalized_MFE, paired=FALSE)

# Add K-S test to look at the differences between the up-regukated and down-regulated genes
ks_test_GSE182018_all_UP_vs_DOWN <- ks.test(MFE_GSE182018_DOWN$Normalized_MFE, MFE_GSE182018_UP$Normalized_MFE)


quantile_075_MFE_GSE182018_UP <- quantile(MFE_GSE182018_UP$Normalized_MFE, probs = c(0.75)) 
quantile_075_MFE_GSE182018_DOWN <- quantile(MFE_GSE182018_DOWN$Normalized_MFE, probs = c(0.75)) 
# Values above 0.75 quantile
ks_test_MFE_GSE182018_075_above <- ks.test(MFE_GSE182018_UP$Normalized_MFE[MFE_GSE182018_UP$Normalized_MFE >= quantile_075_MFE_GSE182018_UP],
                                 MFE_GSE182018_DOWN$Normalized_MFE[MFE_GSE182018_DOWN$Normalized_MFE >= quantile_075_MFE_GSE182018_DOWN])

# Look at the differences between the 0.25 quantile 
quantile_025_MFE_GSE182018_UP <- quantile(MFE_GSE182018_UP$Normalized_MFE, probs = c(0.25)) 
quantile_025_MFE_GSE182018_DOWN <- quantile(MFE_GSE182018_DOWN$Normalized_MFE, probs = c(0.25)) 
# Values below 0.25 quantile
ks_test_MF_GSE182018_025_below <- ks.test(MFE_GSE182018_UP$Normalized_MFE[MFE_GSE182018_UP$Normalized_MFE <= quantile_025_MFE_GSE182018_UP],
                                 MFE_GSE182018_DOWN$Normalized_MFE[MFE_GSE182018_DOWN$Normalized_MFE <= quantile_025_MFE_GSE182018_DOWN])



# Permutation test MFE changes
# Combine the data into a single data frame with labels
upregulated <- data.frame(MFE = MFE_GSE182018_UP$Normalized_MFE, Group = "Up")
downregulated <- data.frame(MFE = MFE_GSE182018_DOWN$Normalized_MFE, Group = "Down")
combined_data <- bind_rows(upregulated, downregulated)

# Observed difference in means
GSE182018_observed_diff <- mean(MFE_GSE182018_UP$Normalized_MFE, na.rm = TRUE) - mean(MFE_GSE182018_DOWN$Normalized_MFE, na.rm = TRUE)

# Number of permutations
n_permutations <- 10000

# Initialize a vector to store the permuted differences
GSE182018_permuted_diffs <- numeric(n_permutations)

# Permutation test
set.seed(123)  # Set seed for reproducibility
for (i in 1:n_permutations) {
  # Permute the Group labels
  permuted_labels <- sample(combined_data$Group)
  
  # Calculate the mean MFE for each permuted group
  permuted_up_mean <- mean(combined_data$MFE[permuted_labels == "Up"])
  permuted_down_mean <- mean(combined_data$MFE[permuted_labels == "Down"])
  
  # Calculate the difference in means for the permuted groups
  GSE182018_permuted_diffs[i] <- permuted_up_mean - permuted_down_mean
}

# Calculate the p-value
GSE182018_p_value <- (sum(abs(GSE182018_permuted_diffs) >= abs(GSE182018_observed_diff)) + 1) / (n_permutations + 1)

# Output the results
cat("Observed difference in GSE182018 means MFE_UP - MFE_DOWN:", GSE182018_observed_diff, "\n")
cat("GSE182018 P-value from permutation test:", GSE182018_p_value, "\n")












## GSE182018 High MFE TX fraction changes ####
# Determine whether within the differentially expressed genes there is a significant up-regulation of high MFE transcripts:
# Define high MFE transcripts by taking the 75th percentile of the combined MFE distributions of control and drug-treated samples.
# Count the number of transcripts in the significantly up- and down-regulated genes that have MFE values above this threshold.
# Perform a two-proportions z-test to compare the proportions of high MFE transcripts between the two groups.


# Extract the normalized count data
# The minimal pre-filtering has already been done in the previous steps
GSE182018_norm_TX_counts <- counts(dds_GSE182018, normalized=TRUE) # This object is already a matrix
GSE182018_norm_TX_counts_df <- as.data.frame(GSE182018_norm_TX_counts)
# Convert row names to column
GSE182018_norm_TX_counts_df$ensembl_transcript_id <- rownames(GSE182018_norm_TX_counts_df)
# Remove row names
rownames(GSE182018_norm_TX_counts_df) <- NULL


# Join the counts with the Table_ANNOTATED containing MFE values and heat capacity values
GSE182018_norm_TX_counts_MFE_df <- dplyr::inner_join(Table_ANNOTATED, GSE182018_norm_TX_counts_df, by="ensembl_transcript_id") %>%
  dplyr::select(ensembl_transcript_id_version, ensembl_transcript_id, ensembl_gene_id, external_gene_name, transcript_is_canonical, Transcript_length,
                GSM5516279, GSM5516280, GSM5516281, GSM5516282, GSM5516283, GSM5516284, GSM5516285, GSM5516286, Normalized_MFE, Temperature, Specific_heat) %>%
  dplyr::filter(ensembl_transcript_id %in% MFE_GSE182018$ensembl_transcript_id)

# Identify the 75th percentile of the combined MFE distributions of control and drug-treated samples
quantile_075_GSE182018_norm_TX_counts_MFE_df <- quantile(GSE182018_norm_TX_counts_MFE_df$Normalized_MFE, probs = c(0.75))

# Select all the transcripts with Normalized_MFE values above the 75th percentile
GSE182018_high_MFE_TX <- dplyr::filter(GSE182018_norm_TX_counts_MFE_df, Normalized_MFE > quantile_075_GSE182018_norm_TX_counts_MFE_df)

# Count the number of transcripts in the significantly up- and down-regulated pools that have MFE values above this threshold.
GSE182018_high_MFE_TX_in_UP <- dplyr::filter(MFE_GSE182018_UP, ensembl_transcript_id_version %in% GSE182018_high_MFE_TX$ensembl_transcript_id_version)
GSE182018_high_MFE_TX_in_DOWN <- dplyr::filter(MFE_GSE182018_DOWN, ensembl_transcript_id_version %in% GSE182018_high_MFE_TX$ensembl_transcript_id_version)


# Counts and sample sizes for each group (UP-regulated and DOWN-regulated)
n_UP <- nrow(MFE_GSE182018_UP) # Total number of transcript significantly UP-regulated
n_DOWN <- nrow(MFE_GSE182018_DOWN) # Total number of transcript significantly DOWN-regulated

count_high_MFE_UP <- nrow(GSE182018_high_MFE_TX_in_UP) # N. of UP_regulated transcripts with MFE values above the 75th percentile
count_high_MFE_DOWN <- nrow(GSE182018_high_MFE_TX_in_DOWN) # N. of DOWN_regulated transcripts with MFE values above the 75th percentile

# Proportions for high MFE transcripts in each group
p_UP <- count_high_MFE_UP / n_UP
p_DOWN <- count_high_MFE_DOWN / n_DOWN

# Pooled proportion
P_pool <- (count_high_MFE_UP + count_high_MFE_DOWN) / (n_UP + n_DOWN)

# Z-test statistic for two proportions
Z <- (p_UP - p_DOWN) / sqrt(P_pool * (1 - P_pool) * (1 / n_UP + 1 / n_DOWN))

# Calculate the p-value for the Z-test
GSE182018_z_test_MFE_p_value <- 2 * (1 - pnorm(abs(Z)))

# Output the results of the Z-test
cat("Two-proportion Z-test statistic:", Z, "\n")
cat("Two-proportion Z-test p-value:", GSE182018_z_test_MFE_p_value, "\n")

# Output the fractions for high MFE in each group
GSE182018_high_MFE_in_UP_fraction <- count_high_MFE_UP / n_UP
GSE182018_high_MFE_in_DOWN_fraction <- count_high_MFE_DOWN / n_DOWN

cat("Fraction of high MFE TX in UP-regulated genes:", GSE182018_high_MFE_in_UP_fraction, "\n")
cat("Fraction of high MFE TX in DOWN-regulated genes:", GSE182018_high_MFE_in_DOWN_fraction, "\n")





# Show data as violin plot
# Add a new column to indicate if the value is above the 75th percentile
MFE_GSE182018$above_quantile_075 <- MFE_GSE182018$Normalized_MFE > quantile_075_GSE182018_norm_TX_counts_MFE_df

# Generate violin plot with conditional jitter coloring
ggplot(MFE_GSE182018, aes(x = factor(log2FoldChange > 0), y = Normalized_MFE)) +
  geom_violin(fill = "white") +
  geom_jitter(aes(color = above_quantile_075), width = 0.1, size = 1, alpha = 0.1) +
  scale_color_manual(values = c("FALSE" = "black", "TRUE" = "blue")) +
  theme_classic() +
  theme(
    legend.position = "none", 
    axis.title = element_text(size = 20), 
    plot.title = element_text(size = 10),
    axis.text.x = element_text(size = 16, color = "black")
  ) +
  geom_vline(xintercept = 0, linewidth = 0.3) +
  labs(
    y = "Normalized_MFE", 
    x = NULL, 
    title = "GSE182018_Log2_FC_adj.P<0.05"
  ) +
  scale_x_discrete(labels = c("log2FoldChange < 0", "log2FoldChange > 0"))








# Determine the impact of these changes in terms of fraction of total counts:
# Calculate the fraction of total counts of high MFE transcripts in control and drug-treated groups. 
# This is done by summing the counts of the high MFE transcripts and dividing by the total counts in each group.
# Fisher’s exact test to compare the proportions of high MFE transcripts counts between control and drug-treated groups.


# Convert from wide to long format
GSE182018_long_data <- GSE182018_norm_TX_counts_MFE_df %>%
  pivot_longer(
    cols = starts_with("GSM"),      # Select all columns starting with "GSM"
    names_to = "replicate",         # Name of the new column for replicate identifiers
    values_to = "counts"            # Name of the new column for the counts
  )

# Add a condition column based on the replicate
GSE182018_long_data <- GSE182018_long_data %>%
  mutate(condition = ifelse(replicate %in% c("GSM5516279", "GSM5516280", "GSM5516281", "GSM5516282"), "Control", "HHT"))


# Aggregate the replicates for each condition
GSE182018_norm_TX_aggregated_data_avg_counts <- GSE182018_long_data %>%
  group_by(ensembl_transcript_id_version, condition, Normalized_MFE, Specific_heat) %>%
  summarise(
    avg_counts = mean(counts),
    .groups = 'drop'
  )



# Two-proportion z-test
# Define the 75th percentile of the entire distribution of MFE values for the GSE182018 data
GSE182018_MFE_all_TX_75_percentile <- quantile(GSE182018_norm_TX_aggregated_data_avg_counts$Normalized_MFE, 0.75)

# Identify all the transcripts with MFE values above the 75th percentile
GSE182018_high_MFE_TX_total <- dplyr::filter(GSE182018_norm_TX_counts_MFE_df, Normalized_MFE > GSE182018_MFE_all_TX_75_percentile)

# Fraction of total high MFE transcripts counts in control and drug-treated groups
GSE182018_control_total_counts <- dplyr::filter(GSE182018_norm_TX_aggregated_data_avg_counts, condition == "Control") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE182018_control_high_MFE_TX_counts <- dplyr::filter(GSE182018_norm_TX_aggregated_data_avg_counts, condition == "Control") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE182018_high_MFE_TX_total$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE182018_control_high_MFE_TX_counts_fraction <- GSE182018_control_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE182018_control_total_counts$total_counts
print(GSE182018_control_high_MFE_TX_counts_fraction) # This value goes in the summary table

GSE182018_HHT_total_counts <- dplyr::filter(GSE182018_norm_TX_aggregated_data_avg_counts, condition == "HHT") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE182018_HHT_high_MFE_TX_counts <- dplyr::filter(GSE182018_norm_TX_aggregated_data_avg_counts, condition == "HHT") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE182018_high_MFE_TX_total$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE182018_HHT_high_MFE_TX_counts_fraction <- GSE182018_HHT_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE182018_HHT_total_counts$total_counts
print(GSE182018_HHT_high_MFE_TX_counts_fraction) # This value goes in the summary table

# Calculate the number of successes (high MFE counts) and sample sizes
x1 <- GSE182018_control_high_MFE_TX_counts$total_counts_high_MFE_TX
x2 <- GSE182018_HHT_high_MFE_TX_counts$total_counts_high_MFE_TX
n1 <- GSE182018_control_total_counts$total_counts
n2 <- GSE182018_HHT_total_counts$total_counts

# Calculate the pooled proportion
p <- (x1 + x2) / (n1 + n2)

# Standard error for the difference of proportions
SE <- sqrt(p * (1 - p) * (1 / n1 + 1 / n2))

# Z-score for the difference in proportions
z_value <- (GSE182018_control_high_MFE_TX_counts_fraction - GSE182018_HHT_high_MFE_TX_counts_fraction) / SE

# Two-tailed p-value for the z-test
GSE182018_z_test_counts_75_p_value <- 2 * (1 - pnorm(abs(z_value)))  # Two-tailed test

# Output the results
cat("GSE182018 Two-Proportion Z-test P-value for high MFE transcripts counts between Control and HHT:", GSE182018_z_test_counts_75_p_value, "\n")
cat("Control Proportion of High MFE TX Counts:", GSE182018_control_high_MFE_TX_counts_fraction, "\n")
cat("HHT Proportion of High MFE TX Counts:", GSE182018_HHT_high_MFE_TX_counts_fraction, "\n")
cat("Net Change in Proportions between Drug and Control:", GSE182018_HHT_high_MFE_TX_counts_fraction - GSE182018_control_high_MFE_TX_counts_fraction, "\n")









