# GSE192446 choriocarcinoma cell lines JAR and JEG-3 treated with vorinostat ####
# These data do NOT counts tables in the GREIN database
# The raw counts at the gene level have been downloaded form: https://www.ncbi.nlm.nih.gov/geo/download/?acc=GSE192446


# Vorinostat's inhibition of histone deacetylases results in the accumulation of acetylated histones and acetylated proteins, including transcription factors crucial for the expression of genes needed to induce cell differentiation.
# https://www.ncbi.nlm.nih.gov/geo/query/acc.cgi?acc=GSE192446

# These data have been generated with two different cell lines (JAR and JEG-3) which have been treated with the same agent and have different controls
# So, I split the data and I perform differential expression analysis with DESeq2 on each of them separately.

# Download the raw counts at the gene level and get the corresponding Ensembl transcripts ID with biomaRt
Counts_GSE192446 <- read.table(file = 'path_to/Choriocarcinoma_vorinostat_GSE192446/GSE192446_raw_counts_GRCh38.p13_NCBI.tsv', sep = '\t', header = TRUE)
Counts_GSE192446 <- dplyr::rename(Counts_GSE192446, JAR_DMSO_rep1 = GSM5747267) %>%
  dplyr::rename(JAR_DMSO_rep2 = GSM5747268) %>%
  dplyr::rename(JAR_DMSO_rep3 = GSM5747269) %>%
  dplyr::rename(JAR_vorinostat_rep1 = GSM5747270) %>%
  dplyr::rename(JAR_vorinostat_rep2 = GSM5747271) %>%
  dplyr::rename(JAR_vorinostat_rep3 = GSM5747272) %>%
  dplyr::rename(JEG3_DMSO_rep1 = GSM5747273) %>%
  dplyr::rename(JEG3_DMSO_rep2 = GSM5747274) %>%
  dplyr::rename(JEG3_DMSO_rep3 = GSM5747275) %>%
  dplyr::rename(JEG3_vorinostat_rep1 = GSM5747276) %>%
  dplyr::rename(JEG3_vorinostat_rep2 = GSM5747277) %>%
  dplyr::rename(JEG3_vorinostat_rep3 = GSM5747278) %>%
  dplyr::rename(entrezgene_id = GeneID)

Counts_GSE192446$entrezgene_id <- as.character(Counts_GSE192446$entrezgene_id)


# Assign to each entrezgene_id the Ensembl transcript id version.
# The complete Ensembl ID is necessary to intersect the data with the Table containing the MFE values of each transcript.
library(biomaRt)
mart <- useMart(biomart = "ensembl", dataset = "hsapiens_gene_ensembl", host="https://www.ensembl.org")
gene_ids <- (Counts_GSE192446$entrezgene_id) # This reads the Ensembl transcripts IDs in the specific column of the 'Table_ANNOTATED file.

res_GSE192446 <- getBM(attributes = c('transcript_is_canonical',
                                      'ensembl_transcript_id_version',
                                      'entrezgene_id',
                                      'external_gene_name'),
                       filters = 'entrezgene_id',
                       values = gene_ids,
                       mart = mart)
res_GSE192446$entrezgene_id <- as.character(res_GSE192446$entrezgene_id)


# IT is necessary to select the counts for only one gene symbol, otherwise it is not possible to change the row names
# Join the transcript Ensembl IDs version with the original counts
Counts_GSE192446_tx <- dplyr::left_join(Counts_GSE192446, res_GSE192446, by="entrezgene_id", multiple = "all") %>%
  dplyr::filter(transcript_is_canonical == 1) %>%
  dplyr::select(-c(entrezgene_id, transcript_is_canonical, external_gene_name)) %>%
  dplyr::distinct(ensembl_transcript_id_version, .keep_all = TRUE) %>%
  dplyr::relocate(ensembl_transcript_id_version, .before = JAR_DMSO_rep1)

Counts_GSE192446_tx <- Counts_GSE192446_tx %>% remove_rownames %>% column_to_rownames(var="ensembl_transcript_id_version") # Convert first column into row names in data frame

Counts_GSE192446_JAR<- Counts_GSE192446_tx[,-c(7:12)] # Remove the samples that are not necessary for the analysis
Counts_GSE192446_JEG3<- Counts_GSE192446_tx[,-c(1:6)] # Remove the samples that are not necessary for the analysis


# Access the Series Matrix
# Data_GSE192446 <- getGEO(GEO = "GSE192446")

# LOad the object
Data_GSE192446 <- readRDS("path_to/GREIN_series_matrices_data/Data_GSE192446.rds")


# Extract the phenotypic/clinical data matrix from the series matrix
Expdata_GSE192446 <- Data_GSE192446[["GSE192446_series_matrix.txt.gz"]]@phenoData@data
colnames(Expdata_GSE192446)[colnames(Expdata_GSE192446) == "agent:ch1"] <- "condition" # Rename the column to have an easier identifier for the conditions
colnames(Expdata_GSE192446)[colnames(Expdata_GSE192446) == "cell line:ch1"] <- "Cell_line" # Rename the column to have an easier identifier for the conditions

# Split the Expdata for the two cell lines
Expdata_GSE192446_JAR <- Expdata_GSE192446[1:6,]
rownames(Expdata_GSE192446_JAR) <- Expdata_GSE192446_JAR$title

Expdata_GSE192446_JEG3 <- Expdata_GSE192446[7:12,]
Expdata_GSE192446_JEG3$title <- gsub('JEG-3_DMSO_rep1', 'JEG3_DMSO_rep1', Expdata_GSE192446_JEG3$title) # Edit the name of the description in the conditions to make them equal to the names in the counts
Expdata_GSE192446_JEG3$title <- gsub('JEG-3_DMSO_rep2', 'JEG3_DMSO_rep2', Expdata_GSE192446_JEG3$title)
Expdata_GSE192446_JEG3$title <- gsub('JEG-3_DMSO_rep3', 'JEG3_DMSO_rep3', Expdata_GSE192446_JEG3$title)
Expdata_GSE192446_JEG3$title <- gsub('JEG-3_vorinostat_rep1', 'JEG3_vorinostat_rep1', Expdata_GSE192446_JEG3$title)
Expdata_GSE192446_JEG3$title <- gsub('JEG-3_vorinostat_rep2', 'JEG3_vorinostat_rep2', Expdata_GSE192446_JEG3$title)
Expdata_GSE192446_JEG3$title <- gsub('JEG-3_vorinostat_rep3', 'JEG3_vorinostat_rep3', Expdata_GSE192446_JEG3$title)
rownames(Expdata_GSE192446_JEG3) <- Expdata_GSE192446_JEG3$title


# IMPORTANT:
# It is absolutely critical that the columns of the count matrix and the rows of the column data (information about samples) are in the same order.

# Replace the row names of Expdata_GSE182018 (sampleID) with the same sample name [title] of [Counts_GSE182018]. 
# This will help to match sample names in both matrices.
# The outcome should be TRUE
all(rownames(Expdata_GSE192446_JAR) %in% colnames(Counts_GSE192446_JAR))
all(colnames(Counts_GSE192446_JAR) %in% rownames(Expdata_GSE192446_JAR))

all(rownames(Expdata_GSE192446_JEG3) %in% colnames(Counts_GSE192446_JEG3))
all(colnames(Counts_GSE192446_JEG3) %in% rownames(Expdata_GSE192446_JEG3))


# Round the counts before using DESeq2
Counts_GSE192446_JAR <- round(Counts_GSE192446_JAR)
Counts_GSE192446_JEG3 <- round(Counts_GSE192446_JEG3)

# Construct the DESeqDataSet:
dds_GSE192446_JAR <- DESeqDataSetFromMatrix(countData = Counts_GSE192446_JAR,
                                  colData = Expdata_GSE192446_JAR,
                                  design = ~ condition)
dds_GSE192446_JAR

dds_GSE192446_JEG3 <- DESeqDataSetFromMatrix(countData = Counts_GSE192446_JEG3,
                                   colData = Expdata_GSE192446_JEG3,
                                   design = ~ condition)
dds_GSE192446_JEG3



# DATA QUALITY ASSESSMENT
# Before performing differential expression analysis, we perform data quality assessment by sample clustering and visualization
library("pheatmap")
# We log transform the normalized counts
ntd <- normTransform(dds_GSE192446_JAR)
# Heatmap of the count matrix
select <- order(rowMeans(counts(dds_GSE192446_JAR,normalized=FALSE)),
                decreasing=TRUE)[1:20]
df_JAR <- as.data.frame(colData(dds_GSE192446_JAR)[,c("condition","type")])
pheatmap(assay(ntd)[select,], cluster_rows=FALSE, show_rownames=FALSE,
         cluster_cols=FALSE, annotation_col=df_JAR)


ntd <- normTransform(dds_GSE192446_JEG3)
# Heatmap of the count matrix
select <- order(rowMeans(counts(dds_GSE192446_JEG3,normalized=FALSE)),
                decreasing=TRUE)[1:20]
df_JEG3 <- as.data.frame(colData(dds_GSE192446_JEG3)[,c("condition","type")])
pheatmap(assay(ntd)[select,], cluster_rows=FALSE, show_rownames=FALSE,
         cluster_cols=FALSE, annotation_col=df_JEG3)


# Heatmap of the sample-to-sample distances
# A heatmap of this distance matrix gives us an overview over similarities and dissimilarities between samples
# Transform the values
vsd <- vst(dds_GSE192446_JAR, blind=FALSE)
# rld <- rlog(dds_GSE192446_JAR, blind=FALSE)
head(assay(vsd), 3)

# Apply the dist function to the transpose of the transformed count matrix to get sample-to-sample distances
sampleDists <- dist(t(assay(vsd)))

library("RColorBrewer")
sampleDistMatrix <- as.matrix(sampleDists)
rownames(sampleDistMatrix) <- paste(vsd$condition, vsd$type, sep="-")
colnames(sampleDistMatrix) <- NULL
colors <- colorRampPalette( rev(brewer.pal(9, "Blues")) )(255)
pheatmap(sampleDistMatrix,
         clustering_distance_rows=sampleDists,
         clustering_distance_cols=sampleDists,
         col=colors)

# Principal component plot of the samples
plotPCA(vsd, intgroup="condition")




# Heatmap of the sample-to-sample distances
# A heatmap of this distance matrix gives us an overview over similarities and dissimilarities between samples
# Transform the values
vsd <- vst(dds_GSE192446_JEG3, blind=FALSE)
#rld <- rlog(dds_GSE192446_JEG3, blind=FALSE)
head(assay(vsd), 3)

# Apply the dist function to the transpose of the transformed count matrix to get sample-to-sample distances
sampleDists <- dist(t(assay(vsd)))

library("RColorBrewer")
sampleDistMatrix <- as.matrix(sampleDists)
rownames(sampleDistMatrix) <- paste(vsd$condition, vsd$type, sep="-")
colnames(sampleDistMatrix) <- NULL
colors <- colorRampPalette( rev(brewer.pal(9, "Blues")) )(255)
pheatmap(sampleDistMatrix,
         clustering_distance_rows=sampleDists,
         clustering_distance_cols=sampleDists,
         col=colors)

# Principal component plot of the samples
plotPCA(vsd, intgroup="condition")



# We perform a minimal pre-filtering to keep only rows that have at least 3 reads total
keep <- rowSums(counts(dds_GSE192446_JAR)) >= 3
dds_GSE192446_JAR <- dds_GSE192446_JAR[keep,]

keep <- rowSums(counts(dds_GSE192446_JEG3)) >= 3
dds_GSE192446_JEG3 <- dds_GSE192446_JEG3[keep,]




# By default, R will choose a reference level for factors based on alphabetical order. 
# Then, if you never tell the DESeq2 functions which level you want to compare against (e.g. which level represents the control group), the comparisons will be based on the alphabetical order of the levels.
# To do this I can explicitly set the factors levels
dds_GSE192446_JAR$condition <- relevel(dds_GSE192446_JAR$condition, ref = "DMSO")
dds_GSE192446_JEG3$condition <- relevel(dds_GSE192446_JEG3$condition, ref = "DMSO")


# DIFFERENTIAL EXPRESSION ANALYSIS
dds_GSE192446_JAR <- DESeq(dds_GSE192446_JAR)
res_GSE192446_JAR <- results(dds_GSE192446_JAR)
res_GSE192446_JAR

dds_GSE192446_JEG3 <- DESeq(dds_GSE192446_JEG3)
res_GSE192446_JEG3 <- results(dds_GSE192446_JEG3)
res_GSE192446_JEG3





# Transform the row names of GSE192446_JAR into a column
res_GSE192446_JAR_df <- data.frame(res_GSE192446_JAR)
res_GSE192446_JAR <- tibble::rownames_to_column(res_GSE192446_JAR_df, "ensembl_transcript_id_version")


# Join the expression change values with the Table_ANNOTATED containing MFE values
MFE_GSE192446_JAR <- dplyr::inner_join(Table_ANNOTATED, res_GSE192446_JAR, by="ensembl_transcript_id_version") %>%
  dplyr::filter(padj < 0.05) 


# Generate a scatter plot Log2_FC vs Normalized_MFE
library(ggplot2)
Plot_GSE192446_JAR <- ggplot(MFE_GSE192446_JAR, aes(y=Normalized_MFE, x=log2FoldChange)) +
  geom_point(size=1.5, alpha=0.3)+
  theme_classic() +
  theme(legend.position="none") +
  geom_vline(xintercept = 0, size=0.3) +
  #xlim(-5.5,5.5) +
  theme(axis.title = element_text(size = 20)) +
  theme(plot.title = element_text(size = 15)) +
  labs(y="DGfold / nt (kcal/mol)",x="Log2_FC_expression",title="GSE192446_JAR_Log2_FC_adj.P<0.05")
print(Plot_GSE192446_JAR)




MFE_GSE192446_JAR_UP <- dplyr::filter(MFE_GSE192446_JAR, log2FoldChange > 0)
Mean_MFE_GSE192446_JAR_UP <- mean(MFE_GSE192446_JAR_UP$Normalized_MFE)

MFE_GSE192446_JAR_DOWN <- dplyr::filter(MFE_GSE192446_JAR, log2FoldChange < 0)
Mean_MFE_GSE192446_JAR_DOWN <- mean(MFE_GSE192446_JAR_DOWN$Normalized_MFE)

TTEST_MFE_GSE192446_JAR_all_UP_vs_DOWN <- t.test(MFE_GSE192446_JAR_DOWN$Normalized_MFE, MFE_GSE192446_JAR_UP$Normalized_MFE, paired=FALSE)

# Add K-S test to look at the differences between the up-regukated and down-regulated genes
ks_test_GSE192446_JAR_all_UP_vs_DOWN <- ks.test(MFE_GSE192446_JAR_DOWN$Normalized_MFE, MFE_GSE192446_JAR_UP$Normalized_MFE)


quantile_075_MFE_GSE192446_JAR_UP <- quantile(MFE_GSE192446_JAR_UP$Normalized_MFE, probs = c(0.75)) 
quantile_075_MFE_GSE192446_JAR_DOWN <- quantile(MFE_GSE192446_JAR_DOWN$Normalized_MFE, probs = c(0.75)) 
# Values above 0.75 quantile
ks_test_MFE_GSE192446_JAR_075_above <- ks.test(MFE_GSE192446_JAR_UP$Normalized_MFE[MFE_GSE192446_JAR_UP$Normalized_MFE >= quantile_075_MFE_GSE192446_JAR_UP],
                                 MFE_GSE192446_JAR_DOWN$Normalized_MFE[MFE_GSE192446_JAR_DOWN$Normalized_MFE >= quantile_075_MFE_GSE192446_JAR_DOWN])

# Look at the differences between the 0.25 quantile 
quantile_025_MFE_GSE192446_JAR_UP <- quantile(MFE_GSE192446_JAR_UP$Normalized_MFE, probs = c(0.25)) 
quantile_025_MFE_GSE192446_JAR_DOWN <- quantile(MFE_GSE192446_JAR_DOWN$Normalized_MFE, probs = c(0.25)) 
# Values below 0.25 quantile
ks_test_MFE_GSE192446_JAR_025_below <- ks.test(MFE_GSE192446_JAR_UP$Normalized_MFE[MFE_GSE192446_JAR_UP$Normalized_MFE <= quantile_025_MFE_GSE192446_JAR_UP],
                                 MFE_GSE192446_JAR_DOWN$Normalized_MFE[MFE_GSE192446_JAR_DOWN$Normalized_MFE <= quantile_025_MFE_GSE192446_JAR_DOWN])


# Permutation test MFE changes
# Combine the data into a single data frame with labels
upregulated <- data.frame(MFE = MFE_GSE192446_JAR_UP$Normalized_MFE, Group = "Up")
downregulated <- data.frame(MFE = MFE_GSE192446_JAR_DOWN$Normalized_MFE, Group = "Down")
combined_data <- bind_rows(upregulated, downregulated)

# Observed difference in means
GSE192446_JAR_observed_diff <- mean(MFE_GSE192446_JAR_UP$Normalized_MFE) - mean(MFE_GSE192446_JAR_DOWN$Normalized_MFE)

# Number of permutations
n_permutations <- 10000

# Initialize a vector to store the permuted differences
GSE192446_JAR_permuted_diffs <- numeric(n_permutations)

# Permutation test
set.seed(123)  # Set seed for reproducibility
for (i in 1:n_permutations) {
  # Permute the Group labels
  permuted_labels <- sample(combined_data$Group)
  
  # Calculate the mean MFE for each permuted group
  permuted_up_mean <- mean(combined_data$MFE[permuted_labels == "Up"])
  permuted_down_mean <- mean(combined_data$MFE[permuted_labels == "Down"])
  
  # Calculate the difference in means for the permuted groups
  GSE192446_JAR_permuted_diffs[i] <- permuted_up_mean - permuted_down_mean
}

# Calculate the p-value
GSE192446_JAR_p_value <- (sum(abs(GSE192446_JAR_permuted_diffs) >= abs(GSE192446_JAR_observed_diff)) + 1) / (n_permutations + 1)

# Output the results
cat("Observed difference in GSE192446_JAR means MFE_UP - MFE_DOWN:", GSE192446_JAR_observed_diff, "\n")
cat("GSE192446_JAR P-value from permutation test:", GSE192446_JAR_p_value, "\n")







