  GSE192446_JEG3_permuted_diffs[i] <- permuted_up_mean - permuted_down_mean
}

# Calculate the p-value
GSE192446_JEG3_p_value <- (sum(abs(GSE192446_JEG3_permuted_diffs) >= abs(GSE192446_JEG3_observed_diff)) + 1) / (n_permutations + 1)

# Output the results
cat("Observed difference in GSE192446_JEG3 means MFE_UP - MFE_DOWN:", GSE192446_JEG3_observed_diff, "\n")
cat("GSE192446_JEG3 P-value from permutation test:", GSE192446_JEG3_p_value, "\n")












## GSE192446_JAR High MFE TX fraction changes ####
# Determine whether within the differentially expressed genes there is a significant up-regulation of high MFE transcripts:
# Define high MFE transcripts by taking the 75th percentile of the combined MFE distributions of control and drug-treated samples.
# Count the number of transcripts in the significantly up- and down-regulated genes that have MFE values above this threshold.
# Perform a two-proportions z-test to compare the proportions of high MFE transcripts between the two groups.

# Extract the normalized count data
GSE192446_JAR_norm_TX_counts <- counts(dds_GSE192446_JAR, normalized=TRUE) # This object is already a matrix
GSE192446_JAR_norm_TX_counts_df <- as.data.frame(GSE192446_JAR_norm_TX_counts)
# Convert row names to column
GSE192446_JAR_norm_TX_counts_df$ensembl_transcript_id <- rownames(GSE192446_JAR_norm_TX_counts_df)
# Remove row names
rownames(GSE192446_JAR_norm_TX_counts_df) <- NULL

# Move ensembl_transcript_id column to the first position
GSE192446_JAR_norm_TX_counts_df <- GSE192446_JAR_norm_TX_counts_df[, c("ensembl_transcript_id", setdiff(names(GSE192446_JAR_norm_TX_counts_df), "ensembl_transcript_id"))]

# Remove everything after the dot (including the dot itself) in the ensembl_transcript_id column
GSE192446_JAR_norm_TX_counts_df$ensembl_transcript_id <- sub("\\..*", "", GSE192446_JAR_norm_TX_counts_df$ensembl_transcript_id)

# Join the counts with the Table_ANNOTATED containing MFE values and heat capacity values
GSE192446_JAR_norm_TX_counts_MFE_df <- dplyr::inner_join(Table_ANNOTATED, GSE192446_JAR_norm_TX_counts_df, by="ensembl_transcript_id") %>%
  dplyr::select(ensembl_transcript_id_version, ensembl_transcript_id, ensembl_gene_id, external_gene_name, transcript_is_canonical, Transcript_length, 
                JAR_DMSO_rep1, JAR_DMSO_rep2, JAR_DMSO_rep3, JAR_vorinostat_rep1, JAR_vorinostat_rep2, JAR_vorinostat_rep3, Normalized_MFE, Temperature, Specific_heat) %>%
  dplyr::filter(ensembl_transcript_id %in% MFE_GSE192446_JAR$ensembl_transcript_id)



# Identify the 75th percentile of the combined MFE distributions of control and drug-treated samples
quantile_075_GSE192446_JAR_norm_TX_counts_MFE_df <- quantile(GSE192446_JAR_norm_TX_counts_MFE_df$Normalized_MFE, probs = c(0.75))

# Select all the transcripts with Normalized_MFE values above the 75th percentile
GSE192446_JAR_high_MFE_TX <- dplyr::filter(GSE192446_JAR_norm_TX_counts_MFE_df, Normalized_MFE > quantile_075_GSE192446_JAR_norm_TX_counts_MFE_df)

# Count the number of transcripts in the significantly up- and down-regulated pools that have MFE values above this threshold.
GSE192446_JAR_high_MFE_TX_in_UP <- dplyr::filter(MFE_GSE192446_JAR_UP, ensembl_transcript_id_version %in% GSE192446_JAR_high_MFE_TX$ensembl_transcript_id_version)
GSE192446_JAR_high_MFE_TX_in_DOWN <- dplyr::filter(MFE_GSE192446_JAR_DOWN, ensembl_transcript_id_version %in% GSE192446_JAR_high_MFE_TX$ensembl_transcript_id_version)

# Total count of UP-regulated and DOWN-regulated genes
GSE192446_JAR_total_UP <- nrow(MFE_GSE192446_JAR_UP)
GSE192446_JAR_total_DOWN <- nrow(MFE_GSE192446_JAR_DOWN)

# Count of high MFE transcripts in the UP and DOWN-regulated groups
GSE192446_JAR_count_high_MFE_UP <- nrow(GSE192446_JAR_high_MFE_TX_in_UP)
GSE192446_JAR_count_high_MFE_DOWN <- nrow(GSE192446_JAR_high_MFE_TX_in_DOWN)

# Calculate the proportions of high MFE transcripts in UP and DOWN-regulated genes
GSE192446_JAR_high_MFE_in_UP_fraction <- GSE192446_JAR_count_high_MFE_UP / GSE192446_JAR_total_UP
GSE192446_JAR_high_MFE_in_DOWN_fraction <- GSE192446_JAR_count_high_MFE_DOWN / GSE192446_JAR_total_DOWN

# Calculate the pooled proportion
p_pool <- (GSE192446_JAR_count_high_MFE_UP + GSE192446_JAR_count_high_MFE_DOWN) / (GSE192446_JAR_total_UP + GSE192446_JAR_total_DOWN)

# Standard error for the difference of proportions
SE <- sqrt(p_pool * (1 - p_pool) * (1 / GSE192446_JAR_total_UP + 1 / GSE192446_JAR_total_DOWN))

# Z-value for the difference in proportions
z_value <- (GSE192446_JAR_high_MFE_in_UP_fraction - GSE192446_JAR_high_MFE_in_DOWN_fraction) / SE

# Two-tailed p-value from the Z-test
GSE192446_JAR_z_test_MFE_p_value <- 2 * (1 - pnorm(abs(z_value)))  # Two-tailed test

# Output the results
cat("GSE192446_JAR Two-Proportion Z-test P-value for high MFE transcripts between UP and DOWN-regulated genes:", GSE192446_JAR_z_test_MFE_p_value, "\n")
cat("Proportion of High MFE TX in UP-regulated genes:", GSE192446_JAR_high_MFE_in_UP_fraction, "\n")
cat("Proportion of High MFE TX in DOWN-regulated genes:", GSE192446_JAR_high_MFE_in_DOWN_fraction, "\n")
cat("Net Change in Proportions between UP and DOWN-regulated genes:", GSE192446_JAR_high_MFE_in_UP_fraction - GSE192446_JAR_high_MFE_in_DOWN_fraction, "\n")









# Show data as violin plot
# Add a new column to indicate if the value is above the 75th percentile
MFE_GSE192446_JAR$above_quantile_075 <- MFE_GSE192446_JAR$Normalized_MFE > quantile_075_GSE192446_JAR_norm_TX_counts_MFE_df

# Generate violin plot with conditional jitter coloring
ggplot(MFE_GSE192446_JAR, aes(x = factor(log2FoldChange > 0), y = Normalized_MFE)) +
  geom_violin(fill = "white") +
  geom_jitter(aes(color = above_quantile_075), width = 0.1, size = 1, alpha = 0.8) +
