  ) +
  geom_vline(xintercept = 0, linewidth = 0.3) +
  labs(
    y = "Normalized_MFE", 
    x = NULL, 
    title = "GSE192446_JAR_Log2_FC_adj.P<0.05"
  ) +
  scale_x_discrete(labels = c("log2FoldChange < 0", "log2FoldChange > 0"))










# Determine the impact of these changes in terms of fraction of total counts:
# Calculate the fraction of total counts of high MFE transcripts in control and drug-treated groups. 
# This is done by summing the counts of the high MFE transcripts and dividing by the total counts in each group.
# Fisher’s exact test to compare the proportions of high MFE transcripts counts between the two groups.

# Convert from wide to long format
GSE192446_JAR_long_data <- GSE192446_JAR_norm_TX_counts_MFE_df %>%
  pivot_longer(
    cols = starts_with("JAR"),      # Select all columns starting with "GSM"
    names_to = "replicate",         # Name of the new column for replicate identifiers
    values_to = "counts"            # Name of the new column for the counts
  )

# Add a condition column based on the replicate
GSE192446_JAR_long_data <- GSE192446_JAR_long_data %>%
  mutate(condition = ifelse(replicate %in% c("JAR_DMSO_rep1", "JAR_DMSO_rep2", "JAR_DMSO_rep3"), "Control", "vorinostat"))

# Aggregate the replicates for each condition
GSE192446_JAR_norm_TX_aggregated_data_avg_counts <- GSE192446_JAR_long_data %>%
  group_by(ensembl_transcript_id_version, condition, Normalized_MFE, Specific_heat) %>%
  summarise(
    avg_counts = mean(counts),
    .groups = 'drop'
  )

# Fraction of total high MFE transcripts counts in control and drug-treated groups
GSE192446_JAR_control_total_counts <- dplyr::filter(GSE192446_JAR_norm_TX_aggregated_data_avg_counts, condition == "Control") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE192446_JAR_control_high_MFE_TX_counts <- dplyr::filter(GSE192446_JAR_norm_TX_aggregated_data_avg_counts, condition == "Control") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE192446_JAR_high_MFE_TX$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE192446_JAR_control_high_MFE_TX_counts_fraction <- GSE192446_JAR_control_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE192446_JAR_control_total_counts$total_counts
print(GSE192446_JAR_control_high_MFE_TX_counts_fraction) # This value goes in the summary table

GSE192446_JAR_vorinostat_total_counts <- dplyr::filter(GSE192446_JAR_norm_TX_aggregated_data_avg_counts, condition == "vorinostat") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE192446_JAR_vorinostat_high_MFE_TX_counts <- dplyr::filter(GSE192446_JAR_norm_TX_aggregated_data_avg_counts, condition == "vorinostat") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE192446_JAR_high_MFE_TX$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE192446_JAR_vorinostat_high_MFE_TX_counts_fraction <- GSE192446_JAR_vorinostat_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE192446_JAR_vorinostat_total_counts$total_counts
print(GSE192446_JAR_vorinostat_high_MFE_TX_counts_fraction) # This value goes in the summary table

# Calculate the number of successes (high MFE counts) and sample sizes
x1 <- GSE192446_JAR_control_high_MFE_TX_counts$total_counts_high_MFE_TX
x2 <- GSE192446_JAR_vorinostat_high_MFE_TX_counts$total_counts_high_MFE_TX
n1 <- GSE192446_JAR_control_total_counts$total_counts
n2 <- GSE192446_JAR_vorinostat_total_counts$total_counts

# Calculate the pooled proportion
p <- (x1 + x2) / (n1 + n2)

# Standard error for the difference of proportions
SE <- sqrt(p * (1 - p) * (1 / n1 + 1 / n2))

# Z-score for the difference in proportions
z_value <- (GSE192446_JAR_control_high_MFE_TX_counts_fraction - GSE192446_JAR_vorinostat_high_MFE_TX_counts_fraction) / SE

# Two-tailed p-value for the z-test
GSE192446_JAR_z_test_counts_75_p_value <- 2 * (1 - pnorm(abs(z_value)))  # Two-tailed test

# Output the results
cat("GSE192446_JAR Two-Proportion Z-test P-value for high MFE transcripts counts between Control and Vorinostat:", GSE192446_JAR_z_test_counts_75_p_value, "\n")
cat("Control Proportion of High MFE TX Counts:", GSE192446_JAR_control_high_MFE_TX_counts_fraction, "\n")
