# Calculate the proportions of high MFE transcripts in UP and DOWN-regulated genes
GSE192446_JEG3_high_MFE_in_UP_fraction <- GSE192446_JEG3_count_high_MFE_UP / GSE192446_JEG3_total_UP
GSE192446_JEG3_high_MFE_in_DOWN_fraction <- GSE192446_JEG3_count_high_MFE_DOWN / GSE192446_JEG3_total_DOWN

# Calculate the pooled proportion
p_pool <- (GSE192446_JEG3_count_high_MFE_UP + GSE192446_JEG3_count_high_MFE_DOWN) / (GSE192446_JEG3_total_UP + GSE192446_JEG3_total_DOWN)

# Standard error for the difference of proportions
SE <- sqrt(p_pool * (1 - p_pool) * (1 / GSE192446_JEG3_total_UP + 1 / GSE192446_JEG3_total_DOWN))

# Z-value for the difference in proportions
z_value <- (GSE192446_JEG3_high_MFE_in_UP_fraction - GSE192446_JEG3_high_MFE_in_DOWN_fraction) / SE

# Two-tailed p-value from the Z-test
GSE192446_JEG3_z_test_MFE_p_value <- 2 * (1 - pnorm(abs(z_value)))  # Two-tailed test

# Output the results
cat("GSE192446_JEG3 Two-Proportion Z-test P-value for high MFE transcripts between UP and DOWN-regulated genes:", GSE192446_JEG3_z_test_MFE_p_value, "\n")
cat("Proportion of High MFE TX in UP-regulated genes:", GSE192446_JEG3_high_MFE_in_UP_fraction, "\n")
cat("Proportion of High MFE TX in DOWN-regulated genes:", GSE192446_JEG3_high_MFE_in_DOWN_fraction, "\n")
cat("Net Change in Proportions between UP and DOWN-regulated genes:", GSE192446_JEG3_high_MFE_in_UP_fraction - GSE192446_JEG3_high_MFE_in_DOWN_fraction, "\n")







