# Assign to each ensembl gene ID an external gene symbol for the filtering with the gene sets
library(biomaRt)
mart <- useMart(biomart = "ensembl", dataset = "hsapiens_gene_ensembl", host="https://www.ensembl.org")
gene_ids <- (Counts_GSE192446_gene$entrezgene_id) # This reads the Ensembl transcripts IDs in the specific column of the 'Table_ANNOTATED file.

res_GSE192446_gene <- getBM(attributes = c('entrezgene_id',
                                           'external_gene_name'),
                            filters = 'entrezgene_id',
                            values = gene_ids,
                            mart = mart)
