Counts_GSE192446_gene <- dplyr::left_join(Counts_GSE192446_gene, res_GSE192446_gene, by = "entrezgene_id") %>%
  dplyr::filter(!is.na(external_gene_name), external_gene_name != "") %>%
  dplyr::select(-entrezgene_id) %>%
  dplyr::select(external_gene_name, everything())
  


# In order to use the gene symbols as raw names, I need to remove the duplicates - I merge the counts of the same gene
Counts_GSE192446_gene <- Counts_GSE192446_gene %>% group_by(external_gene_name) %>%
  summarise (JAR_DMSO_rep1 = sum(JAR_DMSO_rep1),
             JAR_DMSO_rep2 = sum(JAR_DMSO_rep2),
             JAR_DMSO_rep3 = sum(JAR_DMSO_rep3),
             JAR_vorinostat_rep1 = sum(JAR_vorinostat_rep1),
             JAR_vorinostat_rep2 = sum(JAR_vorinostat_rep2),
             JAR_vorinostat_rep3 = sum(JAR_vorinostat_rep3),
             JEG3_DMSO_rep1 = sum(JEG3_DMSO_rep1),
             JEG3_DMSO_rep2 = sum(JEG3_DMSO_rep2),
             JEG3_DMSO_rep3 = sum(JEG3_DMSO_rep3),
             JEG3_vorinostat_rep1 = sum(JEG3_vorinostat_rep1),
             JEG3_vorinostat_rep2 = sum(JEG3_vorinostat_rep2),
             JEG3_vorinostat_rep3 = sum(JEG3_vorinostat_rep3))


