res_GSE165325_G2 <- results(dds_GSE165325, contrast=c("condition","G2_0h","Ctrl_0h")) # to specify the samples to contrast
res_GSE165325_G2

res_GSE165325_bort <- results(dds_GSE165325, contrast=c("condition","bort_3h","G2_0h"))
res_GSE165325_bort

res_GSE165325_mg132 <- results(dds_GSE165325, contrast=c("condition","mg132_3h","G2_0h"))
res_GSE165325_mg132




# Transform the row names of GSE165325_G2 into a column
res_GSE165325_G2_df <- data.frame(res_GSE165325_G2)
# Transform row names into a column
res_GSE165325_G2 <- tibble::rownames_to_column(res_GSE165325_G2_df, "ensembl_transcript_id")


# Join the expression change values with the Table_ANNOTATED containing MFE values
MFE_GSE165325_G2 <- dplyr::inner_join(Table_ANNOTATED, res_GSE165325_G2, by="ensembl_transcript_id") %>%
  dplyr::filter(padj < 0.05)


# Generate a scatter plot Log2_FC vs Normalized_MFE
library(ggplot2)
Plot_GSE165325_G2 <- ggplot(MFE_GSE165325_G2, aes(y=Normalized_MFE, x=log2FoldChange)) +
  geom_point(size=1.5, alpha=0.6)+
  theme_classic() +
  theme(legend.position="none") +
  geom_vline(xintercept = 0, size=0.3) +
  #xlim(-5,5) +
  theme(axis.title = element_text(size = 20)) +
  theme(plot.title = element_text(size = 15)) +
  labs(y="DGfold / nt (kcal/mol)",x="Log2_FC_expression",title="GSE165325_G2_Log2_FC_adj.P<0.05")
print(Plot_GSE165325_G2)



MFE_GSE165325_G2_UP <- dplyr::filter(MFE_GSE165325_G2, log2FoldChange > 0)
Mean_MFE_GSE165325_G2_UP <- mean(MFE_GSE165325_G2_UP$Normalized_MFE)

MFE_GSE165325_G2_DOWN <- dplyr::filter(MFE_GSE165325_G2, log2FoldChange < 0)
Mean_MFE_GSE165325_G2_DOWN <- mean(MFE_GSE165325_G2_DOWN$Normalized_MFE)

TTEST_MFE_GSE165325_G2_all_UP_vs_DOWN <- t.test(MFE_GSE165325_G2_DOWN$Normalized_MFE, MFE_GSE165325_G2_UP$Normalized_MFE, paired=FALSE)

# Add K-S test to look at the differences between the up-regukated and down-regulated genes
ks_test_GSE165325_G2_all_UP_vs_DOWN <- ks.test(MFE_GSE165325_G2_DOWN$Normalized_MFE, MFE_GSE165325_G2_UP$Normalized_MFE)


quantile_075_MFE_GSE165325_G2_UP <- quantile(MFE_GSE165325_G2_UP$Normalized_MFE, probs = c(0.75)) 
quantile_075_MFE_GSE165325_G2_DOWN <- quantile(MFE_GSE165325_G2_DOWN$Normalized_MFE, probs = c(0.75)) 
# Values above 0.75 quantile
ks_test_MFE_075_above <- ks.test(MFE_GSE165325_G2_UP$Normalized_MFE[MFE_GSE165325_G2_UP$Normalized_MFE >= quantile_075_MFE_GSE165325_G2_UP],
                                 MFE_GSE165325_G2_DOWN$Normalized_MFE[MFE_GSE165325_G2_DOWN$Normalized_MFE >= quantile_075_MFE_GSE165325_G2_DOWN])

# Look at the differences between the 0.25 quantile 
quantile_025_MFE_GSE165325_G2_UP <- quantile(MFE_GSE165325_G2_UP$Normalized_MFE, probs = c(0.25)) 
quantile_025_MFE_GSE165325_G2_DOWN <- quantile(MFE_GSE165325_G2_DOWN$Normalized_MFE, probs = c(0.25)) 
# Values below 0.25 quantile
ks_test_MFE_025_below <- ks.test(MFE_GSE165325_G2_UP$Normalized_MFE[MFE_GSE165325_G2_UP$Normalized_MFE <= quantile_025_MFE_GSE165325_G2_UP],
                                 MFE_GSE165325_G2_DOWN$Normalized_MFE[MFE_GSE165325_G2_DOWN$Normalized_MFE <= quantile_025_MFE_GSE165325_G2_DOWN])



# Permutation test MFE changes
# Combine the data into a single data frame with labels
upregulated <- data.frame(MFE = MFE_GSE165325_G2_UP$Normalized_MFE, Group = "Up")
downregulated <- data.frame(MFE = MFE_GSE165325_G2_DOWN$Normalized_MFE, Group = "Down")
combined_data <- bind_rows(upregulated, downregulated)

# Observed difference in means
GSE165325_G2_observed_diff <- mean(MFE_GSE165325_G2_UP$Normalized_MFE) - mean(MFE_GSE165325_G2_DOWN$Normalized_MFE)

# Number of permutations
n_permutations <- 10000

# Initialize a vector to store the permuted differences
GSE165325_G2_permuted_diffs <- numeric(n_permutations)

# Permutation test
set.seed(123)  # Set seed for reproducibility
for (i in 1:n_permutations) {
  # Permute the Group labels
  permuted_labels <- sample(combined_data$Group)
  
  # Calculate the mean MFE for each permuted group
  permuted_up_mean <- mean(combined_data$MFE[permuted_labels == "Up"])
  permuted_down_mean <- mean(combined_data$MFE[permuted_labels == "Down"])
  
  # Calculate the difference in means for the permuted groups
  GSE165325_G2_permuted_diffs[i] <- permuted_up_mean - permuted_down_mean
}

# Calculate the p-value
GSE165325_G2_p_value <- (sum(abs(GSE165325_G2_permuted_diffs) >= abs(GSE165325_G2_observed_diff)) + 1) / (n_permutations + 1)

# Output the results
cat("Observed difference in GSE165325_G2 means MFE_UP - MFE_DOWN:", GSE165325_G2_observed_diff, "\n")
cat("GSE165325_G2 P-value from permutation test:", GSE165325_G2_p_value, "\n")







