## GSE165325 High MFE TX fraction changes ####
# Determine whether within the differentially expressed genes there is a significant up-regulation of high MFE transcripts:
# Define high MFE transcripts by taking the 75th percentile of the combined MFE distributions of control and drug-treated samples.
# Count the number of transcripts in the significantly up- and down-regulated genes that have MFE values above this threshold.
# Perform a Fisher’s exact test to compare the proportions of high MFE transcripts between the two groups.

# Extract the normalized count data
# The minimal pre-filtering has already been done in the previous steps
GSE165325_norm_TX_counts <- counts(dds_GSE165325, normalized=TRUE) # This object is already a matrix
GSE165325_norm_TX_counts_df <- as.data.frame(GSE165325_norm_TX_counts)
# Convert row names to column
GSE165325_norm_TX_counts_df$ensembl_transcript_id <- rownames(GSE165325_norm_TX_counts_df)
# Remove row names
rownames(GSE165325_norm_TX_counts_df) <- NULL

# Move ensembl_transcript_id column to the first position
GSE165325_norm_TX_counts_df <- GSE165325_norm_TX_counts_df[, c("ensembl_transcript_id", setdiff(names(GSE165325_norm_TX_counts_df), "ensembl_transcript_id"))]

# Remove everything after the dot (including the dot itself) in the ensembl_transcript_id column
GSE165325_norm_TX_counts_df$ensembl_transcript_id <- sub("\\..*", "", GSE165325_norm_TX_counts_df$ensembl_transcript_id)

# Join the counts with the Table_ANNOTATED containing MFE values and heat capacity values
GSE165325_norm_TX_counts_MFE_df <- dplyr::inner_join(Table_ANNOTATED, GSE165325_norm_TX_counts_df, by="ensembl_transcript_id") %>%
  dplyr::select(ensembl_transcript_id_version, ensembl_transcript_id, ensembl_gene_id, external_gene_name, transcript_is_canonical, Transcript_length, 
                GSM5031593, GSM5031595, GSM5031596, GSM5031598, GSM5031599, GSM5031601, GSM5031602, GSM5031603, 
                GSM5031604, GSM5031605, GSM5031607, GSM5031608, GSM5031609, GSM5031610, GSM5031611, GSM5031612, 
                Normalized_MFE, Temperature, Specific_heat)





# GSE165325_G2
# Convert from wide to long format
GSE165325_G2_norm_TX_counts_MFE_df <- GSE165325_norm_TX_counts_MFE_df %>%
  dplyr::select(ensembl_transcript_id_version, ensembl_transcript_id, ensembl_gene_id, external_gene_name, transcript_is_canonical, Transcript_length, 
                GSM5031595, GSM5031599, GSM5031603, GSM5031610, GSM5031596, GSM5031601, GSM5031604, GSM5031607, Normalized_MFE, Temperature, Specific_heat) %>%
  dplyr::filter(ensembl_transcript_id %in% MFE_GSE165325_G2$ensembl_transcript_id)


# Identify the 75th percentile of the combined MFE distributions of control and drug-treated samples
quantile_075_GSE165325_G2_norm_TX_counts_MFE_df <- quantile(GSE165325_G2_norm_TX_counts_MFE_df$Normalized_MFE, probs = c(0.75))

# Select all the transcripts with Normalized_MFE values above the 75th percentile
GSE165325_G2_high_MFE_TX <- dplyr::filter(GSE165325_G2_norm_TX_counts_MFE_df, Normalized_MFE > quantile_075_GSE165325_G2_norm_TX_counts_MFE_df)

# Count the number of transcripts in the significantly up- and down-regulated pools that have MFE values above this threshold.
GSE165325_G2_high_MFE_TX_in_UP <- dplyr::filter(MFE_GSE165325_G2_UP, ensembl_transcript_id_version %in% GSE165325_G2_high_MFE_TX$ensembl_transcript_id_version)
GSE165325_G2_high_MFE_TX_in_DOWN <- dplyr::filter(MFE_GSE165325_G2_DOWN, ensembl_transcript_id_version %in% GSE165325_G2_high_MFE_TX$ensembl_transcript_id_version)


# Perform a Two-Proportion Z-test to compare the proportions of high MFE transcripts between the two groups (UP vs DOWN)

# Total number of transcripts in each group
GSE165325_G2_total_UP <- nrow(MFE_GSE165325_G2_UP)
GSE165325_G2_total_DOWN <- nrow(MFE_GSE165325_G2_DOWN)

# Count the number of high MFE transcripts in each group
GSE165325_G2_count_high_MFE_UP <- nrow(GSE165325_G2_high_MFE_TX_in_UP)
GSE165325_G2_count_high_MFE_DOWN <- nrow(GSE165325_G2_high_MFE_TX_in_DOWN)

# Proportions of high MFE transcripts in each group
GSE165325_G2_high_MFE_in_UP_fraction <- GSE165325_G2_count_high_MFE_UP / GSE165325_G2_total_UP
GSE165325_G2_high_MFE_in_DOWN_fraction <- GSE165325_G2_count_high_MFE_DOWN / GSE165325_G2_total_DOWN

# Pooled proportion
p_pool <- (GSE165325_G2_count_high_MFE_UP + GSE165325_G2_count_high_MFE_DOWN) / (GSE165325_G2_total_UP + GSE165325_G2_total_DOWN)

# Standard error of the difference of proportions
SE <- sqrt(p_pool * (1 - p_pool) * (1 / GSE165325_G2_total_UP + 1 / GSE165325_G2_total_DOWN))

# Z-value for the difference in proportions
z_value <- (GSE165325_G2_high_MFE_in_UP_fraction - GSE165325_G2_high_MFE_in_DOWN_fraction) / SE

# Two-tailed p-value from the Z-test
GSE165325_G2_z_test_MFE_p_value <- 2 * (1 - pnorm(abs(z_value)))  # Two-tailed test

# Output the results of the Z-test
cat("GSE165325_G2 Two-Proportion Z-test P-value for high MFE transcripts between UP and DOWN groups:", GSE165325_G2_z_test_MFE_p_value, "\n")

# Output the fractions and other statistics
cat("Fraction of high MFE TX in UP-regulated genes:", GSE165325_G2_high_MFE_in_UP_fraction, "\n")
cat("Fraction of high MFE TX in DOWN-regulated genes:", GSE165325_G2_high_MFE_in_DOWN_fraction, "\n")
cat("Mean of high MFE TX in UP-regulated genes:", mean(GSE165325_G2_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mean of high MFE TX in DOWN-regulated genes:", mean(GSE165325_G2_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")
cat("Mode of high MFE TX in UP-regulated genes:", calculate_mode(GSE165325_G2_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mode of high MFE TX in DOWN-regulated genes:", calculate_mode(GSE165325_G2_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")





