# Determine the impact of these changes in terms of fraction of total counts:
# Calculate the fraction of total counts of high MFE transcripts in control and drug-treated groups. 
# This is done by summing the counts of the high MFE transcripts and dividing by the total counts in each group.
# Fisher’s exact test to compare the proportions of high MFE transcripts counts between the two groups.

# Convert from wide to long format
GSE165325_G2_long_data <- GSE165325_G2_norm_TX_counts_MFE_df %>%
  pivot_longer(
    cols = starts_with("GSM"),      # Select all columns starting with "GSM"
    names_to = "replicate",         # Name of the new column for replicate identifiers
    values_to = "counts"            # Name of the new column for the counts
  )

# Add a condition column based on the replicate
GSE165325_G2_long_data <- GSE165325_G2_long_data %>%
  mutate(condition = ifelse(replicate %in% c("GSM5031595", "GSM5031599", "GSM5031603", "GSM5031610"), "Control", "G2"))

# Aggregate the replicates for each condition
GSE165325_G2_norm_TX_aggregated_data_avg_counts <- GSE165325_G2_long_data %>%
  group_by(ensembl_transcript_id_version, condition, Normalized_MFE, Specific_heat) %>%
  summarise(
    avg_counts = mean(counts),
    .groups = 'drop'
  )

# Fraction of total high MFE transcripts counts in control and drug-treated groups
GSE165325_G2_control_total_counts <- dplyr::filter(GSE165325_G2_norm_TX_aggregated_data_avg_counts, condition == "Control") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE165325_G2_control_high_MFE_TX_counts <- dplyr::filter(GSE165325_G2_norm_TX_aggregated_data_avg_counts, condition == "Control") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE165325_G2_high_MFE_TX$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE165325_G2_control_high_MFE_TX_counts_fraction <- GSE165325_G2_control_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE165325_G2_control_total_counts$total_counts
print(GSE165325_G2_control_high_MFE_TX_counts_fraction)

GSE165325_G2_G2_total_counts <- dplyr::filter(GSE165325_G2_norm_TX_aggregated_data_avg_counts, condition == "G2") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE165325_G2_G2_high_MFE_TX_counts <- dplyr::filter(GSE165325_G2_norm_TX_aggregated_data_avg_counts, condition == "G2") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE165325_G2_high_MFE_TX$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE165325_G2_G2_high_MFE_TX_counts_fraction <- GSE165325_G2_G2_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE165325_G2_G2_total_counts$total_counts
print(GSE165325_G2_G2_high_MFE_TX_counts_fraction)

# Perform a Two-Proportion Z-test to compare the proportions of high MFE transcripts counts between the two groups (Control vs G2)

# Total number of transcripts in each group
total_control <- GSE165325_G2_control_total_counts$total_counts
total_G2 <- GSE165325_G2_G2_total_counts$total_counts

# High MFE counts in each group
high_MFE_control <- GSE165325_G2_control_high_MFE_TX_counts$total_counts_high_MFE_TX
high_MFE_G2 <- GSE165325_G2_G2_high_MFE_TX_counts$total_counts_high_MFE_TX

# Proportions of high MFE counts in each group
p_control <- high_MFE_control / total_control
p_G2 <- high_MFE_G2 / total_G2

# Pooled proportion
p_pool <- (high_MFE_control + high_MFE_G2) / (total_control + total_G2)

# Standard error of the difference in proportions
SE <- sqrt(p_pool * (1 - p_pool) * (1 / total_control + 1 / total_G2))

# Z-value for the difference in proportions
z_value <- (p_control - p_G2) / SE

# Two-tailed p-value from the Z-test
GSE165325_G2_z_test_counts_75_p_value <- 2 * (1 - pnorm(abs(z_value)))  # Two-tailed test

# Output the results of the Z-test
cat("GSE165325_G2 Two-Proportion Z-test P-value for high MFE transcript counts between Control and G2 groups:", GSE165325_G2_z_test_counts_75_p_value, "\n")

# Output the results
cat("GSE165325_G2 control high MFE TX as fraction of total counts:", GSE165325_G2_control_high_MFE_TX_counts_fraction, "\n")
cat("GSE165325_G2 G2 high MFE TX as fraction of total counts:", GSE165325_G2_G2_high_MFE_TX_counts_fraction, "\n")
cat("GSE165325_G2 net change in high MFE TX counts from control to drug treatment:", GSE165325_G2_G2_high_MFE_TX_counts_fraction - GSE165325_G2_control_high_MFE_TX_counts_fraction, "\n")






