GSE165325_bort_bort_high_MFE_TX_counts <- dplyr::filter(GSE165325_bort_norm_TX_aggregated_data_avg_counts, condition == "bort") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE165325_bort_high_MFE_TX$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE165325_bort_bort_high_MFE_TX_counts_fraction <- GSE165325_bort_bort_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE165325_bort_bort_total_counts$total_counts

# Perform a Two-Proportion Z-test to compare the proportions of high MFE transcripts counts between the two groups (Control vs bort)

# Total number of transcripts in each group
total_control <- GSE165325_bort_control_total_counts$total_counts
total_bort <- GSE165325_bort_bort_total_counts$total_counts

# High MFE counts in each group
high_MFE_control <- GSE165325_bort_control_high_MFE_TX_counts$total_counts_high_MFE_TX
high_MFE_bort <- GSE165325_bort_bort_high_MFE_TX_counts$total_counts_high_MFE_TX

# Proportions of high MFE counts in each group
p_control <- high_MFE_control / total_control
p_bort <- high_MFE_bort / total_bort

# Pooled proportion
p_pool <- (high_MFE_control + high_MFE_bort) / (total_control + total_bort)

# Standard error of the difference in proportions
SE <- sqrt(p_pool * (1 - p_pool) * (1 / total_control + 1 / total_bort))

# Z-value for the difference in proportions
z_value <- (p_control - p_bort) / SE

# Two-tailed p-value from the Z-test
GSE165325_bort_z_test_counts_75_p_value <- 2 * (1 - pnorm(abs(z_value)))  # Two-tailed test

# Output the results of the Z-test
cat("GSE165325_bort Two-Proportion Z-test P-value for high MFE transcript counts between Control and bort groups:", GSE165325_bort_z_test_counts_75_p_value, "\n")

# Output the results
cat("GSE165325_bort control high MFE TX as fraction of total counts:", GSE165325_bort_control_high_MFE_TX_counts_fraction, "\n")
cat("GSE165325_bort bort high MFE TX as fraction of total counts:", GSE165325_bort_bort_high_MFE_TX_counts_fraction, "\n")
cat("GSE165325_bort net change in high MFE TX counts from control to drug treatment:", GSE165325_bort_bort_high_MFE_TX_counts_fraction - GSE165325_bort_control_high_MFE_TX_counts_fraction, "\n")





