# Access the Series Matrix
# Data_GSE137535 <- getGEO(GEO = "GSE137535")


# Load the object
Data_GSE137535 <- readRDS("path_to/GREIN_series_matrices_data/Data_GSE137535.rds")


# Extract the phenotypic/clinical data matrix from the series matrix
Expdata_GSE137535 <- Data_GSE137535[["GSE137535_series_matrix.txt.gz"]]@phenoData@data
colnames(Expdata_GSE137535)[colnames(Expdata_GSE137535) == "treatment:ch1"] <- "condition" # Rename the column to have an easier identifier for the conditions
Expdata_GSE137535$condition <- gsub('SH5-54', 'SH5_54', Expdata_GSE137535$condition) # Edit the name of the description in the conditions
# To edit the text in some of the rows
Expdata_GSE137535$condition <- as.character(Expdata_GSE137535$condition)
Expdata_GSE137535 <- Expdata_GSE137535 %>% mutate(condition = ifelse(condition =="DEX+SH4-54","DEX_SH4_54", condition ))
Expdata_GSE137535 <- Expdata_GSE137535 %>% dplyr::mutate(description = ifelse(description =="DEX_SH4-54_1","DEX_SH454_1", description )) %>%
  dplyr::mutate(description = ifelse(description =="DEX_SH4-54_2","DEX_SH454_2", description )) %>%
  dplyr::mutate(description = ifelse(description =="DEX_SH4-54_3","DEX_SH454_3", description )) %>%
  dplyr::mutate(description = ifelse(description =="SH4-54_1","SH4_54_1", description )) %>%
  dplyr::mutate(description = ifelse(description =="SH4-54_2","SH4_54_2", description )) %>%
  dplyr::mutate(description = ifelse(description =="SH4-54_3","SH4_54_3", description )) %>%
  dplyr::mutate(condition = ifelse(condition =="No Drug","No_Drug", condition))


# The order of the rows in Expdata_GSE165325 must be the same as the order of the columns in Counts_GSE165325
# target <- c("DEX_1", "DEX_2", "DEX_3", "DEX_SH454_1", "DEX_SH454_2", "DEX_SH454_3", "No_Drug_1", "No_Drug_2", "No_Drug_3", "SH4_54_1", "SH4_54_2", "SH4_54_3")
# Expdata_GSE137535 <-  Expdata_GSE137535[match(target, Expdata_GSE137535$description), ]


# Data are converted and organized to the format required
Counts_GSE137535_GREIN <- as.matrix(Counts_GSE137535_GREIN)
# rownames(Expdata_GSE137535) <- Expdata_GSE137535$description

# IMPORTANT:
# It is absolutely critical that the columns of the count matrix and the rows of the column data (information about samples) are in the same order.

# Replace the row names of Expdata_GSE137535 (sampleID) with the same sample name [title] of [Counts_GSE137535]. 
# This will help to match sample names in both matrices.
# The outcome should be TRUE
all(rownames(Expdata_GSE137535) %in% colnames(Counts_GSE137535_GREIN))
all(colnames(Counts_GSE137535_GREIN) %in% rownames(Expdata_GSE137535))

# Round counts down to the nearest integer
Counts_GSE137535_GREIN <- floor(Counts_GSE137535_GREIN)

# With the count matrix, Counts_GSE137535_GREIN, and the sample information, Expdata_GSE137535, we can construct a DESeqDataSet:
dds_GSE137535 <- DESeqDataSetFromMatrix(countData = Counts_GSE137535_GREIN,
                              colData = Expdata_GSE137535,
                              design = ~ condition)
dds_GSE137535

   

# DATA QUALITY ASSESSMENT
# Before performing differential expression analysis, we perform data quality assessment by sample clustering and visualization
library("pheatmap")
# We log transform the normalized counts
ntd <- normTransform(dds_GSE137535)
# Heatmap of the count matrix
select <- order(rowMeans(counts(dds_GSE137535,normalized=FALSE)),
                decreasing=TRUE)[1:20]
df <- as.data.frame(colData(dds_GSE137535)[,c("condition","type")])
pheatmap(assay(ntd)[select,], cluster_rows=FALSE, show_rownames=FALSE,
         cluster_cols=FALSE, annotation_col=df)



# Heatmap of the sample-to-sample distances
# A heatmap of this distance matrix gives us an overview over similarities and dissimilarities between samples
# Transform the values
vsd <- vst(dds_GSE137535, blind=FALSE)
# rld <- rlog(dds_GSE137535, blind=FALSE)
head(assay(vsd), 3)

# Apply the dist function to the transpose of the transformed count matrix to get sample-to-sample distances
sampleDists <- dist(t(assay(vsd)))

library("RColorBrewer")
sampleDistMatrix <- as.matrix(sampleDists)
rownames(sampleDistMatrix) <- paste(vsd$condition, vsd$type, sep="-")
colnames(sampleDistMatrix) <- NULL
colors <- colorRampPalette( rev(brewer.pal(9, "Blues")) )(255)
pheatmap(sampleDistMatrix,
         clustering_distance_rows=sampleDists,
         clustering_distance_cols=sampleDists,
         col=colors)

# Principal component plot of the samples
plotPCA(vsd, intgroup="condition")



# We perform a minimal pre-filtering to keep only rows that have at least 3 reads total
keep <- rowSums(counts(dds_GSE137535)) >= 3
dds_GSE137535 <- dds_GSE137535[keep,]


# To specify which level I want to compare against (e.g. which level represents the control group)
# dds_GSE137535$condition <- relevel(dds_GSE137535$condition, ref = "No_Drug")

# DIFFERENTIAL EXPRESSION ANALYSIS
dds_GSE137535 <- DESeq(dds_GSE137535)

res_GSE137535_DEX <- results(dds_GSE137535, contrast=c("condition","DEX","No_Drug")) # to specify the samples to contrast
res_GSE137535_DEX

res_GSE137535_DEX_SH454 <- results(dds_GSE137535, contrast=c("condition","DEX_SH4_54","No_Drug"))
res_GSE137535_DEX_SH454

res_GSE137535_SH454 <- results(dds_GSE137535, contrast=c("condition","SH5_54","No_Drug"))
res_GSE137535_SH454

# Export results to CSV files
# write.csv(as.data.frame(res_GSE137535_DEX), file="Treated_vs_Controls.csv")
# write.csv(as.data.frame(res_GSE137535_DEX_SH454), file="Treated_vs_Controls.csv")
# write.csv(as.data.frame(res_GSE137535_SH454), file="Treated_vs_Controls.csv")



# Transform the row names of GSE137535_DEX into a column
res_GSE137535_DEX_df <- data.frame(res_GSE137535_DEX)
res_GSE137535_DEX <- tibble::rownames_to_column(res_GSE137535_DEX_df, "ensembl_transcript_id")


# Join the expression change values with the Table_ANNOTATED containing MFE values
MFE_GSE137535_DEX <- dplyr::inner_join(Table_ANNOTATED, res_GSE137535_DEX, by="ensembl_transcript_id") %>%
  dplyr::filter(padj < 0.05) 


# Generate a scatter plot Log2_FC vs Normalized_MFE

Plot_GSE137535_DEX <- ggplot(MFE_GSE137535_DEX, aes(y=Normalized_MFE, x=log2FoldChange)) +
  geom_point(size=1.5, alpha=0.3)+
  theme_classic() +
  theme(legend.position="none") +
  geom_vline(xintercept = 0, size=0.3) +
  # xlim(-12, 12) +
  theme(axis.title = element_text(size = 20)) +
  theme(plot.title = element_text(size = 15)) +
  labs(y="DGfold / nt (kcal/mol)",x="Log2_FC_expression",title="GSE137535_DEX_Log2_FC_adj.P<0.05")
print(Plot_GSE137535_DEX)




# It is well known that ANNOTATED transcripts, in general have lower MFEs than the UNANNOTATED transcripts

MFE_GSE137535_DEX_UP <- dplyr::filter(MFE_GSE137535_DEX, log2FoldChange > 0)
Mean_MFE_GSE137535_DEX_UP <- mean(MFE_GSE137535_DEX_UP$Normalized_MFE)

MFE_GSE137535_DEX_DOWN <- dplyr::filter(MFE_GSE137535_DEX, log2FoldChange < 0)
Mean_MFE_GSE137535_DEX_DOWN <- mean(MFE_GSE137535_DEX_DOWN$Normalized_MFE)

TTEST_MFE_GSE137535_DEX_all_UP_vs_DOWN <- t.test(MFE_GSE137535_DEX_DOWN$Normalized_MFE, MFE_GSE137535_DEX_UP$Normalized_MFE, paired=FALSE)

# Add K-S test to look at the differences between the up-regukated and down-regulated genes
ks_test_GSE137535_DEX_all_UP_vs_DOWN <- ks.test(MFE_GSE137535_DEX_DOWN$Normalized_MFE, MFE_GSE137535_DEX_UP$Normalized_MFE)


quantile_075_MFE_GSE137535_DEX_UP <- quantile(MFE_GSE137535_DEX_UP$Normalized_MFE, probs = c(0.75)) 
quantile_075_MFE_GSE137535_DEX_DOWN <- quantile(MFE_GSE137535_DEX_DOWN$Normalized_MFE, probs = c(0.75)) 
# Values above 0.75 quantile
ks_test_MFE_075_above <- ks.test(MFE_GSE137535_DEX_UP$Normalized_MFE[MFE_GSE137535_DEX_UP$Normalized_MFE >= quantile_075_MFE_GSE137535_DEX_UP],
                                 MFE_GSE137535_DEX_DOWN$Normalized_MFE[MFE_GSE137535_DEX_DOWN$Normalized_MFE >= quantile_075_MFE_GSE137535_DEX_DOWN])

# Look at the differences between the 0.25 quantile 
quantile_025_MFE_GSE137535_DEX_UP <- quantile(MFE_GSE137535_DEX_UP$Normalized_MFE, probs = c(0.25)) 
quantile_025_MFE_GSE137535_DEX_DOWN <- quantile(MFE_GSE137535_DEX_DOWN$Normalized_MFE, probs = c(0.25)) 
# Values below 0.25 quantile
ks_test_MFE_025_below <- ks.test(MFE_GSE137535_DEX_UP$Normalized_MFE[MFE_GSE137535_DEX_UP$Normalized_MFE <= quantile_025_MFE_GSE137535_DEX_UP],
                                 MFE_GSE137535_DEX_DOWN$Normalized_MFE[MFE_GSE137535_DEX_DOWN$Normalized_MFE <= quantile_025_MFE_GSE137535_DEX_DOWN])





# Permutation test MFE changes
# Combine the data into a single data frame with labels
upregulated <- data.frame(MFE = MFE_GSE137535_DEX_UP$Normalized_MFE, Group = "Up")
downregulated <- data.frame(MFE = MFE_GSE137535_DEX_DOWN$Normalized_MFE, Group = "Down")
combined_data <- bind_rows(upregulated, downregulated)

# Observed difference in means
GSE137535_DEX_observed_diff <- mean(MFE_GSE137535_DEX_UP$Normalized_MFE) - mean(MFE_GSE137535_DEX_DOWN$Normalized_MFE)

# Number of permutations
n_permutations <- 10000

# Initialize a vector to store the permuted differences
GSE137535_DEX_permuted_diffs <- numeric(n_permutations)

# Permutation test
set.seed(123)  # Set seed for reproducibility
for (i in 1:n_permutations) {
  # Permute the Group labels
  permuted_labels <- sample(combined_data$Group)
  
  # Calculate the mean MFE for each permuted group
  permuted_up_mean <- mean(combined_data$MFE[permuted_labels == "Up"])
  permuted_down_mean <- mean(combined_data$MFE[permuted_labels == "Down"])
  
  # Calculate the difference in means for the permuted groups
  GSE137535_DEX_permuted_diffs[i] <- permuted_up_mean - permuted_down_mean
}

# Calculate the p-value
GSE137535_DEX_p_value <- (sum(abs(GSE137535_DEX_permuted_diffs) >= abs(GSE137535_DEX_observed_diff)) + 1) / (n_permutations + 1)

# Output the results
cat("Observed difference in GSE137535_DEX means MFE_UP - MFE_DOWN:", GSE137535_DEX_observed_diff, "\n")
cat("GSE137535_DEX P-value from permutation test:", GSE137535_DEX_p_value, "\n")










