combined_data <- bind_rows(upregulated, downregulated)

# Observed difference in means
GSE137535_SH454_observed_diff <- mean(MFE_GSE137535_SH454_UP$Normalized_MFE) - mean(MFE_GSE137535_SH454_DOWN$Normalized_MFE)

# Number of permutations
n_permutations <- 10000

# Initialize a vector to store the permuted differences
GSE137535_SH454_permuted_diffs <- numeric(n_permutations)

# Permutation test
set.seed(123)  # Set seed for reproducibility
for (i in 1:n_permutations) {
  # Permute the Group labels
  permuted_labels <- sample(combined_data$Group)
  
  # Calculate the mean MFE for each permuted group
  permuted_up_mean <- mean(combined_data$MFE[permuted_labels == "Up"])
  permuted_down_mean <- mean(combined_data$MFE[permuted_labels == "Down"])
  
  # Calculate the difference in means for the permuted groups
  GSE137535_SH454_permuted_diffs[i] <- permuted_up_mean - permuted_down_mean
}

# Calculate the p-value
GSE137535_SH454_p_value <- (sum(abs(GSE137535_SH454_permuted_diffs) >= abs(GSE137535_SH454_observed_diff)) + 1) / (n_permutations + 1)

# Output the results
cat("Observed difference in GSE137535_SH454 means MFE_UP - MFE_DOWN:", GSE137535_SH454_observed_diff, "\n")
cat("GSE137535_SH454 P-value from permutation test:", GSE137535_SH454_p_value, "\n")
















## GSE137535 High MFE TX fraction changes ####
# Determine whether within the differentially expressed genes there is a significant up-regulation of high MFE transcripts:
# Define high MFE transcripts by taking the 75th percentile of the combined MFE distributions of control and drug-treated samples.
# Count the number of transcripts in the significantly up- and down-regulated genes that have MFE values above this threshold.
# Perform a Fisher’s exact test to compare the proportions of high MFE transcripts between the two groups.


# Extract the normalized count data
# The minimal pre-filtering has already been done in the previous steps
GSE137535_norm_TX_counts <- counts(dds_GSE137535, normalized=TRUE) # This object is already a matrix
GSE137535_norm_TX_counts_df <- as.data.frame(GSE137535_norm_TX_counts)
# Convert row names to column
GSE137535_norm_TX_counts_df$ensembl_transcript_id <- rownames(GSE137535_norm_TX_counts_df)
# Remove row names
rownames(GSE137535_norm_TX_counts_df) <- NULL

# Move ensembl_transcript_id column to the first position
GSE137535_norm_TX_counts_df <- GSE137535_norm_TX_counts_df[, c("ensembl_transcript_id", setdiff(names(GSE137535_norm_TX_counts_df), "ensembl_transcript_id"))]

# Remove everything after the dot (including the dot itself) in the ensembl_transcript_id column
GSE137535_norm_TX_counts_df$ensembl_transcript_id <- sub("\\..*", "", GSE137535_norm_TX_counts_df$ensembl_transcript_id)

# Join the counts with the Table_ANNOTATED containing MFE values and heat capacity values
GSE137535_norm_TX_counts_MFE_df <- dplyr::inner_join(Table_ANNOTATED, GSE137535_norm_TX_counts_df, by="ensembl_transcript_id") %>%
  dplyr::select(ensembl_transcript_id_version, ensembl_transcript_id, ensembl_gene_id, external_gene_name, transcript_is_canonical, Transcript_length, 
                GSM4081442, GSM4081443, GSM4081444, GSM4081445, GSM4081446, GSM4081447, GSM4081448, GSM4081449, GSM4081450, GSM4081451, GSM4081452, GSM4081453, Normalized_MFE, Temperature, Specific_heat)






# GSE137535_DEX
# Convert from wide to long format
GSE137535_DEX_norm_TX_counts_MFE_df <- GSE137535_norm_TX_counts_MFE_df %>%
  dplyr::select(ensembl_transcript_id_version, ensembl_transcript_id, ensembl_gene_id, external_gene_name, transcript_is_canonical, Transcript_length, 
                GSM4081451, GSM4081452, GSM4081453, GSM4081445, GSM4081446, GSM4081447, Normalized_MFE, Temperature, Specific_heat) %>%
  dplyr::filter(ensembl_transcript_id %in% MFE_GSE137535_DEX$ensembl_transcript_id) 

# Identify the 75th percentile of the combined MFE distributions of control and drug-treated samples
quantile_075_GSE137535_DEX_norm_TX_counts_MFE_df <- quantile(GSE137535_DEX_norm_TX_counts_MFE_df$Normalized_MFE, probs = c(0.75))

# Select all the transcripts with Normalized_MFE values above the 75th percentile
GSE137535_DEX_high_MFE_TX <- dplyr::filter(GSE137535_DEX_norm_TX_counts_MFE_df, Normalized_MFE > quantile_075_GSE137535_DEX_norm_TX_counts_MFE_df)

# Count the number of transcripts in the significantly up- and down-regulated pools that have MFE values above this threshold.
GSE137535_DEX_high_MFE_TX_in_UP <- dplyr::filter(MFE_GSE137535_DEX_UP, ensembl_transcript_id_version %in% GSE137535_DEX_high_MFE_TX$ensembl_transcript_id_version)
GSE137535_DEX_high_MFE_TX_in_DOWN <- dplyr::filter(MFE_GSE137535_DEX_DOWN, ensembl_transcript_id_version %in% GSE137535_DEX_high_MFE_TX$ensembl_transcript_id_version)

# Count total number of transcripts in each group (UP and DOWN)
GSE137535_DEX_total_UP <- nrow(MFE_GSE137535_DEX_UP)
GSE137535_DEX_total_DOWN <- nrow(MFE_GSE137535_DEX_DOWN)

# Count high MFE transcripts in UP and DOWN groups
GSE137535_DEX_count_high_MFE_UP <- nrow(GSE137535_DEX_high_MFE_TX_in_UP)
GSE137535_DEX_count_high_MFE_DOWN <- nrow(GSE137535_DEX_high_MFE_TX_in_DOWN)

# Proportions of high MFE counts in each group
p_UP <- GSE137535_DEX_count_high_MFE_UP / GSE137535_DEX_total_UP
p_DOWN <- GSE137535_DEX_count_high_MFE_DOWN / GSE137535_DEX_total_DOWN

# Pooled proportion
p_pool <- (GSE137535_DEX_count_high_MFE_UP + GSE137535_DEX_count_high_MFE_DOWN) / (GSE137535_DEX_total_UP + GSE137535_DEX_total_DOWN)

# Standard error of the difference in proportions
SE <- sqrt(p_pool * (1 - p_pool) * (1 / GSE137535_DEX_total_UP + 1 / GSE137535_DEX_total_DOWN))

# Z-value for the difference in proportions
z_value <- (p_UP - p_DOWN) / SE

# Two-tailed p-value from the Z-test
GSE137535_DEX_z_test_MFE_p_value <- 2 * (1 - pnorm(abs(z_value)))  # Two-tailed test

# Output the results of the Z-test
cat("GSE137535_DEX Two-Proportion Z-test P-value for high MFE transcript counts between UP-regulated and DOWN-regulated genes:", GSE137535_DEX_z_test_MFE_p_value, "\n")

# Look at the fractions
GSE137535_DEX_high_MFE_in_UP_fraction <- GSE137535_DEX_count_high_MFE_UP / GSE137535_DEX_total_UP
GSE137535_DEX_high_MFE_in_DOWN_fraction <- GSE137535_DEX_count_high_MFE_DOWN / GSE137535_DEX_total_DOWN

# Output the results
cat("Fraction of GSE137535_DEX high MFE TX in UP-regulated genes:", GSE137535_DEX_high_MFE_in_UP_fraction, "\n")
cat("Fraction of GSE137535_DEX high MFE TX in DOWN-regulated genes:", GSE137535_DEX_high_MFE_in_DOWN_fraction, "\n")
cat("Mean of GSE137535_DEX high MFE TX in UP-regulated genes:", mean(GSE137535_DEX_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mean of GSE137535_DEX high MFE TX in DOWN-regulated genes:", mean(GSE137535_DEX_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")
cat("Mode of GSE137535_DEX high MFE TX in UP-regulated genes:", calculate_mode(GSE137535_DEX_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mode of GSE137535_DEX high MFE TX in DOWN-regulated genes:", calculate_mode(GSE137535_DEX_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")





# Show data as violin plot
# Add a new column to indicate if the value is above the 75th percentile
MFE_GSE137535_DEX$above_quantile_075 <- MFE_GSE137535_DEX$Normalized_MFE > quantile_075_GSE137535_DEX_norm_TX_counts_MFE_df

# Generate violin plot with conditional jitter coloring
ggplot(MFE_GSE137535_DEX, aes(x = factor(log2FoldChange > 0), y = Normalized_MFE)) +
  geom_violin(fill = "white") +
  geom_jitter(aes(color = above_quantile_075), width = 0.1, size = 1, alpha = 0.8) +
  scale_color_manual(values = c("FALSE" = "black", "TRUE" = "blue")) +
  theme_classic() +
  theme(
    legend.position = "none", 
    axis.title = element_text(size = 20), 
    plot.title = element_text(size = 10),
    axis.text.x = element_text(size = 16, color = "black")
  ) +
  geom_vline(xintercept = 0, linewidth = 0.3) +
  labs(
    y = "Normalized_MFE", 
    x = NULL, 
    title = "GSE137535_DEX_Log2_FC_adj.P<0.05"
  ) +
  scale_x_discrete(labels = c("log2FoldChange < 0", "log2FoldChange > 0"))












