# Determine the impact of these changes in terms of fraction of total counts:
# Calculate the fraction of total counts of high MFE transcripts in control and drug-treated groups. 
# This is done by summing the counts of the high MFE transcripts and dividing by the total counts in each group.

# GSE137535_DEX
# Convert from wide to long format
GSE137535_DEX_long_data <- GSE137535_DEX_norm_TX_counts_MFE_df %>%
  pivot_longer(
    cols = starts_with("GSM"),      # Select all columns starting with "GSM"
    names_to = "replicate",         # Name of the new column for replicate identifiers
    values_to = "counts"            # Name of the new column for the counts
  )

# Add a condition column based on the replicate
GSE137535_DEX_long_data <- GSE137535_DEX_long_data %>%
  mutate(condition = ifelse(replicate %in% c("GSM4081451", "GSM4081452", "GSM4081453"), "Control", "DEX"))

# Aggregate the replicates for each condition
GSE137535_DEX_norm_TX_aggregated_data_avg_counts <- GSE137535_DEX_long_data %>%
  group_by(ensembl_transcript_id_version, condition, Normalized_MFE, Specific_heat) %>%
  summarise(
    avg_counts = mean(counts),
    .groups = 'drop'
  )

# Fraction of total high MFE transcripts counts in control and drug-treated groups
GSE137535_DEX_control_total_counts <- dplyr::filter(GSE137535_DEX_norm_TX_aggregated_data_avg_counts, condition == "Control") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE137535_DEX_control_high_MFE_TX_counts <- dplyr::filter(GSE137535_DEX_norm_TX_aggregated_data_avg_counts, condition == "Control") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE137535_DEX_high_MFE_TX$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE137535_DEX_control_high_MFE_TX_counts_fraction <- GSE137535_DEX_control_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE137535_DEX_control_total_counts$total_counts

GSE137535_DEX_DEX_total_counts <- dplyr::filter(GSE137535_DEX_norm_TX_aggregated_data_avg_counts, condition == "DEX") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE137535_DEX_DEX_high_MFE_TX_counts <- dplyr::filter(GSE137535_DEX_norm_TX_aggregated_data_avg_counts, condition == "DEX") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE137535_DEX_high_MFE_TX$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE137535_DEX_DEX_high_MFE_TX_counts_fraction <- GSE137535_DEX_DEX_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE137535_DEX_DEX_total_counts$total_counts

# Proportions of high MFE counts in each group
p_control <- GSE137535_DEX_control_high_MFE_TX_counts_fraction
p_Dex <- GSE137535_DEX_DEX_high_MFE_TX_counts_fraction

# Pooled proportion
p_pool <- (GSE137535_DEX_control_high_MFE_TX_counts$total_counts_high_MFE_TX + GSE137535_DEX_DEX_high_MFE_TX_counts$total_counts_high_MFE_TX) / 
  (GSE137535_DEX_control_total_counts$total_counts + GSE137535_DEX_DEX_total_counts$total_counts)

# Standard error of the difference in proportions
SE <- sqrt(p_pool * (1 - p_pool) * (1 / GSE137535_DEX_control_total_counts$total_counts + 1 / GSE137535_DEX_DEX_total_counts$total_counts))

# Z-value for the difference in proportions
z_value <- (p_control - p_Dex) / SE

# Two-tailed p-value from the Z-test
GSE137535_DEX_z_test_counts_75_p_value <- 2 * (1 - pnorm(abs(z_value)))  # Two-tailed test

# Output the results of the Z-test
cat("GSE137535_DEX Two-Proportion Z-test P-value for high MFE transcript counts between Control and DEX groups:", GSE137535_DEX_z_test_counts_75_p_value, "\n")

# Output the results for fractions and net change
cat("GSE137535_DEX control high MFE TX as fraction of total counts:", GSE137535_DEX_control_high_MFE_TX_counts_fraction, "\n")
cat("GSE137535_DEX DEX high MFE TX as fraction of total counts:", GSE137535_DEX_DEX_high_MFE_TX_counts_fraction, "\n")
cat("GSE137535_DEX net change counts high MFE TX drug vs control:", GSE137535_DEX_DEX_high_MFE_TX_counts_fraction - GSE137535_DEX_control_high_MFE_TX_counts_fraction, "\n")




