GSE137535_SH454_control_high_MFE_TX_counts_fraction <- GSE137535_SH454_control_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE137535_SH454_control_total_counts$total_counts

GSE137535_SH454_total_counts <- dplyr::filter(GSE137535_SH454_norm_TX_aggregated_data_avg_counts, condition == "SH454") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE137535_SH454_high_MFE_TX_counts <- dplyr::filter(GSE137535_SH454_norm_TX_aggregated_data_avg_counts, condition == "SH454") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE137535_SH454_high_MFE_TX$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE137535_SH454_high_MFE_TX_counts_fraction <- GSE137535_SH454_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE137535_SH454_total_counts$total_counts

# Proportions of high MFE counts in each group
p_control <- GSE137535_SH454_control_high_MFE_TX_counts_fraction
p_SH454 <- GSE137535_SH454_high_MFE_TX_counts_fraction

# Pooled proportion
p_pool <- (GSE137535_SH454_control_high_MFE_TX_counts$total_counts_high_MFE_TX + GSE137535_SH454_high_MFE_TX_counts$total_counts_high_MFE_TX) / 
  (GSE137535_SH454_control_total_counts$total_counts + GSE137535_SH454_total_counts$total_counts)

# Standard error of the difference in proportions
SE <- sqrt(p_pool * (1 - p_pool) * (1 / GSE137535_SH454_control_total_counts$total_counts + 1 / GSE137535_SH454_total_counts$total_counts))

# Z-value for the difference in proportions
z_value <- (p_control - p_SH454) / SE

# Two-tailed p-value from the Z-test
GSE137535_SH454_z_test_counts_75_p_value <- 2 * (1 - pnorm(abs(z_value)))  # Two-tailed test

# Output the results of the Z-test
cat("GSE137535_SH454 Two-Proportion Z-test P-value for high MFE transcript counts between Control and SH454 groups:", GSE137535_SH454_z_test_counts_75_p_value, "\n")

# Output the results for fractions and net change
cat("GSE137535_SH454 control high MFE TX as fraction of total counts:", GSE137535_SH454_control_high_MFE_TX_counts_fraction, "\n")
cat("GSE137535_SH454 SH454 high MFE TX as fraction of total counts:", GSE137535_SH454_high_MFE_TX_counts_fraction, "\n")
cat("GSE137535_SH454 net change counts high MFE TX drug vs control:", GSE137535_SH454_high_MFE_TX_counts_fraction - GSE137535_SH454_control_high_MFE_TX_counts_fraction, "\n")




