## GSE100327 net MFE and heat capacity ####
# Determine whether within the differentially expressed genes there is a significant up-regulation of high MFE transcripts:
# Define high MFE transcripts by taking the 75th percentile of the combined MFE distributions of control and drug-treated samples.
# Count the number of transcripts in the significantly up- and down-regulated genes that have MFE values above this threshold.
# Perform a Fisher’s exact test to compare the proportions of high MFE transcripts between the two groups.



# Extract the normalized count data
# The minimal pre-filtering has already been done in the previous steps
GSE100327_norm_TX_counts <- counts(dds_GSE100327, normalized=TRUE) # This object is already a matrix
GSE100327_norm_TX_counts_df <- as.data.frame(GSE100327_norm_TX_counts)
# Convert row names to column
GSE100327_norm_TX_counts_df$ensembl_transcript_id <- rownames(GSE100327_norm_TX_counts_df)
# Remove row names
rownames(GSE100327_norm_TX_counts_df) <- NULL

# Move ensembl_transcript_id column to the first position
GSE100327_norm_TX_counts_df <- GSE100327_norm_TX_counts_df[, c("ensembl_transcript_id", setdiff(names(GSE100327_norm_TX_counts_df), "ensembl_transcript_id"))]

# Remove everything after the dot (including the dot itself) in the ensembl_transcript_id column
GSE100327_norm_TX_counts_df$ensembl_transcript_id <- sub("\\..*", "", GSE100327_norm_TX_counts_df$ensembl_transcript_id)

# Join the counts with the Table_ANNOTATED containing MFE values and heat capacity values
GSE100327_norm_TX_counts_MFE_df <- dplyr::inner_join(Table_ANNOTATED, GSE100327_norm_TX_counts_df, by="ensembl_transcript_id") %>%
  dplyr::select(ensembl_transcript_id_version, ensembl_transcript_id, ensembl_gene_id, external_gene_name, transcript_is_canonical, Transcript_length, GSM2677861, GSM2677862, GSM2677863, GSM2677864, GSM2677865, GSM2677866, GSM2677867, GSM2677868, GSM2677869, GSM2677870, GSM2677871,
                GSM2677872, GSM2677873, GSM2677874, GSM2677875, GSM2677876, GSM2677877, GSM2677878, GSM2677879, GSM2677880, GSM2677881, GSM2677882, GSM2677883, GSM2677884, GSM2677885, GSM2677886, GSM2677887, GSM2677888,
                GSM2677889, GSM2677890, Normalized_MFE, Temperature, Specific_heat)






# GSE100327_BxPC
GSE100327_BxPC_norm_TX_counts_MFE_df <- GSE100327_norm_TX_counts_MFE_df %>%
  dplyr::select(ensembl_transcript_id_version, ensembl_transcript_id, ensembl_gene_id, external_gene_name, transcript_is_canonical, Transcript_length, 
                GSM2677861, GSM2677862, GSM2677863, GSM2677864, GSM2677865, GSM2677866, Normalized_MFE, Temperature, Specific_heat) %>%
  dplyr::filter(ensembl_transcript_id %in% MFE_GSE100327_BxPC$ensembl_transcript_id)

# Identify the 75th percentile of the combined MFE distributions of control and drug-treated samples
