GSE100327_779e_high_MFE_TX_in_UP <- dplyr::filter(MFE_GSE100327_779e_UP, ensembl_transcript_id_version %in% GSE100327_779e_high_MFE_TX$ensembl_transcript_id_version)
GSE100327_779e_high_MFE_TX_in_DOWN <- dplyr::filter(MFE_GSE100327_779e_DOWN, ensembl_transcript_id_version %in% GSE100327_779e_high_MFE_TX$ensembl_transcript_id_version)

# Perform a Two-Proportion Z-Test to compare the proportions of high MFE transcripts between the two groups (UP-regulated vs DOWN-regulated)
GSE100327_779e_total_UP <- nrow(MFE_GSE100327_779e_UP)
GSE100327_779e_total_DOWN <- nrow(MFE_GSE100327_779e_DOWN)
GSE100327_779e_count_high_MFE_UP <- nrow(GSE100327_779e_high_MFE_TX_in_UP)
GSE100327_779e_count_high_MFE_DOWN <- nrow(GSE100327_779e_high_MFE_TX_in_DOWN)

# Proportions of high MFE counts in each group
p_UP <- GSE100327_779e_count_high_MFE_UP / GSE100327_779e_total_UP
p_DOWN <- GSE100327_779e_count_high_MFE_DOWN / GSE100327_779e_total_DOWN

# Pooled proportion
p_pool <- (GSE100327_779e_count_high_MFE_UP + GSE100327_779e_count_high_MFE_DOWN) / 
  (GSE100327_779e_total_UP + GSE100327_779e_total_DOWN)

# Standard error of the difference in proportions
SE <- sqrt(p_pool * (1 - p_pool) * (1 / GSE100327_779e_total_UP + 1 / GSE100327_779e_total_DOWN))

# Z-value for the difference in proportions
z_value <- (p_UP - p_DOWN) / SE

# Two-tailed p-value from the Z-test
GSE100327_779e_z_test_MFE_p_value <- 2 * (1 - pnorm(abs(z_value)))  # Two-tailed test

# Output the results of the Z-test
cat("GSE100327_779e Two-Proportion Z-test P-value for high MFE transcript counts between UP-regulated and DOWN-regulated genes:", GSE100327_779e_z_test_MFE_p_value, "\n")

# Look at the fractions
GSE100327_779e_high_MFE_in_UP_fraction <- GSE100327_779e_count_high_MFE_UP / GSE100327_779e_total_UP
GSE100327_779e_high_MFE_in_DOWN_fraction <- GSE100327_779e_count_high_MFE_DOWN / GSE100327_779e_total_DOWN

# Output the results
cat("Fraction of GSE100327_779e high MFE TX in UP-regulated genes:", GSE100327_779e_high_MFE_in_UP_fraction, "\n")
cat("Fraction of GSE100327_779e high MFE TX in DOWN-regulated genes:", GSE100327_779e_high_MFE_in_DOWN_fraction, "\n")
cat("Mean of GSE100327_779e high MFE TX in UP-regulated genes:", mean(GSE100327_779e_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mean of GSE100327_779e high MFE TX in DOWN-regulated genes:", mean(GSE100327_779e_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")
cat("Mode of GSE100327_779e high MFE TX in UP-regulated genes:", calculate_mode(GSE100327_779e_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mode of GSE100327_779e high MFE TX in DOWN-regulated genes:", calculate_mode(GSE100327_779e_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")



