# Determine the impact of these changes in terms of fraction of total counts:
# Calculate the fraction of total counts of high MFE transcripts in control and drug-treated groups. 
# This is done by summing the counts of the high MFE transcripts and dividing by the total counts in each group.
# Fisher’s exact test to compare the proportions of high MFE transcripts counts between the two groups.


# Convert from wide to long format
GSE100327_BxPC_long_data <- GSE100327_BxPC_norm_TX_counts_MFE_df %>%
  pivot_longer(
    cols = starts_with("GSM"),      # Select all columns starting with "GSM"
    names_to = "replicate",         # Name of the new column for replicate identifiers
    values_to = "counts"            # Name of the new column for the counts
  )

# Add a condition column based on the replicate
GSE100327_BxPC_long_data <- GSE100327_BxPC_long_data %>%
  mutate(condition = ifelse(replicate %in% c("GSM2677861", "GSM2677862", "GSM2677863"), "Control", "BxPC"))

# Aggregate the replicates for each condition
GSE100327_BxPC_norm_TX_aggregated_data_avg_counts <- GSE100327_BxPC_long_data %>%
  group_by(ensembl_transcript_id_version, condition, Normalized_MFE, Specific_heat) %>%
  summarise(
    avg_counts = mean(counts),
    .groups = 'drop'
  )

# Fraction of total high MFE transcripts counts in control and drug-treated groups
GSE100327_BxPC_control_total_counts <- dplyr::filter(GSE100327_BxPC_norm_TX_aggregated_data_avg_counts, condition == "Control") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE100327_BxPC_control_high_MFE_TX_counts <- dplyr::filter(GSE100327_BxPC_norm_TX_aggregated_data_avg_counts, condition == "Control") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE100327_BxPC_high_MFE_TX$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE100327_BxPC_control_high_MFE_TX_counts_fraction <- GSE100327_BxPC_control_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE100327_BxPC_control_total_counts$total_counts

GSE100327_BxPC_BxPC_total_counts <- dplyr::filter(GSE100327_BxPC_norm_TX_aggregated_data_avg_counts, condition == "BxPC") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE100327_BxPC_BxPC_high_MFE_TX_counts <- dplyr::filter(GSE100327_BxPC_norm_TX_aggregated_data_avg_counts, condition == "BxPC") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE100327_BxPC_high_MFE_TX$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE100327_BxPC_BxPC_high_MFE_TX_counts_fraction <- GSE100327_BxPC_BxPC_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE100327_BxPC_BxPC_total_counts$total_counts

# Two-Proportion Z-Test to compare the proportions of high MFE transcripts counts between the two groups
# Calculate proportions for Control and BxPC groups
p_control <- GSE100327_BxPC_control_high_MFE_TX_counts_fraction
p_BxPC <- GSE100327_BxPC_BxPC_high_MFE_TX_counts_fraction

# Pooled proportion
p_pool <- (GSE100327_BxPC_control_high_MFE_TX_counts$total_counts_high_MFE_TX + GSE100327_BxPC_BxPC_high_MFE_TX_counts$total_counts_high_MFE_TX) / 
  (GSE100327_BxPC_control_total_counts$total_counts + GSE100327_BxPC_BxPC_total_counts$total_counts)

# Standard error of the difference in proportions
SE <- sqrt(p_pool * (1 - p_pool) * (1 / GSE100327_BxPC_control_total_counts$total_counts + 1 / GSE100327_BxPC_BxPC_total_counts$total_counts))

# Z-value for the difference in proportions
z_value <- (p_control - p_BxPC) / SE

# Two-tailed p-value from the Z-test
GSE100327_BxPC_z_test_counts_75_p_value <- 2 * (1 - pnorm(abs(z_value)))  # Two-tailed test

# Output the results of the Z-test
cat("GSE100327_BxPC Two-Proportion Z-test P-value for high MFE transcript counts between Control and BxPC:", GSE100327_BxPC_z_test_counts_75_p_value, "\n")

# Output the results
cat("GSE100327_BxPC control high MFE TX as fraction of total counts:", GSE100327_BxPC_control_high_MFE_TX_counts_fraction, "\n")
cat("GSE100327_BxPC BxPC high MFE TX as fraction of total counts:", GSE100327_BxPC_BxPC_high_MFE_TX_counts_fraction, "\n")
cat("GSE100327_BxPC net change counts high MFE TX drug vs control:", GSE100327_BxPC_BxPC_high_MFE_TX_counts_fraction - GSE100327_BxPC_control_high_MFE_TX_counts_fraction, "\n")





