# GSE100327_779e
# Convert from wide to long format
GSE100327_779e_long_data <- GSE100327_779e_norm_TX_counts_MFE_df %>%
  pivot_longer(
    cols = starts_with("GSM"),      # Select all columns starting with "GSM"
    names_to = "replicate",         # Name of the new column for replicate identifiers
    values_to = "counts"            # Name of the new column for the counts
  )

# Add a condition column based on the replicate
GSE100327_779e_long_data <- GSE100327_779e_long_data %>%
  mutate(condition = ifelse(replicate %in% c("GSM2677885", "GSM2677886", "GSM2677887"), "Control", "779e"))

# Aggregate the replicates for each condition
GSE100327_779e_norm_TX_aggregated_data_avg_counts <- GSE100327_779e_long_data %>%
  group_by(ensembl_transcript_id_version, condition, Normalized_MFE, Specific_heat) %>%
  summarise(
    avg_counts = mean(counts),
    .groups = 'drop'
  )

# Fraction of total high MFE transcripts counts in control and drug-treated groups
GSE100327_779e_control_total_counts <- dplyr::filter(GSE100327_779e_norm_TX_aggregated_data_avg_counts, condition == "Control") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE100327_779e_control_high_MFE_TX_counts <- dplyr::filter(GSE100327_779e_norm_TX_aggregated_data_avg_counts, condition == "Control") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE100327_779e_high_MFE_TX$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE100327_779e_control_high_MFE_TX_counts_fraction <- GSE100327_779e_control_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE100327_779e_control_total_counts$total_counts

GSE100327_779e_779e_total_counts <- dplyr::filter(GSE100327_779e_norm_TX_aggregated_data_avg_counts, condition == "779e") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE100327_779e_779e_high_MFE_TX_counts <- dplyr::filter(GSE100327_779e_norm_TX_aggregated_data_avg_counts, condition == "779e") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE100327_779e_high_MFE_TX$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE100327_779e_779e_high_MFE_TX_counts_fraction <- GSE100327_779e_779e_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE100327_779e_779e_total_counts$total_counts

# Two-Proportion Z-Test to compare the proportions of high MFE transcripts counts between the two groups
# Calculate proportions for Control and 779e groups
p_control <- GSE100327_779e_control_high_MFE_TX_counts_fraction
p_779e <- GSE100327_779e_779e_high_MFE_TX_counts_fraction

# Pooled proportion
p_pool <- (GSE100327_779e_control_high_MFE_TX_counts$total_counts_high_MFE_TX + GSE100327_779e_779e_high_MFE_TX_counts$total_counts_high_MFE_TX) / 
  (GSE100327_779e_control_total_counts$total_counts + GSE100327_779e_779e_total_counts$total_counts)

# Standard error of the difference in proportions
SE <- sqrt(p_pool * (1 - p_pool) * (1 / GSE100327_779e_control_total_counts$total_counts + 1 / GSE100327_779e_779e_total_counts$total_counts))

# Z-value for the difference in proportions
z_value <- (p_control - p_779e) / SE

# Two-tailed p-value from the Z-test
GSE100327_779e_z_test_counts_75_p_value <- 2 * (1 - pnorm(abs(z_value)))  # Two-tailed test

# Output the results of the Z-test
cat("GSE100327_779e Two-Proportion Z-test P-value for high MFE transcript counts between Control and 779e:", GSE100327_779e_z_test_counts_75_p_value, "\n")

# Output the results
cat("GSE100327_779e control high MFE TX as fraction of total counts:", GSE100327_779e_control_high_MFE_TX_counts_fraction, "\n")
cat("GSE100327_779e 779e high MFE TX as fraction of total counts:", GSE100327_779e_779e_high_MFE_TX_counts_fraction, "\n")
cat("GSE100327_779e net change counts high MFE TX drug vs control:", GSE100327_779e_779e_high_MFE_TX_counts_fraction - GSE100327_779e_control_high_MFE_TX_counts_fraction, "\n")




