# DIFFERENTIAL EXPRESSION ANALYSIS MIA_PACA2
# We perform a minimal pre-filtering to keep only rows that have at least 3 reads total
keep <- rowSums(counts(dds_GSE105083_MIA_PACA2)) >= 3
dds_GSE105083_MIA_PACA2 <- dds_GSE105083_MIA_PACA2[keep,]
table(keep) # This shows how many transcripts have been removed after the filtering
nrow(dds_GSE105083_MIA_PACA2) # to confirm the filtered transcripts

# DIFFERENTIAL EXPRESSION ANALYSIS
dds_GSE105083_MIA_PACA2 <- DESeq(dds_GSE105083_MIA_PACA2) # The DESeq() function normalizes the read counts, estimates dispersions, and fits the linear model, all in one go
# dds_GSE105083_MIA_PACA2 <- DESeq(dds_GSE105083_MIA_PACA2, betaPrior = T)  The betaPrior = T opton tells DESeq2 to squeeze the log Fold Changes of lowly expressed genes toward zero.

# If I want to see the normalized counts generated in the DESeq object:
# norm_dds_MIA_PACA2 <- counts(dds_GSE105083_MIA_PACA2, normalized=TRUE)

# resultsNames(dds_GSE105083_MIA_PACA2) # lists the coefficients
# plotDispEsts(dds_GSE105083_MIA_PACA2) # Plot the dispersions
# Each black dot in the plot represents the dispersion for one gene. The red line is fit to data (black bots),
# then the dispersions are squeezed toward the red line, resulting the final (blue) dispersion estimates. Usually,
# the dispersion is highest at the low counts and levels off at higher counts.



# Analysis MIA_PACA2 untreated vs 6h
# Specify the conditions to contrast for differential expression analysis
res_GSE105083_MIA_PACA2_6h <- results(dds_GSE105083_MIA_PACA2, contrast=c("condition","CM03_6h","untreated")) # to specify the samples to contrast
res_GSE105083_MIA_PACA2_6h

# Get a summary of the results
# The summary gives the number of genes that are up and down regulated, the outlier genes, and genes removed due to low counts.
summary(res_GSE105083_MIA_PACA2_6h)



# Plot the log2 Fold Changes as function of expression:
plotMA(res_GSE105083_MIA_PACA2_6h,alpha = 0.05)
abline(h=c(-2,2),col = "red")

# Transform the row names into a column
res_GSE105083_MIA_PACA2_6h_df <- data.frame(res_GSE105083_MIA_PACA2_6h)
res_GSE105083_MIA_PACA2_6h <- tibble::rownames_to_column(res_GSE105083_MIA_PACA2_6h_df, "ensembl_transcript_id")



# Join the expression change values with the Table_ANNOTATED containing MFE values
MFE_GSE105083_MIA_PACA2_6h <- dplyr::inner_join(Table_ANNOTATED, res_GSE105083_MIA_PACA2_6h, by="ensembl_transcript_id") %>% # The file 'Table' contains the Normalized_MFE values of all ANNOTATED transcripts
  dplyr::filter(padj < 0.05)


# Generate a scatter plot Log2_FC vs Normalized_MFE
library(ggplot2)
Plot_GSE105083_MIA_PACA2_6h <- ggplot(MFE_GSE105083_MIA_PACA2_6h, aes(y=Normalized_MFE, x=log2FoldChange)) +
  geom_point(size=1.5, alpha=0.2)+
  theme_classic() +
  theme(legend.position="none") +
  geom_vline(xintercept = 0, size=0.3) +
  #xlim(-5.5,5.5) +
  theme(axis.title = element_text(size = 20)) +
  theme(plot.title = element_text(size = 15)) +
  labs(y="DGfold / nt (kcal/mol)",x="Log2_FC_expression",title="GSE105083_MIA_PACA2_6h_Log2_FC_adj.P<0.05")
print(Plot_GSE105083_MIA_PACA2_6h)








# Look at the mean log2_FC
MFE_GSE105083_MIA_PACA2_6h_UP <- dplyr::filter(MFE_GSE105083_MIA_PACA2_6h, log2FoldChange > 0)
Mean_MFE_GSE105083_MIA_PACA2_6h_UP <- mean(MFE_GSE105083_MIA_PACA2_6h_UP$Normalized_MFE)

MFE_GSE105083_MIA_PACA2_6h_DOWN <- dplyr::filter(MFE_GSE105083_MIA_PACA2_6h, log2FoldChange < 0)
Mean_MFE_GSE105083_MIA_PACA2_6h_DOWN <- mean(MFE_GSE105083_MIA_PACA2_6h_DOWN$Normalized_MFE)

TTEST_MFE_GSE105083_MIA_PACA2_6h_all_UP_vs_DOWN <- t.test(MFE_GSE105083_MIA_PACA2_6h_DOWN$Normalized_MFE, MFE_GSE105083_MIA_PACA2_6h_UP$Normalized_MFE, paired=FALSE)

# Add K-S test to look at the differences between the up-regukated and down-regulated genes
ks_test_GSE105083_MIA_PACA2_6h_all_UP_vs_DOWN <- ks.test(MFE_GSE105083_MIA_PACA2_6h_DOWN$Normalized_MFE, MFE_GSE105083_MIA_PACA2_6h_UP$Normalized_MFE)
print(ks_test_GSE105083_MIA_PACA2_6h_all_UP_vs_DOWN)


quantile_075_MFE_GSE105083_MIA_PACA2_6h_UP <- quantile(MFE_GSE105083_MIA_PACA2_6h_UP$Normalized_MFE, probs = c(0.75)) 
quantile_075_MFE_GSE105083_MIA_PACA2_6h_DOWN <- quantile(MFE_GSE105083_MIA_PACA2_6h_DOWN$Normalized_MFE, probs = c(0.75)) 
# Values above 0.75 quantile
ks_test_MFE_075_above <- ks.test(MFE_GSE105083_MIA_PACA2_6h_UP$Normalized_MFE[MFE_GSE105083_MIA_PACA2_6h_UP$Normalized_MFE >= quantile_075_MFE_GSE105083_MIA_PACA2_6h_UP],
                                 MFE_GSE105083_MIA_PACA2_6h_DOWN$Normalized_MFE[MFE_GSE105083_MIA_PACA2_6h_DOWN$Normalized_MFE >= quantile_075_MFE_GSE105083_MIA_PACA2_6h_DOWN])

# Look at the differences between the 0.25 quantile 
quantile_025_MFE_GSE105083_MIA_PACA2_6h_UP <- quantile(MFE_GSE105083_MIA_PACA2_6h_UP$Normalized_MFE, probs = c(0.25)) 
quantile_025_MFE_GSE105083_MIA_PACA2_6h_DOWN <- quantile(MFE_GSE105083_MIA_PACA2_6h_DOWN$Normalized_MFE, probs = c(0.25)) 
# Values below 0.25 quantile
ks_test_MFE_025_below <- ks.test(MFE_GSE105083_MIA_PACA2_6h_UP$Normalized_MFE[MFE_GSE105083_MIA_PACA2_6h_UP$Normalized_MFE <= quantile_025_MFE_GSE105083_MIA_PACA2_6h_UP],
                                 MFE_GSE105083_MIA_PACA2_6h_DOWN$Normalized_MFE[MFE_GSE105083_MIA_PACA2_6h_DOWN$Normalized_MFE <= quantile_025_MFE_GSE105083_MIA_PACA2_6h_DOWN])






# Permutation test MFE changes
# Combine the data into a single data frame with labels
upregulated <- data.frame(MFE = MFE_GSE105083_MIA_PACA2_6h_UP$Normalized_MFE, Group = "Up")
downregulated <- data.frame(MFE = MFE_GSE105083_MIA_PACA2_6h_DOWN$Normalized_MFE, Group = "Down")
combined_data <- bind_rows(upregulated, downregulated)

# Observed difference in means
GSE105083_MIA_PACA2_6h_observed_diff <- mean(MFE_GSE105083_MIA_PACA2_6h_UP$Normalized_MFE) - mean(MFE_GSE105083_MIA_PACA2_6h_DOWN$Normalized_MFE)

# Number of permutations
n_permutations <- 10000

# Initialize a vector to store the permuted differences
GSE105083_MIA_PACA2_6h_permuted_diffs <- numeric(n_permutations)

# Permutation test
set.seed(123)  # Set seed for reproducibility
for (i in 1:n_permutations) {
  # Permute the Group labels
  permuted_labels <- sample(combined_data$Group)
  
  # Calculate the mean MFE for each permuted group
  permuted_up_mean <- mean(combined_data$MFE[permuted_labels == "Up"])
  permuted_down_mean <- mean(combined_data$MFE[permuted_labels == "Down"])
  
  # Calculate the difference in means for the permuted groups
  GSE105083_MIA_PACA2_6h_permuted_diffs[i] <- permuted_up_mean - permuted_down_mean
}

# Calculate the p-value
GSE105083_MIA_PACA2_6h_p_value <- (sum(abs(GSE105083_MIA_PACA2_6h_permuted_diffs) >= abs(GSE105083_MIA_PACA2_6h_observed_diff)) + 1) / (n_permutations + 1)

# Output the results
cat("Observed difference in GSE105083_MIA_PACA2_6h means MFE_UP - MFE_DOWN:", GSE105083_MIA_PACA2_6h_observed_diff, "\n")
cat("GSE105083_MIA_PACA2_6h P-value from permutation test:", GSE105083_MIA_PACA2_6h_p_value, "\n")













