                                 MFE_GSE105083_PANC1_24h_DOWN$Normalized_MFE[MFE_GSE105083_PANC1_24h_DOWN$Normalized_MFE <= quantile_025_MFE_GSE105083_PANC1_24h_DOWN])





# Permutation test MFE changes
# Combine the data into a single data frame with labels
upregulated <- data.frame(MFE = MFE_GSE105083_PANC1_24h_UP$Normalized_MFE, Group = "Up")
downregulated <- data.frame(MFE = MFE_GSE105083_PANC1_24h_DOWN$Normalized_MFE, Group = "Down")
combined_data <- bind_rows(upregulated, downregulated)

# Observed difference in means
GSE105083_PANC1_24h_observed_diff <- mean(MFE_GSE105083_PANC1_24h_UP$Normalized_MFE) - mean(MFE_GSE105083_PANC1_24h_DOWN$Normalized_MFE)

# Number of permutations
n_permutations <- 10000

# Initialize a vector to store the permuted differences
GSE105083_PANC1_24h_permuted_diffs <- numeric(n_permutations)

# Permutation test
set.seed(123)  # Set seed for reproducibility
for (i in 1:n_permutations) {
  # Permute the Group labels
  permuted_labels <- sample(combined_data$Group)
  
  # Calculate the mean MFE for each permuted group
  permuted_up_mean <- mean(combined_data$MFE[permuted_labels == "Up"])
  permuted_down_mean <- mean(combined_data$MFE[permuted_labels == "Down"])
  
  # Calculate the difference in means for the permuted groups
  GSE105083_PANC1_24h_permuted_diffs[i] <- permuted_up_mean - permuted_down_mean
}

# Calculate the p-value
GSE105083_PANC1_24h_p_value <- (sum(abs(GSE105083_PANC1_24h_permuted_diffs) >= abs(GSE105083_PANC1_24h_observed_diff)) + 1) / (n_permutations + 1)

# Output the results
cat("Observed difference in GSE105083_PANC1_24h means MFE_UP - MFE_DOWN:", GSE105083_PANC1_24h_observed_diff, "\n")
cat("GSE105083_PANC1_24h P-value from permutation test:", GSE105083_PANC1_24h_p_value, "\n")




















## GSE105083 net MFE and heat capacity ####
# IMPORTANT: here, I filter for transcripts with a significant log2_FC.
# The total net MFE is essentially a weighted sum of the MFEs of all transcripts, where the weights are given by the counts of each transcript. 
# This gives the total contribution of each transcript to the overall thermodynamic state of the transcriptome based on their abundance.  


# Analysis GSE105083_MIA_PACA2
# Extract the normalized count data
# The minimal pre-filtering has already been done in the previous steps
GSE105083_MIA_PACA2_norm_TX_counts <- counts(dds_GSE105083_MIA_PACA2, normalized=TRUE) # This object is already a matrix
GSE105083_MIA_PACA2_norm_TX_counts_df <- as.data.frame(GSE105083_MIA_PACA2_norm_TX_counts)
# Convert row names to column
GSE105083_MIA_PACA2_norm_TX_counts_df$ensembl_transcript_id <- rownames(GSE105083_MIA_PACA2_norm_TX_counts_df)
# Remove row names
rownames(GSE105083_MIA_PACA2_norm_TX_counts_df) <- NULL

# Move ensembl_transcript_id column to the first position
GSE105083_MIA_PACA2_norm_TX_counts_df <- GSE105083_MIA_PACA2_norm_TX_counts_df[, c("ensembl_transcript_id", setdiff(names(GSE105083_MIA_PACA2_norm_TX_counts_df), "ensembl_transcript_id"))]

# Remove everything after the dot (including the dot itself) in the ensembl_transcript_id column
GSE105083_MIA_PACA2_norm_TX_counts_df$ensembl_transcript_id <- sub("\\..*", "", GSE105083_MIA_PACA2_norm_TX_counts_df$ensembl_transcript_id)

# Join the counts with the Table_ANNOTATED containing MFE values and heat capacity values
GSE105083_MIA_PACA2_norm_TX_counts_MFE_df <- dplyr::inner_join(Table_ANNOTATED, GSE105083_MIA_PACA2_norm_TX_counts_df, by="ensembl_transcript_id") %>%
  dplyr::select(ensembl_transcript_id_version, ensembl_transcript_id, ensembl_gene_id, external_gene_name, transcript_is_canonical, Transcript_length, 
                GSM2817701, GSM2817702, GSM2817704, GSM2817705, GSM2817706, GSM2817707, GSM2817709, GSM2817709, GSM2817710, GSM2817711, Normalized_MFE, Temperature, Specific_heat)







# GSE105083_MIA_PACA2_6h
# Convert from wide to long format
GSE105083_MIA_PACA2_6h_norm_TX_counts_MFE_df <- GSE105083_MIA_PACA2_norm_TX_counts_MFE_df %>%
  dplyr::select(ensembl_transcript_id_version, ensembl_transcript_id, ensembl_gene_id, external_gene_name, transcript_is_canonical, Transcript_length, 
                GSM2817701, GSM2817702, GSM2817704, GSM2817705, GSM2817706, GSM2817707, Normalized_MFE, Temperature, Specific_heat) %>%
  dplyr::filter(ensembl_transcript_id %in% MFE_GSE105083_MIA_PACA2_6h$ensembl_transcript_id) 

# Identify the 75th percentile of the combined MFE distributions of control and drug-treated samples
quantile_075_GSE105083_MIA_PACA2_6h_norm_TX_counts_MFE_df <- quantile(GSE105083_MIA_PACA2_6h_norm_TX_counts_MFE_df$Normalized_MFE, probs = c(0.75))

# Select all the transcripts with Normalized_MFE values above the 75th percentile
GSE105083_MIA_PACA2_6h_high_MFE_TX <- dplyr::filter(GSE105083_MIA_PACA2_6h_norm_TX_counts_MFE_df, Normalized_MFE > quantile_075_GSE105083_MIA_PACA2_6h_norm_TX_counts_MFE_df)

# Count the number of transcripts in the significantly up- and down-regulated pools that have MFE values above this threshold.
GSE105083_MIA_PACA2_6h_high_MFE_TX_in_UP <- dplyr::filter(MFE_GSE105083_MIA_PACA2_6h_UP, ensembl_transcript_id_version %in% GSE105083_MIA_PACA2_6h_high_MFE_TX$ensembl_transcript_id_version)
GSE105083_MIA_PACA2_6h_high_MFE_TX_in_DOWN <- dplyr::filter(MFE_GSE105083_MIA_PACA2_6h_DOWN, ensembl_transcript_id_version %in% GSE105083_MIA_PACA2_6h_high_MFE_TX$ensembl_transcript_id_version)

# Calculate the proportions of high MFE transcripts in UP- and DOWN-regulated genes
GSE105083_MIA_PACA2_6h_total_UP <- nrow(MFE_GSE105083_MIA_PACA2_6h_UP)
GSE105083_MIA_PACA2_6h_total_DOWN <- nrow(MFE_GSE105083_MIA_PACA2_6h_DOWN)
GSE105083_MIA_PACA2_6h_count_high_MFE_UP <- nrow(GSE105083_MIA_PACA2_6h_high_MFE_TX_in_UP)
GSE105083_MIA_PACA2_6h_count_high_MFE_DOWN <- nrow(GSE105083_MIA_PACA2_6h_high_MFE_TX_in_DOWN)

# Proportions for each group
p_up <- GSE105083_MIA_PACA2_6h_count_high_MFE_UP / GSE105083_MIA_PACA2_6h_total_UP
p_down <- GSE105083_MIA_PACA2_6h_count_high_MFE_DOWN / GSE105083_MIA_PACA2_6h_total_DOWN

# Pooled proportion for both groups
p_pool <- (GSE105083_MIA_PACA2_6h_count_high_MFE_UP + GSE105083_MIA_PACA2_6h_count_high_MFE_DOWN) / 
  (GSE105083_MIA_PACA2_6h_total_UP + GSE105083_MIA_PACA2_6h_total_DOWN)

# Standard error for the difference in proportions
SE <- sqrt(p_pool * (1 - p_pool) * (1 / GSE105083_MIA_PACA2_6h_total_UP + 1 / GSE105083_MIA_PACA2_6h_total_DOWN))

# Z-value for the difference in proportions
z_value <- (p_up - p_down) / SE

# Two-tailed p-value from the Z-test
GSE105083_MIA_PACA2_6h_z_test_MFE_p_value <- 2 * (1 - pnorm(abs(z_value)))  # Two-tailed test

# Output the results of the Z-test
cat("GSE105083_MIA_PACA2_6h Two-Proportion Z-test P-value for high MFE transcript counts between UP-regulated and DOWN-regulated genes:", GSE105083_MIA_PACA2_6h_z_test_MFE_p_value, "\n")

# Look at the fractions
GSE105083_MIA_PACA2_6h_high_MFE_in_UP_fraction <- GSE105083_MIA_PACA2_6h_count_high_MFE_UP / GSE105083_MIA_PACA2_6h_total_UP
GSE105083_MIA_PACA2_6h_high_MFE_in_DOWN_fraction <- GSE105083_MIA_PACA2_6h_count_high_MFE_DOWN / GSE105083_MIA_PACA2_6h_total_DOWN

# Output the fractions and other statistics
cat("Fraction of GSE105083_MIA_PACA2_6h high MFE TX in UP-regulated genes:", GSE105083_MIA_PACA2_6h_high_MFE_in_UP_fraction, "\n")
cat("Fraction of GSE105083_MIA_PACA2_6h high MFE TX in DOWN-regulated genes:", GSE105083_MIA_PACA2_6h_high_MFE_in_DOWN_fraction, "\n")
cat("Mean of GSE105083_MIA_PACA2_6h high MFE TX in UP-regulated genes:", mean(GSE105083_MIA_PACA2_6h_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mean of GSE105083_MIA_PACA2_6h high MFE TX in DOWN-regulated genes:", mean(GSE105083_MIA_PACA2_6h_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")
cat("Mode of GSE105083_MIA_PACA2_6h high MFE TX in UP-regulated genes:", calculate_mode(GSE105083_MIA_PACA2_6h_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mode of GSE105083_MIA_PACA2_6h high MFE TX in DOWN-regulated genes:", calculate_mode(GSE105083_MIA_PACA2_6h_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")



# Show data as violin plot
# Add a new column to indicate if the value is above the 75th percentile
MFE_GSE105083_MIA_PACA2_6h$above_quantile_075 <- MFE_GSE105083_MIA_PACA2_6h$Normalized_MFE > quantile_075_GSE105083_MIA_PACA2_6h_norm_TX_counts_MFE_df

