# Determine the impact of these changes in terms of fraction of total counts:
# Calculate the fraction of total counts of high MFE transcripts in control and drug-treated groups. 
# This is done by summing the counts of the high MFE transcripts and dividing by the total counts in each group.
# Fisher’s exact test to compare the proportions of high MFE transcripts counts between the two groups.


# Convert from wide to long format
GSE105083_MIA_PACA2_6h_long_data <- GSE105083_MIA_PACA2_6h_norm_TX_counts_MFE_df %>%
  pivot_longer(
    cols = starts_with("GSM"),      # Select all columns starting with "GSM"
    names_to = "replicate",         # Name of the new column for replicate identifiers
    values_to = "counts"            # Name of the new column for the counts
  )

# Add a condition column based on the replicate
GSE105083_MIA_PACA2_6h_long_data <- GSE105083_MIA_PACA2_6h_long_data %>%
  mutate(condition = ifelse(replicate %in% c("GSM2817701", "GSM2817702", "GSM2817704"), "Control", "MIA_PACA2_CM03_6h"))

# Aggregate the replicates for each condition
GSE105083_MIA_PACA2_6h_norm_TX_aggregated_data_avg_counts <- GSE105083_MIA_PACA2_6h_long_data %>%
  group_by(ensembl_transcript_id_version, condition, Normalized_MFE, Specific_heat) %>%
  summarise(
    avg_counts = mean(counts),
    .groups = 'drop'
  )

# Fraction of total high MFE transcripts counts in control and drug-treated groups
GSE105083_MIA_PACA2_6h_control_total_counts <- dplyr::filter(GSE105083_MIA_PACA2_6h_norm_TX_aggregated_data_avg_counts, condition == "Control") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE105083_MIA_PACA2_6h_control_high_MFE_TX_counts <- dplyr::filter(GSE105083_MIA_PACA2_6h_norm_TX_aggregated_data_avg_counts, condition == "Control") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE105083_MIA_PACA2_6h_high_MFE_TX$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE105083_MIA_PACA2_6h_control_high_MFE_TX_counts_fraction <- GSE105083_MIA_PACA2_6h_control_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE105083_MIA_PACA2_6h_control_total_counts$total_counts

GSE105083_MIA_PACA2_6h_MIA_PACA2_CM03_6h_total_counts <- dplyr::filter(GSE105083_MIA_PACA2_6h_norm_TX_aggregated_data_avg_counts, condition == "MIA_PACA2_CM03_6h") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE105083_MIA_PACA2_6h_MIA_PACA2_CM03_6h_high_MFE_TX_counts <- dplyr::filter(GSE105083_MIA_PACA2_6h_norm_TX_aggregated_data_avg_counts, condition == "MIA_PACA2_CM03_6h") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE105083_MIA_PACA2_6h_high_MFE_TX$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE105083_MIA_PACA2_6h_MIA_PACA2_CM03_6h_high_MFE_TX_counts_fraction <- GSE105083_MIA_PACA2_6h_MIA_PACA2_CM03_6h_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE105083_MIA_PACA2_6h_MIA_PACA2_CM03_6h_total_counts$total_counts

# Create the groups for the two-proportion z-test
GSE105083_MIA_PACA2_6h_high_MFE_TX_counts_control_CT <- GSE105083_MIA_PACA2_6h_control_high_MFE_TX_counts_fraction * GSE105083_MIA_PACA2_6h_control_total_counts$total_counts
GSE105083_MIA_PACA2_6h_low_MFE_TX_counts_control_CT <- GSE105083_MIA_PACA2_6h_control_total_counts$total_counts - GSE105083_MIA_PACA2_6h_control_high_MFE_TX_counts$total_counts_high_MFE_TX

GSE105083_MIA_PACA2_6h_high_MFE_TX_counts_MIA_PACA2_CM03_6h_CT <- GSE105083_MIA_PACA2_6h_MIA_PACA2_CM03_6h_high_MFE_TX_counts_fraction * GSE105083_MIA_PACA2_6h_MIA_PACA2_CM03_6h_total_counts$total_counts
GSE105083_MIA_PACA2_6h_low_MFE_TX_counts_MIA_PACA2_CM03_6h_CT <- GSE105083_MIA_PACA2_6h_MIA_PACA2_CM03_6h_total_counts$total_counts - GSE105083_MIA_PACA2_6h_MIA_PACA2_CM03_6h_high_MFE_TX_counts$total_counts_high_MFE_TX

# Proportions of high MFE transcripts in both groups
prop_control <- GSE105083_MIA_PACA2_6h_high_MFE_TX_counts_control_CT / GSE105083_MIA_PACA2_6h_control_total_counts$total_counts
prop_treated <- GSE105083_MIA_PACA2_6h_high_MFE_TX_counts_MIA_PACA2_CM03_6h_CT / GSE105083_MIA_PACA2_6h_MIA_PACA2_CM03_6h_total_counts$total_counts

# Pooled proportion for the z-test
pooled_prop <- (GSE105083_MIA_PACA2_6h_high_MFE_TX_counts_control_CT + GSE105083_MIA_PACA2_6h_high_MFE_TX_counts_MIA_PACA2_CM03_6h_CT) / 
  (GSE105083_MIA_PACA2_6h_control_total_counts$total_counts + GSE105083_MIA_PACA2_6h_MIA_PACA2_CM03_6h_total_counts$total_counts)

# Standard error for the difference of proportions
se <- sqrt(pooled_prop * (1 - pooled_prop) * (1 / GSE105083_MIA_PACA2_6h_control_total_counts$total_counts + 1 / GSE105083_MIA_PACA2_6h_MIA_PACA2_CM03_6h_total_counts$total_counts))

# Z-statistic
z_stat <- (prop_control - prop_treated) / se

# P-value from the z-test (two-tailed)
GSE105083_MIA_PACA2_6h_z_test_counts_75_p_value <- 2 * pnorm(-abs(z_stat))  # Two-tailed test

cat("GSE105083_MIA_PACA2_6h Two-proportion Z-test p-value: ", GSE105083_MIA_PACA2_6h_z_test_counts_75_p_value, "\n")

# Output the results
cat("Proportion of high MFE TX in Control:", prop_control, "\n")
cat("Proportion of high MFE TX in MIA_PACA2_CM03_6h:", prop_treated, "\n")
cat("Z-statistic for the test:", z_stat, "\n")
cat("GSE105083_MIA_PACA2_6h control high MFE TX as fraction of total counts:", GSE105083_MIA_PACA2_6h_control_high_MFE_TX_counts_fraction, "\n")
cat("GSE105083_MIA_PACA2_6h MIA_PACA2_CM03_6h high MFE TX as fraction of total counts:", GSE105083_MIA_PACA2_6h_MIA_PACA2_CM03_6h_high_MFE_TX_counts_fraction, "\n")
cat("GSE105083_MIA_PACA2_6h net change counts high MFE TX drug vs control", GSE105083_MIA_PACA2_6h_MIA_PACA2_CM03_6h_high_MFE_TX_counts_fraction - GSE105083_MIA_PACA2_6h_control_high_MFE_TX_counts_fraction, "\n")






