p_treated <- GSE105083_MIA_PACA2_6h_low_MFE_TX_counts_fraction

# Pooled proportion for the z-test
pooled_prop <- (GSE105083_MIA_PACA2_6h_control_low_MFE_TX_counts$total_counts_low_MFE_TX + GSE105083_MIA_PACA2_6h_low_MFE_TX_counts$total_counts_low_MFE_TX) / (n_control + n_treated)

# Standard error for the difference of proportions
se <- sqrt(pooled_prop * (1 - pooled_prop) * (1 / n_control + 1 / n_treated))

# Z-statistic
z_stat <- (p_control - p_treated) / se

# P-value from the z-test (two-tailed)
GSE105083_MIA_PACA2_6h_z_test_counts_25_p_value <- 2 * pnorm(-abs(z_stat))  # Two-tailed test

cat("Two-proportion Z-test p-value:", GSE105083_MIA_PACA2_6h_z_test_counts_25_p_value, "\n")
cat("Z-statistic for the test:", z_stat, "\n")












