GSE105083_MIA_PACA2_24h_MIA_PACA2_CM03_24h_high_MFE_TX_counts_fraction <- GSE105083_MIA_PACA2_24h_MIA_PACA2_CM03_24h_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE105083_MIA_PACA2_24h_MIA_PACA2_CM03_24h_total_counts$total_counts

# Create the groups for the two-proportion z-test
GSE105083_MIA_PACA2_24h_high_MFE_TX_counts_control_CT <- GSE105083_MIA_PACA2_24h_control_high_MFE_TX_counts_fraction * GSE105083_MIA_PACA2_24h_control_total_counts$total_counts
GSE105083_MIA_PACA2_24h_low_MFE_TX_counts_control_CT <- GSE105083_MIA_PACA2_24h_control_total_counts$total_counts - GSE105083_MIA_PACA2_24h_control_high_MFE_TX_counts$total_counts_high_MFE_TX

GSE105083_MIA_PACA2_24h_high_MFE_TX_counts_MIA_PACA2_CM03_24h_CT <- GSE105083_MIA_PACA2_24h_MIA_PACA2_CM03_24h_high_MFE_TX_counts_fraction * GSE105083_MIA_PACA2_24h_MIA_PACA2_CM03_24h_total_counts$total_counts
GSE105083_MIA_PACA2_24h_low_MFE_TX_counts_MIA_PACA2_CM03_24h_CT <- GSE105083_MIA_PACA2_24h_MIA_PACA2_CM03_24h_total_counts$total_counts - GSE105083_MIA_PACA2_24h_MIA_PACA2_CM03_24h_high_MFE_TX_counts$total_counts_high_MFE_TX

