# Analysis GSE105083_PANC1
# Extract the normalized count data
# The minimal pre-filtering has already been done in the previous steps
GSE105083_PANC1_norm_TX_counts <- counts(dds_GSE105083_PANC1, normalized=TRUE) # This object is already a matrix
GSE105083_PANC1_norm_TX_counts_df <- as.data.frame(GSE105083_PANC1_norm_TX_counts)
# Convert row names to column
GSE105083_PANC1_norm_TX_counts_df$ensembl_transcript_id <- rownames(GSE105083_PANC1_norm_TX_counts_df)
# Remove row names
rownames(GSE105083_PANC1_norm_TX_counts_df) <- NULL

# Move ensembl_transcript_id column to the first position
GSE105083_PANC1_norm_TX_counts_df <- GSE105083_PANC1_norm_TX_counts_df[, c("ensembl_transcript_id", setdiff(names(GSE105083_PANC1_norm_TX_counts_df), "ensembl_transcript_id"))]

# Remove everything after the dot (including the dot itself) in the ensembl_transcript_id column
GSE105083_PANC1_norm_TX_counts_df$ensembl_transcript_id <- sub("\\..*", "", GSE105083_PANC1_norm_TX_counts_df$ensembl_transcript_id)

# Join the counts with the Table_ANNOTATED containing MFE values and heat capacity values
GSE105083_PANC1_norm_TX_counts_MFE_df <- dplyr::inner_join(Table_ANNOTATED, GSE105083_PANC1_norm_TX_counts_df, by="ensembl_transcript_id") %>%
  dplyr::select(ensembl_transcript_id_version, ensembl_transcript_id, ensembl_gene_id, external_gene_name, transcript_is_canonical, Transcript_length, 
                GSM2817713, GSM2817715, GSM2817716, GSM2817717, GSM2817718, GSM2817719, GSM2817722, GSM2817723, GSM2817724, Normalized_MFE, Temperature, Specific_heat)







# GSE105083_PANC1_6h
# Convert from wide to long format
GSE105083_PANC1_6h_norm_TX_counts_MFE_df <- GSE105083_PANC1_norm_TX_counts_MFE_df %>%
  dplyr::select(ensembl_transcript_id_version, ensembl_transcript_id, ensembl_gene_id, external_gene_name, transcript_is_canonical, Transcript_length, 
                GSM2817713, GSM2817715, GSM2817716, GSM2817717, GSM2817718, GSM2817719, Normalized_MFE, Temperature, Specific_heat) %>%
  dplyr::filter(ensembl_transcript_id %in% MFE_GSE105083_PANC1_6h$ensembl_transcript_id)

# Identify the 75th percentile of the combined MFE distributions of control and drug-treated samples
quantile_075_GSE105083_PANC1_6h_norm_TX_counts_MFE_df <- quantile(GSE105083_PANC1_6h_norm_TX_counts_MFE_df$Normalized_MFE, probs = c(0.75))

# Select all the transcripts with Normalized_MFE values above the 75th percentile
GSE105083_PANC1_6h_high_MFE_TX <- dplyr::filter(GSE105083_PANC1_6h_norm_TX_counts_MFE_df, Normalized_MFE > quantile_075_GSE105083_PANC1_6h_norm_TX_counts_MFE_df)

# Count the number of transcripts in the significantly up- and down-regulated pools that have MFE values above this threshold.
GSE105083_PANC1_6h_high_MFE_TX_in_UP <- dplyr::filter(MFE_GSE105083_PANC1_6h_UP, ensembl_transcript_id_version %in% GSE105083_PANC1_6h_high_MFE_TX$ensembl_transcript_id_version)
GSE105083_PANC1_6h_high_MFE_TX_in_DOWN <- dplyr::filter(MFE_GSE105083_PANC1_6h_DOWN, ensembl_transcript_id_version %in% GSE105083_PANC1_6h_high_MFE_TX$ensembl_transcript_id_version)

# Calculate sample sizes for UP and DOWN groups
GSE105083_PANC1_6h_total_UP <- nrow(MFE_GSE105083_PANC1_6h_UP)
GSE105083_PANC1_6h_total_DOWN <- nrow(MFE_GSE105083_PANC1_6h_DOWN)

# Calculate the number of high MFE transcripts in UP and DOWN groups
GSE105083_PANC1_6h_count_high_MFE_UP <- nrow(GSE105083_PANC1_6h_high_MFE_TX_in_UP)
GSE105083_PANC1_6h_count_high_MFE_DOWN <- nrow(GSE105083_PANC1_6h_high_MFE_TX_in_DOWN)

# Proportions of high MFE transcripts in both groups
p_UP <- GSE105083_PANC1_6h_count_high_MFE_UP / GSE105083_PANC1_6h_total_UP
p_DOWN <- GSE105083_PANC1_6h_count_high_MFE_DOWN / GSE105083_PANC1_6h_total_DOWN

# Pooled proportion for the z-test
pooled_prop <- (GSE105083_PANC1_6h_count_high_MFE_UP + GSE105083_PANC1_6h_count_high_MFE_DOWN) / (GSE105083_PANC1_6h_total_UP + GSE105083_PANC1_6h_total_DOWN)

# Standard error for the difference of proportions
se <- sqrt(pooled_prop * (1 - pooled_prop) * (1 / GSE105083_PANC1_6h_total_UP + 1 / GSE105083_PANC1_6h_total_DOWN))

# Z-statistic
z_stat <- (p_UP - p_DOWN) / se

# P-value from the z-test (two-tailed)
GSE105083_PANC1_6h_z_test_MFE_p_value <- 2 * pnorm(-abs(z_stat))  # Two-tailed test

# Output the results
cat("Two-proportion Z-test p-value:", GSE105083_PANC1_6h_z_test_MFE_p_value, "\n")
cat("Z-statistic for the test:", z_stat, "\n")

# Look at the fractions
GSE105083_PANC1_6h_high_MFE_in_UP_fraction <- GSE105083_PANC1_6h_count_high_MFE_UP / GSE105083_PANC1_6h_total_UP
GSE105083_PANC1_6h_high_MFE_in_DOWN_fraction <- GSE105083_PANC1_6h_count_high_MFE_DOWN / GSE105083_PANC1_6h_total_DOWN

# Output the fractions
cat("Fraction of high MFE TX in UP-regulated genes:", GSE105083_PANC1_6h_high_MFE_in_UP_fraction, "\n")
cat("Fraction of high MFE TX in DOWN-regulated genes:", GSE105083_PANC1_6h_high_MFE_in_DOWN_fraction, "\n")
cat("Mean of high MFE TX in UP-regulated genes:", mean(GSE105083_PANC1_6h_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mean of high MFE TX in DOWN-regulated genes:", mean(GSE105083_PANC1_6h_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")
cat("Mode of high MFE TX in UP-regulated genes:", calculate_mode(GSE105083_PANC1_6h_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mode of high MFE TX in DOWN-regulated genes:", calculate_mode(GSE105083_PANC1_6h_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")




