GSE105083_PANC1_24h_total_DOWN <- nrow(MFE_GSE105083_PANC1_24h_DOWN)

# Calculate the number of high MFE transcripts in UP and DOWN groups
GSE105083_PANC1_24h_count_high_MFE_UP <- nrow(GSE105083_PANC1_24h_high_MFE_TX_in_UP)
GSE105083_PANC1_24h_count_high_MFE_DOWN <- nrow(GSE105083_PANC1_24h_high_MFE_TX_in_DOWN)

# Proportions of high MFE transcripts in both groups
p_UP <- GSE105083_PANC1_24h_count_high_MFE_UP / GSE105083_PANC1_24h_total_UP
p_DOWN <- GSE105083_PANC1_24h_count_high_MFE_DOWN / GSE105083_PANC1_24h_total_DOWN

# Pooled proportion for the z-test
pooled_prop <- (GSE105083_PANC1_24h_count_high_MFE_UP + GSE105083_PANC1_24h_count_high_MFE_DOWN) / (GSE105083_PANC1_24h_total_UP + GSE105083_PANC1_24h_total_DOWN)

# Standard error for the difference of proportions
se <- sqrt(pooled_prop * (1 - pooled_prop) * (1 / GSE105083_PANC1_24h_total_UP + 1 / GSE105083_PANC1_24h_total_DOWN))

# Z-statistic
z_stat <- (p_UP - p_DOWN) / se

# P-value from the z-test (two-tailed)
GSE105083_PANC1_24h_z_test_MFE_p_value <- 2 * pnorm(-abs(z_stat))  # Two-tailed test

# Output the results
cat("Two-proportion Z-test p-value:", GSE105083_PANC1_24h_z_test_MFE_p_value, "\n")
cat("Z-statistic for the test:", z_stat, "\n")

# Look at the fractions
GSE105083_PANC1_24h_high_MFE_in_UP_fraction <- GSE105083_PANC1_24h_count_high_MFE_UP / GSE105083_PANC1_24h_total_UP
GSE105083_PANC1_24h_high_MFE_in_DOWN_fraction <- GSE105083_PANC1_24h_count_high_MFE_DOWN / GSE105083_PANC1_24h_total_DOWN

# Output the fractions
cat("Fraction of high MFE TX in UP-regulated genes:", GSE105083_PANC1_24h_high_MFE_in_UP_fraction, "\n")
cat("Fraction of high MFE TX in DOWN-regulated genes:", GSE105083_PANC1_24h_high_MFE_in_DOWN_fraction, "\n")
cat("Mean of high MFE TX in UP-regulated genes:", mean(GSE105083_PANC1_24h_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mean of high MFE TX in DOWN-regulated genes:", mean(GSE105083_PANC1_24h_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")
cat("Mode of high MFE TX in UP-regulated genes:", calculate_mode(GSE105083_PANC1_24h_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mode of high MFE TX in DOWN-regulated genes:", calculate_mode(GSE105083_PANC1_24h_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")



