  group_by(ensembl_transcript_id_version, condition, Normalized_MFE, Specific_heat) %>%
  summarise(
    avg_counts = mean(counts),
    .groups = 'drop'
  )

# Fraction of high MFE transcript counts in control group
GSE105083_PANC1_24h_control_total_counts <- dplyr::filter(GSE105083_PANC1_24h_norm_TX_aggregated_data_avg_counts, condition == "Control") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE105083_PANC1_24h_control_high_MFE_TX_counts <- dplyr::filter(GSE105083_PANC1_24h_norm_TX_aggregated_data_avg_counts, condition == "Control") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE105083_PANC1_24h_high_MFE_TX$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE105083_PANC1_24h_control_high_MFE_TX_counts_fraction <- GSE105083_PANC1_24h_control_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE105083_PANC1_24h_control_total_counts$total_counts

# Fraction of high MFE transcript counts in drug-treated group (PANC1_CM03_24h)
GSE105083_PANC1_24h_PANC1_CM03_24h_total_counts <- dplyr::filter(GSE105083_PANC1_24h_norm_TX_aggregated_data_avg_counts, condition == "PANC1_CM03_24h") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE105083_PANC1_24h_PANC1_CM03_24h_high_MFE_TX_counts <- dplyr::filter(GSE105083_PANC1_24h_norm_TX_aggregated_data_avg_counts, condition == "PANC1_CM03_24h") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE105083_PANC1_24h_high_MFE_TX$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE105083_PANC1_24h_PANC1_CM03_24h_high_MFE_TX_counts_fraction <- GSE105083_PANC1_24h_PANC1_CM03_24h_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE105083_PANC1_24h_PANC1_CM03_24h_total_counts$total_counts

# Calculate pooled proportion for Z-test
pooled_prop <- (GSE105083_PANC1_24h_control_high_MFE_TX_counts$total_counts_high_MFE_TX + GSE105083_PANC1_24h_PANC1_CM03_24h_high_MFE_TX_counts$total_counts_high_MFE_TX) /
  (GSE105083_PANC1_24h_control_total_counts$total_counts + GSE105083_PANC1_24h_PANC1_CM03_24h_total_counts$total_counts)

# Calculate the standard error for the difference of proportions
se <- sqrt(pooled_prop * (1 - pooled_prop) * (1 / GSE105083_PANC1_24h_control_total_counts$total_counts + 1 / GSE105083_PANC1_24h_PANC1_CM03_24h_total_counts$total_counts))

# Calculate the Z-statistic for the difference of proportions
z_stat <- (GSE105083_PANC1_24h_control_high_MFE_TX_counts_fraction - GSE105083_PANC1_24h_PANC1_CM03_24h_high_MFE_TX_counts_fraction) / se

# Calculate the p-value from the Z-statistic (two-tailed test)
GSE105083_PANC1_24h_z_test_counts_75_p_value <- 2 * pnorm(-abs(z_stat))

# Output the results
cat("Two-proportion Z-test p-value:", GSE105083_PANC1_24h_z_test_counts_75_p_value, "\n")
cat("Z-statistic for the test:", z_stat, "\n")

# Output the fractions of high MFE transcripts in each condition
cat("GSE105083_PANC1_24h control high MFE TX as fraction of total counts:", GSE105083_PANC1_24h_control_high_MFE_TX_counts_fraction, "\n")
cat("GSE105083_PANC1_24h PANC1_CM03_24h high MFE TX as fraction of total counts:", GSE105083_PANC1_24h_PANC1_CM03_24h_high_MFE_TX_counts_fraction, "\n")
cat("GSE105083_PANC1_24h net change counts high MFE TX drug vs control:", GSE105083_PANC1_24h_PANC1_CM03_24h_high_MFE_TX_counts_fraction - GSE105083_PANC1_24h_control_high_MFE_TX_counts_fraction, "\n")






