# GSE129221  Apatinib induces cell cycle arrest in gefitinib resistant PC9GR lung cancer cells but not its parental sensitive cells PC9.  ####
# The inhibition of cell cycle was mostly achieved through cell cycle arrest of PC9GR cells in G1 phase. 
# Here, I analyze only the data of the gefitinib resistant PC9GR cell line
# http://www.ilincs.org/apps/grein/?gse=GSE129221

Counts_GSE129221_GREIN <- read.delim("path_to/GSE129221/GSE129221_TranscriptLevel_Raw_data.csv", sep = ",", header = T, stringsAsFactors = F)
Counts_GSE129221_GREIN <- Counts_GSE129221_GREIN %>% remove_rownames %>% column_to_rownames(var="X") # Convert first column into row names in data frame
# Round counts down to the nearest integer
Counts_GSE129221_GREIN <- floor(Counts_GSE129221_GREIN)




# Access the Series Matrix
# Data_GSE129221 <- getGEO(GEO = "GSE129221")

# LOad the object
Data_GSE129221 <- readRDS("path_to/GREIN_series_matrices_data/Data_GSE129221.rds")


# Extract the phenotypic/clinical data matrix from the series matrix
Expdata_GSE129221 <- Data_GSE129221[["GSE129221_series_matrix.txt.gz"]]@phenoData@data

colnames(Expdata_GSE129221)[colnames(Expdata_GSE129221) == "group:ch1"] <- "condition" # Rename the column to have an easier identifier for the conditions
colnames(Expdata_GSE129221)[colnames(Expdata_GSE129221) == "cell line:ch1"] <- "cell_line" # Rename the column to have an easier identifier for the conditions

# Rename some of the conditions
Expdata_GSE129221 <- Expdata_GSE129221 %>% dplyr::mutate(condition = case_when(condition == "PC9 after apatinib treatment" ~ "PC9_apatinib", TRUE ~ condition))
Expdata_GSE129221 <- Expdata_GSE129221 %>% dplyr::mutate(condition = case_when(condition == "PC9GR after apatinib treatment" ~ "PC9GR_apatinib", TRUE ~ condition))
Expdata_GSE129221 <- Expdata_GSE129221 %>% dplyr::mutate(condition = case_when(condition == "PC9" ~ "PC9_untreated", TRUE ~ condition))
Expdata_GSE129221 <- Expdata_GSE129221 %>% dplyr::mutate(condition = case_when(condition == "PC9GR" ~ "PC9GR_untreated", TRUE ~ condition))



# IMPORTANT:
# It is absolutely critical that the columns of the count matrix and the rows of the column data (information about samples) are in the same order.

# Replace the row names of Expdata_GSE129221 (sampleID) with the same sample name [title] of [Counts_GSE182018]. 
# This will help to match sample names in both matrices.
# The outcome should be TRUE
all(rownames(Expdata_GSE129221) %in% colnames(Counts_GSE129221_GREIN))
all(colnames(Counts_GSE129221_GREIN) %in% rownames(Expdata_GSE129221))

# # Replace the columns names in the counts with the conditions
# Counts_GSE129221_GREIN <- dplyr::rename(Counts_GSE129221_GREIN, PC9_untreated_R1 = GSM3702795) %>%
#   dplyr::rename(PC9_untreated_R2 = GSM3702796) %>%
#   dplyr::rename(PC9_untreated_R3 = GSM3702797) %>%
#   dplyr::rename(PC9_apatinib_R1 = GSM3702798) %>%
#   dplyr::rename(PC9_apatinib_R2 = GSM3702799) %>%
#   dplyr::rename(PC9_apatinib_R3 = GSM3702800) %>%
#   dplyr::rename(PC9GR_untreated_R1 = GSM3702801) %>%
#   dplyr::rename(PC9GR_untreated_R2 = GSM3702802) %>%
#   dplyr::rename(PC9GR_untreated_R3 = GSM3702803) %>%
#   dplyr::rename(PC9GR_apatinib_R1 = GSM3702804) %>%
#   dplyr::rename(PC9GR_apatinib_R2 = GSM3702805) %>%
#   dplyr::rename(PC9GR_apatinib_R3 = GSM3702806)
# 
# names(Counts_GSE129221_GREIN) <- paste0("GSE129221_", names(Counts_GSE129221_GREIN)) # adds the GSE_ID to the all columns of the data set



# With the count matrix, Counts_GSE108308_GREIN, and the sample information, Expdata_GSE108308, we can construct a DESeqDataSet:
dds_GSE129221 <- DESeqDataSetFromMatrix(countData = Counts_GSE129221_GREIN,
                                        colData = Expdata_GSE129221,
                                        design = ~ condition)
dds_GSE129221




# DATA QUALITY ASSESSMENT MIA_PACA2 COUNTS
# Before performing differential expression analysis, we perform data quality assessment by sample clustering and visualization
library("pheatmap")
# We log transform the counts
ntd <- normTransform(dds_GSE129221)
# Heat map of the count matrix
select <- order(rowMeans(counts(dds_GSE129221,normalized=FALSE)),
                decreasing=TRUE)[1:25]
df <- as.data.frame(colData(dds_GSE129221)[,c("condition","type")])
pheatmap(assay(ntd)[select,], cluster_rows=FALSE, show_rownames=FALSE,
         cluster_cols=FALSE, annotation_col=df)



# Heatmap of the sample-to-sample distances
# A heatmap of this distance matrix gives us an overview over similarities and dissimilarities between samples
# Transform the values
vsd <- vst(dds_GSE129221, blind=FALSE)
# rld <- rlog(dds_GSE129221, blind=FALSE)
head(assay(vsd), 3)

# Apply the dist function to the transpose of the transformed count matrix to get sample-to-sample distances
sampleDists <- dist(t(assay(vsd)))

# Condition
library("RColorBrewer")
sampleDistMatrix <- as.matrix(sampleDists)
rownames(sampleDistMatrix) <- paste(vsd$condition, vsd$type, sep="-")
colnames(sampleDistMatrix) <- NULL
colors <- colorRampPalette( rev(brewer.pal(9, "Blues")) )(255)
pheatmap(sampleDistMatrix,
         clustering_distance_rows=sampleDists,
         clustering_distance_cols=sampleDists,
         col=colors)

# Principal component plot of the samples
plotPCA(vsd, intgroup="condition")





# DIFFERENTIAL EXPRESSION ANALYSIS
# We perform a minimal pre-filtering to keep only rows that have at least 3 reads total
keep <- rowSums(counts(dds_GSE129221)) >= 3
dds_GSE129221 <- dds_GSE129221[keep,]
table(keep) # This shows how many transcripts have been removed after the filtering
nrow(dds_GSE129221) # to confirm the filtered transcripts

# DIFFERENTIAL EXPRESSION ANALYSIS
dds_GSE129221 <- DESeq(dds_GSE129221) # The DESeq() function normalizes the read counts, estimates dispersions, and fits the linear model, all in one go
# dds_GSE129221 <- DESeq(dds_GSE129221, betaPrior = T)  The betaPrior = T opton tells DESeq2 to squeeze the log Fold Changes of lowly expressed genes toward zero.

# If I want to see the normalized counts generated in the DESeq object:
# norm_dds_GSE129221 <- counts(dds_GSE129221, normalized=TRUE)

# resultsNames(dds_GSE129221) # lists the coefficients
# plotDispEsts(dds_GSE129221) # Plot the dispersions
# Each black dot in the plot represents the dispersion for one gene. The red line is fit to data (black bots),
# then the dispersions are squeezed toward the red line, resulting the final (blue) dispersion estimates. Usually,
# the dispersion is highest at the low counts and levels off at higher counts.


# Specify the conditions to contrast for differential expression analysis
res_GSE129221_PC9 <- results(dds_GSE129221, contrast=c("condition","PC9_apatinib","PC9_untreated")) # to specify the samples to contrast
res_GSE129221_PC9
# Get a summary of the results
summary(res_GSE129221_PC9)

res_GSE129221_PC9GR <- results(dds_GSE129221, contrast=c("condition","PC9GR_apatinib","PC9GR_untreated")) # to specify the samples to contrast
res_GSE129221_PC9GR
# Get a summary of the results
summary(res_GSE129221_PC9GR)




# Analayis PC9
# Plot the log2 Fold Changes as function of expression:
plotMA(res_GSE129221_PC9,alpha = 0.05)
abline(h=c(-2,2),col = "red")

# Transform the row names into a column
res_GSE129221_PC9_df <- data.frame(res_GSE129221_PC9)
res_GSE129221_PC9 <- tibble::rownames_to_column(res_GSE129221_PC9_df, "ensembl_transcript_id")
# There are a few ranscripts with counts > 100,000. I discard these transcripts because they coud bias the analysis here below
res_GSE129221_PC9 <- dplyr::filter(res_GSE129221_PC9, baseMean < 100000)



# Join the expression change values with the Table_ANNOTATED containing MFE values
MFE_res_GSE129221_PC9 <- dplyr::inner_join(Table_ANNOTATED, res_GSE129221_PC9, by="ensembl_transcript_id") %>% # The file 'Table' contains the Normalized_MFE values of all ANNOTATED transcripts
  dplyr::filter(padj < 0.05)


# Generate a scatter plot Log2_FC vs Normalized_MFE
library(ggplot2)
Plot_GSE129221_PC9_apatinib <- ggplot(MFE_res_GSE129221_PC9, aes(y=Normalized_MFE, x=log2FoldChange)) +
  geom_point(size=1.5, alpha=0.3)+
  theme_classic() +
  theme(legend.position="none") +
  geom_vline(xintercept = 0, size=0.3) +
  #xlim(-5.5,5.5) +
  theme(axis.title = element_text(size = 20)) +
  theme(plot.title = element_text(size = 15)) +
  labs(y="DGfold / nt (kcal/mol)",x="Log2_FC_expression",title="GSE129221_PC9_apatinib_Log2_FC_adj.P<0.05")
print(Plot_GSE129221_PC9_apatinib)



# Look at the mean log2_FC
MFE_res_GSE129221_PC9_UP <- dplyr::filter(MFE_res_GSE129221_PC9, log2FoldChange > 0)
Mean_MFE_res_GSE129221_PC9_UP <- mean(MFE_res_GSE129221_PC9_UP$Normalized_MFE)

MFE_res_GSE129221_PC9_DOWN <- dplyr::filter(MFE_res_GSE129221_PC9, log2FoldChange < 0)
Mean_MFE_res_GSE129221_PC9_DOWN <- mean(MFE_res_GSE129221_PC9_DOWN$Normalized_MFE)

TTEST_MFE_res_GSE129221_PC9_all_UP_vs_DOWN <- t.test(MFE_res_GSE129221_PC9_DOWN$Normalized_MFE, MFE_res_GSE129221_PC9_UP$Normalized_MFE, paired=FALSE)

# Add K-S test to look at the differences between the up-regukated and down-regulated genes
ks_test_res_GSE129221_PC9_all_UP_vs_DOWN <- ks.test(MFE_res_GSE129221_PC9_DOWN$Normalized_MFE, MFE_res_GSE129221_PC9_UP$Normalized_MFE)


quantile_075_MFE_res_GSE129221_PC9_UP <- quantile(MFE_res_GSE129221_PC9_UP$Normalized_MFE, probs = c(0.75)) 
quantile_075_MFE_res_GSE129221_PC9_DOWN <- quantile(MFE_res_GSE129221_PC9_DOWN$Normalized_MFE, probs = c(0.75)) 
# Values above 0.75 quantile
ks_test_MFE_075_above <- ks.test(MFE_res_GSE129221_PC9_UP$Normalized_MFE[MFE_res_GSE129221_PC9_UP$Normalized_MFE >= quantile_075_MFE_res_GSE129221_PC9_UP],
                                 MFE_res_GSE129221_PC9_DOWN$Normalized_MFE[MFE_res_GSE129221_PC9_DOWN$Normalized_MFE >= quantile_075_MFE_res_GSE129221_PC9_DOWN])

# Look at the differences between the 0.25 quantile 
quantile_025_MFE_res_GSE129221_PC9_UP <- quantile(MFE_res_GSE129221_PC9_UP$Normalized_MFE, probs = c(0.25)) 
quantile_025_MFE_res_GSE129221_PC9_DOWN <- quantile(MFE_res_GSE129221_PC9_DOWN$Normalized_MFE, probs = c(0.25)) 
# Values below 0.25 quantile
ks_test_MFE_025_below <- ks.test(MFE_res_GSE129221_PC9_UP$Normalized_MFE[MFE_res_GSE129221_PC9_UP$Normalized_MFE <= quantile_025_MFE_res_GSE129221_PC9_UP],
                                 MFE_res_GSE129221_PC9_DOWN$Normalized_MFE[MFE_res_GSE129221_PC9_DOWN$Normalized_MFE <= quantile_025_MFE_res_GSE129221_PC9_DOWN])




# Permutation test MFE changes
# Combine the data into a single data frame with labels
upregulated <- data.frame(MFE = MFE_res_GSE129221_PC9_UP$Normalized_MFE, Group = "Up")
downregulated <- data.frame(MFE = MFE_res_GSE129221_PC9_DOWN$Normalized_MFE, Group = "Down")
combined_data <- bind_rows(upregulated, downregulated)

# Observed difference in means
MFE_res_GSE129221_PC9_observed_diff <- mean(MFE_res_GSE129221_PC9_UP$Normalized_MFE) - mean(MFE_res_GSE129221_PC9_DOWN$Normalized_MFE)

# Number of permutations
n_permutations <- 10000

# Initialize a vector to store the permuted differences
MFE_res_GSE129221_PC9_permuted_diffs <- numeric(n_permutations)

# Permutation test
set.seed(123)  # Set seed for reproducibility
for (i in 1:n_permutations) {
  # Permute the Group labels
  permuted_labels <- sample(combined_data$Group)
  
  # Calculate the mean MFE for each permuted group
  permuted_up_mean <- mean(combined_data$MFE[permuted_labels == "Up"])
  permuted_down_mean <- mean(combined_data$MFE[permuted_labels == "Down"])
  
  # Calculate the difference in means for the permuted groups
  MFE_res_GSE129221_PC9_permuted_diffs[i] <- permuted_up_mean - permuted_down_mean
}

# Calculate the p-value
MFE_res_GSE129221_PC9_p_value <- (sum(abs(MFE_res_GSE129221_PC9_permuted_diffs) >= abs(MFE_res_GSE129221_PC9_observed_diff)) + 1) / (n_permutations + 1)

# Output the results
cat("Observed difference in MFE_res_GSE129221_PC9 means MFE_UP - MFE_DOWN:", MFE_res_GSE129221_PC9_observed_diff, "\n")
cat("MFE_res_GSE129221_PC9 P-value from permutation test:", MFE_res_GSE129221_PC9_p_value, "\n")











