## GSE129221 High MFE TX fraction changes ####
# Determine whether within the differentially expressed genes there is a significant up-regulation of high MFE transcripts:
# Define high MFE transcripts by taking the 75th percentile of the combined MFE distributions of control and drug-treated samples.
# Count the number of transcripts in the significantly up- and down-regulated genes that have MFE values above this threshold.
# Perform a Fisher’s exact test to compare the proportions of high MFE transcripts between the two groups. 


# Analysis GSE129221
# Extract the normalized count data
# The minimal pre-filtering has already been done in the previous steps
GSE129221_norm_TX_counts <- counts(dds_GSE129221, normalized=TRUE) # This object is already a matrix
GSE129221_norm_TX_counts_df <- as.data.frame(GSE129221_norm_TX_counts)
# Convert row names to column
GSE129221_norm_TX_counts_df$ensembl_transcript_id <- rownames(GSE129221_norm_TX_counts_df)
# Remove row names
rownames(GSE129221_norm_TX_counts_df) <- NULL

# Move ensembl_transcript_id column to the first position
GSE129221_norm_TX_counts_df <- GSE129221_norm_TX_counts_df[, c("ensembl_transcript_id", setdiff(names(GSE129221_norm_TX_counts_df), "ensembl_transcript_id"))]

# Remove everything after the dot (including the dot itself) in the ensembl_transcript_id column
GSE129221_norm_TX_counts_df$ensembl_transcript_id <- sub("\\..*", "", GSE129221_norm_TX_counts_df$ensembl_transcript_id)

# Join the counts with the Table_ANNOTATED containing MFE values and heat capacity values
GSE129221_norm_TX_counts_MFE_df <- dplyr::inner_join(Table_ANNOTATED, GSE129221_norm_TX_counts_df, by="ensembl_transcript_id") %>%
  dplyr::select(ensembl_transcript_id_version, ensembl_transcript_id, ensembl_gene_id, external_gene_name, transcript_is_canonical, Transcript_length, 
                GSM3702795, GSM3702796, GSM3702797, GSM3702798, GSM3702799, GSM3702800, GSM3702801, GSM3702802, GSM3702803, GSM3702804, GSM3702805, GSM3702806, Normalized_MFE, Temperature, Specific_heat)
# Remove all transcripts with > 100,000 counts. There are only a few and they could skew the calculations below
GSE129221_norm_TX_counts_MFE_df <- GSE129221_norm_TX_counts_MFE_df %>%
  dplyr::filter(GSM3702795 < 100000 & GSM3702796 < 100000 & GSM3702797 < 100000 & GSM3702798 < 100000 & GSM3702799 < 100000 & GSM3702800 < 100000 & GSM3702801 < 100000 & GSM3702802 < 100000 & GSM3702803 < 100000 & GSM3702804 < 100000 & GSM3702805 < 100000 & GSM3702806 < 100000)






# GSE129221_PC9
# Convert from wide to long format
GSE129221_PC9_norm_TX_counts_MFE_df <- GSE129221_norm_TX_counts_MFE_df %>%
  dplyr::select(ensembl_transcript_id_version, ensembl_transcript_id, ensembl_gene_id, external_gene_name, transcript_is_canonical, Transcript_length, 
                GSM3702795, GSM3702796, GSM3702797, GSM3702798, GSM3702799, GSM3702800, Normalized_MFE, Temperature, Specific_heat) %>%
  dplyr::filter(ensembl_transcript_id %in% MFE_res_GSE129221_PC9$ensembl_transcript_id)

# Identify the 75th percentile of the combined MFE distributions of control and drug-treated samples
quantile_075_GSE129221_PC9_norm_TX_counts_MFE_df <- quantile(GSE129221_PC9_norm_TX_counts_MFE_df$Normalized_MFE, probs = c(0.75))

# Select all the transcripts with Normalized_MFE values above the 75th percentile
GSE129221_PC9_high_MFE_TX <- dplyr::filter(GSE129221_PC9_norm_TX_counts_MFE_df, Normalized_MFE > quantile_075_GSE129221_PC9_norm_TX_counts_MFE_df)

# Count the number of transcripts in the significantly up- and down-regulated pools that have MFE values above this threshold.
GSE129221_PC9_high_MFE_TX_in_UP <- dplyr::filter(MFE_res_GSE129221_PC9_UP, ensembl_transcript_id_version %in% GSE129221_PC9_high_MFE_TX$ensembl_transcript_id_version)
GSE129221_PC9_high_MFE_TX_in_DOWN <- dplyr::filter(MFE_res_GSE129221_PC9_DOWN, ensembl_transcript_id_version %in% GSE129221_PC9_high_MFE_TX$ensembl_transcript_id_version)

# Total count of UP and DOWN-regulated transcripts
GSE129221_PC9_total_UP <- nrow(MFE_res_GSE129221_PC9_UP)
GSE129221_PC9_total_DOWN <- nrow(MFE_res_GSE129221_PC9_DOWN)

# Count of high MFE transcripts in UP and DOWN-regulated transcripts
GSE129221_PC9_count_high_MFE_UP <- nrow(GSE129221_PC9_high_MFE_TX_in_UP)
GSE129221_PC9_count_high_MFE_DOWN <- nrow(GSE129221_PC9_high_MFE_TX_in_DOWN)

# Calculate proportions
GSE129221_PC9_high_MFE_in_UP_fraction <- GSE129221_PC9_count_high_MFE_UP / GSE129221_PC9_total_UP
GSE129221_PC9_high_MFE_in_DOWN_fraction <- GSE129221_PC9_count_high_MFE_DOWN / GSE129221_PC9_total_DOWN

# Calculate pooled proportion for Z-test
pooled_prop <- (GSE129221_PC9_count_high_MFE_UP + GSE129221_PC9_count_high_MFE_DOWN) /
  (GSE129221_PC9_total_UP + GSE129221_PC9_total_DOWN)

# Calculate standard error for the difference of proportions
se <- sqrt(pooled_prop * (1 - pooled_prop) * (1 / GSE129221_PC9_total_UP + 1 / GSE129221_PC9_total_DOWN))

# Calculate the Z-statistic for the difference of proportions
z_stat <- (GSE129221_PC9_high_MFE_in_UP_fraction - GSE129221_PC9_high_MFE_in_DOWN_fraction) / se

# Calculate the p-value from the Z-statistic (two-tailed test)
GSE129221_PC9_z_test_MFE_p_value <- 2 * pnorm(-abs(z_stat))

# Output the results
cat("Two-proportion Z-test p-value:", GSE129221_PC9_z_test_MFE_p_value, "\n")
cat("Z-statistic for the test:", z_stat, "\n")

# Output the fractions
cat("Fraction of high MFE TX in UP-regulated genes:", GSE129221_PC9_high_MFE_in_UP_fraction, "\n")
cat("Fraction of high MFE TX in DOWN-regulated genes:", GSE129221_PC9_high_MFE_in_DOWN_fraction, "\n")
cat("Mean of high MFE TX in UP-regulated genes:", mean(GSE129221_PC9_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mean of high MFE TX in DOWN-regulated genes:", mean(GSE129221_PC9_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")
cat("Mode of high MFE TX in UP-regulated genes:", calculate_mode(GSE129221_PC9_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mode of high MFE TX in DOWN-regulated genes:", calculate_mode(GSE129221_PC9_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")




# Show data as violin plot
# Add a new column to indicate if the value is above the 75th percentile
MFE_res_GSE129221_PC9$above_quantile_075 <- MFE_res_GSE129221_PC9$Normalized_MFE > quantile_075_GSE129221_PC9_norm_TX_counts_MFE_df

# Generate violin plot with conditional jitter coloring
ggplot(MFE_res_GSE129221_PC9, aes(x = factor(log2FoldChange > 0), y = Normalized_MFE)) +
  geom_violin(fill = "white") +
  geom_jitter(aes(color = above_quantile_075), width = 0.1, size = 1, alpha = 0.1) +
  scale_color_manual(values = c("FALSE" = "black", "TRUE" = "blue")) +
  theme_classic() +
  theme(
    legend.position = "none", 
    axis.title = element_text(size = 20), 
    plot.title = element_text(size = 10),
    axis.text.x = element_text(size = 16, color = "black")
  ) +
  geom_vline(xintercept = 0, linewidth = 0.3) +
  labs(
    y = "Normalized_MFE", 
    x = NULL, 
    title = "GSE129221_PC9_Log2_FC_adj.P<0.05"
  ) +
  scale_x_discrete(labels = c("log2FoldChange < 0", "log2FoldChange > 0"))








# Determine the impact of these changes in terms of fraction of total counts:
# Calculate the fraction of total counts of high MFE transcripts in control and drug-treated groups. 
# This is done by summing the counts of the high MFE transcripts and dividing by the total counts in each group.
# Fisher’s exact test to compare the proportions of high MFE transcripts counts between the two groups.

# Convert from wide to long format
GSE129221_PC9_long_data <- GSE129221_PC9_norm_TX_counts_MFE_df %>%
  pivot_longer(
    cols = starts_with("GSM"),      # Select all columns starting with "GSM"
    names_to = "replicate",         # Name of the new column for replicate identifiers
    values_to = "counts"            # Name of the new column for the counts
  )

# Add a condition column based on the replicate
GSE129221_PC9_long_data <- GSE129221_PC9_long_data %>%
  mutate(condition = ifelse(replicate %in% c("GSM3702795", "GSM3702796", "GSM3702797"), "Control", "PC9_apatinib"))

# Aggregate the replicates for each condition
GSE129221_PC9_norm_TX_aggregated_data_avg_counts <- GSE129221_PC9_long_data %>%
  group_by(ensembl_transcript_id_version, condition, Normalized_MFE, Specific_heat) %>%
  summarise(
    avg_counts = mean(counts),
    .groups = 'drop'
  )

# Fraction of total high MFE transcripts counts in control and drug-treated groups
GSE129221_PC9_control_total_counts <- dplyr::filter(GSE129221_PC9_norm_TX_aggregated_data_avg_counts, condition == "Control") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE129221_PC9_control_high_MFE_TX_counts <- dplyr::filter(GSE129221_PC9_norm_TX_aggregated_data_avg_counts, condition == "Control") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE129221_PC9_high_MFE_TX$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE129221_PC9_control_high_MFE_TX_counts_fraction <- GSE129221_PC9_control_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE129221_PC9_control_total_counts$total_counts

GSE129221_PC9_PC9_apatinib_total_counts <- dplyr::filter(GSE129221_PC9_norm_TX_aggregated_data_avg_counts, condition == "PC9_apatinib") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE129221_PC9_PC9_apatinib_high_MFE_TX_counts <- dplyr::filter(GSE129221_PC9_norm_TX_aggregated_data_avg_counts, condition == "PC9_apatinib") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE129221_PC9_high_MFE_TX$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE129221_PC9_PC9_apatinib_high_MFE_TX_counts_fraction <- GSE129221_PC9_PC9_apatinib_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE129221_PC9_PC9_apatinib_total_counts$total_counts

# Calculate proportions for Z-test
p_control <- GSE129221_PC9_control_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE129221_PC9_control_total_counts$total_counts
p_apatinib <- GSE129221_PC9_PC9_apatinib_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE129221_PC9_PC9_apatinib_total_counts$total_counts

# Calculate pooled proportion
pooled_prop <- (GSE129221_PC9_control_high_MFE_TX_counts$total_counts_high_MFE_TX + GSE129221_PC9_PC9_apatinib_high_MFE_TX_counts$total_counts_high_MFE_TX) /
  (GSE129221_PC9_control_total_counts$total_counts + GSE129221_PC9_PC9_apatinib_total_counts$total_counts)

# Calculate standard error (SE)
se <- sqrt(pooled_prop * (1 - pooled_prop) * (1 / GSE129221_PC9_control_total_counts$total_counts + 1 / GSE129221_PC9_PC9_apatinib_total_counts$total_counts))

# Calculate the Z-statistic
z_stat <- (p_control - p_apatinib) / se

# Calculate p-value from Z-statistic (two-tailed test)
GSE129221_PC9_z_test_counts_75_p_value <- 2 * pnorm(-abs(z_stat))

# Output the results
cat("Two-proportion Z-test p-value:", GSE129221_PC9_z_test_counts_75_p_value, "\n")
cat("Z-statistic for the test:", z_stat, "\n")

# Output the fractions
cat("Fraction of high MFE TX in Control:", p_control, "\n")
cat("Fraction of high MFE TX in PC9_apatinib:", p_apatinib, "\n")
cat("Net change in high MFE TX counts (drug vs control):", GSE129221_PC9_PC9_apatinib_high_MFE_TX_counts_fraction - GSE129221_PC9_control_high_MFE_TX_counts_fraction, "\n")




# Plot Normalized_MFE vs transcript counts of both control and drug-treated conditions
# Create separate data frames for Control and PC9_apatinib conditions
GSE129221_PC9_control_data <- GSE129221_PC9_norm_TX_aggregated_data_avg_counts %>%
