# Determine the impact of these changes in terms of fraction of total counts:
# Calculate the fraction of total counts of high MFE transcripts in control and drug-treated groups. 
# This is done by summing the counts of the high MFE transcripts and dividing by the total counts in each group.
# Fisher’s exact test to compare the proportions of high MFE transcripts counts between the two groups.


# Convert from wide to long format
# Convert from wide to long format
GSE129221_PC9GR_long_data <- GSE129221_PC9GR_norm_TX_counts_MFE_df %>%
  pivot_longer(
    cols = starts_with("GSM"),      # Select all columns starting with "GSM"
    names_to = "replicate",         # Name of the new column for replicate identifiers
    values_to = "counts"            # Name of the new column for the counts
  )

# Add a condition column based on the replicate
GSE129221_PC9GR_long_data <- GSE129221_PC9GR_long_data %>%
  mutate(condition = ifelse(replicate %in% c("GSM3702801", "GSM3702802", "GSM3702803"), "Control", "PC9GR_apatinib"))

# Aggregate the replicates for each condition
GSE129221_PC9GR_norm_TX_aggregated_data_avg_counts <- GSE129221_PC9GR_long_data %>%
  group_by(ensembl_transcript_id_version, condition, Normalized_MFE, Specific_heat) %>%
  summarise(
    avg_counts = mean(counts),
    .groups = 'drop'
  )

# Calculate total counts and high MFE counts for control and drug-treated conditions
GSE129221_PC9GR_control_total_counts <- dplyr::filter(GSE129221_PC9GR_norm_TX_aggregated_data_avg_counts, condition == "Control") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE129221_PC9GR_control_high_MFE_TX_counts <- dplyr::filter(GSE129221_PC9GR_norm_TX_aggregated_data_avg_counts, condition == "Control") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE129221_PC9GR_high_MFE_TX$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE129221_PC9GR_control_high_MFE_TX_counts_fraction <- GSE129221_PC9GR_control_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE129221_PC9GR_control_total_counts$total_counts

GSE129221_PC9GR_PC9GR_apatinib_total_counts <- dplyr::filter(GSE129221_PC9GR_norm_TX_aggregated_data_avg_counts, condition == "PC9GR_apatinib") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE129221_PC9GR_PC9GR_apatinib_high_MFE_TX_counts <- dplyr::filter(GSE129221_PC9GR_norm_TX_aggregated_data_avg_counts, condition == "PC9GR_apatinib") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE129221_PC9GR_high_MFE_TX$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE129221_PC9GR_PC9GR_apatinib_high_MFE_TX_counts_fraction <- GSE129221_PC9GR_PC9GR_apatinib_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE129221_PC9GR_PC9GR_apatinib_total_counts$total_counts

# Calculate the proportions for the Z-test
p_control <- GSE129221_PC9GR_control_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE129221_PC9GR_control_total_counts$total_counts
p_apatinib <- GSE129221_PC9GR_PC9GR_apatinib_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE129221_PC9GR_PC9GR_apatinib_total_counts$total_counts

# Calculate the pooled proportion
pooled_prop <- (GSE129221_PC9GR_control_high_MFE_TX_counts$total_counts_high_MFE_TX + GSE129221_PC9GR_PC9GR_apatinib_high_MFE_TX_counts$total_counts_high_MFE_TX) /
  (GSE129221_PC9GR_control_total_counts$total_counts + GSE129221_PC9GR_PC9GR_apatinib_total_counts$total_counts)

# Calculate the standard error (SE)
se <- sqrt(pooled_prop * (1 - pooled_prop) * (1 / GSE129221_PC9GR_control_total_counts$total_counts + 1 / GSE129221_PC9GR_PC9GR_apatinib_total_counts$total_counts))

# Calculate the Z-statistic
z_stat <- (p_control - p_apatinib) / se

# Calculate p-value from Z-statistic (two-tailed test)
GSE129221_PC9GR_z_test_counts_75_p_value <- 2 * pnorm(-abs(z_stat))

# Output the results
cat("Two-proportion Z-test p-value:", GSE129221_PC9GR_z_test_counts_75_p_value, "\n")
cat("Z-statistic for the test:", z_stat, "\n")
cat("Fraction of high MFE TX in Control:", p_control, "\n")
cat("Fraction of high MFE TX in PC9GR_apatinib:", p_apatinib, "\n")
cat("Net change in high MFE TX counts drug vs control:", p_apatinib - p_control, "\n")





