# GSE62056 EZH2 Inhibitor on germinal center B cell-like diffuse large B cell lymphoma KARPAS-422 cell line.  ####
# These datasets have only two replicates per condition and should not be considered in the final analysis
# http://www.ilincs.org/apps/grein/?gse=GSE62056

Counts_GSE62056_GREIN <- read.delim("path_to/GSE62056/GSE62056_TranscriptLevel_Raw_data.csv", sep = ",", header = T, stringsAsFactors = F)
Counts_GSE62056_GREIN <- Counts_GSE62056_GREIN %>% remove_rownames %>% column_to_rownames(var="X") # Convert first column into row names in data frame
# Round counts down to the nearest integer
Counts_GSE62056_GREIN <- floor(Counts_GSE62056_GREIN)


# Access the Series Matrix
# Data_GSE62056 <- getGEO(GEO = "GSE62056")

# LOad the object
Data_GSE62056 <- readRDS("path_to/GREIN_series_matrices_data/Data_GSE62056.rds")


# Extract the phenotypic/clinical data matrix from the series matrix
Expdata_GSE62056 <- Data_GSE62056[["GSE62056_series_matrix.txt.gz"]]@phenoData@data


colnames(Expdata_GSE62056)[colnames(Expdata_GSE62056) == "treatment:ch1"] <- "condition" # Rename the column to have an easier identifier for the conditions
colnames(Expdata_GSE62056)[colnames(Expdata_GSE62056) == "cell line:ch1"] <- "cell_line" # Rename the column to have an easier identifier for the conditions




# IMPORTANT:
# It is absolutely critical that the columns of the count matrix and the rows of the column data (information about samples) are in the same order.

# Replace the row names of Expdata_GSE62056 (sampleID) with the same sample name [title] of [Counts_GSE182018]. 
# This will help to match sample names in both matrices.
# The outcome should be TRUE
all(rownames(Expdata_GSE62056) %in% colnames(Counts_GSE62056_GREIN))
all(colnames(Counts_GSE62056_GREIN) %in% rownames(Expdata_GSE62056))

# With the count matrix, Counts_GSE108308_GREIN, and the sample information, Expdata_GSE108308, we can construct a DESeqDataSet:
dds_GSE62056 <- DESeqDataSetFromMatrix(countData = Counts_GSE62056_GREIN,
                                        colData = Expdata_GSE62056,
                                        design = ~ condition)
dds_GSE62056




# DATA QUALITY ASSESSMENT MIA_PACA2 COUNTS
# Before performing differential expression analysis, we perform data quality assessment by sample clustering and visualization
library("pheatmap")
# We log transform the counts
ntd <- normTransform(dds_GSE62056)
# Heat map of the count matrix
select <- order(rowMeans(counts(dds_GSE62056,normalized=FALSE)),
                decreasing=TRUE)[1:25]
df <- as.data.frame(colData(dds_GSE62056)[,c("condition","type")])
pheatmap(assay(ntd)[select,], cluster_rows=FALSE, show_rownames=FALSE,
         cluster_cols=FALSE, annotation_col=df)



# Heatmap of the sample-to-sample distances
# A heatmap of this distance matrix gives us an overview over similarities and dissimilarities between samples
# Transform the values
vsd <- vst(dds_GSE62056, blind=FALSE)
# rld <- rlog(dds_GSE62056, blind=FALSE)
head(assay(vsd), 3)

# Apply the dist function to the transpose of the transformed count matrix to get sample-to-sample distances
sampleDists <- dist(t(assay(vsd)))

# Condition
library("RColorBrewer")
sampleDistMatrix <- as.matrix(sampleDists)
rownames(sampleDistMatrix) <- paste(vsd$condition, vsd$type, sep="-")
colnames(sampleDistMatrix) <- NULL
colors <- colorRampPalette( rev(brewer.pal(9, "Blues")) )(255)
pheatmap(sampleDistMatrix,
         clustering_distance_rows=sampleDists,
         clustering_distance_cols=sampleDists,
         col=colors)

# Principal component plot of the samples
plotPCA(vsd, intgroup="condition")






# DIFFERENTIAL EXPRESSION ANALYSIS
# We perform a minimal pre-filtering to keep only rows that have at least 3 reads total
keep <- rowSums(counts(dds_GSE62056)) >= 3
dds_GSE62056 <- dds_GSE62056[keep,]
table(keep) # This shows how many transcripts have been removed after the filtering
nrow(dds_GSE62056) # to confirm the filtered transcripts

# DIFFERENTIAL EXPRESSION ANALYSIS
dds_GSE62056 <- DESeq(dds_GSE62056) # The DESeq() function normalizes the read counts, estimates dispersions, and fits the linear model, all in one go
# dds_GSE62056 <- DESeq(dds_GSE62056, betaPrior = T)  The betaPrior = T opton tells DESeq2 to squeeze the log Fold Changes of lowly expressed genes toward zero.

# If I want to see the normalized counts generated in the DESeq object:
# norm_dds_GSE62056 <- counts(dds_GSE62056, normalized=TRUE)

# resultsNames(dds_GSE62056) # lists the coefficients
# plotDispEsts(dds_GSE62056) # Plot the dispersions
# Each black dot in the plot represents the dispersion for one gene. The red line is fit to data (black bots),
# then the dispersions are squeezed toward the red line, resulting the final (blue) dispersion estimates. Usually,
# the dispersion is highest at the low counts and levels off at higher counts.


# Specify the conditions to contrast for differential expression analysis
res_GSE62056_CPI360 <- results(dds_GSE62056, contrast=c("condition","CPI360","DMSO")) # to specify the samples to contrast
res_GSE62056_CPI360
# Get a summary of the results
summary(res_GSE62056_CPI360)

res_GSE62056_EPZ6438 <- results(dds_GSE62056, contrast=c("condition","EPZ6438","DMSO")) # to specify the samples to contrast
res_GSE62056_EPZ6438
# Get a summary of the results
summary(res_GSE62056_EPZ6438)

res_GSE62056_GSK126 <- results(dds_GSE62056, contrast=c("condition","GSK126","DMSO")) # to specify the samples to contrast
res_GSE62056_GSK126
# Get a summary of the results
summary(res_GSE62056_GSK126)



# Plot the log2 Fold Changes as function of expression:
plotMA(res_GSE62056_CPI360,alpha = 0.05)
abline(h=c(-2,2),col = "red")

# Transform the row names into a column
res_GSE62056_CPI360_df <- data.frame(res_GSE62056_CPI360)
res_GSE62056_CPI360 <- tibble::rownames_to_column(res_GSE62056_CPI360_df, "ensembl_transcript_id")



# Join the expression change values with the Table_ANNOTATED containing MFE values
MFE_res_GSE62056_CPI360 <- dplyr::inner_join(Table_ANNOTATED, res_GSE62056_CPI360, by="ensembl_transcript_id") %>% # The file 'Table' contains the Normalized_MFE values of all ANNOTATED transcripts
  dplyr::filter(padj < 0.05) 


# Generate a scatter plot Log2_FC vs Normalized_MFE
Plot_GSE62056_CPI360 <- ggplot(MFE_res_GSE62056_CPI360, aes(y=Normalized_MFE, x=log2FoldChange)) +
  geom_point(size=1.5, alpha=0.3)+
  theme_classic() +
  theme(legend.position="none") +
  geom_vline(xintercept = 0, size=0.3) +
  #xlim(-5.5,5.5) +
  theme(axis.title = element_text(size = 20)) +
  theme(plot.title = element_text(size = 15)) +
  labs(y="DGfold / nt (kcal/mol)",x="Log2_FC_expression",title="GSE62056_CPI360_Log2_FC_adj.P<0.05")
print(Plot_GSE62056_CPI360)



# Look at the mean log2_FC
MFE_res_GSE62056_CPI360_UP <- dplyr::filter(MFE_res_GSE62056_CPI360, log2FoldChange > 0)
Mean_MFE_res_GSE62056_CPI360_UP <- mean(MFE_res_GSE62056_CPI360_UP$Normalized_MFE)

MFE_res_GSE62056_CPI360_DOWN <- dplyr::filter(MFE_res_GSE62056_CPI360, log2FoldChange < 0)
Mean_MFE_res_GSE62056_CPI360_DOWN <- mean(MFE_res_GSE62056_CPI360_DOWN$Normalized_MFE)

TTEST_MFE_res_GSE62056_CPI360_all_UP_vs_DOWN <- t.test(MFE_res_GSE62056_CPI360_DOWN$Normalized_MFE, MFE_res_GSE62056_CPI360_UP$Normalized_MFE, paired=FALSE)

# Add K-S test to look at the differences between the up-regukated and down-regulated genes
ks_test_res_GSE62056_CPI360_all_UP_vs_DOWN <- ks.test(MFE_res_GSE62056_CPI360_DOWN$Normalized_MFE, MFE_res_GSE62056_CPI360_UP$Normalized_MFE)


quantile_075_MFE_res_GSE62056_CPI360_UP <- quantile(MFE_res_GSE62056_CPI360_UP$Normalized_MFE, probs = c(0.75)) 
quantile_075_MFE_res_GSE62056_CPI360_DOWN <- quantile(MFE_res_GSE62056_CPI360_DOWN$Normalized_MFE, probs = c(0.75)) 
# Values above 0.75 quantile
ks_test_MFE_075_above <- ks.test(MFE_res_GSE62056_CPI360_UP$Normalized_MFE[MFE_res_GSE62056_CPI360_UP$Normalized_MFE >= quantile_075_MFE_res_GSE62056_CPI360_UP],
                                 MFE_res_GSE62056_CPI360_DOWN$Normalized_MFE[MFE_res_GSE62056_CPI360_DOWN$Normalized_MFE >= quantile_075_MFE_res_GSE62056_CPI360_DOWN])

# Look at the differences between the 0.25 quantile 
quantile_025_MFE_res_GSE62056_CPI360_UP <- quantile(MFE_res_GSE62056_CPI360_UP$Normalized_MFE, probs = c(0.25)) 
quantile_025_MFE_res_GSE62056_CPI360_DOWN <- quantile(MFE_res_GSE62056_CPI360_DOWN$Normalized_MFE, probs = c(0.25)) 
# Values below 0.25 quantile
ks_test_MFE_025_below <- ks.test(MFE_res_GSE62056_CPI360_UP$Normalized_MFE[MFE_res_GSE62056_CPI360_UP$Normalized_MFE <= quantile_025_MFE_res_GSE62056_CPI360_UP],
                                 MFE_res_GSE62056_CPI360_DOWN$Normalized_MFE[MFE_res_GSE62056_CPI360_DOWN$Normalized_MFE <= quantile_025_MFE_res_GSE62056_CPI360_DOWN])





# Permutation test MFE changes
# Combine the data into a single data frame with labels
upregulated <- data.frame(MFE = MFE_res_GSE62056_CPI360_UP$Normalized_MFE, Group = "Up")
downregulated <- data.frame(MFE = MFE_res_GSE62056_CPI360_DOWN$Normalized_MFE, Group = "Down")
combined_data <- bind_rows(upregulated, downregulated)

# Observed difference in means
GSE62056_CPI360_observed_diff <- mean(MFE_res_GSE62056_CPI360_UP$Normalized_MFE) - mean(MFE_res_GSE62056_CPI360_DOWN$Normalized_MFE)

# Number of permutations
n_permutations <- 10000

# Initialize a vector to store the permuted differences
GSE62056_CPI360_permuted_diffs <- numeric(n_permutations)

# Permutation test
set.seed(123)  # Set seed for reproducibility
for (i in 1:n_permutations) {
  # Permute the Group labels
  permuted_labels <- sample(combined_data$Group)
  
  # Calculate the mean MFE for each permuted group
  permuted_up_mean <- mean(combined_data$MFE[permuted_labels == "Up"])
  permuted_down_mean <- mean(combined_data$MFE[permuted_labels == "Down"])
  
  # Calculate the difference in means for the permuted groups
  GSE62056_CPI360_permuted_diffs[i] <- permuted_up_mean - permuted_down_mean
}

# Calculate the p-value
GSE62056_CPI360_p_value <- (sum(abs(GSE62056_CPI360_permuted_diffs) >= abs(GSE62056_CPI360_observed_diff)) + 1) / (n_permutations + 1)

# Output the results
cat("Observed difference in GSE62056_CPI360 means MFE_UP - MFE_DOWN:", GSE62056_CPI360_observed_diff, "\n")
cat("GSE62056_CPI360 P-value from permutation test:", GSE62056_CPI360_p_value, "\n")









