## GSE62056 High MFE TX fraction changes ####
# Determine whether within the differentially expressed genes there is a significant up-regulation of high MFE transcripts:
# Define high MFE transcripts by taking the 75th percentile of the combined MFE distributions of control and drug-treated samples.
# Count the number of transcripts in the significantly up- and down-regulated genes that have MFE values above this threshold.
# Perform a Fisher’s exact test to compare the proportions of high MFE transcripts between the two groups.



# Analysis GSE62056
# Extract the normalized count data
# The minimal pre-filtering has already been done in the previous steps
GSE62056_norm_TX_counts <- counts(dds_GSE62056, normalized=TRUE) # This object is already a matrix
GSE62056_norm_TX_counts_df <- as.data.frame(GSE62056_norm_TX_counts)
# Convert row names to column
GSE62056_norm_TX_counts_df$ensembl_transcript_id <- rownames(GSE62056_norm_TX_counts_df)
# Remove row names
rownames(GSE62056_norm_TX_counts_df) <- NULL

# Move ensembl_transcript_id column to the first position
GSE62056_norm_TX_counts_df <- GSE62056_norm_TX_counts_df[, c("ensembl_transcript_id", setdiff(names(GSE62056_norm_TX_counts_df), "ensembl_transcript_id"))]

# Remove everything after the dot (including the dot itself) in the ensembl_transcript_id column
GSE62056_norm_TX_counts_df$ensembl_transcript_id <- sub("\\..*", "", GSE62056_norm_TX_counts_df$ensembl_transcript_id)

# Join the counts with the Table_ANNOTATED containing MFE values and heat capacity values
GSE62056_norm_TX_counts_MFE_df <- dplyr::inner_join(Table_ANNOTATED, GSE62056_norm_TX_counts_df, by="ensembl_transcript_id") %>%
  dplyr::select(ensembl_transcript_id_version, ensembl_transcript_id, ensembl_gene_id, external_gene_name, transcript_is_canonical, Transcript_length, 
                GSM1519048, GSM1519049, GSM1519050, GSM1519051, GSM1519052, GSM1519053, GSM1519054, GSM1519055, Normalized_MFE, Temperature, Specific_heat)







# GSE62056_CPI360
# Convert from wide to long format
GSE62056_CPI360_norm_TX_counts_MFE_df <- GSE62056_norm_TX_counts_MFE_df %>%
  dplyr::select(ensembl_transcript_id_version, ensembl_transcript_id, ensembl_gene_id, external_gene_name, transcript_is_canonical, Transcript_length, 
                GSM1519048, GSM1519049, GSM1519050, GSM1519051, Normalized_MFE, Temperature, Specific_heat) %>%
  dplyr::filter(ensembl_transcript_id %in% MFE_res_GSE62056_CPI360$ensembl_transcript_id)

# Identify the 75th percentile of the combined MFE distributions of control and drug-treated samples
quantile_075_GSE62056_CPI360_norm_TX_counts_MFE_df <- quantile(GSE62056_CPI360_norm_TX_counts_MFE_df$Normalized_MFE, probs = c(0.75))

# Select all the transcripts with Normalized_MFE values above the 75th percentile
GSE62056_CPI360_high_MFE_TX <- dplyr::filter(GSE62056_CPI360_norm_TX_counts_MFE_df, Normalized_MFE > quantile_075_GSE62056_CPI360_norm_TX_counts_MFE_df)

# Count the number of transcripts in the significantly up- and down-regulated pools that have MFE values above this threshold.
GSE62056_CPI360_high_MFE_TX_in_UP <- dplyr::filter(MFE_res_GSE62056_CPI360_UP, ensembl_transcript_id_version %in% GSE62056_CPI360_high_MFE_TX$ensembl_transcript_id_version)
GSE62056_CPI360_high_MFE_TX_in_DOWN <- dplyr::filter(MFE_res_GSE62056_CPI360_DOWN, ensembl_transcript_id_version %in% GSE62056_CPI360_high_MFE_TX$ensembl_transcript_id_version)

# Get total counts for UP and DOWN-regulated genes
GSE62056_CPI360_total_UP <- nrow(MFE_res_GSE62056_CPI360_UP)
GSE62056_CPI360_total_DOWN <- nrow(MFE_res_GSE62056_CPI360_DOWN)

# Get counts for high MFE TX in UP and DOWN-regulated genes
GSE62056_CPI360_count_high_MFE_UP <- nrow(GSE62056_CPI360_high_MFE_TX_in_UP)
GSE62056_CPI360_count_high_MFE_DOWN <- nrow(GSE62056_CPI360_high_MFE_TX_in_DOWN)

# Calculate the proportions for the Z-test
p_up <- GSE62056_CPI360_count_high_MFE_UP / GSE62056_CPI360_total_UP
p_down <- GSE62056_CPI360_count_high_MFE_DOWN / GSE62056_CPI360_total_DOWN

# Calculate the pooled proportion
pooled_prop <- (GSE62056_CPI360_count_high_MFE_UP + GSE62056_CPI360_count_high_MFE_DOWN) /
  (GSE62056_CPI360_total_UP + GSE62056_CPI360_total_DOWN)

# Calculate the standard error (SE)
se <- sqrt(pooled_prop * (1 - pooled_prop) * (1 / GSE62056_CPI360_total_UP + 1 / GSE62056_CPI360_total_DOWN))

# Calculate the Z-statistic
z_stat <- (p_up - p_down) / se

# Calculate p-value from Z-statistic (two-tailed test)
GSE62056_CPI360_z_test_MFE_p_value <- 2 * pnorm(-abs(z_stat))

# Output the results
cat("Two-proportion Z-test p-value:", GSE62056_CPI360_z_test_MFE_p_value, "\n")
cat("Z-statistic for the test:", z_stat, "\n")
cat("Fraction of high MFE TX in UP-regulated genes:", p_up, "\n")
cat("Fraction of high MFE TX in DOWN-regulated genes:", p_down, "\n")
cat("Net change in high MFE TX counts UP vs DOWN:", p_up - p_down, "\n")

# Look at the fractions
GSE62056_CPI360_high_MFE_in_UP_fraction <- GSE62056_CPI360_count_high_MFE_UP / GSE62056_CPI360_total_UP
GSE62056_CPI360_high_MFE_in_DOWN_fraction <- GSE62056_CPI360_count_high_MFE_DOWN / GSE62056_CPI360_total_DOWN

cat("Fraction of high MFE TX in UP-regulated genes:", GSE62056_CPI360_high_MFE_in_UP_fraction, "\n")
cat("Fraction of high MFE TX in DOWN-regulated genes:", GSE62056_CPI360_high_MFE_in_DOWN_fraction, "\n")
cat("Mean of high MFE TX in UP-regulated genes:", mean(GSE62056_CPI360_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mean of high MFE TX in DOWN-regulated genes:", mean(GSE62056_CPI360_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")
cat("Mode of high MFE TX in UP-regulated genes:", calculate_mode(GSE62056_CPI360_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mode of high MFE TX in DOWN-regulated genes:", calculate_mode(GSE62056_CPI360_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")




