# Determine the impact of these changes in terms of fraction of total counts:
# Calculate the fraction of total counts of high MFE transcripts in control and drug-treated groups. 
# This is done by summing the counts of the high MFE transcripts and dividing by the total counts in each group.
# Fisher’s exact test to compare the proportions of high MFE transcripts counts between the two groups.


# Convert from wide to long format
GSE62056_CPI360_long_data <- GSE62056_CPI360_norm_TX_counts_MFE_df %>%
  pivot_longer(
    cols = starts_with("GSM"),      # Select all columns starting with "GSM"
    names_to = "replicate",         # Name of the new column for replicate identifiers
    values_to = "counts"            # Name of the new column for the counts
  )

# Add a condition column based on the replicate
GSE62056_CPI360_long_data <- GSE62056_CPI360_long_data %>%
  mutate(condition = ifelse(replicate %in% c("GSM1519048", "GSM1519049"), "Control", "CPI360"))

# Aggregate the replicates for each condition
GSE62056_CPI360_norm_TX_aggregated_data_avg_counts <- GSE62056_CPI360_long_data %>%
  group_by(ensembl_transcript_id_version, condition, Normalized_MFE, Specific_heat) %>%
  summarise(
    avg_counts = mean(counts),
    .groups = 'drop'
  )

# Calculate the fractions of high MFE transcripts in Control and CPI360
GSE62056_CPI360_control_total_counts <- dplyr::filter(GSE62056_CPI360_norm_TX_aggregated_data_avg_counts, condition == "Control") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE62056_CPI360_control_high_MFE_TX_counts <- dplyr::filter(GSE62056_CPI360_norm_TX_aggregated_data_avg_counts, condition == "Control") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE62056_CPI360_high_MFE_TX$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE62056_CPI360_control_high_MFE_TX_counts_fraction <- GSE62056_CPI360_control_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE62056_CPI360_control_total_counts$total_counts

GSE62056_CPI360_CPI360_total_counts <- dplyr::filter(GSE62056_CPI360_norm_TX_aggregated_data_avg_counts, condition == "CPI360") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE62056_CPI360_CPI360_high_MFE_TX_counts <- dplyr::filter(GSE62056_CPI360_norm_TX_aggregated_data_avg_counts, condition == "CPI360") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE62056_CPI360_high_MFE_TX$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE62056_CPI360_CPI360_high_MFE_TX_counts_fraction <- GSE62056_CPI360_CPI360_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE62056_CPI360_CPI360_total_counts$total_counts

# Calculate the proportions for the Z-test
p_control <- GSE62056_CPI360_control_high_MFE_TX_counts_fraction
p_CPI360 <- GSE62056_CPI360_CPI360_high_MFE_TX_counts_fraction

# Calculate the pooled proportion
pooled_prop <- (GSE62056_CPI360_control_high_MFE_TX_counts$total_counts_high_MFE_TX + GSE62056_CPI360_CPI360_high_MFE_TX_counts$total_counts_high_MFE_TX) /
  (GSE62056_CPI360_control_total_counts$total_counts + GSE62056_CPI360_CPI360_total_counts$total_counts)

# Calculate the standard error (SE)
se <- sqrt(pooled_prop * (1 - pooled_prop) * (1 / GSE62056_CPI360_control_total_counts$total_counts + 1 / GSE62056_CPI360_CPI360_total_counts$total_counts))

# Calculate the Z-statistic
z_stat <- (p_control - p_CPI360) / se

# Calculate p-value from Z-statistic (two-tailed test)
GSE62056_CPI360_z_test_counts_75_p_value <- 2 * pnorm(-abs(z_stat))

# Output the results
cat("Two-proportion Z-test p-value:", GSE62056_CPI360_z_test_counts_75_p_value, "\n")
cat("Z-statistic for the test:", z_stat, "\n")
cat("Fraction of high MFE TX in Control:", p_control, "\n")
cat("Fraction of high MFE TX in CPI360:", p_CPI360, "\n")
cat("Net change in high MFE TX counts Control vs CPI360:", p_control - p_CPI360, "\n")

# Output the fractions
cat("Control high MFE TX as fraction of total counts:", GSE62056_CPI360_control_high_MFE_TX_counts_fraction, "\n")
cat("CPI360 high MFE TX as fraction of total counts:", GSE62056_CPI360_CPI360_high_MFE_TX_counts_fraction, "\n")
cat("Net change counts high MFE TX drug vs control:", GSE62056_CPI360_CPI360_high_MFE_TX_counts_fraction - GSE62056_CPI360_control_high_MFE_TX_counts_fraction, "\n")




