# Identify all the transcriots with MFE values below the 25th percentile
GSE62056_CPI360_low_MFE_TX_total <- dplyr::filter(GSE62056_CPI360_norm_TX_counts_MFE_df, Normalized_MFE < GSE62056_CPI360_MFE_all_TX_25_percentile)

# Fraction of total low MFE transcripts counts in control and drug-treated groups
GSE62056_CPI360_control_total_counts <- dplyr::filter(GSE62056_CPI360_norm_TX_aggregated_data_avg_counts, condition == "Control") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE62056_CPI360_control_low_MFE_TX_counts <- dplyr::filter(GSE62056_CPI360_norm_TX_aggregated_data_avg_counts, condition == "Control") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE62056_CPI360_low_MFE_TX_total$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_low_MFE_TX = sum(avg_counts))

GSE62056_CPI360_control_low_MFE_TX_counts_fraction <- GSE62056_CPI360_control_low_MFE_TX_counts$total_counts_low_MFE_TX / GSE62056_CPI360_control_total_counts$total_counts
cat("Control low MFE TX fraction:", GSE62056_CPI360_control_low_MFE_TX_counts_fraction, "\n") # This value goes in the summary table

GSE62056_CPI360_CPI360_total_counts <- dplyr::filter(GSE62056_CPI360_norm_TX_aggregated_data_avg_counts, condition == "CPI360") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE62056_CPI360_CPI360_low_MFE_TX_counts <- dplyr::filter(GSE62056_CPI360_norm_TX_aggregated_data_avg_counts, condition == "CPI360") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE62056_CPI360_low_MFE_TX_total$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_low_MFE_TX = sum(avg_counts))

GSE62056_CPI360_CPI360_low_MFE_TX_counts_fraction <- GSE62056_CPI360_CPI360_low_MFE_TX_counts$total_counts_low_MFE_TX / GSE62056_CPI360_CPI360_total_counts$total_counts
cat("CPI360 low MFE TX fraction:", GSE62056_CPI360_CPI360_low_MFE_TX_counts_fraction, "\n") # This value goes in the summary table

# Now, perform the Two-Proportion Z-Test

# Proportions for Control and CPI360 groups
p_control <- GSE62056_CPI360_control_low_MFE_TX_counts_fraction
p_CPI360 <- GSE62056_CPI360_CPI360_low_MFE_TX_counts_fraction

# Calculate the pooled proportion
pooled_prop <- (GSE62056_CPI360_control_low_MFE_TX_counts$total_counts_low_MFE_TX + GSE62056_CPI360_CPI360_low_MFE_TX_counts$total_counts_low_MFE_TX) /
  (GSE62056_CPI360_control_total_counts$total_counts + GSE62056_CPI360_CPI360_total_counts$total_counts)

# Standard error (SE) for the difference in proportions
se <- sqrt(pooled_prop * (1 - pooled_prop) * (1 / GSE62056_CPI360_control_total_counts$total_counts + 1 / GSE62056_CPI360_CPI360_total_counts$total_counts))

# Calculate Z-statistic
z_stat <- (p_control - p_CPI360) / se

# p-value from Z-statistic (two-tailed test)
GSE62056_CPI360_z_test_counts_25_p_value <- 2 * pnorm(-abs(z_stat))

# Output results
cat("Two-proportion Z-test p-value:", GSE62056_CPI360_z_test_counts_25_p_value, "\n")
cat("Z-statistic for low MFE TX counts comparison:", z_stat, "\n")
cat("Control low MFE TX fraction:", p_control, "\n")
cat("CPI360 low MFE TX fraction:", p_CPI360, "\n")
cat("Net change in low MFE TX counts Control vs CPI360:", p_control - p_CPI360, "\n")

# Output the fractions
cat("Control low MFE TX as fraction of total counts:", GSE62056_CPI360_control_low_MFE_TX_counts_fraction, "\n")
cat("CPI360 low MFE TX as fraction of total counts:", GSE62056_CPI360_CPI360_low_MFE_TX_counts_fraction, "\n")
cat("Net change counts low MFE TX drug vs control:", GSE62056_CPI360_CPI360_low_MFE_TX_counts_fraction - GSE62056_CPI360_control_low_MFE_TX_counts_fraction, "\n")












