# Convert from wide to long format
GSE62056_GSK126_long_data <- GSE62056_GSK126_norm_TX_counts_MFE_df %>%
  pivot_longer(
    cols = starts_with("GSM"),      # Select all columns starting with "GSM"
    names_to = "replicate",         # Name of the new column for replicate identifiers
    values_to = "counts"            # Name of the new column for the counts
  )

# Add a condition column based on the replicate
GSE62056_GSK126_long_data <- GSE62056_GSK126_long_data %>%
  mutate(condition = ifelse(replicate %in% c("GSM1519048", "GSM1519049"), "Control", "GSK126"))

# Aggregate the replicates for each condition
GSE62056_GSK126_norm_TX_aggregated_data_avg_counts <- GSE62056_GSK126_long_data %>%
  group_by(ensembl_transcript_id_version, condition, Normalized_MFE, Specific_heat) %>%
  summarise(
    avg_counts = mean(counts),
    .groups = 'drop'
  )

# Fraction of total high MFE transcripts counts in control and drug-treated groups
GSE62056_GSK126_control_total_counts <- dplyr::filter(GSE62056_GSK126_norm_TX_aggregated_data_avg_counts, condition == "Control") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE62056_GSK126_control_high_MFE_TX_counts <- dplyr::filter(GSE62056_GSK126_norm_TX_aggregated_data_avg_counts, condition == "Control") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE62056_GSK126_high_MFE_TX$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE62056_GSK126_control_high_MFE_TX_counts_fraction <- GSE62056_GSK126_control_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE62056_GSK126_control_total_counts$total_counts

GSE62056_GSK126_GSK126_total_counts <- dplyr::filter(GSE62056_GSK126_norm_TX_aggregated_data_avg_counts, condition == "GSK126") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE62056_GSK126_GSK126_high_MFE_TX_counts <- dplyr::filter(GSE62056_GSK126_norm_TX_aggregated_data_avg_counts, condition == "GSK126") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE62056_GSK126_high_MFE_TX$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE62056_GSK126_GSK126_high_MFE_TX_counts_fraction <- GSE62056_GSK126_GSK126_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE62056_GSK126_GSK126_total_counts$total_counts

# Now, perform the Two-Proportion Z-Test

# Proportions for Control and GSK126 groups
p_control <- GSE62056_GSK126_control_high_MFE_TX_counts_fraction
p_GSK126 <- GSE62056_GSK126_GSK126_high_MFE_TX_counts_fraction

# Calculate the pooled proportion
pooled_prop <- (GSE62056_GSK126_control_high_MFE_TX_counts$total_counts_high_MFE_TX + GSE62056_GSK126_GSK126_high_MFE_TX_counts$total_counts_high_MFE_TX) /
  (GSE62056_GSK126_control_total_counts$total_counts + GSE62056_GSK126_GSK126_total_counts$total_counts)

# Standard error (SE) for the difference in proportions
se <- sqrt(pooled_prop * (1 - pooled_prop) * (1 / GSE62056_GSK126_control_total_counts$total_counts + 1 / GSE62056_GSK126_GSK126_total_counts$total_counts))

# Calculate Z-statistic
z_stat <- (p_control - p_GSK126) / se

# p-value from Z-statistic (two-tailed test)
GSE62056_GSK126_z_test_counts_75_p_value <- 2 * pnorm(-abs(z_stat))

# Output results
cat("Two-proportion Z-test p-value for high MFE TX comparison between Control and GSK126:", GSE62056_GSK126_z_test_counts_75_p_value, "\n")
cat("Z-statistic for high MFE TX counts comparison:", z_stat, "\n")
cat("Control high MFE TX fraction:", p_control, "\n")
cat("GSK126 high MFE TX fraction:", p_GSK126, "\n")
cat("Net change in high MFE TX counts Control vs GSK126:", p_control - p_GSK126, "\n")

# Output the fractions
cat("Control high MFE TX as fraction of total counts:", GSE62056_GSK126_control_high_MFE_TX_counts_fraction, "\n")
cat("GSK126 high MFE TX as fraction of total counts:", GSE62056_GSK126_GSK126_high_MFE_TX_counts_fraction, "\n")
cat("Net change counts high MFE TX drug vs control:", GSE62056_GSK126_GSK126_high_MFE_TX_counts_fraction - GSE62056_GSK126_control_high_MFE_TX_counts_fraction, "\n")




