## GSE135514 High MFE TX fraction changes ####
# Determine whether within the differentially expressed genes there is a significant up-regulation of high MFE transcripts:
# Define high MFE transcripts by taking the 75th percentile of the combined MFE distributions of control and drug-treated samples.
# Count the number of transcripts in the significantly up- and down-regulated genes that have MFE values above this threshold.
# Perform a Fisher’s exact test to compare the proportions of high MFE transcripts between the two groups. 


# Analysis GSE135514
# Extract the normalized count data
# The minimal pre-filtering has already been done in the previous steps
GSE135514_norm_TX_counts <- counts(dds_GSE135514, normalized=TRUE) # This object is already a matrix
GSE135514_norm_TX_counts_df <- as.data.frame(GSE135514_norm_TX_counts)
# Convert row names to column
GSE135514_norm_TX_counts_df$ensembl_transcript_id <- rownames(GSE135514_norm_TX_counts_df)
# Remove row names
rownames(GSE135514_norm_TX_counts_df) <- NULL

# Move ensembl_transcript_id column to the first position
GSE135514_norm_TX_counts_df <- GSE135514_norm_TX_counts_df[, c("ensembl_transcript_id", setdiff(names(GSE135514_norm_TX_counts_df), "ensembl_transcript_id"))]

# Remove everything after the dot (including the dot itself) in the ensembl_transcript_id column
GSE135514_norm_TX_counts_df$ensembl_transcript_id <- sub("\\..*", "", GSE135514_norm_TX_counts_df$ensembl_transcript_id)

# Join the counts with the Table_ANNOTATED containing MFE values and heat capacity values
GSE135514_norm_TX_counts_MFE_df <- dplyr::inner_join(Table_ANNOTATED, GSE135514_norm_TX_counts_df, by="ensembl_transcript_id") %>%
  dplyr::select(ensembl_transcript_id_version, ensembl_transcript_id, ensembl_gene_id, external_gene_name, transcript_is_canonical, Transcript_length, 
                GSM4013426, GSM4013427, GSM4013428, GSM4013430, GSM4013431, GSM4013432, GSM4013434, GSM4013435, GSM4013436, GSM4013438, GSM4013439, GSM4013440,
                GSM4013442, GSM4013443, GSM4013444, GSM4013446, GSM4013447, GSM4013448, GSM4013450, GSM4013451, GSM4013452, GSM4013454, GSM4013455, GSM4013456,
                Normalized_MFE, Temperature, Specific_heat)
# There are a few transcripts with huge n. of counts. Set a threshold to 100,000
GSE135514_norm_TX_counts_MFE_df <- GSE135514_norm_TX_counts_MFE_df %>%
  dplyr::filter(GSM4013426 < 100000 & GSM4013427 < 100000 & GSM4013428 < 100000 & GSM4013430 < 100000 & GSM4013431 < 100000 & GSM4013432 < 100000 & GSM4013434 < 100000 & GSM4013435 < 100000 & GSM4013436 < 100000 & GSM4013438 < 100000 & GSM4013439 < 100000 & GSM4013440 < 100000 & GSM4013442 < 100000 & GSM4013443 < 100000 & GSM4013444 < 100000 & GSM4013446 < 100000 & GSM4013447 < 100000 & GSM4013448 < 100000 & GSM4013450 < 100000 & GSM4013451 < 100000 & GSM4013452 < 100000 & GSM4013454 < 100000 & GSM4013455 < 100000 & GSM4013456 < 100000)






# GSE135514_Sal_24h
# Convert from wide to long format
GSE135514_Sal_24h_norm_TX_counts_MFE_df <- GSE135514_norm_TX_counts_MFE_df %>%
  dplyr::select(ensembl_transcript_id_version, ensembl_transcript_id, ensembl_gene_id, external_gene_name, transcript_is_canonical, Transcript_length, 
                GSM4013426, GSM4013427, GSM4013428, GSM4013430, GSM4013431, GSM4013432, Normalized_MFE, Temperature, Specific_heat) %>%
  dplyr::filter(ensembl_transcript_id %in% MFE_res_GSE135514_Sal_24h$ensembl_transcript_id) 

# Identify the 75th percentile of the combined MFE distributions of control and drug-treated samples
quantile_075_GSE135514_Sal_24h_norm_TX_counts_MFE_df <- quantile(GSE135514_Sal_24h_norm_TX_counts_MFE_df$Normalized_MFE, probs = c(0.75))

# Select all the transcripts with Normalized_MFE values above the 75th percentile
GSE135514_Sal_24h_high_MFE_TX <- dplyr::filter(GSE135514_Sal_24h_norm_TX_counts_MFE_df, Normalized_MFE > quantile_075_GSE135514_Sal_24h_norm_TX_counts_MFE_df)

# Count the number of transcripts in the significantly up- and down-regulated pools that have MFE values above this threshold.
GSE135514_Sal_24h_high_MFE_TX_in_UP <- dplyr::filter(MFE_res_GSE135514_Sal_24h_UP, ensembl_transcript_id_version %in% GSE135514_Sal_24h_high_MFE_TX$ensembl_transcript_id_version)
GSE135514_Sal_24h_high_MFE_TX_in_DOWN <- dplyr::filter(MFE_res_GSE135514_Sal_24h_DOWN, ensembl_transcript_id_version %in% GSE135514_Sal_24h_high_MFE_TX$ensembl_transcript_id_version)

# Calculate the fractions for high MFE TX in UP-regulated and DOWN-regulated genes
GSE135514_Sal_24h_total_UP <- nrow(MFE_res_GSE135514_Sal_24h_UP)
GSE135514_Sal_24h_total_DOWN <- nrow(MFE_res_GSE135514_Sal_24h_DOWN)
GSE135514_Sal_24h_count_high_MFE_UP <- nrow(GSE135514_Sal_24h_high_MFE_TX_in_UP)
GSE135514_Sal_24h_count_high_MFE_DOWN <- nrow(GSE135514_Sal_24h_high_MFE_TX_in_DOWN)

# Proportions for UP-regulated and DOWN-regulated groups
GSE135514_Sal_24h_high_MFE_in_UP_fraction <- GSE135514_Sal_24h_count_high_MFE_UP / GSE135514_Sal_24h_total_UP
GSE135514_Sal_24h_high_MFE_in_DOWN_fraction <- GSE135514_Sal_24h_count_high_MFE_DOWN / GSE135514_Sal_24h_total_DOWN

# Pooled proportion
pooled_prop <- (GSE135514_Sal_24h_count_high_MFE_UP + GSE135514_Sal_24h_count_high_MFE_DOWN) /
  (GSE135514_Sal_24h_total_UP + GSE135514_Sal_24h_total_DOWN)

# Standard error (SE) for the difference in proportions
se <- sqrt(pooled_prop * (1 - pooled_prop) * (1 / GSE135514_Sal_24h_total_UP + 1 / GSE135514_Sal_24h_total_DOWN))

# Z-statistic
z_stat <- (GSE135514_Sal_24h_high_MFE_in_UP_fraction - GSE135514_Sal_24h_high_MFE_in_DOWN_fraction) / se

# p-value (two-tailed test)
GSE135514_Sal_24h_z_test_MFE_p_value <- 2 * pnorm(-abs(z_stat))

# Output the results of the two-proportion Z-test
cat("Two-proportion Z-test p-value for high MFE TX in UP vs DOWN-regulated genes:", GSE135514_Sal_24h_z_test_MFE_p_value, "\n")
cat("Z-statistic for high MFE TX in UP vs DOWN-regulated genes:", z_stat, "\n")

# Output the fractions for high MFE in UP and DOWN-regulated genes
cat("Fraction of high MFE TX in UP-regulated genes:", GSE135514_Sal_24h_high_MFE_in_UP_fraction, "\n")
cat("Fraction of high MFE TX in DOWN-regulated genes:", GSE135514_Sal_24h_high_MFE_in_DOWN_fraction, "\n")

# Additional statistics (mean, mode) for high MFE TX in UP and DOWN-regulated genes
cat("Mean of high MFE TX in UP-regulated genes:", mean(GSE135514_Sal_24h_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mean of high MFE TX in DOWN-regulated genes:", mean(GSE135514_Sal_24h_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")
cat("Mode of high MFE TX in UP-regulated genes:", calculate_mode(GSE135514_Sal_24h_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mode of high MFE TX in DOWN-regulated genes:", calculate_mode(GSE135514_Sal_24h_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")




# Show data as violin plot
# Add a new column to indicate if the value is above the 75th percentile
MFE_res_GSE135514_Sal_24h$above_quantile_075 <- MFE_res_GSE135514_Sal_24h$Normalized_MFE > quantile_075_GSE135514_Sal_24h_norm_TX_counts_MFE_df

# Generate violin plot with conditional jitter coloring
ggplot(MFE_res_GSE135514_Sal_24h, aes(x = factor(log2FoldChange > 0), y = Normalized_MFE)) +
  geom_violin(fill = "white") +
  geom_jitter(aes(color = above_quantile_075), width = 0.1, size = 1, alpha = 0.1) +
  scale_color_manual(values = c("FALSE" = "black", "TRUE" = "blue")) +
  theme_classic() +
