# GSE135514_Sal_Das_72h
# Convert from wide to long format
GSE135514_Sal_Das_72h_norm_TX_counts_MFE_df <- GSE135514_norm_TX_counts_MFE_df %>%
  dplyr::select(ensembl_transcript_id_version, ensembl_transcript_id, ensembl_gene_id, external_gene_name, transcript_is_canonical, Transcript_length, 
                GSM4013442, GSM4013443, GSM4013444, GSM4013454, GSM4013455, GSM4013456, Normalized_MFE, Temperature, Specific_heat) %>%
  dplyr::filter(ensembl_transcript_id %in% MFE_res_GSE135514_Sal_Das_72h$ensembl_transcript_id) 

# Identify the 75th percentile of the combined MFE distributions of control and drug-treated samples
quantile_075_GSE135514_Sal_Das_72h_norm_TX_counts_MFE_df <- quantile(GSE135514_Sal_Das_72h_norm_TX_counts_MFE_df$Normalized_MFE, probs = c(0.75))

# Select all the transcripts with Normalized_MFE values above the 75th percentile
GSE135514_Sal_Das_72h_high_MFE_TX <- dplyr::filter(GSE135514_Sal_Das_72h_norm_TX_counts_MFE_df, Normalized_MFE > quantile_075_GSE135514_Sal_Das_72h_norm_TX_counts_MFE_df)

# Count the number of transcripts in the significantly up- and down-regulated pools that have MFE values above this threshold.
GSE135514_Sal_Das_72h_high_MFE_TX_in_UP <- dplyr::filter(MFE_res_GSE135514_Sal_Das_72h_UP, ensembl_transcript_id_version %in% GSE135514_Sal_Das_72h_high_MFE_TX$ensembl_transcript_id_version)
GSE135514_Sal_Das_72h_high_MFE_TX_in_DOWN <- dplyr::filter(MFE_res_GSE135514_Sal_Das_72h_DOWN, ensembl_transcript_id_version %in% GSE135514_Sal_Das_72h_high_MFE_TX$ensembl_transcript_id_version)

# Calculate the fractions for high MFE TX in UP-regulated and DOWN-regulated genes
GSE135514_Sal_Das_72h_total_UP <- nrow(MFE_res_GSE135514_Sal_Das_72h_UP)
GSE135514_Sal_Das_72h_total_DOWN <- nrow(MFE_res_GSE135514_Sal_Das_72h_DOWN)
GSE135514_Sal_Das_72h_count_high_MFE_UP <- nrow(GSE135514_Sal_Das_72h_high_MFE_TX_in_UP)
GSE135514_Sal_Das_72h_count_high_MFE_DOWN <- nrow(GSE135514_Sal_Das_72h_high_MFE_TX_in_DOWN)

# Proportions for UP-regulated and DOWN-regulated groups
GSE135514_Sal_Das_72h_high_MFE_in_UP_fraction <- GSE135514_Sal_Das_72h_count_high_MFE_UP / GSE135514_Sal_Das_72h_total_UP
GSE135514_Sal_Das_72h_high_MFE_in_DOWN_fraction <- GSE135514_Sal_Das_72h_count_high_MFE_DOWN / GSE135514_Sal_Das_72h_total_DOWN

# Pooled proportion
pooled_prop <- (GSE135514_Sal_Das_72h_count_high_MFE_UP + GSE135514_Sal_Das_72h_count_high_MFE_DOWN) /
  (GSE135514_Sal_Das_72h_total_UP + GSE135514_Sal_Das_72h_total_DOWN)

# Standard error (SE) for the difference in proportions
se <- sqrt(pooled_prop * (1 - pooled_prop) * (1 / GSE135514_Sal_Das_72h_total_UP + 1 / GSE135514_Sal_Das_72h_total_DOWN))

# Z-statistic
z_stat <- (GSE135514_Sal_Das_72h_high_MFE_in_UP_fraction - GSE135514_Sal_Das_72h_high_MFE_in_DOWN_fraction) / se

# p-value (two-tailed test)
GSE135514_Sal_Das_72h_z_test_MFE_p_value <- 2 * pnorm(-abs(z_stat))

# Output the results of the two-proportion Z-test
cat("Two-proportion Z-test p-value for high MFE TX in UP vs DOWN-regulated genes:", GSE135514_Sal_Das_72h_z_test_MFE_p_value, "\n")
cat("Z-statistic for high MFE TX in UP vs DOWN-regulated genes:", z_stat, "\n")

# Output the fractions for high MFE in UP and DOWN-regulated genes
cat("Fraction of high MFE TX in UP-regulated genes:", GSE135514_Sal_Das_72h_high_MFE_in_UP_fraction, "\n")
cat("Fraction of high MFE TX in DOWN-regulated genes:", GSE135514_Sal_Das_72h_high_MFE_in_DOWN_fraction, "\n")

# Additional statistics (mean, mode) for high MFE TX in UP and DOWN-regulated genes
cat("Mean of high MFE TX in UP-regulated genes:", mean(GSE135514_Sal_Das_72h_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mean of high MFE TX in DOWN-regulated genes:", mean(GSE135514_Sal_Das_72h_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")
