  pivot_longer(
    cols = starts_with("GSM"),      # Select all columns starting with "GSM"
    names_to = "replicate",         # Name of the new column for replicate identifiers
    values_to = "counts"            # Name of the new column for the counts
  )

# Add a condition column based on the replicate
GSE135514_Das_24h_long_data <- GSE135514_Das_24h_long_data %>%
  mutate(condition = ifelse(replicate %in% c("GSM4013426", "GSM4013427", "GSM4013428"), "Control", "Das_24h"))

# Aggregate the replicates for each condition
GSE135514_Das_24h_norm_TX_aggregated_data_avg_counts <- GSE135514_Das_24h_long_data %>%
  group_by(ensembl_transcript_id_version, condition, Normalized_MFE, Specific_heat) %>%
  summarise(
    avg_counts = mean(counts),
    .groups = 'drop'
  )

# Fraction of total high MFE transcripts counts in control and drug-treated groups
GSE135514_Das_24h_control_total_counts <- dplyr::filter(GSE135514_Das_24h_norm_TX_aggregated_data_avg_counts, condition == "Control") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE135514_Das_24h_control_high_MFE_TX_counts <- dplyr::filter(GSE135514_Das_24h_norm_TX_aggregated_data_avg_counts, condition == "Control") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE135514_Das_24h_high_MFE_TX$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE135514_Das_24h_control_high_MFE_TX_counts_fraction <- GSE135514_Das_24h_control_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE135514_Das_24h_control_total_counts$total_counts

GSE135514_Das_24h_Das_24h_total_counts <- dplyr::filter(GSE135514_Das_24h_norm_TX_aggregated_data_avg_counts, condition == "Das_24h") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE135514_Das_24h_Das_24h_high_MFE_TX_counts <- dplyr::filter(GSE135514_Das_24h_norm_TX_aggregated_data_avg_counts, condition == "Das_24h") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE135514_Das_24h_high_MFE_TX$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE135514_Das_24h_Das_24h_high_MFE_TX_counts_fraction <- GSE135514_Das_24h_Das_24h_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE135514_Das_24h_Das_24h_total_counts$total_counts

# Calculate the proportions for high MFE TX counts in both groups
p_control <- GSE135514_Das_24h_control_high_MFE_TX_counts_fraction
p_Das_24h <- GSE135514_Das_24h_Das_24h_high_MFE_TX_counts_fraction

# Calculate the pooled proportion
pooled_prop <- (GSE135514_Das_24h_control_high_MFE_TX_counts$total_counts_high_MFE_TX + GSE135514_Das_24h_Das_24h_high_MFE_TX_counts$total_counts_high_MFE_TX) /
  (GSE135514_Das_24h_control_total_counts$total_counts + GSE135514_Das_24h_Das_24h_total_counts$total_counts)

# Standard error for the difference in proportions
se <- sqrt(pooled_prop * (1 - pooled_prop) * (1 / GSE135514_Das_24h_control_total_counts$total_counts + 1 / GSE135514_Das_24h_Das_24h_total_counts$total_counts))

# Z-statistic
z_stat <- (p_control - p_Das_24h) / se

# p-value (two-tailed test)
GSE135514_Das_24h_z_test_counts_75_p_value <- 2 * pnorm(-abs(z_stat))

# Output the results of the two-proportion Z-test
cat("Two-proportion Z-test p-value for high MFE TX counts in Control vs Das_24h:", GSE135514_Das_24h_z_test_counts_75_p_value, "\n")
cat("Z-statistic for high MFE TX counts in Control vs Das_24h:", z_stat, "\n")

# Output the fractions for high MFE in Control and Das_24h
cat("Fraction of high MFE TX in Control:", p_control, "\n")
cat("Fraction of high MFE TX in Das_24h:", p_Das_24h, "\n")

# Net change in high MFE TX counts (Das_24h vs Control)
cat("Net change in high MFE TX counts (Das_24h vs Control):", p_Das_24h - p_control, "\n")





