# Convert from wide to long format
GSE135514_Sal_72h_long_data <- GSE135514_Sal_72h_norm_TX_counts_MFE_df %>%
  pivot_longer(
    cols = starts_with("GSM"),      # Select all columns starting with "GSM"
    names_to = "replicate",         # Name of the new column for replicate identifiers
    values_to = "counts"            # Name of the new column for the counts
  )

# Add a condition column based on the replicate
GSE135514_Sal_72h_long_data <- GSE135514_Sal_72h_long_data %>%
  mutate(condition = ifelse(replicate %in% c("GSM4013442", "GSM4013443", "GSM4013444"), "Control", "Sal_72h"))

# Aggregate the replicates for each condition
GSE135514_Sal_72h_norm_TX_aggregated_data_avg_counts <- GSE135514_Sal_72h_long_data %>%
  group_by(ensembl_transcript_id_version, condition, Normalized_MFE, Specific_heat) %>%
  summarise(
    avg_counts = mean(counts),
    .groups = 'drop'
  )

# Fraction of total high MFE transcripts counts in control and drug-treated groups
GSE135514_Sal_72h_control_total_counts <- dplyr::filter(GSE135514_Sal_72h_norm_TX_aggregated_data_avg_counts, condition == "Control") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE135514_Sal_72h_control_high_MFE_TX_counts <- dplyr::filter(GSE135514_Sal_72h_norm_TX_aggregated_data_avg_counts, condition == "Control") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE135514_Sal_72h_high_MFE_TX$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE135514_Sal_72h_control_high_MFE_TX_counts_fraction <- GSE135514_Sal_72h_control_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE135514_Sal_72h_control_total_counts$total_counts

GSE135514_Sal_72h_Sal_72h_total_counts <- dplyr::filter(GSE135514_Sal_72h_norm_TX_aggregated_data_avg_counts, condition == "Sal_72h") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE135514_Sal_72h_Sal_72h_high_MFE_TX_counts <- dplyr::filter(GSE135514_Sal_72h_norm_TX_aggregated_data_avg_counts, condition == "Sal_72h") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE135514_Sal_72h_high_MFE_TX$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE135514_Sal_72h_Sal_72h_high_MFE_TX_counts_fraction <- GSE135514_Sal_72h_Sal_72h_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE135514_Sal_72h_Sal_72h_total_counts$total_counts

# Calculate the proportions for high MFE TX counts in both groups
p_control <- GSE135514_Sal_72h_control_high_MFE_TX_counts_fraction
p_Sal_72h <- GSE135514_Sal_72h_Sal_72h_high_MFE_TX_counts_fraction

# Calculate the pooled proportion
pooled_prop <- (GSE135514_Sal_72h_control_high_MFE_TX_counts$total_counts_high_MFE_TX + GSE135514_Sal_72h_Sal_72h_high_MFE_TX_counts$total_counts_high_MFE_TX) /
  (GSE135514_Sal_72h_control_total_counts$total_counts + GSE135514_Sal_72h_Sal_72h_total_counts$total_counts)

# Standard error for the difference in proportions
se <- sqrt(pooled_prop * (1 - pooled_prop) * (1 / GSE135514_Sal_72h_control_total_counts$total_counts + 1 / GSE135514_Sal_72h_Sal_72h_total_counts$total_counts))

# Z-statistic
z_stat <- (p_control - p_Sal_72h) / se

# p-value (two-tailed test)
GSE135514_Sal_72h_z_test_counts_75_p_value <- 2 * pnorm(-abs(z_stat))

# Output the results of the two-proportion Z-test
cat("Two-proportion Z-test p-value for high MFE TX counts in Control vs Sal_72h:", GSE135514_Sal_72h_z_test_counts_75_p_value, "\n")
cat("Z-statistic for high MFE TX counts in Control vs Sal_72h:", z_stat, "\n")

# Output the fractions for high MFE in Control and Sal_72h
cat("Fraction of high MFE TX in Control:", p_control, "\n")
cat("Fraction of high MFE TX in Sal_72h:", p_Sal_72h, "\n")

# Net change in high MFE TX counts (Sal_72h vs Control)
cat("Net change in high MFE TX counts (Sal_72h vs Control):", p_Sal_72h - p_control, "\n")






