pooled_prop <- (GSE135514_Das_72h_control_high_MFE_TX_counts$total_counts_high_MFE_TX + GSE135514_Das_72h_Das_72h_high_MFE_TX_counts$total_counts_high_MFE_TX) /
  (GSE135514_Das_72h_control_total_counts$total_counts + GSE135514_Das_72h_Das_72h_total_counts$total_counts)

# Standard error for the difference in proportions
se <- sqrt(pooled_prop * (1 - pooled_prop) * (1 / GSE135514_Das_72h_control_total_counts$total_counts + 1 / GSE135514_Das_72h_Das_72h_total_counts$total_counts))

# Z-statistic
z_stat <- (p_control - p_Das_72h) / se

# p-value (two-tailed test)
GSE135514_Das_72h_z_test_counts_75_p_value <- 2 * pnorm(-abs(z_stat))

# Output the results of the two-proportion Z-test
cat("Two-proportion Z-test p-value for high MFE TX counts in Control vs Das_72h:", GSE135514_Das_72h_z_test_counts_75_p_value, "\n")
cat("Z-statistic for high MFE TX counts in Control vs Das_72h:", z_stat, "\n")

# Output the fractions for high MFE in Control and Das_72h
cat("Fraction of high MFE TX in Control:", p_control, "\n")
cat("Fraction of high MFE TX in Das_72h:", p_Das_72h, "\n")

# Net change in high MFE TX counts (Das_72h vs Control)
cat("Net change in high MFE TX counts (Das_72h vs Control):", p_Das_72h - p_control, "\n")





