# DIFFERENTIAL EXPRESSION ANALYSIS
# We perform a minimal pre-filtering to keep only rows that have at least 3 reads total
keep <- rowSums(counts(dds_GSE143798)) >= 3
dds_GSE143798 <- dds_GSE143798[keep,]
table(keep) # This shows how many transcripts have been removed after the filtering
nrow(dds_GSE143798) # to confirm the filtered transcripts

# DIFFERENTIAL EXPRESSION ANALYSIS
dds_GSE143798 <- DESeq(dds_GSE143798) # The DESeq() function normalizes the read counts, estimates dispersions, and fits the linear model, all in one go
# dds_GSE143798 <- DESeq(dds_GSE143798, betaPrior = T)  The betaPrior = T opton tells DESeq2 to squeeze the log Fold Changes of lowly expressed genes toward zero.

# If I want to see the normalized counts generated in the DESeq object:
# norm_dds_GSE143798 <- counts(dds_GSE143798, normalized=TRUE)

# resultsNames(dds_GSE143798) # lists the coefficients
# plotDispEsts(dds_GSE143798) # Plot the dispersions
# Each black dot in the plot represents the dispersion for one gene. The red line is fit to data (black bots),
# then the dispersions are squeezed toward the red line, resulting the final (blue) dispersion estimates. Usually,
# the dispersion is highest at the low counts and levels off at higher counts.


# Specify the conditions to contrast for differential expression analysis
res_GSE143798 <- results(dds_GSE143798, contrast=c("condition","UDCA","control")) # to specify the samples to contrast
res_GSE143798
# Get a summary of the results
summary(res_GSE143798)




# Plot the log2 Fold Changes as function of expression:
plotMA(res_GSE143798,alpha = 0.05)
abline(h=c(-2,2),col = "red")

# Transform the row names into a column
res_GSE143798_df <- data.frame(res_GSE143798)
res_GSE143798 <- tibble::rownames_to_column(res_GSE143798_df, "ensembl_transcript_id")



# Join the expression change values with the Table_ANNOTATED containing MFE values
MFE_res_GSE143798 <- dplyr::inner_join(Table_ANNOTATED, res_GSE143798, by="ensembl_transcript_id") %>%
  dplyr::filter(padj < 0.05 & padj > 0)


# Generate a scatter plot Log2_FC vs Normalized_MFE

Plot_GSE143798 <- ggplot(MFE_res_GSE143798, aes(y=Normalized_MFE, x=log2FoldChange)) +
  geom_point(size=1.5, alpha=0.05)+
  theme_classic() +
  theme(legend.position="none") +
  geom_vline(xintercept = 0, size=0.3) +
  #xlim(-5.5,5.5) +
  theme(axis.title = element_text(size = 20)) +
  theme(plot.title = element_text(size = 15)) +
  labs(y="DGfold / nt (kcal/mol)",x="Log2_FC_expression",title="GSE143798_Log2_FC_adj.P<0.05")
print(Plot_GSE143798)





# Look at the mean log2_FC
MFE_res_GSE143798_UP <- dplyr::filter(MFE_res_GSE143798, log2FoldChange > 0)
Mean_MFE_res_GSE143798_UP <- mean(MFE_res_GSE143798_UP$Normalized_MFE)

MFE_res_GSE143798_DOWN <- dplyr::filter(MFE_res_GSE143798, log2FoldChange < 0)
Mean_MFE_res_GSE143798_DOWN <- mean(MFE_res_GSE143798_DOWN$Normalized_MFE)

TTEST_MFE_res_GSE143798_all_UP_vs_DOWN <- t.test(MFE_res_GSE143798_DOWN$Normalized_MFE, MFE_res_GSE143798_UP$Normalized_MFE, paired=FALSE)

# Add K-S test to look at the differences between the up-regukated and down-regulated genes
ks_test_res_GSE143798_all_UP_vs_DOWN <- ks.test(MFE_res_GSE143798_DOWN$Normalized_MFE, MFE_res_GSE143798_UP$Normalized_MFE)


quantile_075_MFE_res_GSE143798_UP <- quantile(MFE_res_GSE143798_UP$Normalized_MFE, probs = c(0.75)) 
quantile_075_MFE_res_GSE143798_DOWN <- quantile(MFE_res_GSE143798_DOWN$Normalized_MFE, probs = c(0.75)) 
# Values above 0.75 quantile
ks_test_MFE_075_above <- ks.test(MFE_res_GSE143798_UP$Normalized_MFE[MFE_res_GSE143798_UP$Normalized_MFE >= quantile_075_MFE_res_GSE143798_UP],
                                 MFE_res_GSE143798_DOWN$Normalized_MFE[MFE_res_GSE143798_DOWN$Normalized_MFE >= quantile_075_MFE_res_GSE143798_DOWN])

# Look at the differences between the 0.25 quantile 
quantile_025_MFE_res_GSE143798_UP <- quantile(MFE_res_GSE143798_UP$Normalized_MFE, probs = c(0.25)) 
quantile_025_MFE_res_GSE143798_DOWN <- quantile(MFE_res_GSE143798_DOWN$Normalized_MFE, probs = c(0.25)) 
# Values below 0.25 quantile
ks_test_MFE_025_below <- ks.test(MFE_res_GSE143798_UP$Normalized_MFE[MFE_res_GSE143798_UP$Normalized_MFE <= quantile_025_MFE_res_GSE143798_UP],
                                 MFE_res_GSE143798_DOWN$Normalized_MFE[MFE_res_GSE143798_DOWN$Normalized_MFE <= quantile_025_MFE_res_GSE143798_DOWN])



# Permutation test MFE changes
# Combine the data into a single data frame with labels
upregulated <- data.frame(MFE = MFE_res_GSE143798_UP$Normalized_MFE, Group = "Up")
downregulated <- data.frame(MFE = MFE_res_GSE143798_DOWN$Normalized_MFE, Group = "Down")
combined_data <- bind_rows(upregulated, downregulated)

# Observed difference in means
MFE_res_GSE143798_observed_diff <- mean(MFE_res_GSE143798_UP$Normalized_MFE) - mean(MFE_res_GSE143798_DOWN$Normalized_MFE)

# Number of permutations
n_permutations <- 10000

# Initialize a vector to store the permuted differences
MFE_res_GSE143798_permuted_diffs <- numeric(n_permutations)

# Permutation test
set.seed(123)  # Set seed for reproducibility
for (i in 1:n_permutations) {
  # Permute the Group labels
  permuted_labels <- sample(combined_data$Group)
  
  # Calculate the mean MFE for each permuted group
  permuted_up_mean <- mean(combined_data$MFE[permuted_labels == "Up"])
  permuted_down_mean <- mean(combined_data$MFE[permuted_labels == "Down"])
  
  # Calculate the difference in means for the permuted groups
  MFE_res_GSE143798_permuted_diffs[i] <- permuted_up_mean - permuted_down_mean
}

# Calculate the p-value
MFE_res_GSE143798_p_value <- (sum(abs(MFE_res_GSE143798_permuted_diffs) >= abs(MFE_res_GSE143798_observed_diff)) + 1) / (n_permutations + 1)

# Output the results
cat("Observed difference in MFE_res_GSE143798 means MFE_UP - MFE_DOWN:", MFE_res_GSE143798_observed_diff, "\n")
cat("MFE_res_GSE143798 P-value from permutation test:", MFE_res_GSE143798_p_value, "\n")












## GSE143798 net MFE and heat capacity ####
# IMPORTANT: here, I filter for transcripts with a significant log2_FC.
# The total net MFE is essentially a weighted sum of the MFEs of all transcripts, where the weights are given by the counts of each transcript. 
# This gives the total contribution of each transcript to the overall thermodynamic state of the transcriptome based on their abundance.  


# Analysis GSE143798
# Extract the normalized count data
# The minimal pre-filtering has already been done in the previous steps
GSE143798_norm_TX_counts <- counts(dds_GSE143798, normalized=TRUE) # This object is already a matrix
GSE143798_norm_TX_counts_df <- as.data.frame(GSE143798_norm_TX_counts)
# Convert row names to column
GSE143798_norm_TX_counts_df$ensembl_transcript_id <- rownames(GSE143798_norm_TX_counts_df)
# Remove row names
rownames(GSE143798_norm_TX_counts_df) <- NULL

# Move ensembl_transcript_id column to the first position
GSE143798_norm_TX_counts_df <- GSE143798_norm_TX_counts_df[, c("ensembl_transcript_id", setdiff(names(GSE143798_norm_TX_counts_df), "ensembl_transcript_id"))]

# Remove everything after the dot (including the dot itself) in the ensembl_transcript_id column
GSE143798_norm_TX_counts_df$ensembl_transcript_id <- sub("\\..*", "", GSE143798_norm_TX_counts_df$ensembl_transcript_id)

# Join the counts with the Table_ANNOTATED containing MFE values and heat capacity values
GSE143798_norm_TX_counts_MFE_df <- dplyr::inner_join(Table_ANNOTATED, GSE143798_norm_TX_counts_df, by="ensembl_transcript_id") %>%
  dplyr::select(ensembl_transcript_id_version, ensembl_transcript_id, ensembl_gene_id, external_gene_name, transcript_is_canonical, Transcript_length, 
                GSM4274743, GSM4274744, GSM4274745, GSM4274746, GSM4274747, GSM4274748,
                Normalized_MFE, Temperature, Specific_heat)






# GSE143798
# Convert from wide to long format
GSE143798_norm_TX_counts_MFE_df <- dplyr::select(GSE143798_norm_TX_counts_MFE_df, ensembl_transcript_id_version, ensembl_transcript_id, ensembl_gene_id, external_gene_name, transcript_is_canonical, Transcript_length, 
                                                 GSM4274743, GSM4274744, GSM4274745, GSM4274746, GSM4274747, GSM4274748, Normalized_MFE, Temperature, Specific_heat) %>%
  dplyr::filter(ensembl_transcript_id %in% MFE_res_GSE143798$ensembl_transcript_id) 

# Identify the 75th percentile of the combined MFE distributions of control and drug-treated samples
quantile_075_GSE143798_norm_TX_counts_MFE_df <- quantile(GSE143798_norm_TX_counts_MFE_df$Normalized_MFE, probs = c(0.75))

# Select all the transcripts with Normalized_MFE values above the 75th percentile
GSE143798_high_MFE_TX <- dplyr::filter(GSE143798_norm_TX_counts_MFE_df, Normalized_MFE > quantile_075_GSE143798_norm_TX_counts_MFE_df)

# Count the number of transcripts in the significantly up- and down-regulated pools that have MFE values above this threshold.
GSE143798_high_MFE_TX_in_UP <- dplyr::filter(MFE_res_GSE143798_UP, ensembl_transcript_id_version %in% GSE143798_high_MFE_TX$ensembl_transcript_id_version)
GSE143798_high_MFE_TX_in_DOWN <- dplyr::filter(MFE_res_GSE143798_DOWN, ensembl_transcript_id_version %in% GSE143798_high_MFE_TX$ensembl_transcript_id_version)

# Count the total number of UP and DOWN regulated transcripts
GSE143798_total_UP <- nrow(MFE_res_GSE143798_UP)
GSE143798_total_DOWN <- nrow(MFE_res_GSE143798_DOWN)

# Count the high MFE transcripts in both UP and DOWN regulated groups
GSE143798_count_high_MFE_UP <- nrow(GSE143798_high_MFE_TX_in_UP)
GSE143798_count_high_MFE_DOWN <- nrow(GSE143798_high_MFE_TX_in_DOWN)

# Proportions of high MFE transcripts in UP and DOWN regulated groups
p_UP_high <- GSE143798_count_high_MFE_UP / GSE143798_total_UP
p_DOWN_high <- GSE143798_count_high_MFE_DOWN / GSE143798_total_DOWN

# Calculate the pooled proportion
pooled_prop_high <- (GSE143798_count_high_MFE_UP + GSE143798_count_high_MFE_DOWN) / 
  (GSE143798_total_UP + GSE143798_total_DOWN)

# Standard error for the difference in proportions
se_high <- sqrt(pooled_prop_high * (1 - pooled_prop_high) * 
                  (1 / GSE143798_total_UP + 1 / GSE143798_total_DOWN))

# Z-statistic for high MFE TX counts
z_stat_high <- (p_UP_high - p_DOWN_high) / se_high

# p-value for high MFE TX counts (two-tailed test)
GSE143798_z_test_MFE_p_value <- 2 * pnorm(-abs(z_stat_high))

# Output the results of the two-proportion Z-test for high MFE TX counts
cat("Two-proportion Z-test p-value for high MFE TX in UP-regulated vs DOWN-regulated:", GSE143798_z_test_MFE_p_value, "\n")
cat("Z-statistic for high MFE TX in UP-regulated vs DOWN-regulated:", z_stat_high, "\n")

# Look at the fractions
GSE143798_high_MFE_in_UP_fraction <- GSE143798_count_high_MFE_UP / GSE143798_total_UP
GSE143798_high_MFE_in_DOWN_fraction <- GSE143798_count_high_MFE_DOWN / GSE143798_total_DOWN

# Output the results
cat("Fraction of GSE143798 high MFE TX in UP-regulated genes:", GSE143798_high_MFE_in_UP_fraction, "\n") # This value goes in the summary table
cat("Fraction of GSE143798 high MFE TX in DOWN-regulated genes:", GSE143798_high_MFE_in_DOWN_fraction, "\n") # This value goes in the summary table
cat("Mean of GSE143798 high MFE TX in UP-regulated genes:", mean(GSE143798_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mean of GSE143798 high MFE TX in DOWN-regulated genes:", mean(GSE143798_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")
cat("Mode of GSE143798 high MFE TX in UP-regulated genes:", calculate_mode(GSE143798_high_MFE_TX_in_UP$Normalized_MFE), "\n")
