# Determine the impact of these changes in terms of fraction of total counts:
# Calculate the fraction of total counts of high MFE transcripts in control and drug-treated groups. 
# This is done by summing the counts of the high MFE transcripts and dividing by the total counts in each group.
# Fisher’s exact test to compare the proportions of high MFE transcripts counts between the two groups.


# Convert from wide to long format
GSE143798_long_data <- GSE143798_norm_TX_counts_MFE_df %>%
  pivot_longer(
    cols = starts_with("GSM"),      # Select all columns starting with "GSM"
    names_to = "replicate",         # Name of the new column for replicate identifiers
    values_to = "counts"            # Name of the new column for the counts
  )

# Add a condition column based on the replicate
GSE143798_long_data <- GSE143798_long_data %>%
  mutate(condition = ifelse(replicate %in% c("GSM4274743", "GSM4274744", "GSM4274745"), "Control", "UDCA"))

# Aggregate the replicates for each condition
GSE143798_norm_TX_aggregated_data_avg_counts <- GSE143798_long_data %>%
  group_by(ensembl_transcript_id_version, condition, Normalized_MFE, Specific_heat) %>%
  summarise(
    avg_counts = mean(counts),
    .groups = 'drop'
  )

# Define the 75th percentile of the entire distribution of MFE values for the GSE143798 data
GSE143798_MFE_all_TX_75_percentile <- quantile(GSE143798_norm_TX_aggregated_data_avg_counts$Normalized_MFE, 0.75)

# Identify all the transcripts with MFE values above the 75th percentile
GSE143798_high_MFE_TX_total <- dplyr::filter(GSE143798_norm_TX_counts_MFE_df, Normalized_MFE > GSE143798_MFE_all_TX_75_percentile)

# Fraction of total high MFE transcripts counts in control and drug-treated groups
GSE143798_control_total_counts <- dplyr::filter(GSE143798_norm_TX_aggregated_data_avg_counts, condition == "Control") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE143798_control_high_MFE_TX_counts <- dplyr::filter(GSE143798_norm_TX_aggregated_data_avg_counts, condition == "Control") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE143798_high_MFE_TX_total$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE143798_control_high_MFE_TX_counts_fraction <- GSE143798_control_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE143798_control_total_counts$total_counts
cat("Fraction of control high MFE TX:", GSE143798_control_high_MFE_TX_counts_fraction, "\n") # This value goes in the summary table

GSE143798_UDCA_total_counts <- dplyr::filter(GSE143798_norm_TX_aggregated_data_avg_counts, condition == "UDCA") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE143798_UDCA_high_MFE_TX_counts <- dplyr::filter(GSE143798_norm_TX_aggregated_data_avg_counts, condition == "UDCA") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE143798_high_MFE_TX_total$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE143798_UDCA_high_MFE_TX_counts_fraction <- GSE143798_UDCA_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE143798_UDCA_total_counts$total_counts
cat("Fraction of UDCA high MFE TX:", GSE143798_UDCA_high_MFE_TX_counts_fraction, "\n") # This value goes in the summary table

# Two-proportion Z-test to compare the proportions of high MFE transcripts counts between the two groups
# Proportions of high MFE transcripts in Control and UDCA conditions
p_control_high <- GSE143798_control_high_MFE_TX_counts_fraction
p_UDCA_high <- GSE143798_UDCA_high_MFE_TX_counts_fraction

# Calculate the pooled proportion
pooled_prop_high <- (GSE143798_control_high_MFE_TX_counts$total_counts_high_MFE_TX + GSE143798_UDCA_high_MFE_TX_counts$total_counts_high_MFE_TX) / 
  (GSE143798_control_total_counts$total_counts + GSE143798_UDCA_total_counts$total_counts)

# Standard error for the difference in proportions
se_high <- sqrt(pooled_prop_high * (1 - pooled_prop_high) * 
                  (1 / GSE143798_control_total_counts$total_counts + 1 / GSE143798_UDCA_total_counts$total_counts))

# Z-statistic for high MFE TX counts
z_stat_high <- (p_control_high - p_UDCA_high) / se_high

# p-value for high MFE TX counts (two-tailed test)
GSE143798_z_test_counts_75_p_value <- 2 * pnorm(-abs(z_stat_high))

# Output the results of the two-proportion Z-test for high MFE TX counts
cat("Two-proportion Z-test p-value for high MFE TX in Control vs UDCA:", GSE143798_z_test_counts_75_p_value, "\n")
cat("Z-statistic for high MFE TX in Control vs UDCA:", z_stat_high, "\n")

# Net change in proportions
cat("GSE143798 net change in proportions of high MFE TX (UDCA - Control):", p_UDCA_high - p_control_high, "\n")





