# GSE143462 Omipalisib in Esophageal Cancer ####
# http://www.ilincs.org/apps/grein/?gse=GSE143462

Counts_GSE143462_GREIN <- read.delim("path_to/GSE143462/GSE143462_TranscriptLevel_Raw_data.csv", sep = ",", header = T, stringsAsFactors = F)
Counts_GSE143462_GREIN <- Counts_GSE143462_GREIN %>% remove_rownames %>% column_to_rownames(var="X") # Convert first column into row names in data frame
# Round counts down to the nearest integer
Counts_GSE143462_GREIN <- floor(Counts_GSE143462_GREIN)


# Access the Series Matrix
# Data_GSE143462 <- getGEO(GEO = "GSE143462")

# Load the object
Data_GSE143462 <- readRDS("path_to/GREIN_series_matrices_data/Data_GSE143462.rds")


# Extract the phenotypic/clinical data matrix from the series matrix
Expdata_GSE143462 <- Data_GSE143462[["GSE143462_series_matrix.txt.gz"]]@phenoData@data

colnames(Expdata_GSE143462)[colnames(Expdata_GSE143462) == "treatment:ch1"] <- "condition" # Rename the column to have an easier identifier for the conditions


# IMPORTANT:
# It is absolutely critical that the columns of the count matrix and the rows of the column data (information about samples) are in the same order.

# Replace the row names of Expdata_GSE143462 (sampleID) with the same sample name [title] of [Counts_GSE182018]. 
# This will help to match sample names in both matrices.
# The outcome should be TRUE
all(rownames(Expdata_GSE143462) %in% colnames(Counts_GSE143462_GREIN))
all(colnames(Counts_GSE143462_GREIN) %in% rownames(Expdata_GSE143462))

# With the count matrix, Counts_GSE108308_GREIN, and the sample information, Expdata_GSE108308, we can construct a DESeqDataSet:
dds_GSE143462 <- DESeqDataSetFromMatrix(countData = Counts_GSE143462_GREIN,
                                        colData = Expdata_GSE143462,
                                        design = ~ condition)
dds_GSE143462




# DATA QUALITY ASSESSMENT MIA_PACA2 COUNTS
# Before performing differential expression analysis, we perform data quality assessment by sample clustering and visualization
library("pheatmap")
# We log transform the counts
ntd <- normTransform(dds_GSE143462)
# Heat map of the count matrix
select <- order(rowMeans(counts(dds_GSE143462,normalized=FALSE)),
                decreasing=TRUE)[1:25]
df <- as.data.frame(colData(dds_GSE143462)[,c("condition","type")])
pheatmap(assay(ntd)[select,], cluster_rows=FALSE, show_rownames=FALSE,
         cluster_cols=FALSE, annotation_col=df)



# Heatmap of the sample-to-sample distances
# A heatmap of this distance matrix gives us an overview over similarities and dissimilarities between samples
# Transform the values
vsd <- vst(dds_GSE143462, blind=FALSE)
# rld <- rlog(dds_GSE143462, blind=FALSE)
head(assay(vsd), 3)

# Apply the dist function to the transpose of the transformed count matrix to get sample-to-sample distances
sampleDists <- dist(t(assay(vsd)))

# Condition
library("RColorBrewer")
sampleDistMatrix <- as.matrix(sampleDists)
rownames(sampleDistMatrix) <- paste(vsd$condition, vsd$type, sep="-")
colnames(sampleDistMatrix) <- NULL
colors <- colorRampPalette( rev(brewer.pal(9, "Blues")) )(255)
pheatmap(sampleDistMatrix,
         clustering_distance_rows=sampleDists,
         clustering_distance_cols=sampleDists,
         col=colors)

# Principal component plot of the samples
plotPCA(vsd, intgroup="condition")




# DIFFERENTIAL EXPRESSION ANALYSIS
# We perform a minimal pre-filtering to keep only rows that have at least 3 reads total
keep <- rowSums(counts(dds_GSE143462)) >= 3
dds_GSE143462 <- dds_GSE143462[keep,]
table(keep) # This shows how many transcripts have been removed after the filtering
nrow(dds_GSE143462) # to confirm the filtered transcripts

# DIFFERENTIAL EXPRESSION ANALYSIS
dds_GSE143462 <- DESeq(dds_GSE143462) # The DESeq() function normalizes the read counts, estimates dispersions, and fits the linear model, all in one go
# dds_GSE143462 <- DESeq(dds_GSE143462, betaPrior = T)  The betaPrior = T opton tells DESeq2 to squeeze the log Fold Changes of lowly expressed genes toward zero.

# If I want to see the normalized counts generated in the DESeq object:
# norm_dds_GSE143462 <- counts(dds_GSE143462, normalized=TRUE)

# resultsNames(dds_GSE143462) # lists the coefficients
# plotDispEsts(dds_GSE143462) # Plot the dispersions
# Each black dot in the plot represents the dispersion for one gene. The red line is fit to data (black bots),
# then the dispersions are squeezed toward the red line, resulting the final (blue) dispersion estimates. Usually,
# the dispersion is highest at the low counts and levels off at higher counts.


# Specify the conditions to contrast for differential expression analysis
res_GSE143462 <- results(dds_GSE143462, contrast=c("condition","omipalisib","control")) # to specify the samples to contrast
res_GSE143462
# Get a summary of the results
summary(res_GSE143462)




# Plot the log2 Fold Changes as function of expression:
plotMA(res_GSE143462,alpha = 0.05)
abline(h=c(-2,2),col = "red")

# Transform the row names into a column
res_GSE143462_df <- data.frame(res_GSE143462)
res_GSE143462 <- tibble::rownames_to_column(res_GSE143462_df, "ensembl_transcript_id")



# Join the expression change values with the Table_ANNOTATED containing MFE values
MFE_res_GSE143462 <- dplyr::inner_join(Table_ANNOTATED, res_GSE143462, by="ensembl_transcript_id") %>% # The file 'Table' contains the Normalized_MFE values of all ANNOTATED transcripts
  dplyr::filter(padj < 0.05) 


# Generate a scatter plot Log2_FC vs Normalized_MFE

Plot_GSE143462 <- ggplot(MFE_res_GSE143462, aes(y=Normalized_MFE, x=log2FoldChange)) +
  geom_point(size=1.5, alpha=0.05)+
  theme_classic() +
  theme(legend.position="none") +
  geom_vline(xintercept = 0, size=0.3) +
  #xlim(-5.5,5.5) +
  theme(axis.title = element_text(size = 20)) +
  theme(plot.title = element_text(size = 15)) +
  labs(y="DGfold / nt (kcal/mol)",x="Log2_FC_expression",title="GSE143462_Log2_FC_adj.P<0.05")
print(Plot_GSE143462)



# Look at the mean log2_FC
MFE_res_GSE143462_UP <- dplyr::filter(MFE_res_GSE143462, log2FoldChange > 0)
Mean_MFE_res_GSE143462_UP <- mean(MFE_res_GSE143462_UP$Normalized_MFE)

MFE_res_GSE143462_DOWN <- dplyr::filter(MFE_res_GSE143462, log2FoldChange < 0)
Mean_MFE_res_GSE143462_DOWN <- mean(MFE_res_GSE143462_DOWN$Normalized_MFE)

TTEST_MFE_res_GSE143462_all_UP_vs_DOWN <- t.test(MFE_res_GSE143462_DOWN$Normalized_MFE, MFE_res_GSE143462_UP$Normalized_MFE, paired=FALSE)

# Add K-S test to look at the differences between the up-regukated and down-regulated genes
ks_test_res_GSE143462_all_UP_vs_DOWN <- ks.test(MFE_res_GSE143462_DOWN$Normalized_MFE, MFE_res_GSE143462_UP$Normalized_MFE)


quantile_075_MFE_res_GSE143462_UP <- quantile(MFE_res_GSE143462_UP$Normalized_MFE, probs = c(0.75)) 
quantile_075_MFE_res_GSE143462_DOWN <- quantile(MFE_res_GSE143462_DOWN$Normalized_MFE, probs = c(0.75)) 
# Values above 0.75 quantile
ks_test_MFE_075_above <- ks.test(MFE_res_GSE143462_UP$Normalized_MFE[MFE_res_GSE143462_UP$Normalized_MFE >= quantile_075_MFE_res_GSE143462_UP],
                                 MFE_res_GSE143462_DOWN$Normalized_MFE[MFE_res_GSE143462_DOWN$Normalized_MFE >= quantile_075_MFE_res_GSE143462_DOWN])

# Look at the differences between the 0.25 quantile 
quantile_025_MFE_res_GSE143462_UP <- quantile(MFE_res_GSE143462_UP$Normalized_MFE, probs = c(0.25)) 
quantile_025_MFE_res_GSE143462_DOWN <- quantile(MFE_res_GSE143462_DOWN$Normalized_MFE, probs = c(0.25)) 
# Values below 0.25 quantile
ks_test_MFE_025_below <- ks.test(MFE_res_GSE143462_UP$Normalized_MFE[MFE_res_GSE143462_UP$Normalized_MFE <= quantile_025_MFE_res_GSE143462_UP],
                                 MFE_res_GSE143462_DOWN$Normalized_MFE[MFE_res_GSE143462_DOWN$Normalized_MFE <= quantile_025_MFE_res_GSE143462_DOWN])


# Permutation test MFE changes
# Combine the data into a single data frame with labels
upregulated <- data.frame(MFE = MFE_res_GSE143462_UP$Normalized_MFE, Group = "Up")
downregulated <- data.frame(MFE = MFE_res_GSE143462_DOWN$Normalized_MFE, Group = "Down")
combined_data <- bind_rows(upregulated, downregulated)

# Observed difference in means
GSE143462_observed_diff <- mean(MFE_res_GSE143462_UP$Normalized_MFE) - mean(MFE_res_GSE143462_DOWN$Normalized_MFE)

# Number of permutations
n_permutations <- 10000

# Initialize a vector to store the permuted differences
GSE143462_permuted_diffs <- numeric(n_permutations)

# Permutation test
set.seed(123)  # Set seed for reproducibility
for (i in 1:n_permutations) {
  # Permute the Group labels
  permuted_labels <- sample(combined_data$Group)
  
  # Calculate the mean MFE for each permuted group
  permuted_up_mean <- mean(combined_data$MFE[permuted_labels == "Up"])
  permuted_down_mean <- mean(combined_data$MFE[permuted_labels == "Down"])
  
  # Calculate the difference in means for the permuted groups
  GSE143462_permuted_diffs[i] <- permuted_up_mean - permuted_down_mean
}

# Calculate the p-value
GSE143462_p_value <- (sum(abs(GSE143462_permuted_diffs) >= abs(GSE143462_observed_diff)) + 1) / (n_permutations + 1)

# Output the results
cat("Observed difference in GSE143462 means MFE_UP - MFE_DOWN:", GSE143462_observed_diff, "\n")
cat("GSE143462 P-value from permutation test:", GSE143462_p_value, "\n")















## GSE143462 net MFE and heat capacity ####
# IMPORTANT: here, I filter for transcripts with a significant log2_FC.
# The total net MFE is essentially a weighted sum of the MFEs of all transcripts, where the weights are given by the counts of each transcript. 
# This gives the total contribution of each transcript to the overall thermodynamic state of the transcriptome based on their abundance.  


# Analysis GSE143462
# Extract the normalized count data
# The minimal pre-filtering has already been done in the previous steps
GSE143462_norm_TX_counts <- counts(dds_GSE143462, normalized=TRUE) # This object is already a matrix
GSE143462_norm_TX_counts_df <- as.data.frame(GSE143462_norm_TX_counts)
# Convert row names to column
GSE143462_norm_TX_counts_df$ensembl_transcript_id <- rownames(GSE143462_norm_TX_counts_df)
# Remove row names
rownames(GSE143462_norm_TX_counts_df) <- NULL

# Move ensembl_transcript_id column to the first position
GSE143462_norm_TX_counts_df <- GSE143462_norm_TX_counts_df[, c("ensembl_transcript_id", setdiff(names(GSE143462_norm_TX_counts_df), "ensembl_transcript_id"))]

# Remove everything after the dot (including the dot itself) in the ensembl_transcript_id column
GSE143462_norm_TX_counts_df$ensembl_transcript_id <- sub("\\..*", "", GSE143462_norm_TX_counts_df$ensembl_transcript_id)

# Join the counts with the Table_ANNOTATED containing MFE values and heat capacity values
GSE143462_norm_TX_counts_MFE_df <- dplyr::inner_join(Table_ANNOTATED, GSE143462_norm_TX_counts_df, by="ensembl_transcript_id") %>%
  dplyr::select(ensembl_transcript_id_version, ensembl_transcript_id, ensembl_gene_id, external_gene_name, transcript_is_canonical, Transcript_length, 
                GSM4259875, GSM4259876, GSM4259877, GSM4259878, GSM4259879, GSM4259880,
                Normalized_MFE, Temperature, Specific_heat)





# GSE143462
# Convert from wide to long format
GSE143462_norm_TX_counts_MFE_df <- dplyr::select(GSE143462_norm_TX_counts_MFE_df, ensembl_transcript_id_version, ensembl_transcript_id, ensembl_gene_id, external_gene_name, transcript_is_canonical, Transcript_length, 
                                                 GSM4259875, GSM4259876, GSM4259877, GSM4259878, GSM4259879, GSM4259880, Normalized_MFE, Temperature, Specific_heat) %>%
  dplyr::filter(ensembl_transcript_id %in% MFE_res_GSE143462$ensembl_transcript_id) 

# Identify the 75th percentile of the combined MFE distributions of control and drug-treated samples
quantile_075_GSE143462_norm_TX_counts_MFE_df <- quantile(GSE143462_norm_TX_counts_MFE_df$Normalized_MFE, probs = c(0.75))

# Select all the transcripts with Normalized_MFE values above the 75th percentile
GSE143462_high_MFE_TX <- dplyr::filter(GSE143462_norm_TX_counts_MFE_df, Normalized_MFE > quantile_075_GSE143462_norm_TX_counts_MFE_df)

# Count the number of transcripts in the significantly up- and down-regulated pools that have MFE values above this threshold.
GSE143462_high_MFE_TX_in_UP <- dplyr::filter(MFE_res_GSE143462_UP, ensembl_transcript_id_version %in% GSE143462_high_MFE_TX$ensembl_transcript_id_version)
GSE143462_high_MFE_TX_in_DOWN <- dplyr::filter(MFE_res_GSE143462_DOWN, ensembl_transcript_id_version %in% GSE143462_high_MFE_TX$ensembl_transcript_id_version)

# Total number of transcripts in UP and DOWN-regulated groups
GSE143462_total_UP <- nrow(MFE_res_GSE143462_UP)
GSE143462_total_DOWN <- nrow(MFE_res_GSE143462_DOWN)

# Count high MFE transcripts in UP and DOWN-regulated groups
GSE143462_count_high_MFE_UP <- nrow(GSE143462_high_MFE_TX_in_UP)
GSE143462_count_high_MFE_DOWN <- nrow(GSE143462_high_MFE_TX_in_DOWN)

# Proportions of high MFE transcripts in UP and DOWN-regulated groups
p_UP_high <- GSE143462_count_high_MFE_UP / GSE143462_total_UP
p_DOWN_high <- GSE143462_count_high_MFE_DOWN / GSE143462_total_DOWN

# Calculate the pooled proportion for the two proportions test
pooled_prop_high <- (GSE143462_count_high_MFE_UP + GSE143462_count_high_MFE_DOWN) / 
  (GSE143462_total_UP + GSE143462_total_DOWN)

# Standard error for the difference in proportions
se_high <- sqrt(pooled_prop_high * (1 - pooled_prop_high) * 
                  (1 / GSE143462_total_UP + 1 / GSE143462_total_DOWN))

# Z-statistic for the difference in proportions
z_stat_high <- (p_UP_high - p_DOWN_high) / se_high

# p-value for the Z-test (two-tailed test)
GSE143462_z_test_MFE_p_value <- 2 * pnorm(-abs(z_stat_high))

# Output the results of the two-proportion Z-test for high MFE TX counts
cat("Two-proportion Z-test p-value for high MFE TX in UP vs DOWN-regulated genes:", GSE143462_z_test_MFE_p_value, "\n")
cat("Z-statistic for high MFE TX in UP vs DOWN-regulated genes:", z_stat_high, "\n")

# Look at the fractions of high MFE transcripts in UP and DOWN-regulated genes
GSE143462_high_MFE_in_UP_fraction <- GSE143462_count_high_MFE_UP / GSE143462_total_UP
GSE143462_high_MFE_in_DOWN_fraction <- GSE143462_count_high_MFE_DOWN / GSE143462_total_DOWN

# Output the results
cat("Fraction of GSE143462 high MFE TX in UP-regulated genes:", GSE143462_high_MFE_in_UP_fraction, "\n") # This value goes in the summary table
cat("Fraction of GSE143462 high MFE TX in DOWN-regulated genes:", GSE143462_high_MFE_in_DOWN_fraction, "\n") # This value goes in the summary table
cat("Mean of GSE143462 high MFE TX in UP-regulated genes:", mean(GSE143462_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mean of GSE143462 high MFE TX in DOWN-regulated genes:", mean(GSE143462_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")
cat("Mode of GSE143462 high MFE TX in UP-regulated genes:", calculate_mode(GSE143462_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mode of GSE143462 high MFE TX in DOWN-regulated genes:", calculate_mode(GSE143462_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")



# Show data as violin plot
# Add a new column to indicate if the value is above the 75th percentile
MFE_res_GSE143462$above_quantile_075 <- MFE_res_GSE143462$Normalized_MFE > quantile_075_GSE143462_norm_TX_counts_MFE_df

# Generate violin plot with conditional jitter coloring
Plot_MFE_GSE143462 <- ggplot(MFE_res_GSE143462, aes(x = factor(log2FoldChange > 0), y = Normalized_MFE)) +
  geom_violin(fill = "white", size = 1.5) +
  geom_jitter(aes(color = above_quantile_075), width = 0.1, size = 1, alpha = 1) +
  scale_color_manual(values = c("FALSE" = "black", "TRUE" = "dodgerblue3")) +
  theme_classic() +
  ylim(-0.6, 0) +
  theme(
    legend.position = "none", 
    axis.title = element_text(size = 20), 
    plot.title = element_text(size = 10),
    axis.text.x = element_text(size = 16, color = "black")
  ) +
  geom_vline(xintercept = 0, linewidth = 0.3) +
  labs(
    y = "Normalized_MFE", 
    x = NULL, 
    title = "GSE143462_Log2_FC_adj.P<0.05"
  ) +
  scale_x_discrete(labels = c("log2_FC < 0", "log2_FC > 0"))

print(Plot_MFE_GSE143462)















# Determine the impact of these changes in terms of fraction of total counts:
# Calculate the fraction of total counts of high MFE transcripts in control and drug-treated groups. 
# This is done by summing the counts of the high MFE transcripts and dividing by the total counts in each group.
# Fisher’s exact test to compare the proportions of high MFE transcripts counts between the two groups.

# Convert from wide to long format
GSE143462_long_data <- GSE143462_norm_TX_counts_MFE_df %>%
  pivot_longer(
    cols = starts_with("GSM"),      # Select all columns starting with "GSM"
    names_to = "replicate",         # Name of the new column for replicate identifiers
    values_to = "counts"            # Name of the new column for the counts
  )

# Add a condition column based on the replicate
GSE143462_long_data <- GSE143462_long_data %>%
  mutate(condition = ifelse(replicate %in% c("GSM4259875", "GSM4259876", "GSM4259877"), "Control", "Omipalisib"))

# Aggregate the replicates for each condition
GSE143462_norm_TX_aggregated_data_avg_counts <- GSE143462_long_data %>%
  group_by(ensembl_transcript_id_version, condition, Normalized_MFE, Specific_heat) %>%
  summarise(
    avg_counts = mean(counts),
    .groups = 'drop'
  )

# Define the 75th percentile of the entire distribution of MFE values for the GSE143462 data
GSE143462_MFE_all_TX_75_percentile <- quantile(GSE143462_norm_TX_aggregated_data_avg_counts$Normalized_MFE, 0.75)

# Identify all the transcripts with MFE values above the 75th percentile
GSE143462_high_MFE_TX_total <- dplyr::filter(GSE143462_norm_TX_counts_MFE_df, Normalized_MFE > GSE143462_MFE_all_TX_75_percentile)

# Fraction of total high MFE transcript counts in control and drug-treated groups (Control group)
GSE143462_control_total_counts <- dplyr::filter(GSE143462_norm_TX_aggregated_data_avg_counts, condition == "Control") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE143462_control_high_MFE_TX_counts <- dplyr::filter(GSE143462_norm_TX_aggregated_data_avg_counts, condition == "Control") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE143462_high_MFE_TX_total$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE143462_control_high_MFE_TX_counts_fraction <- GSE143462_control_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE143462_control_total_counts$total_counts
print(GSE143462_control_high_MFE_TX_counts_fraction) # This value goes in the summary table

# Fraction of total high MFE transcript counts in Omipalisib-treated group
GSE143462_Omipalisib_total_counts <- dplyr::filter(GSE143462_norm_TX_aggregated_data_avg_counts, condition == "Omipalisib") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE143462_Omipalisib_high_MFE_TX_counts <- dplyr::filter(GSE143462_norm_TX_aggregated_data_avg_counts, condition == "Omipalisib") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE143462_high_MFE_TX_total$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE143462_Omipalisib_high_MFE_TX_counts_fraction <- GSE143462_Omipalisib_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE143462_Omipalisib_total_counts$total_counts
print(GSE143462_Omipalisib_high_MFE_TX_counts_fraction) # This value goes in the summary table

# Proportions of high MFE transcript counts in control and Omipalisib-treated groups
p_control_high <- GSE143462_control_high_MFE_TX_counts_fraction
p_omipalisib_high <- GSE143462_Omipalisib_high_MFE_TX_counts_fraction

# Calculate the pooled proportion for the two-proportion Z-test
pooled_prop_high <- (GSE143462_control_high_MFE_TX_counts$total_counts_high_MFE_TX + GSE143462_Omipalisib_high_MFE_TX_counts$total_counts_high_MFE_TX) / 
  (GSE143462_control_total_counts$total_counts + GSE143462_Omipalisib_total_counts$total_counts)

# Standard error for the difference in proportions
se_high <- sqrt(pooled_prop_high * (1 - pooled_prop_high) * 
                  (1 / GSE143462_control_total_counts$total_counts + 1 / GSE143462_Omipalisib_total_counts$total_counts))

# Z-statistic for the difference in proportions
z_stat_high <- (p_control_high - p_omipalisib_high) / se_high

# p-value for the Z-test (two-tailed test)
GSE143462_z_test_counts_75_p_value <- 2 * pnorm(-abs(z_stat_high))

# Output the results of the two-proportion Z-test for high MFE transcript counts
cat("Two-proportion Z-test p-value for high MFE TX counts in Control vs Omipalisib:", GSE143462_z_test_counts_75_p_value, "\n")
cat("Z-statistic for high MFE TX counts in Control vs Omipalisib:", z_stat_high, "\n")




# Plot Normalized_MFE vs transcript counts of both control and drug-treated conditions
# Create separate data frames for Control and Omipalisib conditions
GSE143462_control_data <- GSE143462_norm_TX_aggregated_data_avg_counts %>%
  dplyr::filter(condition == "Control")

GSE143462_Omipalisib_data <- GSE143462_norm_TX_aggregated_data_avg_counts %>%
  dplyr::filter(condition == "Omipalisib") 


