# Analysis proliferation
# Filter the proliferation gene sets in the DESeq2 results by using a function
# Use a function also to determine the mean and standard deviation of each set and the plot all of them together

# Generate the function that filters each gene set in the target data frame
# This function will be used in the following commands

filtering <- function(x) {
  Filtering<-dplyr::filter(res_GSE143462_gene_df, Gene_symbol %in% x)
  return(Filtering)
}


# Generate the list containing all the gene sets to be used for the filtering.
CURATED_PATHWAYS.input <- list(MTOR_positive_regulators, MTOR_negative_regulators, Proliferation_Science_paper, Meta_PCNA, Proliferation_GO_genes_Magill_Sack_2018, Proliferation_STOP_genes_Magill_Sack_2018, Reactome_G1_phase, Proliferation_Carey_2021, Essential_cell_cycle_Viner_Breuer_Cell_Division_2019, Essential_S_Phase_Viner_Breuer_Cell_Division_2019, Homologous_recombination, Fanconi_anemia, High_fidelity_polymerases)

# This creates the names that will be used to for the final data frames of each file resulting from the filtering of the target data frame with each gene set
CURATED_PATHWAYS.output <- c("MTOR_POS", "MTOR_NEG", "Proliferation_Science", "Meta_PCNA", "Proliferation_GO", "Proliferation_STOP", "G1_phase", "Proliferation_Carey", "Essential_cell_cycle_Viner_Breuer_Cell_Division_2019", "Essential_S_Phase_Viner_Breuer_Cell_Division_2019", "HR", "Fanconi_anemia", "HF_POL")

# Assign the names of the gene sets to each entry in the list
names(CURATED_PATHWAYS.input) <- CURATED_PATHWAYS.output

# Apply the filtering function to create a list of data.frames
Curated_test_df <- lapply(CURATED_PATHWAYS.input, function(x) filtering(x))

# creating a vector with desired names of filtered data.frames
Curated_dfs.output <- c("df_MTOR_POS", "df_MTOR_NEG", "df_Proliferation_Science", "df_Meta_PCNA", "df_Proliferation_GO", "df_Proliferation_STOP", "df_G1_phase", "df_Proliferation_Carey", "df_Essential_cell_cycle_Viner_Breuer_Cell_Division_2019", "df_Essential_S_Phase_Viner_Breuer_Cell_Division_2019", "df_HR", "df_FA", "df_HF_POL")

# loop to assign data.frames to the desired variable name
for (i in (seq_along(Curated_dfs.output))) {
  do.call("<-",list(Curated_dfs.output[i], Curated_test_df[[i]]))
}

# Now simply type a gene set (for example: 'df_MTOR_POS' to have the full table of the filtered data)
# Each gene set is a data frame that can be used to generate the plots.





# Generate new functions 'mean' and 'sd' and loop them through the 'Normalized_MFE' columns of each data frame generated by the automatc filtering here above

# Generate the function for to calculate the MEAN of the normalized_MFE of each gene set resulting from the filtering here above.
Mean_curated <- function(x) {
  mean_curated<-mean(x$log2FoldChange)
  return(mean_curated)
}

# Create an input of the data frames generated here above that I will use to calculate the mean of a specific column
Curated_input_dfs <- list(df_MTOR_POS, df_MTOR_NEG, df_Proliferation_Science, df_Meta_PCNA, df_Proliferation_GO, df_Proliferation_STOP, df_G1_phase, df_Proliferation_Carey, df_Essential_cell_cycle_Viner_Breuer_Cell_Division_2019, df_Essential_S_Phase_Viner_Breuer_Cell_Division_2019, df_HR, df_FA, df_HF_POL)

# Apply the mean function to create a list of data.frames
Curated_mean_test_df <- lapply(Curated_input_dfs, function(x) Mean_curated(x))

# creating a vector with desired names of the files containing the mean of each gene set Normalized MFE
Curated_mean_dfs.output <- c("Mean_MTOR_POS", "Mean_MTOR_NEG", "Mean_Proliferation_Science", "Mean_Meta_PCNA", "Mean_Proliferation_GO", "Mean_Proliferation_STOP", "Mean_G1_phase", "Mean_Proliferation_Carey", "Mean_Essential_cell_cycle_Viner_Breuer_Cell_Division_2019", "Mean_Essential_S_Phase_Viner_Breuer_Cell_Division_2019", "Mean_HR", "Mean_FA", "Mean_HF_POL")

# loop to assign data.frames to the desired variable name
for (i in (seq_along(Curated_mean_dfs.output))) {
  do.call("<-",list(Curated_mean_dfs.output[i], Curated_mean_test_df[[i]]))
}




# Generate the function for to calculate the STANDRAD DEVIATION of the normalized_MFE of each gene set resulting from the fuiltering here above.
STDEV_curated <- function(x) {
  stdev_curated<-sd(x$log2FoldChange)
  return(stdev_curated)
}

# Apply the mean function to create a list of data.frames
Curated_stdev_test_df <- lapply(Curated_input_dfs, function(x) STDEV_curated(x))

# creating a vector with desired names of the files containing the mean of each gene set Normalized MFE
Curated_STDEV_dfs.output <- c("STDEV_MTOR_POS", "STDEV_MTOR_NEG", "STDEV_Proliferation_Science", "STDEV_Meta_PCNA", "STDEV_Proliferation_GO", "STDEV_Proliferation_STOP", "STDEV_G1_phase", "STDEV_Proliferation_Carey", "STDEV_Essential_cell_cycle_Viner_Breuer_Cell_Division_2019", "STDEV_Essential_S_Phase_Viner_Breuer_Cell_Division_2019", "STDEV_HR", "STDEV_FA", "STDEV_HF_POL")

# loop to assign data.frames to the desired variable name
for (i in (seq_along(Curated_STDEV_dfs.output))) {
  do.call("<-",list(Curated_STDEV_dfs.output[i], Curated_stdev_test_df[[i]]))
}



