# GSE130161 6-TG on MCF-7 breast cancer cell line ####
# http://www.ilincs.org/apps/grein/?gse=GSE130161

Counts_GSE130161_GREIN <- read.delim("path_to/GSE130161/GSE130161_TranscriptLevel_Raw_data.csv", sep = ",", header = T, stringsAsFactors = F)
Counts_GSE130161_GREIN <- Counts_GSE130161_GREIN %>% remove_rownames %>% column_to_rownames(var="X") # Convert first column into row names in data frame
# Round counts down to the nearest integer
Counts_GSE130161_GREIN <- floor(Counts_GSE130161_GREIN)


# Access the Series Matrix
# Data_GSE130161 <- getGEO(GEO = "GSE130161")

# LOad the object
Data_GSE130161 <- readRDS("path_to/GREIN_series_matrices_data/Data_GSE130161.rds")


# Extract the phenotypic/clinical data matrix from the series matrix
Expdata_GSE130161 <- Data_GSE130161[["GSE130161_series_matrix.txt.gz"]]@phenoData@data

colnames(Expdata_GSE130161)[colnames(Expdata_GSE130161) == "drug treatment:ch1"] <- "condition" # Rename the column to have an easier identifier for the conditions
Expdata_GSE130161$condition <- gsub("^Thioguanine.*", "thioguanine", Expdata_GSE130161$condition) # Replace anything starting with "Thioguanine." with Thioguanine.
Expdata_GSE130161 <- Expdata_GSE130161 %>% dplyr::mutate(condition = case_when(condition == "none" ~ "control", TRUE ~ condition))


# IMPORTANT:
# It is absolutely critical that the columns of the count matrix and the rows of the column data (information about samples) are in the same order.

# Replace the row names of Expdata_GSE130161 (sampleID) with the same sample name [title] of [Counts_GSE182018]. 
# This will help to match sample names in both matrices.
# The outcome should be TRUE
all(rownames(Expdata_GSE130161) %in% colnames(Counts_GSE130161_GREIN))
all(colnames(Counts_GSE130161_GREIN) %in% rownames(Expdata_GSE130161))

# With the count matrix, Counts_GSE108308_GREIN, and the sample information, Expdata_GSE108308, we can construct a DESeqDataSet:
dds_GSE130161 <- DESeqDataSetFromMatrix(countData = Counts_GSE130161_GREIN,
                                        colData = Expdata_GSE130161,
                                        design = ~ condition)
dds_GSE130161




# DATA QUALITY ASSESSMENT MIA_PACA2 COUNTS
# Before performing differential expression analysis, we perform data quality assessment by sample clustering and visualization
library("pheatmap")
# We log transform the counts
ntd <- normTransform(dds_GSE130161)
# Heat map of the count matrix
select <- order(rowMeans(counts(dds_GSE130161,normalized=FALSE)),
                decreasing=TRUE)[1:25]
df <- as.data.frame(colData(dds_GSE130161)[,c("condition","type")])
pheatmap(assay(ntd)[select,], cluster_rows=FALSE, show_rownames=FALSE,
         cluster_cols=FALSE, annotation_col=df)



# Heatmap of the sample-to-sample distances
# A heatmap of this distance matrix gives us an overview over similarities and dissimilarities between samples
# Transform the values
vsd <- vst(dds_GSE130161, blind=FALSE)
# rld <- rlog(dds_GSE130161, blind=FALSE)
head(assay(vsd), 3)

# Apply the dist function to the transpose of the transformed count matrix to get sample-to-sample distances
sampleDists <- dist(t(assay(vsd)))

# Condition
library("RColorBrewer")
sampleDistMatrix <- as.matrix(sampleDists)
rownames(sampleDistMatrix) <- paste(vsd$condition, vsd$type, sep="-")
colnames(sampleDistMatrix) <- NULL
colors <- colorRampPalette( rev(brewer.pal(9, "Blues")) )(255)
pheatmap(sampleDistMatrix,
         clustering_distance_rows=sampleDists,
         clustering_distance_cols=sampleDists,
         col=colors)

# Principal component plot of the samples
plotPCA(vsd, intgroup="condition")




# DIFFERENTIAL EXPRESSION ANALYSIS
# We perform a minimal pre-filtering to keep only rows that have at least 3 reads total
keep <- rowSums(counts(dds_GSE130161)) >= 3
dds_GSE130161 <- dds_GSE130161[keep,]
table(keep) # This shows how many transcripts have been removed after the filtering
nrow(dds_GSE130161) # to confirm the filtered transcripts

# DIFFERENTIAL EXPRESSION ANALYSIS
dds_GSE130161 <- DESeq(dds_GSE130161) # The DESeq() function normalizes the read counts, estimates dispersions, and fits the linear model, all in one go
# dds_GSE130161 <- DESeq(dds_GSE130161, betaPrior = T)  The betaPrior = T opton tells DESeq2 to squeeze the log Fold Changes of lowly expressed genes toward zero.

# If I want to see the normalized counts generated in the DESeq object:
# norm_dds_GSE130161 <- counts(dds_GSE130161, normalized=TRUE)

# resultsNames(dds_GSE130161) # lists the coefficients
# plotDispEsts(dds_GSE130161) # Plot the dispersions
# Each black dot in the plot represents the dispersion for one gene. The red line is fit to data (black bots),
# then the dispersions are squeezed toward the red line, resulting the final (blue) dispersion estimates. Usually,
# the dispersion is highest at the low counts and levels off at higher counts.


# Specify the conditions to contrast for differential expression analysis
res_GSE130161 <- results(dds_GSE130161, contrast=c("condition","thioguanine","control")) # to specify the samples to contrast
res_GSE130161
# Get a summary of the results
summary(res_GSE130161)




# Plot the log2 Fold Changes as function of expression:
plotMA(res_GSE130161,alpha = 0.05)
abline(h=c(-2,2),col = "red")

# Transform the row names into a column
res_GSE130161_df <- data.frame(res_GSE130161)
res_GSE130161 <- tibble::rownames_to_column(res_GSE130161_df, "ensembl_transcript_id")



# Join the expression change values with the Table_ANNOTATED containing MFE values
MFE_res_GSE130161 <- dplyr::inner_join(Table_ANNOTATED, res_GSE130161, by="ensembl_transcript_id") %>% # The file 'Table' contains the Normalized_MFE values of all ANNOTATED transcripts
  dplyr::filter(padj < 0.05) 


# Generate a scatter plot Log2_FC vs Normalized_MFE

Plot_GSE130161 <- ggplot(MFE_res_GSE130161, aes(y=Normalized_MFE, x=log2FoldChange)) +
  geom_point(size=1.5, alpha=0.05)+
  theme_classic() +
  theme(legend.position="none") +
  geom_vline(xintercept = 0, size=0.3) +
  #xlim(-5.5,5.5) +
  theme(axis.title = element_text(size = 20)) +
  theme(plot.title = element_text(size = 15)) +
  labs(y="DGfold / nt (kcal/mol)",x="Log2_FC_expression",title="GSE130161_Log2_FC_adj.P<0.05")
print(Plot_GSE130161)




# Look at the mean log2_FC
MFE_res_GSE130161_UP <- dplyr::filter(MFE_res_GSE130161, log2FoldChange > 0)
Mean_MFE_res_GSE130161_UP <- mean(MFE_res_GSE130161_UP$Normalized_MFE)

MFE_res_GSE130161_DOWN <- dplyr::filter(MFE_res_GSE130161, log2FoldChange < 0)
Mean_MFE_res_GSE130161_DOWN <- mean(MFE_res_GSE130161_DOWN$Normalized_MFE)

TTEST_MFE_res_GSE130161_all_UP_vs_DOWN <- t.test(MFE_res_GSE130161_DOWN$Normalized_MFE, MFE_res_GSE130161_UP$Normalized_MFE, paired=FALSE)

# Add K-S test to look at the differences between the up-regukated and down-regulated genes
ks_test_res_GSE130161_all_UP_vs_DOWN <- ks.test(MFE_res_GSE130161_DOWN$Normalized_MFE, MFE_res_GSE130161_UP$Normalized_MFE)


quantile_075_MFE_res_GSE130161_UP <- quantile(MFE_res_GSE130161_UP$Normalized_MFE, probs = c(0.75)) 
quantile_075_MFE_res_GSE130161_DOWN <- quantile(MFE_res_GSE130161_DOWN$Normalized_MFE, probs = c(0.75)) 
# Values above 0.75 quantile
ks_test_MFE_075_above <- ks.test(MFE_res_GSE130161_UP$Normalized_MFE[MFE_res_GSE130161_UP$Normalized_MFE >= quantile_075_MFE_res_GSE130161_UP],
                                 MFE_res_GSE130161_DOWN$Normalized_MFE[MFE_res_GSE130161_DOWN$Normalized_MFE >= quantile_075_MFE_res_GSE130161_DOWN])

# Look at the differences between the 0.25 quantile 
quantile_025_MFE_res_GSE130161_UP <- quantile(MFE_res_GSE130161_UP$Normalized_MFE, probs = c(0.25)) 
quantile_025_MFE_res_GSE130161_DOWN <- quantile(MFE_res_GSE130161_DOWN$Normalized_MFE, probs = c(0.25)) 
# Values below 0.25 quantile
ks_test_MFE_025_below <- ks.test(MFE_res_GSE130161_UP$Normalized_MFE[MFE_res_GSE130161_UP$Normalized_MFE <= quantile_025_MFE_res_GSE130161_UP],
                                 MFE_res_GSE130161_DOWN$Normalized_MFE[MFE_res_GSE130161_DOWN$Normalized_MFE <= quantile_025_MFE_res_GSE130161_DOWN])




# Permutation test MFE changes
# Combine the data into a single data frame with labels
upregulated <- data.frame(MFE = MFE_res_GSE130161_UP$Normalized_MFE, Group = "Up")
downregulated <- data.frame(MFE = MFE_res_GSE130161_DOWN$Normalized_MFE, Group = "Down")
combined_data <- bind_rows(upregulated, downregulated)

# Observed difference in means
GSE130161_observed_diff <- mean(MFE_res_GSE130161_UP$Normalized_MFE) - mean(MFE_res_GSE130161_DOWN$Normalized_MFE)

# Number of permutations
n_permutations <- 10000

# Initialize a vector to store the permuted differences
GSE130161_permuted_diffs <- numeric(n_permutations)

# Permutation test
set.seed(123)  # Set seed for reproducibility
for (i in 1:n_permutations) {
  # Permute the Group labels
  permuted_labels <- sample(combined_data$Group)
  
  # Calculate the mean MFE for each permuted group
  permuted_up_mean <- mean(combined_data$MFE[permuted_labels == "Up"])
  permuted_down_mean <- mean(combined_data$MFE[permuted_labels == "Down"])
  
  # Calculate the difference in means for the permuted groups
  GSE130161_permuted_diffs[i] <- permuted_up_mean - permuted_down_mean
}

# Calculate the p-value
GSE130161_p_value <- (sum(abs(GSE130161_permuted_diffs) >= abs(GSE130161_observed_diff)) + 1) / (n_permutations + 1)

# Output the results
cat("Observed difference in GSE130161 means MFE_UP - MFE_DOWN:", GSE130161_observed_diff, "\n")
cat("GSE130161 P-value from permutation test:", GSE130161_p_value, "\n")












## GSE130161 net MFE and heat capacity ####
# IMPORTANT: here, I filter for transcripts with a significant log2_FC.
# The total net MFE is essentially a weighted sum of the MFEs of all transcripts, where the weights are given by the counts of each transcript. 
# This gives the total contribution of each transcript to the overall thermodynamic state of the transcriptome based on their abundance.  

# Analysis GSE130161
# Extract the normalized count data
# The minimal pre-filtering has already been done in the previous steps
GSE130161_norm_TX_counts <- counts(dds_GSE130161, normalized=TRUE) # This object is already a matrix
GSE130161_norm_TX_counts_df <- as.data.frame(GSE130161_norm_TX_counts)
# Convert row names to column
GSE130161_norm_TX_counts_df$ensembl_transcript_id <- rownames(GSE130161_norm_TX_counts_df)
# Remove row names
rownames(GSE130161_norm_TX_counts_df) <- NULL

# Move ensembl_transcript_id column to the first position
GSE130161_norm_TX_counts_df <- GSE130161_norm_TX_counts_df[, c("ensembl_transcript_id", setdiff(names(GSE130161_norm_TX_counts_df), "ensembl_transcript_id"))]

# Remove everything after the dot (including the dot itself) in the ensembl_transcript_id column
GSE130161_norm_TX_counts_df$ensembl_transcript_id <- sub("\\..*", "", GSE130161_norm_TX_counts_df$ensembl_transcript_id)

# Join the counts with the Table_ANNOTATED containing MFE values and heat capacity values
GSE130161_norm_TX_counts_MFE_df <- dplyr::inner_join(Table_ANNOTATED, GSE130161_norm_TX_counts_df, by="ensembl_transcript_id") %>%
  dplyr::select(ensembl_transcript_id_version, ensembl_transcript_id, ensembl_gene_id, external_gene_name, transcript_is_canonical, Transcript_length, 
                GSM3733269, GSM3733270, GSM3733271, GSM3733272, GSM3733273, GSM3733274, GSM3733275, GSM3733276,
                Normalized_MFE, Temperature, Specific_heat)



# Identify the 75th percentile of the combined MFE distributions of control and drug-treated samples
quantile_075_GSE130161_norm_TX_counts_MFE_df <- quantile(GSE130161_norm_TX_counts_MFE_df$Normalized_MFE, probs = c(0.75))

# Select all the transcripts with Normalized_MFE values above the 75th percentile
GSE130161_high_MFE_TX <- dplyr::filter(GSE130161_norm_TX_counts_MFE_df, Normalized_MFE > quantile_075_GSE130161_norm_TX_counts_MFE_df)

# Count the number of transcripts in the significantly up- and down-regulated pools that have MFE values above this threshold.
GSE130161_high_MFE_TX_in_UP <- dplyr::filter(MFE_res_GSE130161_UP, ensembl_transcript_id_version %in% GSE130161_high_MFE_TX$ensembl_transcript_id_version)
GSE130161_high_MFE_TX_in_DOWN <- dplyr::filter(MFE_res_GSE130161_DOWN, ensembl_transcript_id_version %in% GSE130161_high_MFE_TX$ensembl_transcript_id_version)

# Total counts for each group (UP-regulated and DOWN-regulated)
GSE130161_total_UP <- nrow(MFE_res_GSE130161_UP)
GSE130161_total_DOWN <- nrow(MFE_res_GSE130161_DOWN)

# Count high MFE transcripts in each group
GSE130161_count_high_MFE_UP <- nrow(GSE130161_high_MFE_TX_in_UP)
GSE130161_count_high_MFE_DOWN <- nrow(GSE130161_high_MFE_TX_in_DOWN)

# Proportions of high MFE transcripts in each group
p_UP_high <- GSE130161_count_high_MFE_UP / GSE130161_total_UP
p_DOWN_high <- GSE130161_count_high_MFE_DOWN / GSE130161_total_DOWN

# Calculate the pooled proportion for the two-proportion Z-test
pooled_prop <- (GSE130161_count_high_MFE_UP + GSE130161_count_high_MFE_DOWN) / 
  (GSE130161_total_UP + GSE130161_total_DOWN)

# Standard error for the difference in proportions
se <- sqrt(pooled_prop * (1 - pooled_prop) * 
             (1 / GSE130161_total_UP + 1 / GSE130161_total_DOWN))

# Z-statistic for the difference in proportions
z_stat <- (p_UP_high - p_DOWN_high) / se

# p-value for the Z-test (two-tailed test)
GSE130161_z_test_MFE_p_value <- 2 * pnorm(-abs(z_stat))

# Output the results of the two-proportion Z-test
cat("Two-proportion Z-test p-value for high MFE TX between UP-regulated and DOWN-regulated genes:", GSE130161_z_test_MFE_p_value, "\n")
cat("Z-statistic for high MFE TX between UP-regulated and DOWN-regulated genes:", z_stat, "\n")

# Look at the fractions
GSE130161_high_MFE_in_UP_fraction <- GSE130161_count_high_MFE_UP / GSE130161_total_UP
GSE130161_high_MFE_in_DOWN_fraction <- GSE130161_count_high_MFE_DOWN / GSE130161_total_DOWN

# Output the fractions
cat("Fraction of GSE130161 high MFE TX in UP-regulated genes:", GSE130161_high_MFE_in_UP_fraction, "\n") # This value goes in the summary table
cat("Fraction of GSE130161 high MFE TX in DOWN-regulated genes:", GSE130161_high_MFE_in_DOWN_fraction, "\n") # This value goes in the summary table
cat("Mean of GSE130161 high MFE TX in UP-regulated genes:", mean(GSE130161_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mean of GSE130161 high MFE TX in DOWN-regulated genes:", mean(GSE130161_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")
cat("Mode of GSE130161 high MFE TX in UP-regulated genes:", calculate_mode(GSE130161_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mode of GSE130161 high MFE TX in DOWN-regulated genes:", calculate_mode(GSE130161_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")



# Show data as violin plot
# Add a new column to indicate if the value is above the 75th percentile
MFE_res_GSE130161$above_quantile_075 <- MFE_res_GSE130161$Normalized_MFE > quantile_075_GSE130161_norm_TX_counts_MFE_df

# Generate violin plot with conditional jitter coloring
ggplot(MFE_res_GSE130161, aes(x = factor(log2FoldChange > 0), y = Normalized_MFE)) +
  geom_violin(fill = "white") +
