# Determine the impact of these changes in terms of fraction of total counts:
# Calculate the fraction of total counts of high MFE transcripts in control and drug-treated groups. 
# This is done by summing the counts of the high MFE transcripts and dividing by the total counts in each group.
# Fisher’s exact test to compare the proportions of high MFE transcripts counts between the two groups.


# Convert from wide to long format
GSE130161_long_data <- GSE130161_norm_TX_counts_MFE_df %>%
  pivot_longer(
    cols = starts_with("GSM"),      # Select all columns starting with "GSM"
    names_to = "replicate",         # Name of the new column for replicate identifiers
    values_to = "counts"            # Name of the new column for the counts
  )

# Add a condition column based on the replicate
GSE130161_long_data <- GSE130161_long_data %>%
  mutate(condition = ifelse(replicate %in% c("GSM3733269", "GSM3733270", "GSM3733271", "GSM3733272"), "Control", "6-TG"))

# Aggregate the replicates for each condition
GSE130161_norm_TX_aggregated_data_avg_counts <- GSE130161_long_data %>%
  group_by(ensembl_transcript_id_version, condition, Normalized_MFE, Specific_heat) %>%
  summarise(
    avg_counts = mean(counts),
    .groups = 'drop'
  )

# Define the 75th percentile of the entire distribution of MFE values for the GSE130161 data
GSE130161_MFE_all_TX_75_percentile <- quantile(GSE130161_norm_TX_aggregated_data_avg_counts$Normalized_MFE, 0.75)

# Identify all the transcripts with MFE values above the 75th percentile
GSE130161_high_MFE_TX_total <- dplyr::filter(GSE130161_norm_TX_counts_MFE_df, Normalized_MFE > GSE130161_MFE_all_TX_75_percentile)

# Fraction of total high MFE transcripts counts in control and drug-treated groups
GSE130161_control_total_counts <- dplyr::filter(GSE130161_norm_TX_aggregated_data_avg_counts, condition == "Control") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE130161_control_high_MFE_TX_counts <- dplyr::filter(GSE130161_norm_TX_aggregated_data_avg_counts, condition == "Control") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE130161_high_MFE_TX_total$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE130161_control_high_MFE_TX_counts_fraction <- GSE130161_control_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE130161_control_total_counts$total_counts
cat("GSE130161 control high MFE TX as fraction of total counts:", GSE130161_control_high_MFE_TX_counts_fraction, "\n") # This value goes in the summary table

GSE130161_6TG_total_counts <- dplyr::filter(GSE130161_norm_TX_aggregated_data_avg_counts, condition == "6-TG") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE130161_6TG_high_MFE_TX_counts <- dplyr::filter(GSE130161_norm_TX_aggregated_data_avg_counts, condition == "6-TG") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE130161_high_MFE_TX_total$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE130161_6TG_high_MFE_TX_counts_fraction <- GSE130161_6TG_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE130161_6TG_total_counts$total_counts
cat("GSE130161 6-TG high MFE TX as fraction of total counts:", GSE130161_6TG_high_MFE_TX_counts_fraction, "\n") # This value goes in the summary table

# Now perform the Two-Proportion Z-test
# Proportions of high MFE TX in each group
p_control_high <- GSE130161_control_high_MFE_TX_counts_fraction
p_6TG_high <- GSE130161_6TG_high_MFE_TX_counts_fraction

# Total counts for each group
n_control <- GSE130161_control_total_counts$total_counts
n_6TG <- GSE130161_6TG_total_counts$total_counts

# Pooled proportion
pooled_prop <- (GSE130161_control_high_MFE_TX_counts$total_counts_high_MFE_TX + GSE130161_6TG_high_MFE_TX_counts$total_counts_high_MFE_TX) / (n_control + n_6TG)

# Standard error for the difference in proportions
se <- sqrt(pooled_prop * (1 - pooled_prop) * (1 / n_control + 1 / n_6TG))

# Z-statistic
z_stat <- (p_control_high - p_6TG_high) / se

# P-value for the two-proportion Z-test (two-tailed test)
GSE130161_z_test_counts_75_p_value <- 2 * pnorm(-abs(z_stat))

# Output the Z-test results
cat("Two-proportion Z-test p-value for high MFE TX between Control and 6-TG groups:", GSE130161_z_test_counts_75_p_value, "\n")
cat("Z-statistic for high MFE TX between Control and 6-TG groups:", z_stat, "\n")

# Output net change
cat("GSE130161 net change counts high MFE TX drug vs control:", GSE130161_6TG_high_MFE_TX_counts_fraction - GSE130161_control_high_MFE_TX_counts_fraction, "\n")




