# DIFFERENTIAL EXPRESSION ANALYSIS
# We perform a minimal pre-filtering to keep only rows that have at least 3 reads total
keep <- rowSums(counts(dds_GSE184125)) >= 3
dds_GSE184125 <- dds_GSE184125[keep,]
table(keep) # This shows how many transcripts have been removed after the filtering
nrow(dds_GSE184125) # to confirm the filtered transcripts

# DIFFERENTIAL EXPRESSION ANALYSIS
dds_GSE184125 <- DESeq(dds_GSE184125) # The DESeq() function normalizes the read counts, estimates dispersions, and fits the linear model, all in one go
# dds_GSE184125 <- DESeq(dds_GSE184125, betaPrior = T)  The betaPrior = T opton tells DESeq2 to squeeze the log Fold Changes of lowly expressed genes toward zero.

# If I want to see the normalized counts generated in the DESeq object:
# norm_dds_GSE184125 <- counts(dds_GSE184125, normalized=TRUE)

# resultsNames(dds_GSE184125) # lists the coefficients
# plotDispEsts(dds_GSE184125) # Plot the dispersions
# Each black dot in the plot represents the dispersion for one gene. The red line is fit to data (black bots),
# then the dispersions are squeezed toward the red line, resulting the final (blue) dispersion estimates. Usually,
# the dispersion is highest at the low counts and levels off at higher counts.


# Specify the conditions to contrast for differential expression analysis
res_GSE184125 <- results(dds_GSE184125, contrast=c("condition","9ING41","control")) # to specify the samples to contrast
res_GSE184125
# Get a summary of the results
summary(res_GSE184125)




# Plot the log2 Fold Changes as function of expression:
plotMA(res_GSE184125,alpha = 0.05)
abline(h=c(-2,2),col = "red")

# Transform the row names into a column
res_GSE184125_df <- data.frame(res_GSE184125)
res_GSE184125 <- tibble::rownames_to_column(res_GSE184125_df, "ensembl_transcript_id")



# Join the expression change values with the Table_ANNOTATED containing MFE values
MFE_res_GSE184125 <- dplyr::inner_join(Table_ANNOTATED, res_GSE184125, by="ensembl_transcript_id") %>% # The file 'Table' contains the Normalized_MFE values of all ANNOTATED transcripts
  dplyr::filter(padj < 0.05)



# Generate a scatter plot Log2_FC vs Normalized_MFE

Plot_GSE184125 <- ggplot(MFE_res_GSE184125, aes(y=Normalized_MFE, x=log2FoldChange)) +
  geom_point(size=1.5, alpha=0.5)+
  theme_classic() +
  theme(legend.position="none") +
  geom_vline(xintercept = 0, size=0.3) +
  #xlim(-5.5,5.5) +
  theme(axis.title = element_text(size = 20)) +
  theme(plot.title = element_text(size = 15)) +
  labs(y="DGfold / nt (kcal/mol)",x="Log2_FC_expression",title="GSE184125_Log2_FC_adj.P<0.05")
print(Plot_GSE184125)



# Look at the mean log2_FC
MFE_res_GSE184125_UP <- dplyr::filter(MFE_res_GSE184125, log2FoldChange > 0)
Mean_MFE_res_GSE184125_UP <- mean(MFE_res_GSE184125_UP$Normalized_MFE)

MFE_res_GSE184125_DOWN <- dplyr::filter(MFE_res_GSE184125, log2FoldChange < 0)
Mean_MFE_res_GSE184125_DOWN <- mean(MFE_res_GSE184125_DOWN$Normalized_MFE)

TTEST_MFE_res_GSE184125_all_UP_vs_DOWN <- t.test(MFE_res_GSE184125_DOWN$Normalized_MFE, MFE_res_GSE184125_UP$Normalized_MFE, paired=FALSE)

# Add K-S test to look at the differences between the up-regukated and down-regulated genes
ks_test_res_GSE184125_all_UP_vs_DOWN <- ks.test(MFE_res_GSE184125_DOWN$Normalized_MFE, MFE_res_GSE184125_UP$Normalized_MFE)


quantile_075_MFE_res_GSE184125_UP <- quantile(MFE_res_GSE184125_UP$Normalized_MFE, probs = c(0.75)) 
quantile_075_MFE_res_GSE184125_DOWN <- quantile(MFE_res_GSE184125_DOWN$Normalized_MFE, probs = c(0.75)) 
# Values above 0.75 quantile
ks_test_MFE_075_above <- ks.test(MFE_res_GSE184125_UP$Normalized_MFE[MFE_res_GSE184125_UP$Normalized_MFE >= quantile_075_MFE_res_GSE184125_UP],
                                 MFE_res_GSE184125_DOWN$Normalized_MFE[MFE_res_GSE184125_DOWN$Normalized_MFE >= quantile_075_MFE_res_GSE184125_DOWN])

# Look at the differences between the 0.25 quantile 
quantile_025_MFE_res_GSE184125_UP <- quantile(MFE_res_GSE184125_UP$Normalized_MFE, probs = c(0.25)) 
quantile_025_MFE_res_GSE184125_DOWN <- quantile(MFE_res_GSE184125_DOWN$Normalized_MFE, probs = c(0.25)) 
# Values below 0.25 quantile
ks_test_MFE_025_below <- ks.test(MFE_res_GSE184125_UP$Normalized_MFE[MFE_res_GSE184125_UP$Normalized_MFE <= quantile_025_MFE_res_GSE184125_UP],
                                 MFE_res_GSE184125_DOWN$Normalized_MFE[MFE_res_GSE184125_DOWN$Normalized_MFE <= quantile_025_MFE_res_GSE184125_DOWN])


# Permutation test MFE changes
# Combine the data into a single data frame with labels
upregulated <- data.frame(MFE = MFE_res_GSE184125_UP$Normalized_MFE, Group = "Up")
downregulated <- data.frame(MFE = MFE_res_GSE184125_DOWN$Normalized_MFE, Group = "Down")
combined_data <- bind_rows(upregulated, downregulated)

# Observed difference in means
GSE184125_observed_diff <- mean(MFE_res_GSE184125_UP$Normalized_MFE) - mean(MFE_res_GSE184125_DOWN$Normalized_MFE)

# Number of permutations
n_permutations <- 10000

# Initialize a vector to store the permuted differences
GSE184125_permuted_diffs <- numeric(n_permutations)

# Permutation test
set.seed(123)  # Set seed for reproducibility
for (i in 1:n_permutations) {
  # Permute the Group labels
  permuted_labels <- sample(combined_data$Group)
  
  # Calculate the mean MFE for each permuted group
  permuted_up_mean <- mean(combined_data$MFE[permuted_labels == "Up"])
  permuted_down_mean <- mean(combined_data$MFE[permuted_labels == "Down"])
  
  # Calculate the difference in means for the permuted groups
  GSE184125_permuted_diffs[i] <- permuted_up_mean - permuted_down_mean
}

# Calculate the p-value
GSE184125_p_value <- (sum(abs(GSE184125_permuted_diffs) >= abs(GSE184125_observed_diff)) + 1) / (n_permutations + 1)

# Output the results
cat("Observed difference in GSE184125 means MFE_UP - MFE_DOWN:", GSE184125_observed_diff, "\n")
cat("GSE184125 P-value from permutation test:", GSE184125_p_value, "\n")











## GSE184125 High MFE TX fraction changes ####
# Determine whether within the differentially expressed genes there is a significant up-regulation of high MFE transcripts:
# Define high MFE transcripts by taking the 75th percentile of the combined MFE distributions of control and drug-treated samples.
# Count the number of transcripts in the significantly up- and down-regulated genes that have MFE values above this threshold.
# Perform a Fisher’s exact test to compare the proportions of high MFE transcripts between the two groups.


# Analysis GSE184125
# Extract the normalized count data
# The minimal pre-filtering has already been done in the previous steps
GSE184125_norm_TX_counts <- counts(dds_GSE184125, normalized=TRUE) # This object is already a matrix
GSE184125_norm_TX_counts_df <- as.data.frame(GSE184125_norm_TX_counts)
# Convert row names to column
GSE184125_norm_TX_counts_df$ensembl_transcript_id <- rownames(GSE184125_norm_TX_counts_df)
# Remove row names
rownames(GSE184125_norm_TX_counts_df) <- NULL

# Move ensembl_transcript_id column to the first position
GSE184125_norm_TX_counts_df <- GSE184125_norm_TX_counts_df[, c("ensembl_transcript_id", setdiff(names(GSE184125_norm_TX_counts_df), "ensembl_transcript_id"))]

# Remove everything after the dot (including the dot itself) in the ensembl_transcript_id column
GSE184125_norm_TX_counts_df$ensembl_transcript_id <- sub("\\..*", "", GSE184125_norm_TX_counts_df$ensembl_transcript_id)

# Join the counts with the Table_ANNOTATED containing MFE values and heat capacity values
GSE184125_norm_TX_counts_MFE_df <- dplyr::inner_join(Table_ANNOTATED, GSE184125_norm_TX_counts_df, by="ensembl_transcript_id") %>%
  dplyr::select(ensembl_transcript_id_version, ensembl_transcript_id, ensembl_gene_id, external_gene_name, transcript_is_canonical, Transcript_length, 
                GSM5578278, GSM5578279, GSM5578280, GSM5578281, GSM5578282, GSM5578283,
                Normalized_MFE, Temperature, Specific_heat)





# Define the 75th percentile of the entire distribution of MFE values for the GSE184125 data
quantile_075_GSE184125_norm_TX_counts_MFE_df <- quantile(GSE184125_norm_TX_counts_MFE_df$Normalized_MFE, probs = c(0.75))

# Select all the transcripts with Normalized_MFE values above the 75th percentile
GSE184125_high_MFE_TX <- dplyr::filter(GSE184125_norm_TX_counts_MFE_df, Normalized_MFE > quantile_075_GSE184125_norm_TX_counts_MFE_df)

# Count the number of transcripts in the UP- and DOWN-regulated pools that have MFE values above this threshold.
GSE184125_high_MFE_TX_in_UP <- dplyr::filter(MFE_res_GSE184125_UP, ensembl_transcript_id_version %in% GSE184125_high_MFE_TX$ensembl_transcript_id_version)
GSE184125_high_MFE_TX_in_DOWN <- dplyr::filter(MFE_res_GSE184125_DOWN, ensembl_transcript_id_version %in% GSE184125_high_MFE_TX$ensembl_transcript_id_version)

# Total counts in UP- and DOWN-regulated genes
GSE184125_total_UP <- nrow(MFE_res_GSE184125_UP)
GSE184125_total_DOWN <- nrow(MFE_res_GSE184125_DOWN)

# Counts of high MFE transcripts in UP- and DOWN-regulated genes
GSE184125_count_high_MFE_UP <- nrow(GSE184125_high_MFE_TX_in_UP)
GSE184125_count_high_MFE_DOWN <- nrow(GSE184125_high_MFE_TX_in_DOWN)

# Proportions of high MFE transcripts in UP- and DOWN-regulated genes
GSE184125_high_MFE_in_UP_fraction <- GSE184125_count_high_MFE_UP / GSE184125_total_UP
GSE184125_high_MFE_in_DOWN_fraction <- GSE184125_count_high_MFE_DOWN / GSE184125_total_DOWN

# Pooled proportion for high MFE transcripts
pooled_prop <- (GSE184125_count_high_MFE_UP + GSE184125_count_high_MFE_DOWN) / (GSE184125_total_UP + GSE184125_total_DOWN)

# Standard error for the difference in proportions
se <- sqrt(pooled_prop * (1 - pooled_prop) * (1 / GSE184125_total_UP + 1 / GSE184125_total_DOWN))

# Z-statistic for the difference in proportions
z_stat <- (GSE184125_high_MFE_in_UP_fraction - GSE184125_high_MFE_in_DOWN_fraction) / se

# P-value for the two-proportion Z-test (two-tailed test)
GSE184125_z_test_MFE_p_value <- 2 * pnorm(-abs(z_stat))

# Output the results of the Z-test
cat("Two-proportion Z-test p-value for high MFE TX between UP-regulated and DOWN-regulated genes:", GSE184125_z_test_MFE_p_value, "\n")
cat("Z-statistic for high MFE TX between UP-regulated and DOWN-regulated genes:", z_stat, "\n")

# Output the fractions of high MFE TX in UP- and DOWN-regulated genes
cat("Fraction of high MFE TX in UP-regulated genes:", GSE184125_high_MFE_in_UP_fraction, "\n")
cat("Fraction of high MFE TX in DOWN-regulated genes:", GSE184125_high_MFE_in_DOWN_fraction, "\n")

# Output the means and modes for high MFE TX in UP- and DOWN-regulated genes
cat("Mean of high MFE TX in UP-regulated genes:", mean(GSE184125_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mean of high MFE TX in DOWN-regulated genes:", mean(GSE184125_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")
cat("Mode of high MFE TX in UP-regulated genes:", calculate_mode(GSE184125_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mode of high MFE TX in DOWN-regulated genes:", calculate_mode(GSE184125_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")

# Net change in fraction of high MFE TX between UP- and DOWN-regulated genes
cat("Net change in fraction of high MFE TX between UP- and DOWN-regulated genes:", GSE184125_high_MFE_in_UP_fraction - GSE184125_high_MFE_in_DOWN_fraction, "\n")






# Show data as violin plot
# Add a new column to indicate if the value is above the 75th percentile
