# Determine the impact of these changes in terms of fraction of total counts:
# Calculate the fraction of total counts of high MFE transcripts in control and drug-treated groups. 
# This is done by summing the counts of the high MFE transcripts and dividing by the total counts in each group.
# Fisher’s exact test to compare the proportions of high MFE transcripts counts between the two groups.


# Convert from wide to long format
GSE184125_long_data <- GSE184125_norm_TX_counts_MFE_df %>%
  pivot_longer(
    cols = starts_with("GSM"),      # Select all columns starting with "GSM"
    names_to = "replicate",         # Name of the new column for replicate identifiers
    values_to = "counts"            # Name of the new column for the counts
  )

# Add a condition column based on the replicate
GSE184125_long_data <- GSE184125_long_data %>%
  mutate(condition = ifelse(replicate %in% c("GSM5578281", "GSM5578282", "GSM5578283"), "Control", "GSK-3β"))

# Aggregate the replicates for each condition
GSE184125_norm_TX_aggregated_data_avg_counts <- GSE184125_long_data %>%
  group_by(ensembl_transcript_id_version, condition, Normalized_MFE, Specific_heat) %>%
  summarise(
    avg_counts = mean(counts),
    .groups = 'drop'
  )

# Define the 75th percentile of the entire distribution of MFE values for the GSE184125 data
GSE184125_MFE_all_TX_75_percentile <- quantile(GSE184125_norm_TX_aggregated_data_avg_counts$Normalized_MFE, 0.75)

# Identify all the transcripts with MFE values above the 75th percentile
GSE184125_high_MFE_TX_total <- dplyr::filter(GSE184125_norm_TX_counts_MFE_df, Normalized_MFE > GSE184125_MFE_all_TX_75_percentile)

# Fraction of total high MFE transcripts counts in control and drug-treated groups
GSE184125_control_total_counts <- dplyr::filter(GSE184125_norm_TX_aggregated_data_avg_counts, condition == "Control") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE184125_control_high_MFE_TX_counts <- dplyr::filter(GSE184125_norm_TX_aggregated_data_avg_counts, condition == "Control") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE184125_high_MFE_TX_total$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE184125_control_high_MFE_TX_counts_fraction <- GSE184125_control_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE184125_control_total_counts$total_counts
print(GSE184125_control_high_MFE_TX_counts_fraction) # This value goes in the summary table

GSE184125_GSK3β_total_counts <- dplyr::filter(GSE184125_norm_TX_aggregated_data_avg_counts, condition == "GSK-3β") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE184125_GSK3β_high_MFE_TX_counts <- dplyr::filter(GSE184125_norm_TX_aggregated_data_avg_counts, condition == "GSK-3β") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE184125_high_MFE_TX_total$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE184125_GSK3β_high_MFE_TX_counts_fraction <- GSE184125_GSK3β_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE184125_GSK3β_total_counts$total_counts
print(GSE184125_GSK3β_high_MFE_TX_counts_fraction) # This value goes in the summary table

# Fisher's exact test to compare the proportions of high MFE transcripts counts between the two groups
# Create the groups
GSE184125_high_MFE_TX_counts_control_CT <- GSE184125_control_high_MFE_TX_counts_fraction * GSE184125_control_total_counts$total_counts
GSE184125_low_MFE_TX_counts_control_CT <- GSE184125_control_total_counts$total_counts - GSE184125_control_high_MFE_TX_counts$total_counts_high_MFE_TX

GSE184125_high_MFE_TX_counts_GSK3β_CT <- GSE184125_GSK3β_high_MFE_TX_counts_fraction * GSE184125_GSK3β_total_counts$total_counts
GSE184125_low_MFE_TX_counts_GSK3β_CT <- GSE184125_GSK3β_total_counts$total_counts - GSE184125_GSK3β_high_MFE_TX_counts$total_counts_high_MFE_TX

# Construct the contingency table
GSE184125_counts_contingency_table <- matrix(c(GSE184125_high_MFE_TX_counts_control_CT, GSE184125_high_MFE_TX_counts_GSK3β_CT,
                                               GSE184125_low_MFE_TX_counts_control_CT, GSE184125_low_MFE_TX_counts_GSK3β_CT),
                                             nrow = 2,
                                             byrow = TRUE,
                                             dimnames = list(Group = c("Control", "GSK-3β"),
                                                             MFE_Transcripts = c("High_MFE_TX_counts", "Low_MFE_TX_counts")))

# Fisher's test (to be replaced by two-proportion Z-test)
GSE184125_fisher_result_counts <- fisher.test(GSE184125_counts_contingency_table)
cat("GSE184125 Fisher P-value Fisher proportions of high MFE transcripts counts in drug-treated and control :", GSE184125_fisher_result_counts$p.value, "\n")  # This value goes in the summary table

# Now, we will do the two-proportion Z-test

# Proportions of high MFE transcripts in Control and GSK-3β conditions
p_control <- GSE184125_control_high_MFE_TX_counts_fraction
p_GSK3β <- GSE184125_GSK3β_high_MFE_TX_counts_fraction

# Total counts in Control and GSK-3β conditions
n_control <- GSE184125_control_total_counts$total_counts
n_GSK3β <- GSE184125_GSK3β_total_counts$total_counts

# Pooled proportion for high MFE transcripts across both conditions
pooled_prop <- (GSE184125_control_high_MFE_TX_counts$total_counts_high_MFE_TX + GSE184125_GSK3β_high_MFE_TX_counts$total_counts_high_MFE_TX) / (n_control + n_GSK3β)

# Standard error for the difference in proportions
se <- sqrt(pooled_prop * (1 - pooled_prop) * (1 / n_control + 1 / n_GSK3β))

# Z-statistic for the difference in proportions
z_stat <- (p_control - p_GSK3β) / se

# P-value for the two-proportion Z-test (two-tailed test)
GSE184125_z_test_counts_75_p_value <- 2 * pnorm(-abs(z_stat))

# Output the results of the Z-test
cat("Two-proportion Z-test p-value for high MFE TX between Control and GSK-3β drug-treated conditions:", GSE184125_z_test_counts_75_p_value, "\n")
cat("Z-statistic for high MFE TX between Control and GSK-3β drug-treated conditions:", z_stat, "\n")

# Output the fractions of high MFE TX in Control and GSK-3β conditions
cat("Fraction of high MFE TX in Control condition:", p_control, "\n")
cat("Fraction of high MFE TX in GSK-3β condition:", p_GSK3β, "\n")

# Net change in fraction of high MFE TX between Control and GSK-3β conditions
cat("Net change in fraction of high MFE TX between Control and GSK-3β conditions:", p_GSK3β - p_control, "\n")





# Plot Normalized_MFE vs transcript counts of both control and drug-treated conditions
# Create separate data frames for Control and GSK3β conditions
GSE184125_control_data <- GSE184125_norm_TX_aggregated_data_avg_counts %>%
  dplyr::filter(condition == "Control")

