# Look at the mean log2_FC
MFE_res_GSE185141_UP <- dplyr::filter(MFE_res_GSE185141, log2FoldChange > 0)
Mean_MFE_res_GSE185141_UP <- mean(MFE_res_GSE185141_UP$Normalized_MFE)

MFE_res_GSE185141_DOWN <- dplyr::filter(MFE_res_GSE185141, log2FoldChange < 0)
Mean_MFE_res_GSE185141_DOWN <- mean(MFE_res_GSE185141_DOWN$Normalized_MFE)

TTEST_MFE_res_GSE185141_all_UP_vs_DOWN <- t.test(MFE_res_GSE185141_DOWN$Normalized_MFE, MFE_res_GSE185141_UP$Normalized_MFE, paired=FALSE)

# Add K-S test to look at the differences between the up-regukated and down-regulated genes
ks_test_res_GSE185141_all_UP_vs_DOWN <- ks.test(MFE_res_GSE185141_DOWN$Normalized_MFE, MFE_res_GSE185141_UP$Normalized_MFE)


quantile_075_MFE_res_GSE185141_UP <- quantile(MFE_res_GSE185141_UP$Normalized_MFE, probs = c(0.75)) 
quantile_075_MFE_res_GSE185141_DOWN <- quantile(MFE_res_GSE185141_DOWN$Normalized_MFE, probs = c(0.75)) 
# Values above 0.75 quantile
ks_test_MFE_075_above <- ks.test(MFE_res_GSE185141_UP$Normalized_MFE[MFE_res_GSE185141_UP$Normalized_MFE >= quantile_075_MFE_res_GSE185141_UP],
                                 MFE_res_GSE185141_DOWN$Normalized_MFE[MFE_res_GSE185141_DOWN$Normalized_MFE >= quantile_075_MFE_res_GSE185141_DOWN])

# Look at the differences between the 0.25 quantile 
quantile_025_MFE_res_GSE185141_UP <- quantile(MFE_res_GSE185141_UP$Normalized_MFE, probs = c(0.25)) 
quantile_025_MFE_res_GSE185141_DOWN <- quantile(MFE_res_GSE185141_DOWN$Normalized_MFE, probs = c(0.25)) 
# Values below 0.25 quantile
ks_test_MFE_025_below <- ks.test(MFE_res_GSE185141_UP$Normalized_MFE[MFE_res_GSE185141_UP$Normalized_MFE <= quantile_025_MFE_res_GSE185141_UP],
                                 MFE_res_GSE185141_DOWN$Normalized_MFE[MFE_res_GSE185141_DOWN$Normalized_MFE <= quantile_025_MFE_res_GSE185141_DOWN])




# Permutation test MFE changes
# Combine the data into a single data frame with labels
upregulated <- data.frame(MFE = MFE_res_GSE185141_UP$Normalized_MFE, Group = "Up")
downregulated <- data.frame(MFE = MFE_res_GSE185141_DOWN$Normalized_MFE, Group = "Down")
combined_data <- bind_rows(upregulated, downregulated)

# Observed difference in means
GSE185141_observed_diff <- mean(MFE_res_GSE185141_UP$Normalized_MFE) - mean(MFE_res_GSE185141_DOWN$Normalized_MFE)

# Number of permutations
n_permutations <- 10000

# Initialize a vector to store the permuted differences
GSE185141_permuted_diffs <- numeric(n_permutations)

# Permutation test
set.seed(123)  # Set seed for reproducibility
for (i in 1:n_permutations) {
  # Permute the Group labels
  permuted_labels <- sample(combined_data$Group)
  
  # Calculate the mean MFE for each permuted group
  permuted_up_mean <- mean(combined_data$MFE[permuted_labels == "Up"])
  permuted_down_mean <- mean(combined_data$MFE[permuted_labels == "Down"])
  
  # Calculate the difference in means for the permuted groups
  GSE185141_permuted_diffs[i] <- permuted_up_mean - permuted_down_mean
}

# Calculate the p-value
GSE185141_p_value <- (sum(abs(GSE185141_permuted_diffs) >= abs(GSE185141_observed_diff)) + 1) / (n_permutations + 1)

# Output the results
cat("Observed difference in GSE185141 means MFE_UP - MFE_DOWN:", GSE185141_observed_diff, "\n")
cat("GSE185141 P-value from permutation test:", GSE185141_p_value, "\n")









## GSE185141 High MFE TX fraction changes ####
# Determine whether within the differentially expressed genes there is a significant up-regulation of high MFE transcripts:
# Define high MFE transcripts by taking the 75th percentile of the combined MFE distributions of control and drug-treated samples.
# Count the number of transcripts in the significantly up- and down-regulated genes that have MFE values above this threshold.
# Perform a Fisher’s exact test to compare the proportions of high MFE transcripts between the two groups.


# Analysis GSE185141
# Extract the normalized count data
# The minimal pre-filtering has already been done in the previous steps
GSE185141_norm_TX_counts <- counts(dds_GSE185141, normalized=TRUE) # This object is already a matrix
GSE185141_norm_TX_counts_df <- as.data.frame(GSE185141_norm_TX_counts)
# Convert row names to column
GSE185141_norm_TX_counts_df$ensembl_transcript_id <- rownames(GSE185141_norm_TX_counts_df)
# Remove row names
rownames(GSE185141_norm_TX_counts_df) <- NULL

# Move ensembl_transcript_id column to the first position
GSE185141_norm_TX_counts_df <- GSE185141_norm_TX_counts_df[, c("ensembl_transcript_id", setdiff(names(GSE185141_norm_TX_counts_df), "ensembl_transcript_id"))]

# Remove everything after the dot (including the dot itself) in the ensembl_transcript_id column
GSE185141_norm_TX_counts_df$ensembl_transcript_id <- sub("\\..*", "", GSE185141_norm_TX_counts_df$ensembl_transcript_id)

# Join the counts with the Table_ANNOTATED containing MFE values and heat capacity values
GSE185141_norm_TX_counts_MFE_df <- dplyr::inner_join(Table_ANNOTATED, GSE185141_norm_TX_counts_df, by="ensembl_transcript_id") %>%
  dplyr::select(ensembl_transcript_id_version, ensembl_transcript_id, ensembl_gene_id, external_gene_name, transcript_is_canonical, Transcript_length, 
                GSM5606949, GSM5606950, GSM5606951, GSM5606952, GSM5606953, GSM5606954,
                Normalized_MFE, Temperature, Specific_heat)


# GSE185141
# Convert from wide to long format and filter based on ensembl_transcript_id
GSE185141_norm_TX_counts_MFE_df <- dplyr::select(GSE185141_norm_TX_counts_MFE_df, 
                                                 ensembl_transcript_id_version, 
                                                 ensembl_transcript_id, 
                                                 ensembl_gene_id, 
                                                 external_gene_name, 
                                                 transcript_is_canonical, 
                                                 Transcript_length, 
                                                 GSM5606949, GSM5606950, GSM5606951, GSM5606952, GSM5606953, GSM5606954,
                                                 Normalized_MFE, Temperature, Specific_heat) %>%
  dplyr::filter(ensembl_transcript_id %in% MFE_res_GSE185141$ensembl_transcript_id)

# Identify the 75th percentile of the combined MFE distributions of control and drug-treated samples
quantile_075_GSE185141_norm_TX_counts_MFE_df <- quantile(GSE185141_norm_TX_counts_MFE_df$Normalized_MFE, probs = c(0.75))

# Select all the transcripts with Normalized_MFE values above the 75th percentile
GSE185141_high_MFE_TX <- dplyr::filter(GSE185141_norm_TX_counts_MFE_df, Normalized_MFE > quantile_075_GSE185141_norm_TX_counts_MFE_df)

# Count the number of transcripts in the significantly up- and down-regulated pools that have MFE values above this threshold
GSE185141_high_MFE_TX_in_UP <- dplyr::filter(MFE_res_GSE185141_UP, ensembl_transcript_id_version %in% GSE185141_high_MFE_TX$ensembl_transcript_id_version)
GSE185141_high_MFE_TX_in_DOWN <- dplyr::filter(MFE_res_GSE185141_DOWN, ensembl_transcript_id_version %in% GSE185141_high_MFE_TX$ensembl_transcript_id_version)

# Perform a Fisher’s exact test to compare the proportions of high MFE transcripts between the two groups
GSE185141_total_UP <- nrow(MFE_res_GSE185141_UP)
GSE185141_total_DOWN <- nrow(MFE_res_GSE185141_DOWN)
GSE185141_count_high_MFE_UP <- nrow(GSE185141_high_MFE_TX_in_UP)
GSE185141_count_high_MFE_DOWN <- nrow(GSE185141_high_MFE_TX_in_DOWN)

# Construct the contingency table
GSE185141_counts_contingency_table <- matrix(c(GSE185141_count_high_MFE_UP, GSE185141_total_UP - GSE185141_count_high_MFE_UP,
                                               GSE185141_count_high_MFE_DOWN, GSE185141_total_DOWN - GSE185141_count_high_MFE_DOWN),
                                             nrow = 2, byrow = TRUE,
                                             dimnames = list(UP = c("UP-regulated", "DOWN-regulated"),
                                                             DOWN = c("High MFE TX", "Not High MFE TX")))

# Fisher's test
GSE185141_fisher_result <- fisher.test(GSE185141_counts_contingency_table)
cat("GSE185141 P-value from Fisher test:", GSE185141_fisher_result$p.value, "\n")

# Calculate the fractions for the two-proportion Z-test
GSE185141_high_MFE_in_UP_fraction <- GSE185141_count_high_MFE_UP / GSE185141_total_UP
GSE185141_high_MFE_in_DOWN_fraction <- GSE185141_count_high_MFE_DOWN / GSE185141_total_DOWN

# Output the fractions
cat("Fraction of GSE185141 high MFE TX in UP-regulated genes:", GSE185141_high_MFE_in_UP_fraction, "\n")
cat("Fraction of GSE185141 high MFE TX in DOWN-regulated genes:", GSE185141_high_MFE_in_DOWN_fraction, "\n")

# Now, we will do the two-proportion Z-test
# Pooled proportion for high MFE transcripts across both conditions
pooled_prop <- (GSE185141_count_high_MFE_UP + GSE185141_count_high_MFE_DOWN) / (GSE185141_total_UP + GSE185141_total_DOWN)

# Standard error for the difference in proportions
se <- sqrt(pooled_prop * (1 - pooled_prop) * (1 / GSE185141_total_UP + 1 / GSE185141_total_DOWN))

# Z-statistic for the difference in proportions
z_stat <- (GSE185141_high_MFE_in_UP_fraction - GSE185141_high_MFE_in_DOWN_fraction) / se

# P-value for the two-proportion Z-test (two-tailed test)
GSE185141_z_test_MFE_p_value <- 2 * pnorm(-abs(z_stat))

# Output the results of the Z-test
cat("Two-proportion Z-test p-value for high MFE TX between UP-regulated and DOWN-regulated conditions:", GSE185141_z_test_MFE_p_value, "\n")
cat("Z-statistic for high MFE TX between UP-regulated and DOWN-regulated conditions:", z_stat, "\n")

# Mean of high MFE TX in UP-regulated genes
cat("Mean of GSE185141 high MFE TX in UP-regulated genes:", mean(GSE185141_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mean of GSE185141 high MFE TX in DOWN-regulated genes:", mean(GSE185141_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")
cat("Mode of GSE185141 high MFE TX in UP-regulated genes:", calculate_mode(GSE185141_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mode of GSE185141 high MFE TX in DOWN-regulated genes:", calculate_mode(GSE185141_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")






# Show data as violin plot
# Add a new column to indicate if the value is above the 75th percentile
MFE_res_GSE185141$above_quantile_075 <- MFE_res_GSE185141$Normalized_MFE > quantile_075_GSE185141_norm_TX_counts_MFE_df

# Generate violin plot with conditional jitter coloring
