# Look at the mean log2_FC
MFE_res_GSE148096_UP <- dplyr::filter(MFE_res_GSE148096, log2FoldChange > 0)
Mean_MFE_res_GSE148096_UP <- mean(MFE_res_GSE148096_UP$Normalized_MFE, na.rm = TRUE)

MFE_res_GSE148096_DOWN <- dplyr::filter(MFE_res_GSE148096, log2FoldChange < 0)
Mean_MFE_res_GSE148096_DOWN <- mean(MFE_res_GSE148096_DOWN$Normalized_MFE, na.rm = TRUE)

TTEST_MFE_res_GSE148096_all_UP_vs_DOWN <- t.test(MFE_res_GSE148096_DOWN$Normalized_MFE, MFE_res_GSE148096_UP$Normalized_MFE, paired=FALSE)

# Add K-S test to look at the differences between the up-regukated and down-regulated genes
ks_test_res_GSE148096_all_UP_vs_DOWN <- ks.test(MFE_res_GSE148096_DOWN$Normalized_MFE, MFE_res_GSE148096_UP$Normalized_MFE)


quantile_075_MFE_res_GSE148096_UP <- quantile(MFE_res_GSE148096_UP$Normalized_MFE, probs = c(0.75)) 
quantile_075_MFE_res_GSE148096_DOWN <- quantile(MFE_res_GSE148096_DOWN$Normalized_MFE, probs = c(0.75)) 
# Values above 0.75 quantile
ks_test_MFE_075_above <- ks.test(MFE_res_GSE148096_UP$Normalized_MFE[MFE_res_GSE148096_UP$Normalized_MFE >= quantile_075_MFE_res_GSE148096_UP],
                                 MFE_res_GSE148096_DOWN$Normalized_MFE[MFE_res_GSE148096_DOWN$Normalized_MFE >= quantile_075_MFE_res_GSE148096_DOWN])

# Look at the differences between the 0.25 quantile 
quantile_025_MFE_res_GSE148096_UP <- quantile(MFE_res_GSE148096_UP$Normalized_MFE, probs = c(0.25)) 
quantile_025_MFE_res_GSE148096_DOWN <- quantile(MFE_res_GSE148096_DOWN$Normalized_MFE, probs = c(0.25)) 
# Values below 0.25 quantile
ks_test_MFE_025_below <- ks.test(MFE_res_GSE148096_UP$Normalized_MFE[MFE_res_GSE148096_UP$Normalized_MFE <= quantile_025_MFE_res_GSE148096_UP],
                                 MFE_res_GSE148096_DOWN$Normalized_MFE[MFE_res_GSE148096_DOWN$Normalized_MFE <= quantile_025_MFE_res_GSE148096_DOWN])







# Permutation test MFE changes
# Combine the data into a single data frame with labels
upregulated <- data.frame(MFE = MFE_res_GSE148096_UP$Normalized_MFE, Group = "Up")
downregulated <- data.frame(MFE = MFE_res_GSE148096_DOWN$Normalized_MFE, Group = "Down")
combined_data <- bind_rows(upregulated, downregulated)

# Observed difference in means
GSE148096_observed_diff <- mean(MFE_res_GSE148096_UP$Normalized_MFE) - mean(MFE_res_GSE148096_DOWN$Normalized_MFE)

# Number of permutations
n_permutations <- 10000

# Initialize a vector to store the permuted differences
GSE148096_permuted_diffs <- numeric(n_permutations)

# Permutation test
set.seed(123)  # Set seed for reproducibility
for (i in 1:n_permutations) {
  # Permute the Group labels
  permuted_labels <- sample(combined_data$Group)
  
  # Calculate the mean MFE for each permuted group
  permuted_up_mean <- mean(combined_data$MFE[permuted_labels == "Up"])
  permuted_down_mean <- mean(combined_data$MFE[permuted_labels == "Down"])
  
  # Calculate the difference in means for the permuted groups
  GSE148096_permuted_diffs[i] <- permuted_up_mean - permuted_down_mean
}

# Calculate the p-value
GSE148096_p_value <- (sum(abs(GSE148096_permuted_diffs) >= abs(GSE148096_observed_diff)) + 1) / (n_permutations + 1)

# Output the results
cat("Observed difference in GSE148096 means MFE_UP - MFE_DOWN:", GSE148096_observed_diff, "\n")
cat("GSE148096 P-value from permutation test:", GSE148096_p_value, "\n")






## GSE148096 net MFE and heat capacity ####
# IMPORTANT: here, I filter for transcripts with a significant log2_FC.
# The total net MFE is essentially a weighted sum of the MFEs of all transcripts, where the weights are given by the counts of each transcript. 
# This gives the total contribution of each transcript to the overall thermodynamic state of the transcriptome based on their abundance.  


# Analysis GSE148096
# Extract the normalized count data
# The minimal pre-filtering has already been done in the previous steps
GSE148096_norm_TX_counts <- counts(dds_GSE148096, normalized=TRUE) # This object is already a matrix
GSE148096_norm_TX_counts_df <- as.data.frame(GSE148096_norm_TX_counts)
# Convert row names to column
GSE148096_norm_TX_counts_df$ensembl_transcript_id <- rownames(GSE148096_norm_TX_counts_df)
# Remove row names
rownames(GSE148096_norm_TX_counts_df) <- NULL

# Move ensembl_transcript_id column to the first position
GSE148096_norm_TX_counts_df <- GSE148096_norm_TX_counts_df[, c("ensembl_transcript_id", setdiff(names(GSE148096_norm_TX_counts_df), "ensembl_transcript_id"))]

# Remove everything after the dot (including the dot itself) in the ensembl_transcript_id column
GSE148096_norm_TX_counts_df$ensembl_transcript_id <- sub("\\..*", "", GSE148096_norm_TX_counts_df$ensembl_transcript_id)

# Join the counts with the Table_ANNOTATED containing MFE values and heat capacity values
GSE148096_norm_TX_counts_MFE_df <- dplyr::inner_join(Table_ANNOTATED, GSE148096_norm_TX_counts_df, by="ensembl_transcript_id") %>%
  dplyr::select(ensembl_transcript_id_version, ensembl_transcript_id, ensembl_gene_id, external_gene_name, transcript_is_canonical, Transcript_length, 
                GSM4454048, GSM4454049, GSM4454050, GSM4454051, GSM4454052, GSM4454053,
                Normalized_MFE, Temperature, Specific_heat) %>%
  dplyr::filter(ensembl_transcript_id %in% MFE_res_GSE148096$ensembl_transcript_id) 


# Load necessary libraries
library(dplyr)

# Identify the 75th percentile of the combined MFE distributions of control and drug-treated samples
quantile_075_GSE148096_norm_TX_counts_MFE_df <- quantile(GSE148096_norm_TX_counts_MFE_df$Normalized_MFE, probs = c(0.75))

# Select all the transcripts with Normalized_MFE values above the 75th percentile
GSE148096_high_MFE_TX <- dplyr::filter(GSE148096_norm_TX_counts_MFE_df, Normalized_MFE > quantile_075_GSE148096_norm_TX_counts_MFE_df)

# Count the number of transcripts in the significantly up- and down-regulated pools that have MFE values above this threshold
GSE148096_high_MFE_TX_in_UP <- dplyr::filter(MFE_res_GSE148096_UP, ensembl_transcript_id_version %in% GSE148096_high_MFE_TX$ensembl_transcript_id_version)
GSE148096_high_MFE_TX_in_DOWN <- dplyr::filter(MFE_res_GSE148096_DOWN, ensembl_transcript_id_version %in% GSE148096_high_MFE_TX$ensembl_transcript_id_version)

# Calculate fractions of high MFE transcripts in up-regulated and down-regulated gene sets
GSE148096_total_UP <- nrow(MFE_res_GSE148096_UP)
GSE148096_total_DOWN <- nrow(MFE_res_GSE148096_DOWN)

GSE148096_count_high_MFE_UP <- nrow(GSE148096_high_MFE_TX_in_UP)
GSE148096_count_high_MFE_DOWN <- nrow(GSE148096_high_MFE_TX_in_DOWN)

GSE148096_high_MFE_in_UP_fraction <- GSE148096_count_high_MFE_UP / GSE148096_total_UP
GSE148096_high_MFE_in_DOWN_fraction <- GSE148096_count_high_MFE_DOWN / GSE148096_total_DOWN

# Output the results
cat("Fraction of GSE148096 high MFE TX in UP-regulated genes:", GSE148096_high_MFE_in_UP_fraction, "\n")
cat("Fraction of GSE148096 high MFE TX in DOWN-regulated genes:", GSE148096_high_MFE_in_DOWN_fraction, "\n")

# Now, we will perform the two-proportion Z-test

# Proportions of high MFE transcripts in up-regulated and down-regulated gene sets
p_up <- GSE148096_high_MFE_in_UP_fraction
p_down <- GSE148096_high_MFE_in_DOWN_fraction

# Total counts in up-regulated and down-regulated gene sets
n_up <- GSE148096_total_UP
n_down <- GSE148096_total_DOWN

# Pooled proportion for high MFE transcripts across both groups
pooled_prop <- (GSE148096_count_high_MFE_UP + GSE148096_count_high_MFE_DOWN) / (n_up + n_down)

# Standard error for the difference in proportions
se <- sqrt(pooled_prop * (1 - pooled_prop) * (1 / n_up + 1 / n_down))

# Z-statistic for the difference in proportions
z_stat <- (p_up - p_down) / se

# P-value for the two-proportion Z-test (two-tailed test)
GSE148096_z_test_MFE_p_value <- 2 * pnorm(-abs(z_stat))

# Output the results of the Z-test
cat("Two-proportion Z-test p-value for high MFE TX between UP-regulated and DOWN-regulated genes:", GSE148096_z_test_MFE_p_value, "\n")
cat("Z-statistic for high MFE TX between UP-regulated and DOWN-regulated genes:", z_stat, "\n")

# Output the mean and mode of high MFE TX in UP- and DOWN-regulated genes
cat("Mean of GSE148096 high MFE TX in UP-regulated genes:", mean(GSE148096_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mean of GSE148096 high MFE TX in DOWN-regulated genes:", mean(GSE148096_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")

cat("Mode of GSE148096 high MFE TX in UP-regulated genes:", calculate_mode(GSE148096_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mode of GSE148096 high MFE TX in DOWN-regulated genes:", calculate_mode(GSE148096_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")




# Show data as violin plot
# Add a new column to indicate if the value is above the 75th percentile
MFE_res_GSE148096$above_quantile_075 <- MFE_res_GSE148096$Normalized_MFE > quantile_075_GSE148096_norm_TX_counts_MFE_df

# Generate violin plot with conditional jitter coloring
Plot_MFE_GSE148096 <- ggplot(MFE_res_GSE148096, aes(x = factor(log2FoldChange > 0), y = Normalized_MFE)) +
  geom_violin(fill = "white", size = 1.5) +
  geom_jitter(aes(color = above_quantile_075), width = 0.1, size = 1, alpha = 1) +
  scale_color_manual(values = c("FALSE" = "black", "TRUE" = "dodgerblue3")) +
  theme_classic() +
  ylim(-0.6, 0) +
  theme(
    legend.position = "none", 
    axis.title = element_text(size = 20), 
    plot.title = element_text(size = 10),
    axis.text.x = element_text(size = 16, color = "black")
  ) +
  geom_vline(xintercept = 0, linewidth = 0.3) +
  labs(
    y = "Normalized_MFE", 
    x = NULL, 
    title = "GSE148096_Log2_FC_adj.P<0.05"
  ) +
  scale_x_discrete(labels = c("log2_FC < 0", "log2_FC > 0"))

print(Plot_MFE_GSE148096)












# Determine the impact of these changes in terms of fraction of total counts:
# Calculate the fraction of total counts of high MFE transcripts in control and drug-treated groups. 
# This is done by summing the counts of the high MFE transcripts and dividing by the total counts in each group.
# Fisher’s exact test to compare the proportions of high MFE transcripts counts between the two groups.


# Load necessary libraries
library(dplyr)

# Convert from wide to long format
GSE148096_long_data <- GSE148096_norm_TX_counts_MFE_df %>%
  pivot_longer(
    cols = starts_with("GSM"),      # Select all columns starting with "GSM"
    names_to = "replicate",         # Name of the new column for replicate identifiers
    values_to = "counts"            # Name of the new column for the counts
  )

# Add a condition column based on the replicate
GSE148096_long_data <- GSE148096_long_data %>%
  mutate(condition = ifelse(replicate %in% c("GSM4454048", "GSM4454049", "GSM4454050"), "Control", "Erlotinib"))

# Aggregate the replicates for each condition
GSE148096_norm_TX_aggregated_data_avg_counts <- GSE148096_long_data %>%
  group_by(ensembl_transcript_id_version, condition, Normalized_MFE, Specific_heat) %>%
  summarise(
    avg_counts = mean(counts),
    .groups = 'drop'
  )

# Define the 75th percentile of the entire distribution of MFE values for the GSE148096 data
GSE148096_MFE_all_TX_75_percentile <- quantile(GSE148096_norm_TX_aggregated_data_avg_counts$Normalized_MFE, 0.75)

# Identify all the transcripts with MFE values above the 75th percentile
GSE148096_high_MFE_TX_total <- dplyr::filter(GSE148096_norm_TX_counts_MFE_df, Normalized_MFE > GSE148096_MFE_all_TX_75_percentile)

# Fraction of total high MFE transcripts counts in control and drug-treated groups
GSE148096_control_total_counts <- dplyr::filter(GSE148096_norm_TX_aggregated_data_avg_counts, condition == "Control") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE148096_control_high_MFE_TX_counts <- dplyr::filter(GSE148096_norm_TX_aggregated_data_avg_counts, condition == "Control") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE148096_high_MFE_TX_total$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE148096_control_high_MFE_TX_counts_fraction <- GSE148096_control_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE148096_control_total_counts$total_counts
print(GSE148096_control_high_MFE_TX_counts_fraction) # This value goes in the summary table

GSE148096_Erlotinib_total_counts <- dplyr::filter(GSE148096_norm_TX_aggregated_data_avg_counts, condition == "Erlotinib") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE148096_Erlotinib_high_MFE_TX_counts <- dplyr::filter(GSE148096_norm_TX_aggregated_data_avg_counts, condition == "Erlotinib") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE148096_high_MFE_TX_total$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE148096_Erlotinib_high_MFE_TX_counts_fraction <- GSE148096_Erlotinib_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE148096_Erlotinib_total_counts$total_counts
print(GSE148096_Erlotinib_high_MFE_TX_counts_fraction) # This value goes in the summary table

# Now, perform the two-proportion Z-test

# Proportions of high MFE transcripts in Control and Erlotinib groups
p_control <- GSE148096_control_high_MFE_TX_counts_fraction
p_erlotinib <- GSE148096_Erlotinib_high_MFE_TX_counts_fraction

# Total counts in Control and Erlotinib groups
n_control <- GSE148096_control_total_counts$total_counts
n_erlotinib <- GSE148096_Erlotinib_total_counts$total_counts

# Pooled proportion for high MFE transcripts across both groups
pooled_prop <- (GSE148096_control_high_MFE_TX_counts$total_counts_high_MFE_TX + GSE148096_Erlotinib_high_MFE_TX_counts$total_counts_high_MFE_TX) / (n_control + n_erlotinib)

# Standard error for the difference in proportions
se <- sqrt(pooled_prop * (1 - pooled_prop) * (1 / n_control + 1 / n_erlotinib))

# Z-statistic for the difference in proportions
z_stat <- (p_control - p_erlotinib) / se

# P-value for the two-proportion Z-test (two-tailed test)
GSE148096_z_test_counts_75_p_value <- 2 * pnorm(-abs(z_stat))

# Output the results of the Z-test
cat("Two-proportion Z-test p-value for high MFE TX between Control and Erlotinib:", GSE148096_z_test_counts_75_p_value, "\n")
cat("Z-statistic for high MFE TX between Control and Erlotinib:", z_stat, "\n")

# Output the results for the fractions
cat("GSE148096 control high MFE TX as fraction of total counts:", GSE148096_control_high_MFE_TX_counts_fraction, "\n")
cat("GSE148096 Erlotinib high MFE TX as fraction of total counts:", GSE148096_Erlotinib_high_MFE_TX_counts_fraction, "\n")
cat("GSE148096 net change counts high MFE TX drug vs control:", GSE148096_Erlotinib_high_MFE_TX_counts_fraction - GSE148096_control_high_MFE_TX_counts_fraction, "\n")





