# GSE178755 erlotinib on HCC827 lung adenocarcinoma cell line ####
# http://www.ilincs.org/apps/grein/?gse=GSE178755

Counts_GSE178755_GREIN <- read.delim("path_to/GSE178755/GSE178755_TranscriptLevel_Raw_data.csv", sep = ",", header = T, stringsAsFactors = F)
Counts_GSE178755_GREIN <- Counts_GSE178755_GREIN %>% remove_rownames %>% column_to_rownames(var="X") # Convert first column into row names in data frame
# Round counts down to the nearest integer
Counts_GSE178755_GREIN <- floor(Counts_GSE178755_GREIN)


# Access the Series Matrix
# Data_GSE178755 <- getGEO(GEO = "GSE178755")

# LOad the object
Data_GSE178755 <- readRDS("path_to/GREIN_series_matrices_data/Data_GSE178755.rds")


# Extract the phenotypic/clinical data matrix from the series matrix
Expdata_GSE178755 <- Data_GSE178755[["GSE178755_series_matrix.txt.gz"]]@phenoData@data

colnames(Expdata_GSE178755)[colnames(Expdata_GSE178755) == "treatment:ch1"] <- "condition" # Rename the column to have an easier identifier for the conditions
Expdata_GSE178755$condition <- gsub("DMSO treated", "DMSO", Expdata_GSE178755$condition)
Expdata_GSE178755$condition <- gsub("erlotinib treated", "ERLOTINIB", Expdata_GSE178755$condition)


# IMPORTANT:
# It is absolutely critical that the columns of the count matrix and the rows of the column data (information about samples) are in the same order.

# Replace the row names of Expdata_GSE178755 (sampleID) with the same sample name [title] of [Counts_GSE182018]. 
# This will help to match sample names in both matrices.
# The outcome should be TRUE
all(rownames(Expdata_GSE178755) %in% colnames(Counts_GSE178755_GREIN))
all(colnames(Counts_GSE178755_GREIN) %in% rownames(Expdata_GSE178755))

# With the count matrix, Counts_GSE108308_GREIN, and the sample information, Expdata_GSE108308, we can construct a DESeqDataSet:
dds_GSE178755 <- DESeqDataSetFromMatrix(countData = Counts_GSE178755_GREIN,
                                        colData = Expdata_GSE178755,
                                        design = ~ condition)
dds_GSE178755




# DATA QUALITY ASSESSMENT MIA_PACA2 COUNTS
# Before performing differential expression analysis, we perform data quality assessment by sample clustering and visualization
library("pheatmap")
# We log transform the counts
ntd <- normTransform(dds_GSE178755)
# Heat map of the count matrix
select <- order(rowMeans(counts(dds_GSE178755,normalized=FALSE)),
                decreasing=TRUE)[1:25]
df <- as.data.frame(colData(dds_GSE178755)[,c("condition","type")])
pheatmap(assay(ntd)[select,], cluster_rows=FALSE, show_rownames=FALSE,
         cluster_cols=FALSE, annotation_col=df)



# Heatmap of the sample-to-sample distances
# A heatmap of this distance matrix gives us an overview over similarities and dissimilarities between samples
# Transform the values
vsd <- vst(dds_GSE178755, blind=FALSE)
# rld <- rlog(dds_GSE178755, blind=FALSE)
head(assay(vsd), 3)

# Apply the dist function to the transpose of the transformed count matrix to get sample-to-sample distances
sampleDists <- dist(t(assay(vsd)))

# Condition
library("RColorBrewer")
sampleDistMatrix <- as.matrix(sampleDists)
rownames(sampleDistMatrix) <- paste(vsd$condition, vsd$type, sep="-")
colnames(sampleDistMatrix) <- NULL
colors <- colorRampPalette( rev(brewer.pal(9, "Blues")) )(255)
pheatmap(sampleDistMatrix,
         clustering_distance_rows=sampleDists,
         clustering_distance_cols=sampleDists,
         col=colors)

# Principal component plot of the samples
plotPCA(vsd, intgroup="condition")




# DIFFERENTIAL EXPRESSION ANALYSIS
# We perform a minimal pre-filtering to keep only rows that have at least 3 reads total
keep <- rowSums(counts(dds_GSE178755)) >= 3
dds_GSE178755 <- dds_GSE178755[keep,]
table(keep) # This shows how many transcripts have been removed after the filtering
nrow(dds_GSE178755) # to confirm the filtered transcripts

# DIFFERENTIAL EXPRESSION ANALYSIS
dds_GSE178755 <- DESeq(dds_GSE178755) # The DESeq() function normalizes the read counts, estimates dispersions, and fits the linear model, all in one go
# dds_GSE178755 <- DESeq(dds_GSE178755, betaPrior = T)  The betaPrior = T opton tells DESeq2 to squeeze the log Fold Changes of lowly expressed genes toward zero.

# If I want to see the normalized counts generated in the DESeq object:
# norm_dds_GSE178755 <- counts(dds_GSE178755, normalized=TRUE)

# resultsNames(dds_GSE178755) # lists the coefficients
# plotDispEsts(dds_GSE178755) # Plot the dispersions
# Each black dot in the plot represents the dispersion for one gene. The red line is fit to data (black bots),
# then the dispersions are squeezed toward the red line, resulting the final (blue) dispersion estimates. Usually,
# the dispersion is highest at the low counts and levels off at higher counts.


# Specify the conditions to contrast for differential expression analysis
res_GSE178755 <- results(dds_GSE178755, contrast=c("condition","ERLOTINIB","DMSO")) # to specify the samples to contrast
res_GSE178755
# Get a summary of the results
summary(res_GSE178755)




# Plot the log2 Fold Changes as function of expression:
plotMA(res_GSE178755,alpha = 0.05)
abline(h=c(-2,2),col = "red")

# Transform the row names into a column
res_GSE178755_df <- data.frame(res_GSE178755)
res_GSE178755 <- tibble::rownames_to_column(res_GSE178755_df, "ensembl_transcript_id")



# Join the expression change values with the Table_ANNOTATED containing MFE values
MFE_res_GSE178755 <- dplyr::inner_join(Table_ANNOTATED, res_GSE178755, by="ensembl_transcript_id") %>% # The file 'Table' contains the Normalized_MFE values of all ANNOTATED transcripts
  dplyr::filter(padj < 0.05) 


# Generate a scatter plot Log2_FC vs Normalized_MFE

Plot_GSE178755 <- ggplot(MFE_res_GSE178755, aes(y=Normalized_MFE, x=log2FoldChange)) +
  geom_point(size=1.5, alpha=0.3)+
  theme_classic() +
  theme(legend.position="none") +
  geom_vline(xintercept = 0, size=0.3) +
  #xlim(-5.5,5.5) +
  theme(axis.title = element_text(size = 20)) +
  theme(plot.title = element_text(size = 15)) +
  labs(y="DGfold / nt (kcal/mol)",x="Log2_FC_expression",title="GSE178755_Log2_FC_adj.P<0.05")
print(Plot_GSE178755)



# Look at the mean log2_FC
MFE_res_GSE178755_UP <- dplyr::filter(MFE_res_GSE178755, log2FoldChange > 0)
Mean_MFE_res_GSE178755_UP <- mean(MFE_res_GSE178755_UP$Normalized_MFE, na.rm = TRUE)

MFE_res_GSE178755_DOWN <- dplyr::filter(MFE_res_GSE178755, log2FoldChange < 0)
Mean_MFE_res_GSE178755_DOWN <- mean(MFE_res_GSE178755_DOWN$Normalized_MFE, na.rm = TRUE)

TTEST_MFE_res_GSE178755_all_UP_vs_DOWN <- t.test(MFE_res_GSE178755_DOWN$Normalized_MFE, MFE_res_GSE178755_UP$Normalized_MFE, paired=FALSE)

# Add K-S test to look at the differences between the up-regulated and down-regulated genes
ks_test_res_GSE178755_all_UP_vs_DOWN <- ks.test(MFE_res_GSE178755_DOWN$Normalized_MFE, MFE_res_GSE178755_UP$Normalized_MFE)


quantile_075_MFE_res_GSE178755_UP <- quantile(MFE_res_GSE178755_UP$Normalized_MFE, probs = c(0.75)) 
quantile_075_MFE_res_GSE178755_DOWN <- quantile(MFE_res_GSE178755_DOWN$Normalized_MFE, probs = c(0.75)) 
# Values above 0.75 quantile
ks_test_MFE_075_above <- ks.test(MFE_res_GSE178755_UP$Normalized_MFE[MFE_res_GSE178755_UP$Normalized_MFE >= quantile_075_MFE_res_GSE178755_UP],
                                 MFE_res_GSE178755_DOWN$Normalized_MFE[MFE_res_GSE178755_DOWN$Normalized_MFE >= quantile_075_MFE_res_GSE178755_DOWN])

# Look at the differences between the 0.25 quantile 
quantile_025_MFE_res_GSE178755_UP <- quantile(MFE_res_GSE178755_UP$Normalized_MFE, probs = c(0.25)) 
quantile_025_MFE_res_GSE178755_DOWN <- quantile(MFE_res_GSE178755_DOWN$Normalized_MFE, probs = c(0.25)) 
# Values below 0.25 quantile
ks_test_MFE_025_below <- ks.test(MFE_res_GSE178755_UP$Normalized_MFE[MFE_res_GSE178755_UP$Normalized_MFE <= quantile_025_MFE_res_GSE178755_UP],
                                 MFE_res_GSE178755_DOWN$Normalized_MFE[MFE_res_GSE178755_DOWN$Normalized_MFE <= quantile_025_MFE_res_GSE178755_DOWN])






# Permutation test MFE changes
# Combine the data into a single data frame with labels
upregulated <- data.frame(MFE = MFE_res_GSE178755_UP$Normalized_MFE, Group = "Up")
downregulated <- data.frame(MFE = MFE_res_GSE178755_DOWN$Normalized_MFE, Group = "Down")
combined_data <- bind_rows(upregulated, downregulated)

# Observed difference in means
GSE178755_observed_diff <- mean(MFE_res_GSE178755_UP$Normalized_MFE) - mean(MFE_res_GSE178755_DOWN$Normalized_MFE)

# Number of permutations
n_permutations <- 10000

# Initialize a vector to store the permuted differences
GSE178755_permuted_diffs <- numeric(n_permutations)

# Permutation test
set.seed(123)  # Set seed for reproducibility
for (i in 1:n_permutations) {
  # Permute the Group labels
  permuted_labels <- sample(combined_data$Group)
  
  # Calculate the mean MFE for each permuted group
  permuted_up_mean <- mean(combined_data$MFE[permuted_labels == "Up"])
  permuted_down_mean <- mean(combined_data$MFE[permuted_labels == "Down"])
  
  # Calculate the difference in means for the permuted groups
  GSE178755_permuted_diffs[i] <- permuted_up_mean - permuted_down_mean
}

# Calculate the p-value
GSE178755_p_value <- (sum(abs(GSE178755_permuted_diffs) >= abs(GSE178755_observed_diff)) + 1) / (n_permutations + 1)

# Output the results
cat("Observed difference in GSE178755 means MFE_UP - MFE_DOWN:", GSE178755_observed_diff, "\n")
cat("GSE178755 P-value from permutation test:", GSE178755_p_value, "\n")











## GSE182018 High MFE TX fraction changes ####
# Determine whether within the differentially expressed genes there is a significant up-regulation of high MFE transcripts:
# Define high MFE transcripts by taking the 75th percentile of the combined MFE distributions of control and drug-treated samples.
# Count the number of transcripts in the significantly up- and down-regulated genes that have MFE values above this threshold.
# Perform a Fisher’s exact test to compare the proportions of high MFE transcripts between the two groups.


# Analysis GSE178755
# Extract the normalized count data
# The minimal pre-filtering has already been done in the previous steps
GSE178755_norm_TX_counts <- counts(dds_GSE178755, normalized=TRUE) # This object is already a matrix
GSE178755_norm_TX_counts_df <- as.data.frame(GSE178755_norm_TX_counts)
# Convert row names to column
GSE178755_norm_TX_counts_df$ensembl_transcript_id <- rownames(GSE178755_norm_TX_counts_df)
# Remove row names
rownames(GSE178755_norm_TX_counts_df) <- NULL

# Move ensembl_transcript_id column to the first position
GSE178755_norm_TX_counts_df <- GSE178755_norm_TX_counts_df[, c("ensembl_transcript_id", setdiff(names(GSE178755_norm_TX_counts_df), "ensembl_transcript_id"))]

# Remove everything after the dot (including the dot itself) in the ensembl_transcript_id column
GSE178755_norm_TX_counts_df$ensembl_transcript_id <- sub("\\..*", "", GSE178755_norm_TX_counts_df$ensembl_transcript_id)

# Join the counts with the Table_ANNOTATED containing MFE values and heat capacity values
GSE178755_norm_TX_counts_MFE_df <- dplyr::inner_join(Table_ANNOTATED, GSE178755_norm_TX_counts_df, by="ensembl_transcript_id") %>%
  dplyr::select(ensembl_transcript_id_version, ensembl_transcript_id, ensembl_gene_id, external_gene_name, transcript_is_canonical, Transcript_length, 
                GSM5396967, GSM5396968, GSM5396969, GSM5396970, GSM5396971, GSM5396972,
                Normalized_MFE, Temperature, Specific_heat) %>%
  dplyr::filter(ensembl_transcript_id %in% MFE_res_GSE178755$ensembl_transcript_id) 



# Identify the 75th percentile of the combined MFE distributions of control and drug-treated samples
quantile_075_GSE178755_norm_TX_counts_MFE_df <- quantile(GSE178755_norm_TX_counts_MFE_df$Normalized_MFE, probs = c(0.75))

# Select all the transcripts with Normalized_MFE values above the 75th percentile
GSE178755_high_MFE_TX <- dplyr::filter(GSE178755_norm_TX_counts_MFE_df, Normalized_MFE > quantile_075_GSE178755_norm_TX_counts_MFE_df)

# Count the number of transcripts in the significantly up- and down-regulated pools that have MFE values above this threshold.
GSE178755_high_MFE_TX_in_UP <- dplyr::filter(MFE_res_GSE178755_UP, ensembl_transcript_id_version %in% GSE178755_high_MFE_TX$ensembl_transcript_id_version)
GSE178755_high_MFE_TX_in_DOWN <- dplyr::filter(MFE_res_GSE178755_DOWN, ensembl_transcript_id_version %in% GSE178755_high_MFE_TX$ensembl_transcript_id_version)

# Calculate the proportions of high MFE transcripts in up-regulated and down-regulated genes
GSE178755_total_UP <- nrow(MFE_res_GSE178755_UP)
GSE178755_total_DOWN <- nrow(MFE_res_GSE178755_DOWN)
GSE178755_count_high_MFE_UP <- nrow(GSE178755_high_MFE_TX_in_UP)
GSE178755_count_high_MFE_DOWN <- nrow(GSE178755_high_MFE_TX_in_DOWN)

# Calculate the proportions of high MFE transcripts
p_UP_high_MFE <- GSE178755_count_high_MFE_UP / GSE178755_total_UP
p_DOWN_high_MFE <- GSE178755_count_high_MFE_DOWN / GSE178755_total_DOWN

# Pooled proportion for high MFE transcripts across both groups
pooled_prop_high_MFE <- (GSE178755_count_high_MFE_UP + GSE178755_count_high_MFE_DOWN) / (GSE178755_total_UP + GSE178755_total_DOWN)

# Standard error for the difference in proportions
se_high_MFE <- sqrt(pooled_prop_high_MFE * (1 - pooled_prop_high_MFE) * (1 / GSE178755_total_UP + 1 / GSE178755_total_DOWN))

# Z-statistic for the difference in proportions
z_stat_high_MFE <- (p_UP_high_MFE - p_DOWN_high_MFE) / se_high_MFE

# P-value for the two-proportion Z-test (two-tailed test)
GSE178755_z_test_MFE_p_value <- 2 * pnorm(-abs(z_stat_high_MFE))

# Output the results of the Z-test
cat("Two-proportion Z-test p-value for high MFE TX between UP-regulated and DOWN-regulated genes:", GSE178755_z_test_MFE_p_value, "\n")
cat("Z-statistic for high MFE TX between UP-regulated and DOWN-regulated genes:", z_stat_high_MFE, "\n")

# Look at the fractions for high MFE TX
GSE178755_high_MFE_in_UP_fraction <- GSE178755_count_high_MFE_UP / GSE178755_total_UP
GSE178755_high_MFE_in_DOWN_fraction <- GSE178755_count_high_MFE_DOWN / GSE178755_total_DOWN

# Output the fractions
cat("Fraction of GSE178755 high MFE TX in UP-regulated genes:", GSE178755_high_MFE_in_UP_fraction, "\n") # This value goes in the summary table
cat("Fraction of GSE178755 high MFE TX in DOWN-regulated genes:", GSE178755_high_MFE_in_DOWN_fraction, "\n") # This value goes in the summary table

# Output the mean and mode of MFE for high MFE transcripts in up- and down-regulated genes
cat("Mean of GSE178755 high MFE TX in UP-regulated genes:", mean(GSE178755_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mean of GSE178755 high MFE TX in DOWN-regulated genes:", mean(GSE178755_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")
cat("Mode of GSE178755 high MFE TX in UP-regulated genes:", calculate_mode(GSE178755_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mode of GSE178755 high MFE TX in DOWN-regulated genes:", calculate_mode(GSE178755_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")





# Show data as violin plot
# Add a new column to indicate if the value is above the 75th percentile
