# Determine the impact of these changes in terms of fraction of total counts:
# Calculate the fraction of total counts of high MFE transcripts in control and drug-treated groups. 
# This is done by summing the counts of the high MFE transcripts and dividing by the total counts in each group.
# Fisher’s exact test to compare the proportions of high MFE transcripts counts between the two groups.


# Convert from wide to long format
GSE178755_long_data <- GSE178755_norm_TX_counts_MFE_df %>%
  pivot_longer(
    cols = starts_with("GSM"),      # Select all columns starting with "GSM"
    names_to = "replicate",         # Name of the new column for replicate identifiers
    values_to = "counts"            # Name of the new column for the counts
  )

# Add a condition column based on the replicate
GSE178755_long_data <- GSE178755_long_data %>%
  mutate(condition = ifelse(replicate %in% c("GSM5396967", "GSM5396968", "GSM5396969"), "Control", "Erlotinib"))

# Aggregate the replicates for each condition
GSE178755_norm_TX_aggregated_data_avg_counts <- GSE178755_long_data %>%
  group_by(ensembl_transcript_id_version, condition, Normalized_MFE, Specific_heat) %>%
  summarise(
    avg_counts = mean(counts),
    .groups = 'drop'
  )

# Define the 75th percentile of the entire distribution of MFE values for the GSE178755 data
GSE178755_MFE_all_TX_75_percentile <- quantile(GSE178755_norm_TX_aggregated_data_avg_counts$Normalized_MFE, 0.75)

# Identify all the transcripts with MFE values above the 75th percentile
GSE178755_high_MFE_TX_total <- dplyr::filter(GSE178755_norm_TX_counts_MFE_df, Normalized_MFE > GSE178755_MFE_all_TX_75_percentile)

# Fraction of total high MFE transcripts counts in control and drug-treated groups
GSE178755_control_total_counts <- dplyr::filter(GSE178755_norm_TX_aggregated_data_avg_counts, condition == "Control") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE178755_control_high_MFE_TX_counts <- dplyr::filter(GSE178755_norm_TX_aggregated_data_avg_counts, condition == "Control") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE178755_high_MFE_TX_total$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE178755_control_high_MFE_TX_counts_fraction <- GSE178755_control_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE178755_control_total_counts$total_counts
print(GSE178755_control_high_MFE_TX_counts_fraction) # This value goes in the summary table



GSE178755_Erlotinib_total_counts <- dplyr::filter(GSE178755_norm_TX_aggregated_data_avg_counts, condition == "Erlotinib") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE178755_Erlotinib_high_MFE_TX_counts <- dplyr::filter(GSE178755_norm_TX_aggregated_data_avg_counts, condition == "Erlotinib") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE178755_high_MFE_TX_total$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE178755_Erlotinib_high_MFE_TX_counts_fraction <- GSE178755_Erlotinib_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE178755_Erlotinib_total_counts$total_counts
print(GSE178755_Erlotinib_high_MFE_TX_counts_fraction) # This value goes in the summary table




# Number of high MFE transcripts in Control and Erlotinib
high_MFE_TX_control <- GSE178755_control_high_MFE_TX_counts$total_counts_high_MFE_TX
high_MFE_TX_Erlotinib <- GSE178755_Erlotinib_high_MFE_TX_counts$total_counts_high_MFE_TX

# Total number of transcripts in Control and Erlotinib
total_control <- GSE178755_control_total_counts$total_counts
total_Erlotinib <- GSE178755_Erlotinib_total_counts$total_counts

# Calculate the pooled proportion of high MFE transcripts
pooled_proportion <- (high_MFE_TX_control + high_MFE_TX_Erlotinib) / (total_control + total_Erlotinib)

# Calculate the standard error of the difference in proportions
SE <- sqrt(pooled_proportion * (1 - pooled_proportion) * (1 / total_control + 1 / total_Erlotinib))

# Calculate the Z-score
z_score <- (GSE178755_control_high_MFE_TX_counts_fraction - GSE178755_Erlotinib_high_MFE_TX_counts_fraction) / SE

# Calculate the p-value (Two-tailed test)
GSE178755_z_test_counts_75_p_value <- 2 * pnorm(-abs(z_score))  # Two-tailed test

# Output the results
cat("Z-score for Two-Proportion Z-test:", z_score, "\n")
cat("P-value for Two-Proportion Z-test:", GSE178755_z_test_counts_75_p_value, "\n")


# Also, output the net change (difference) in the proportions
net_change_in_proportions <- GSE178755_Erlotinib_high_MFE_TX_counts_fraction - GSE178755_control_high_MFE_TX_counts_fraction
cat("Net change in proportions of high MFE transcripts (Erlotinib vs Control):", net_change_in_proportions, "\n")





