#Counts_GSE103021_trametinib_A549_GREIN <- dplyr::select(Counts_GSE103021_GREIN, c(GSM2752555, GSM2752556, GSM2752559, GSM2752560))


# Access the Series Matrix
# Data_GSE103021 <- getGEO(GEO = "GSE103021")

# LOad the object
Data_GSE103021 <- readRDS("path_to/GREIN_series_matrices_data/Data_GSE103021.rds")


# Extract the phenotypic/clinical data matrix from the series matrix
Expdata_GSE103021 <- Data_GSE103021[["GSE103021_series_matrix.txt.gz"]]@phenoData@data
# Merge two columns describing the conditions
Expdata_GSE103021$condition <- paste(Expdata_GSE103021$`agent:ch1`, Expdata_GSE103021$`cell line:ch1`, sep = "-")

Expdata_GSE103021$condition <- gsub("DMSO treated-NCI-H358", "DMSO_H358", Expdata_GSE103021$condition)
