Expdata_GSE103021$condition <- gsub("trametinib treated 50nM-A549", "trametinib_A549", Expdata_GSE103021$condition)

# Create the metadata for each cell line and drug treatment
# Select only the rows of the counts that are necessary for the analysis
Expdata_GSE103021_H358_ARS_1620 = Expdata_GSE103021[c(1,2,3,4,5,6,7),] 
Expdata_GSE103021_ARS_1620_LU65 = Expdata_GSE103021[c(14,15,16,17,18,19),] 
Expdata_GSE103021_trametinib_LU65 = Expdata_GSE103021[c(14,15,16,20,21),] 
