#Expdata_GSE103021_trametinib_A549 = Expdata_GSE103021[c(22,23,26,27),] 



# Analysis Counts_GSE103021_H358_ARS_1620_GREIN
# IMPORTANT:
# It is absolutely critical that the columns of the count matrix and the rows of the column data (information about samples) are in the same order.

# Replace the row names of Expdata_GSE103021_H358_ARS_1620 (sampleID) with the same sample name [title] of [Counts_GSE182018]. 
# This will help to match sample names in both matrices.
# The outcome should be TRUE
all(rownames(Expdata_GSE103021_H358_ARS_1620) %in% colnames(Counts_GSE103021_H358_ARS_1620_GREIN))
all(colnames(Counts_GSE103021_H358_ARS_1620_GREIN) %in% rownames(Expdata_GSE103021_H358_ARS_1620))

# With the count matrix, Counts_GSE108308_GREIN, and the sample information, Expdata_GSE108308, we can construct a DESeqDataSet:
dds_GSE103021_H358_ARS_1620 <- DESeqDataSetFromMatrix(countData = Counts_GSE103021_H358_ARS_1620_GREIN,
                                        colData = Expdata_GSE103021_H358_ARS_1620,
                                        design = ~ condition)
dds_GSE103021_H358_ARS_1620




# DATA QUALITY ASSESSMENT MIA_PACA2 COUNTS
# Before performing differential expression analysis, we perform data quality assessment by sample clustering and visualization
library("pheatmap")
# We log transform the counts
ntd <- normTransform(dds_GSE103021_H358_ARS_1620)
# Heat map of the count matrix
select <- order(rowMeans(counts(dds_GSE103021_H358_ARS_1620,normalized=FALSE)),
                decreasing=TRUE)[1:25]
df <- as.data.frame(colData(dds_GSE103021_H358_ARS_1620)[,c("condition","type")])
pheatmap(assay(ntd)[select,], cluster_rows=FALSE, show_rownames=FALSE,
         cluster_cols=FALSE, annotation_col=df)



# Heatmap of the sample-to-sample distances
# A heatmap of this distance matrix gives us an overview over similarities and dissimilarities between samples
# Transform the values
vsd <- vst(dds_GSE103021_H358_ARS_1620, blind=FALSE)
# rld <- rlog(dds_GSE103021_H358_ARS_1620, blind=FALSE)
head(assay(vsd), 3)

# Apply the dist function to the transpose of the transformed count matrix to get sample-to-sample distances
sampleDists <- dist(t(assay(vsd)))

# Condition
library("RColorBrewer")
sampleDistMatrix <- as.matrix(sampleDists)
rownames(sampleDistMatrix) <- paste(vsd$condition, vsd$type, sep="-")
colnames(sampleDistMatrix) <- NULL
colors <- colorRampPalette( rev(brewer.pal(9, "Blues")) )(255)
pheatmap(sampleDistMatrix,
         clustering_distance_rows=sampleDists,
         clustering_distance_cols=sampleDists,
         col=colors)

# Principal component plot of the samples
plotPCA(vsd, intgroup="condition")




# DIFFERENTIAL EXPRESSION ANALYSIS
# We perform a minimal pre-filtering to keep only rows that have at least 3 reads total
keep <- rowSums(counts(dds_GSE103021_H358_ARS_1620)) >= 3
dds_GSE103021_H358_ARS_1620 <- dds_GSE103021_H358_ARS_1620[keep,]
table(keep) # This shows how many transcripts have been removed after the filtering
nrow(dds_GSE103021_H358_ARS_1620) # to confirm the filtered transcripts

# DIFFERENTIAL EXPRESSION ANALYSIS
dds_GSE103021_H358_ARS_1620 <- DESeq(dds_GSE103021_H358_ARS_1620) # The DESeq() function normalizes the read counts, estimates dispersions, and fits the linear model, all in one go
# dds_GSE103021_H358_ARS_1620 <- DESeq(dds_GSE103021_H358_ARS_1620, betaPrior = T)  The betaPrior = T opton tells DESeq2 to squeeze the log Fold Changes of lowly expressed genes toward zero.

# If I want to see the normalized counts generated in the DESeq object:
# norm_dds_GSE103021_H358_ARS_1620 <- counts(dds_GSE103021_H358_ARS_1620, normalized=TRUE)

# resultsNames(dds_GSE103021_H358_ARS_1620) # lists the coefficients
# plotDispEsts(dds_GSE103021_H358_ARS_1620) # Plot the dispersions
# Each black dot in the plot represents the dispersion for one gene. The red line is fit to data (black bots),
# then the dispersions are squeezed toward the red line, resulting the final (blue) dispersion estimates. Usually,
# the dispersion is highest at the low counts and levels off at higher counts.


# Specify the conditions to contrast for differential expression analysis
res_GSE103021_H358_ARS_1620 <- results(dds_GSE103021_H358_ARS_1620, contrast=c("condition","ARS_1620_H358","DMSO_H358")) # to specify the samples to contrast
res_GSE103021_H358_ARS_1620
# Get a summary of the results
summary(res_GSE103021_H358_ARS_1620)




# Plot the log2 Fold Changes as function of expression:
plotMA(res_GSE103021_H358_ARS_1620,alpha = 0.05)
abline(h=c(-2,2),col = "red")

# Transform the row names into a column
res_GSE103021_H358_ARS_1620_df <- data.frame(res_GSE103021_H358_ARS_1620)
res_GSE103021_H358_ARS_1620 <- tibble::rownames_to_column(res_GSE103021_H358_ARS_1620_df, "ensembl_transcript_id")



# Join the expression change values with the Table_ANNOTATED containing MFE values
MFE_res_GSE103021_H358_ARS_1620 <- dplyr::inner_join(Table_ANNOTATED, res_GSE103021_H358_ARS_1620, by="ensembl_transcript_id") %>% # The file 'Table' contains the Normalized_MFE values of all ANNOTATED transcripts
  dplyr::filter(padj < 0.05) 



# Generate a scatter plot Log2_FC vs Normalized_MFE

Plot_GSE103021_H358_ARS_1620 <- ggplot(MFE_res_GSE103021_H358_ARS_1620, aes(y=Normalized_MFE, x=log2FoldChange)) +
  geom_point(size=1.5, alpha=0.1)+
  theme_classic() +
  theme(legend.position="none") +
  geom_vline(xintercept = 0, size=0.3) +
  #xlim(-5.5,5.5) +
  theme(axis.title = element_text(size = 20)) +
  theme(plot.title = element_text(size = 15)) +
  labs(y="DGfold / nt (kcal/mol)",x="Log2_FC_expression",title="GSE103021_H358_ARS_1620_Log2_FC_adj.P<0.05")
print(Plot_GSE103021_H358_ARS_1620)



# Look at the mean log2_FC
MFE_res_GSE103021_H358_ARS_1620_UP <- dplyr::filter(MFE_res_GSE103021_H358_ARS_1620, log2FoldChange > 0)
Mean_MFE_res_GSE103021_H358_ARS_1620_UP <- mean(MFE_res_GSE103021_H358_ARS_1620_UP$Normalized_MFE)

MFE_res_GSE103021_H358_ARS_1620_DOWN <- dplyr::filter(MFE_res_GSE103021_H358_ARS_1620, log2FoldChange < 0)
Mean_MFE_res_GSE103021_H358_ARS_1620_DOWN <- mean(MFE_res_GSE103021_H358_ARS_1620_DOWN$Normalized_MFE)

TTEST_MFE_res_GSE103021_H358_ARS_1620_all_UP_vs_DOWN <- t.test(MFE_res_GSE103021_H358_ARS_1620_DOWN$Normalized_MFE, MFE_res_GSE103021_H358_ARS_1620_UP$Normalized_MFE, paired=FALSE)

# Add K-S test to look at the differences between the up-regukated and down-regulated genes
ks_test_res_GSE103021_H358_ARS_1620_all_UP_vs_DOWN <- ks.test(MFE_res_GSE103021_H358_ARS_1620_DOWN$Normalized_MFE, MFE_res_GSE103021_H358_ARS_1620_UP$Normalized_MFE)


quantile_075_MFE_res_GSE103021_H358_ARS_1620_UP <- quantile(MFE_res_GSE103021_H358_ARS_1620_UP$Normalized_MFE, probs = c(0.75)) 
quantile_075_MFE_res_GSE103021_H358_ARS_1620_DOWN <- quantile(MFE_res_GSE103021_H358_ARS_1620_DOWN$Normalized_MFE, probs = c(0.75)) 
# Values above 0.75 quantile
ks_test_MFE_075_above <- ks.test(MFE_res_GSE103021_H358_ARS_1620_UP$Normalized_MFE[MFE_res_GSE103021_H358_ARS_1620_UP$Normalized_MFE >= quantile_075_MFE_res_GSE103021_H358_ARS_1620_UP],
                                 MFE_res_GSE103021_H358_ARS_1620_DOWN$Normalized_MFE[MFE_res_GSE103021_H358_ARS_1620_DOWN$Normalized_MFE >= quantile_075_MFE_res_GSE103021_H358_ARS_1620_DOWN])

# Look at the differences between the 0.25 quantile 
quantile_025_MFE_res_GSE103021_H358_ARS_1620_UP <- quantile(MFE_res_GSE103021_H358_ARS_1620_UP$Normalized_MFE, probs = c(0.25)) 
quantile_025_MFE_res_GSE103021_H358_ARS_1620_DOWN <- quantile(MFE_res_GSE103021_H358_ARS_1620_DOWN$Normalized_MFE, probs = c(0.25)) 
# Values below 0.25 quantile
ks_test_MFE_025_below <- ks.test(MFE_res_GSE103021_H358_ARS_1620_UP$Normalized_MFE[MFE_res_GSE103021_H358_ARS_1620_UP$Normalized_MFE <= quantile_025_MFE_res_GSE103021_H358_ARS_1620_UP],
                                 MFE_res_GSE103021_H358_ARS_1620_DOWN$Normalized_MFE[MFE_res_GSE103021_H358_ARS_1620_DOWN$Normalized_MFE <= quantile_025_MFE_res_GSE103021_H358_ARS_1620_DOWN])




# Permutation test MFE changes
# Combine the data into a single data frame with labels
upregulated <- data.frame(MFE = MFE_res_GSE103021_H358_ARS_1620_UP$Normalized_MFE, Group = "Up")
downregulated <- data.frame(MFE = MFE_res_GSE103021_H358_ARS_1620_DOWN$Normalized_MFE, Group = "Down")
combined_data <- bind_rows(upregulated, downregulated)

# Observed difference in means
GSE103021_H358_ARS_1620_observed_diff <- mean(MFE_res_GSE103021_H358_ARS_1620_UP$Normalized_MFE) - mean(MFE_res_GSE103021_H358_ARS_1620_DOWN$Normalized_MFE)

# Number of permutations
n_permutations <- 10000

# Initialize a vector to store the permuted differences
GSE103021_H358_ARS_1620_permuted_diffs <- numeric(n_permutations)

# Permutation test
set.seed(123)  # Set seed for reproducibility
for (i in 1:n_permutations) {
  # Permute the Group labels
  permuted_labels <- sample(combined_data$Group)
  
  # Calculate the mean MFE for each permuted group
  permuted_up_mean <- mean(combined_data$MFE[permuted_labels == "Up"])
  permuted_down_mean <- mean(combined_data$MFE[permuted_labels == "Down"])
  
  # Calculate the difference in means for the permuted groups
  GSE103021_H358_ARS_1620_permuted_diffs[i] <- permuted_up_mean - permuted_down_mean
}

# Calculate the p-value
GSE103021_H358_ARS_1620_p_value <- (sum(abs(GSE103021_H358_ARS_1620_permuted_diffs) >= abs(GSE103021_H358_ARS_1620_observed_diff)) + 1) / (n_permutations + 1)

