                                 MFE_res_GSE103021_ARS_1620_LU65_DOWN$Normalized_MFE[MFE_res_GSE103021_ARS_1620_LU65_DOWN$Normalized_MFE <= quantile_025_MFE_res_GSE103021_ARS_1620_LU65_DOWN])





