# Permutation test
set.seed(123)  # Set seed for reproducibility
for (i in 1:n_permutations) {
  # Permute the Group labels
  permuted_labels <- sample(combined_data$Group)
  
  # Calculate the mean MFE for each permuted group
  permuted_up_mean <- mean(combined_data$MFE[permuted_labels == "Up"])
  permuted_down_mean <- mean(combined_data$MFE[permuted_labels == "Down"])
  
  # Calculate the difference in means for the permuted groups
  GSE103021_ARS_1620_LU65_permuted_diffs[i] <- permuted_up_mean - permuted_down_mean
}

# Calculate the p-value
GSE103021_ARS_1620_LU65_p_value <- (sum(abs(GSE103021_ARS_1620_LU65_permuted_diffs) >= abs(GSE103021_ARS_1620_LU65_observed_diff)) + 1) / (n_permutations + 1)

# Output the results
cat("Observed difference in GSE103021_ARS_1620_LU65 means MFE_UP - MFE_DOWN:", GSE103021_ARS_1620_LU65_observed_diff, "\n")
cat("GSE103021_ARS_1620_LU65 P-value from permutation test:", GSE103021_ARS_1620_LU65_p_value, "\n")










