## GSE103021 High MFE TX fraction changes ####
# Determine whether within the differentially expressed genes there is a significant up-regulation of high MFE transcripts:
# Define high MFE transcripts by taking the 75th percentile of the combined MFE distributions of control and drug-treated samples.
# Count the number of transcripts in the significantly up- and down-regulated genes that have MFE values above this threshold.
# Perform a Fisher’s exact test to compare the proportions of high MFE transcripts between the two groups.

Counts_GSE103021_ARS_1620_LU65_GREIN <- dplyr::select(Counts_GSE103021_GREIN, c(GSM2752547, GSM2752548, GSM2752549, GSM2752550, GSM2752551, GSM2752552))
Counts_GSE103021_trametinib_LU65_GREIN <- dplyr::select(Counts_GSE103021_GREIN, c(GSM2752547, GSM2752548, GSM2752549, GSM2752553, GSM2752554))






# Analysis GSE103021_H358_ARS_1620

# Extract the normalized count data
# The minimal pre-filtering has already been done in the previous steps
GSE103021_H358_ARS_1620_norm_TX_counts <- counts(dds_GSE103021_H358_ARS_1620, normalized=TRUE) # This object is already a matrix
GSE103021_H358_ARS_1620_norm_TX_counts_df <- as.data.frame(GSE103021_H358_ARS_1620_norm_TX_counts)
# Convert row names to column
GSE103021_H358_ARS_1620_norm_TX_counts_df$ensembl_transcript_id <- rownames(GSE103021_H358_ARS_1620_norm_TX_counts_df)
# Remove row names
rownames(GSE103021_H358_ARS_1620_norm_TX_counts_df) <- NULL

# Move ensembl_transcript_id column to the first position
GSE103021_H358_ARS_1620_norm_TX_counts_df <- GSE103021_H358_ARS_1620_norm_TX_counts_df[, c("ensembl_transcript_id", setdiff(names(GSE103021_H358_ARS_1620_norm_TX_counts_df), "ensembl_transcript_id"))]

# Remove everything after the dot (including the dot itself) in the ensembl_transcript_id column
GSE103021_H358_ARS_1620_norm_TX_counts_df$ensembl_transcript_id <- sub("\\..*", "", GSE103021_H358_ARS_1620_norm_TX_counts_df$ensembl_transcript_id)

# Join the counts with the Table_ANNOTATED containing MFE values and heat capacity values
GSE103021_H358_ARS_1620_norm_TX_counts_MFE_df <- dplyr::inner_join(Table_ANNOTATED, GSE103021_H358_ARS_1620_norm_TX_counts_df, by="ensembl_transcript_id") %>%
  dplyr::select(ensembl_transcript_id_version, ensembl_transcript_id, ensembl_gene_id, external_gene_name, transcript_is_canonical, Transcript_length, 
                GSM2752534, GSM2752535, GSM2752536, GSM2752537, GSM2752538, GSM2752539, GSM2752540,
                Normalized_MFE, Temperature, Specific_heat)  %>%
  dplyr::filter(ensembl_transcript_id %in% MFE_res_GSE103021_H358_ARS_1620$ensembl_transcript_id) 





# Identify the 75th percentile of the combined MFE distributions of control and drug-treated samples
quantile_075_GSE103021_H358_ARS_1620_norm_TX_counts_MFE_df <- quantile(GSE103021_H358_ARS_1620_norm_TX_counts_MFE_df$Normalized_MFE, probs = c(0.75))

# Select all the transcripts with Normalized_MFE values above the 75th percentile
GSE103021_H358_ARS_1620_high_MFE_TX <- dplyr::filter(GSE103021_H358_ARS_1620_norm_TX_counts_MFE_df, Normalized_MFE > quantile_075_GSE103021_H358_ARS_1620_norm_TX_counts_MFE_df)

# Count the number of transcripts in the significantly up- and down-regulated pools that have MFE values above this threshold.
GSE103021_H358_ARS_1620_high_MFE_TX_in_UP <- dplyr::filter(MFE_res_GSE103021_H358_ARS_1620_UP, ensembl_transcript_id_version %in% GSE103021_H358_ARS_1620_high_MFE_TX$ensembl_transcript_id_version)
GSE103021_H358_ARS_1620_high_MFE_TX_in_DOWN <- dplyr::filter(MFE_res_GSE103021_H358_ARS_1620_DOWN, ensembl_transcript_id_version %in% GSE103021_H358_ARS_1620_high_MFE_TX$ensembl_transcript_id_version)

# Calculate the number of high MFE transcripts in UP and DOWN-regulated genes
GSE103021_H358_ARS_1620_total_UP <- nrow(MFE_res_GSE103021_H358_ARS_1620_UP)
GSE103021_H358_ARS_1620_total_DOWN <- nrow(MFE_res_GSE103021_H358_ARS_1620_DOWN)
GSE103021_H358_ARS_1620_count_high_MFE_UP <- nrow(GSE103021_H358_ARS_1620_high_MFE_TX_in_UP)
GSE103021_H358_ARS_1620_count_high_MFE_DOWN <- nrow(GSE103021_H358_ARS_1620_high_MFE_TX_in_DOWN)

# Calculate the fractions of high MFE transcripts in UP and DOWN-regulated genes
GSE103021_H358_ARS_1620_high_MFE_in_UP_fraction <- GSE103021_H358_ARS_1620_count_high_MFE_UP / GSE103021_H358_ARS_1620_total_UP
GSE103021_H358_ARS_1620_high_MFE_in_DOWN_fraction <- GSE103021_H358_ARS_1620_count_high_MFE_DOWN / GSE103021_H358_ARS_1620_total_DOWN

# Calculate the pooled proportion of high MFE transcripts
pooled_proportion <- (GSE103021_H358_ARS_1620_count_high_MFE_UP + GSE103021_H358_ARS_1620_count_high_MFE_DOWN) /
  (GSE103021_H358_ARS_1620_total_UP + GSE103021_H358_ARS_1620_total_DOWN)

# Calculate the standard error of the difference in proportions
SE <- sqrt(pooled_proportion * (1 - pooled_proportion) * (1 / GSE103021_H358_ARS_1620_total_UP + 1 / GSE103021_H358_ARS_1620_total_DOWN))

# Calculate the Z-score
z_score <- (GSE103021_H358_ARS_1620_high_MFE_in_UP_fraction - GSE103021_H358_ARS_1620_high_MFE_in_DOWN_fraction) / SE

# Calculate the p-value (Two-tailed test)
GSE103021_H358_ARS_1620_z_test_MFE_p_value <- 2 * pnorm(-abs(z_score))  # Two-tailed test

# Output the results
cat("Z-score for Two-Proportion Z-test:", z_score, "\n")
cat("P-value for Two-Proportion Z-test:", GSE103021_H358_ARS_1620_z_test_MFE_p_value, "\n")


# Also, output the net change (difference) in the proportions
net_change_in_proportions <- GSE103021_H358_ARS_1620_high_MFE_in_UP_fraction - GSE103021_H358_ARS_1620_high_MFE_in_DOWN_fraction
cat("Net change in proportions of high MFE transcripts (UP-regulated vs DOWN-regulated):", net_change_in_proportions, "\n")

# Additional statistics
cat("Fraction of high MFE TX in UP-regulated genes:", GSE103021_H358_ARS_1620_high_MFE_in_UP_fraction, "\n")
cat("Fraction of high MFE TX in DOWN-regulated genes:", GSE103021_H358_ARS_1620_high_MFE_in_DOWN_fraction, "\n")
cat("Mean of high MFE TX in UP-regulated genes:", mean(GSE103021_H358_ARS_1620_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mean of high MFE TX in DOWN-regulated genes:", mean(GSE103021_H358_ARS_1620_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")
cat("Mode of high MFE TX in UP-regulated genes:", calculate_mode(GSE103021_H358_ARS_1620_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mode of high MFE TX in DOWN-regulated genes:", calculate_mode(GSE103021_H358_ARS_1620_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")



