MFE_res_GSE103021_H358_ARS_1620$above_quantile_075 <- MFE_res_GSE103021_H358_ARS_1620$Normalized_MFE > quantile_075_GSE103021_H358_ARS_1620_norm_TX_counts_MFE_df

