# Determine the impact of these changes in terms of fraction of total counts:
# Calculate the fraction of total counts of high MFE transcripts in control and drug-treated groups. 
# This is done by summing the counts of the high MFE transcripts and dividing by the total counts in each group.
# Fisher’s exact test to compare the proportions of high MFE transcripts counts between the two groups.


# Convert from wide to long format
GSE103021_H358_ARS_1620_long_data <- GSE103021_H358_ARS_1620_norm_TX_counts_MFE_df %>%
  pivot_longer(
    cols = starts_with("GSM"),      # Select all columns starting with "GSM"
    names_to = "replicate",         # Name of the new column for replicate identifiers
    values_to = "counts"            # Name of the new column for the counts
  )

# Add a condition column based on the replicate
GSE103021_H358_ARS_1620_long_data <- GSE103021_H358_ARS_1620_long_data %>%
  mutate(condition = ifelse(replicate %in% c("GSM2752534", "GSM2752535", "GSM2752536"), "Control", "H358_ARS_1620"))

# Aggregate the replicates for each condition
GSE103021_H358_ARS_1620_norm_TX_aggregated_data_avg_counts <- GSE103021_H358_ARS_1620_long_data %>%
  group_by(ensembl_transcript_id_version, condition, Normalized_MFE, Specific_heat) %>%
  summarise(
    avg_counts = mean(counts),
    .groups = 'drop'
  )

# Define the 75th percentile of the entire distribution of MFE values for the GSE103021_H358_ARS_1620 data
GSE103021_H358_ARS_1620_MFE_all_TX_75_percentile <- quantile(GSE103021_H358_ARS_1620_norm_TX_aggregated_data_avg_counts$Normalized_MFE, 0.75)

# Identify all the transcripts with MFE values above the 75th percentile
GSE103021_H358_ARS_1620_high_MFE_TX_total <- dplyr::filter(GSE103021_H358_ARS_1620_norm_TX_counts_MFE_df, Normalized_MFE > GSE103021_H358_ARS_1620_MFE_all_TX_75_percentile)

# Fraction of total high MFE transcripts counts in control and drug-treated groups
GSE103021_H358_ARS_1620_control_total_counts <- dplyr::filter(GSE103021_H358_ARS_1620_norm_TX_aggregated_data_avg_counts, condition == "Control") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE103021_H358_ARS_1620_control_high_MFE_TX_counts <- dplyr::filter(GSE103021_H358_ARS_1620_norm_TX_aggregated_data_avg_counts, condition == "Control") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE103021_H358_ARS_1620_high_MFE_TX_total$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE103021_H358_ARS_1620_control_high_MFE_TX_counts_fraction <- GSE103021_H358_ARS_1620_control_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE103021_H358_ARS_1620_control_total_counts$total_counts
print(GSE103021_H358_ARS_1620_control_high_MFE_TX_counts_fraction) # This value goes in the summary table

GSE103021_H358_ARS_1620_H358_ARS_1620_total_counts <- dplyr::filter(GSE103021_H358_ARS_1620_norm_TX_aggregated_data_avg_counts, condition == "H358_ARS_1620") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE103021_H358_ARS_1620_H358_ARS_1620_high_MFE_TX_counts <- dplyr::filter(GSE103021_H358_ARS_1620_norm_TX_aggregated_data_avg_counts, condition == "H358_ARS_1620") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE103021_H358_ARS_1620_high_MFE_TX_total$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE103021_H358_ARS_1620_H358_ARS_1620_high_MFE_TX_counts_fraction <- GSE103021_H358_ARS_1620_H358_ARS_1620_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE103021_H358_ARS_1620_H358_ARS_1620_total_counts$total_counts
print(GSE103021_H358_ARS_1620_H358_ARS_1620_high_MFE_TX_counts_fraction) # This value goes in the summary table

# Perform Two-Proportion Z-Test to compare the proportions of high MFE transcript counts between the two groups (Control vs H358_ARS_1620)
# Calculate the pooled proportion of high MFE counts
pooled_proportion <- (GSE103021_H358_ARS_1620_control_high_MFE_TX_counts$total_counts_high_MFE_TX + GSE103021_H358_ARS_1620_H358_ARS_1620_high_MFE_TX_counts$total_counts_high_MFE_TX) /
  (GSE103021_H358_ARS_1620_control_total_counts$total_counts + GSE103021_H358_ARS_1620_H358_ARS_1620_total_counts$total_counts)

# Calculate the standard error of the difference in proportions
SE <- sqrt(pooled_proportion * (1 - pooled_proportion) * (1 / GSE103021_H358_ARS_1620_control_total_counts$total_counts + 1 / GSE103021_H358_ARS_1620_H358_ARS_1620_total_counts$total_counts))

# Calculate the Z-score
z_score <- (GSE103021_H358_ARS_1620_control_high_MFE_TX_counts_fraction - GSE103021_H358_ARS_1620_H358_ARS_1620_high_MFE_TX_counts_fraction) / SE

# Calculate the p-value (Two-tailed test)
GSE103021_H358_ARS_1620_z_test_counts_75_p_value <- 2 * pnorm(-abs(z_score))  # Two-tailed test

# Output the results
cat("Z-score for Two-Proportion Z-test:", z_score, "\n")
cat("P-value for Two-Proportion Z-test:", GSE103021_H358_ARS_1620_z_test_counts_75_p_value, "\n")



# Output the net change in the proportions of high MFE counts
net_change_in_proportions <- GSE103021_H358_ARS_1620_control_high_MFE_TX_counts_fraction - GSE103021_H358_ARS_1620_H358_ARS_1620_high_MFE_TX_counts_fraction
cat("Net change in proportions of high MFE transcript counts (Control vs H358_ARS_1620):", net_change_in_proportions, "\n")

# Additional statistics
cat("Control high MFE TX as fraction of total counts:", GSE103021_H358_ARS_1620_control_high_MFE_TX_counts_fraction, "\n")
cat("H358_ARS_1620 high MFE TX as fraction of total counts:", GSE103021_H358_ARS_1620_H358_ARS_1620_high_MFE_TX_counts_fraction, "\n")
cat("Net change counts high MFE TX drug vs control:", GSE103021_H358_ARS_1620_H358_ARS_1620_high_MFE_TX_counts_fraction - GSE103021_H358_ARS_1620_control_high_MFE_TX_counts_fraction, "\n")





