print(ks_test_heat_capacity_GSE103021_H358_ARS_1620_all_high_MFE_TX_UP_vs_DOWN)









# GSE103021_ARS_1620_LU65
# Extract the normalized count data
# The minimal pre-filtering has already been done in the previous steps
GSE103021_ARS_1620_LU65_norm_TX_counts <- counts(dds_GSE103021_ARS_1620_LU65, normalized=TRUE) # This object is already a matrix
GSE103021_ARS_1620_LU65_norm_TX_counts_df <- as.data.frame(GSE103021_ARS_1620_LU65_norm_TX_counts)
# Convert row names to column
GSE103021_ARS_1620_LU65_norm_TX_counts_df$ensembl_transcript_id <- rownames(GSE103021_ARS_1620_LU65_norm_TX_counts_df)
# Remove row names
rownames(GSE103021_ARS_1620_LU65_norm_TX_counts_df) <- NULL

# Move ensembl_transcript_id column to the first position
GSE103021_ARS_1620_LU65_norm_TX_counts_df <- GSE103021_ARS_1620_LU65_norm_TX_counts_df[, c("ensembl_transcript_id", setdiff(names(GSE103021_ARS_1620_LU65_norm_TX_counts_df), "ensembl_transcript_id"))]

# Remove everything after the dot (including the dot itself) in the ensembl_transcript_id column
GSE103021_ARS_1620_LU65_norm_TX_counts_df$ensembl_transcript_id <- sub("\\..*", "", GSE103021_ARS_1620_LU65_norm_TX_counts_df$ensembl_transcript_id)

# Join the counts with the Table_ANNOTATED containing MFE values and heat capacity values
GSE103021_ARS_1620_LU65_norm_TX_counts_MFE_df <- dplyr::inner_join(Table_ANNOTATED, GSE103021_ARS_1620_LU65_norm_TX_counts_df, by="ensembl_transcript_id") %>%
  dplyr::select(ensembl_transcript_id_version, ensembl_transcript_id, ensembl_gene_id, external_gene_name, transcript_is_canonical, Transcript_length, 
                GSM2752547, GSM2752548, GSM2752549, GSM2752550, GSM2752551, GSM2752552,
                Normalized_MFE, Temperature, Specific_heat) %>%
  dplyr::filter(ensembl_transcript_id %in% MFE_res_GSE103021_H358_ARS_1620$ensembl_transcript_id) 





# Identify the 75th percentile of the combined MFE distributions of control and drug-treated samples
quantile_075_GSE103021_ARS_1620_LU65_norm_TX_counts_MFE_df <- quantile(GSE103021_ARS_1620_LU65_norm_TX_counts_MFE_df$Normalized_MFE, probs = c(0.75))

# Select all the transcripts with Normalized_MFE values above the 75th percentile
GSE103021_ARS_1620_LU65_high_MFE_TX <- dplyr::filter(GSE103021_ARS_1620_LU65_norm_TX_counts_MFE_df, Normalized_MFE > quantile_075_GSE103021_ARS_1620_LU65_norm_TX_counts_MFE_df)

# Count the number of transcripts in the significantly up- and down-regulated pools that have MFE values above this threshold.
GSE103021_ARS_1620_LU65_high_MFE_TX_in_UP <- dplyr::filter(MFE_res_GSE103021_ARS_1620_LU65_UP, ensembl_transcript_id_version %in% GSE103021_ARS_1620_LU65_high_MFE_TX$ensembl_transcript_id_version)
GSE103021_ARS_1620_LU65_high_MFE_TX_in_DOWN <- dplyr::filter(MFE_res_GSE103021_ARS_1620_LU65_DOWN, ensembl_transcript_id_version %in% GSE103021_ARS_1620_LU65_high_MFE_TX$ensembl_transcript_id_version)

# Count the total number of UP and DOWN regulated genes
GSE103021_ARS_1620_LU65_total_UP <- nrow(MFE_res_GSE103021_ARS_1620_LU65_UP)
GSE103021_ARS_1620_LU65_total_DOWN <- nrow(MFE_res_GSE103021_ARS_1620_LU65_DOWN)

# Count the number of high MFE transcripts in the UP and DOWN groups
GSE103021_ARS_1620_LU65_count_high_MFE_UP <- nrow(GSE103021_ARS_1620_LU65_high_MFE_TX_in_UP)
GSE103021_ARS_1620_LU65_count_high_MFE_DOWN <- nrow(GSE103021_ARS_1620_LU65_high_MFE_TX_in_DOWN)

# Perform Two-Proportion Z-Test to compare the proportions of high MFE transcripts between the two groups (UP-regulated vs DOWN-regulated)
# Calculate the proportions of high MFE transcripts in UP and DOWN-regulated genes
prop_high_MFE_UP <- GSE103021_ARS_1620_LU65_count_high_MFE_UP / GSE103021_ARS_1620_LU65_total_UP
prop_high_MFE_DOWN <- GSE103021_ARS_1620_LU65_count_high_MFE_DOWN / GSE103021_ARS_1620_LU65_total_DOWN

# Calculate the pooled proportion of high MFE counts
pooled_proportion <- (GSE103021_ARS_1620_LU65_count_high_MFE_UP + GSE103021_ARS_1620_LU65_count_high_MFE_DOWN) /
  (GSE103021_ARS_1620_LU65_total_UP + GSE103021_ARS_1620_LU65_total_DOWN)

# Calculate the standard error of the difference in proportions
SE <- sqrt(pooled_proportion * (1 - pooled_proportion) * (1 / GSE103021_ARS_1620_LU65_total_UP + 1 / GSE103021_ARS_1620_LU65_total_DOWN))

# Calculate the Z-score
z_score <- (prop_high_MFE_UP - prop_high_MFE_DOWN) / SE

# Calculate the p-value (Two-tailed test)
GSE103021_ARS_1620_LU65_z_test_MFE_p_value <- 2 * pnorm(-abs(z_score))  # Two-tailed test

# Output the results
cat("Z-score for Two-Proportion Z-test:", z_score, "\n")
cat("P-value for Two-Proportion Z-test:", GSE103021_ARS_1620_LU65_z_test_MFE_p_value, "\n")


# Look at the fractions
GSE103021_ARS_1620_LU65_high_MFE_in_UP_fraction <- GSE103021_ARS_1620_LU65_count_high_MFE_UP / GSE103021_ARS_1620_LU65_total_UP
GSE103021_ARS_1620_LU65_high_MFE_in_DOWN_fraction <- GSE103021_ARS_1620_LU65_count_high_MFE_DOWN / GSE103021_ARS_1620_LU65_total_DOWN

# Output the results
cat("Fraction of GSE103021_ARS_1620_LU65 high MFE TX in UP-regulated genes:", GSE103021_ARS_1620_LU65_high_MFE_in_UP_fraction, "\n") # This value goes in the summary table
cat("Fraction of GSE103021_ARS_1620_LU65 high MFE TX in DOWN-regulated genes:", GSE103021_ARS_1620_LU65_high_MFE_in_DOWN_fraction, "\n") # This value goes in the summary table
cat("Mean of GSE103021_ARS_1620_LU65 high MFE TX in UP-regulated genes:", mean(GSE103021_ARS_1620_LU65_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mean of GSE103021_ARS_1620_LU65 high MFE TX in DOWN-regulated genes:", mean(GSE103021_ARS_1620_LU65_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")
cat("Mode of GSE103021_ARS_1620_LU65 high MFE TX in UP-regulated genes:", calculate_mode(GSE103021_ARS_1620_LU65_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mode of GSE103021_ARS_1620_LU65 high MFE TX in DOWN-regulated genes:", calculate_mode(GSE103021_ARS_1620_LU65_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")



# Show data as violin plot
# Add a new column to indicate if the value is above the 75th percentile
MFE_res_GSE103021_ARS_1620_LU65$above_quantile_075 <- MFE_res_GSE103021_ARS_1620_LU65$Normalized_MFE > quantile_075_GSE103021_ARS_1620_LU65_norm_TX_counts_MFE_df

