GSE103021_ARS_1620_LU65_long_data <- GSE103021_ARS_1620_LU65_norm_TX_counts_MFE_df %>%
  pivot_longer(
    cols = starts_with("GSM"),      # Select all columns starting with "GSM"
    names_to = "replicate",         # Name of the new column for replicate identifiers
    values_to = "counts"            # Name of the new column for the counts
  )

# Add a condition column based on the replicate
GSE103021_ARS_1620_LU65_long_data <- GSE103021_ARS_1620_LU65_long_data %>%
  mutate(condition = ifelse(replicate %in% c("GSM2752547", "GSM2752548", "GSM2752549"), "Control", "ARS_1620_LU65"))

# Aggregate the replicates for each condition
GSE103021_ARS_1620_LU65_norm_TX_aggregated_data_avg_counts <- GSE103021_ARS_1620_LU65_long_data %>%
  group_by(ensembl_transcript_id_version, condition, Normalized_MFE, Specific_heat) %>%
  summarise(
    avg_counts = mean(counts),
    .groups = 'drop'
  )

# Define the 75th percentile of the entire distribution of MFE values for the GSE103021_ARS_1620_LU65 data
GSE103021_ARS_1620_LU65_MFE_all_TX_75_percentile <- quantile(GSE103021_ARS_1620_LU65_norm_TX_aggregated_data_avg_counts$Normalized_MFE, 0.75)

