GSE103021_ARS_1620_LU65_ARS_1620_LU65_high_MFE_TX_counts <- dplyr::filter(GSE103021_ARS_1620_LU65_norm_TX_aggregated_data_avg_counts, condition == "ARS_1620_LU65") %>%
