  dplyr::filter(ensembl_transcript_id_version %in% GSE103021_ARS_1620_LU65_low_MFE_TX_total$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_low_MFE_TX = sum(avg_counts))

