# Calculate the standard error for the two-proportion z-test
pooled_prop <- (GSE103021_ARS_1620_LU65_control_low_MFE_TX_counts$total_counts_low_MFE_TX + GSE103021_ARS_1620_LU65_low_MFE_TX_counts$total_counts_low_MFE_TX) / 
  (GSE103021_ARS_1620_LU65_control_total_counts$total_counts + GSE103021_ARS_1620_LU65_ARS_1620_LU65_total_counts$total_counts)

se <- sqrt(pooled_prop * (1 - pooled_prop) * (1 / GSE103021_ARS_1620_LU65_control_total_counts$total_counts + 
                                                1 / GSE103021_ARS_1620_LU65_ARS_1620_LU65_total_counts$total_counts))

# Calculate the z-score
z_score <- (GSE103021_ARS_1620_LU65_control_low_MFE_TX_counts_fraction - GSE103021_ARS_1620_LU65_low_MFE_TX_counts_fraction) / se

# Calculate the p-value from the z-score
GSE103021_ARS_1620_LU65_z_test_counts_25_p_value <- 2 * (1 - pnorm(abs(z_score)))  # Two-tailed test

# Output the results
cat("Z-score for low MFE transcripts between Control and ARS_1620_LU65:", z_score, "\n")
cat("P-value for the two-proportion z-test:", GSE103021_ARS_1620_LU65_z_test_counts_25_p_value, "\n")






















