                                 MFE_res_GSE118548_Trametinib_DOWN$Normalized_MFE[MFE_res_GSE118548_Trametinib_DOWN$Normalized_MFE <= quantile_025_MFE_res_GSE118548_Trametinib_DOWN])




# Permutation test MFE changes
# Combine the data into a single data frame with labels
upregulated <- data.frame(MFE = MFE_res_GSE118548_Trametinib_UP$Normalized_MFE, Group = "Up")
downregulated <- data.frame(MFE = MFE_res_GSE118548_Trametinib_DOWN$Normalized_MFE, Group = "Down")
combined_data <- bind_rows(upregulated, downregulated)

# Observed difference in means
GSE118548_Trametinib_observed_diff <- mean(MFE_res_GSE118548_Trametinib_UP$Normalized_MFE) - mean(MFE_res_GSE118548_Trametinib_DOWN$Normalized_MFE)

# Number of permutations
n_permutations <- 10000

# Initialize a vector to store the permuted differences
GSE118548_Trametinib_permuted_diffs <- numeric(n_permutations)

# Permutation test
set.seed(123)  # Set seed for reproducibility
for (i in 1:n_permutations) {
  # Permute the Group labels
  permuted_labels <- sample(combined_data$Group)
  
  # Calculate the mean MFE for each permuted group
  permuted_up_mean <- mean(combined_data$MFE[permuted_labels == "Up"])
  permuted_down_mean <- mean(combined_data$MFE[permuted_labels == "Down"])
  
  # Calculate the difference in means for the permuted groups
  GSE118548_Trametinib_permuted_diffs[i] <- permuted_up_mean - permuted_down_mean
}

# Calculate the p-value
GSE118548_Trametinib_p_value <- (sum(abs(GSE118548_Trametinib_permuted_diffs) >= abs(GSE118548_Trametinib_observed_diff)) + 1) / (n_permutations + 1)

# Output the results
cat("Observed difference in GSE118548_Trametinib means MFE_UP - MFE_DOWN:", GSE118548_Trametinib_observed_diff, "\n")
cat("GSE118548_Trametinib P-value from permutation test:", GSE118548_Trametinib_p_value, "\n")








