## GSE118548 High MFE TX fraction changes ####
# Determine whether within the differentially expressed genes there is a significant up-regulation of high MFE transcripts:
# Define high MFE transcripts by taking the 75th percentile of the combined MFE distributions of control and drug-treated samples.
# Count the number of transcripts in the significantly up- and down-regulated genes that have MFE values above this threshold.
# Perform a Fisher’s exact test to compare the proportions of high MFE transcripts between the two groups.


# Analysis GSE118548
# Extract the normalized count data
# The minimal pre-filtering has already been done in the previous steps
GSE118548_norm_TX_counts <- counts(dds_GSE118548, normalized=TRUE) # This object is already a matrix
GSE118548_norm_TX_counts_df <- as.data.frame(GSE118548_norm_TX_counts)
# Convert row names to column
GSE118548_norm_TX_counts_df$ensembl_transcript_id <- rownames(GSE118548_norm_TX_counts_df)
# Remove row names
rownames(GSE118548_norm_TX_counts_df) <- NULL

# Move ensembl_transcript_id column to the first position
GSE118548_norm_TX_counts_df <- GSE118548_norm_TX_counts_df[, c("ensembl_transcript_id", setdiff(names(GSE118548_norm_TX_counts_df), "ensembl_transcript_id"))]

# Remove everything after the dot (including the dot itself) in the ensembl_transcript_id column
GSE118548_norm_TX_counts_df$ensembl_transcript_id <- sub("\\..*", "", GSE118548_norm_TX_counts_df$ensembl_transcript_id)

# Join the counts with the Table_ANNOTATED containing MFE values and heat capacity values
GSE118548_norm_TX_counts_MFE_df <- dplyr::inner_join(Table_ANNOTATED, GSE118548_norm_TX_counts_df, by="ensembl_transcript_id") %>%
  dplyr::select(ensembl_transcript_id_version, ensembl_transcript_id, ensembl_gene_id, external_gene_name, transcript_is_canonical, Transcript_length, 
                GSM3332281, GSM3332282, GSM3332283, GSM3332284, GSM3332285, GSM3332286, GSM3332287, GSM3332288, GSM3332289, GSM3332290, GSM3332291, GSM3332292, 
                Normalized_MFE, Temperature, Specific_heat)





# GSE118548_JQ1
# Convert from wide to long format
GSE118548_JQ1_norm_TX_counts_MFE_df <- GSE118548_norm_TX_counts_MFE_df %>%
  dplyr::select(ensembl_transcript_id_version, ensembl_transcript_id, ensembl_gene_id, external_gene_name, transcript_is_canonical, Transcript_length, 
                GSM3332281, GSM3332282, GSM3332283, GSM3332287, GSM3332288, GSM3332289, 
                Normalized_MFE, Temperature, Specific_heat) %>%
  dplyr::filter(ensembl_transcript_id %in% MFE_res_GSE118548_JQ1$ensembl_transcript_id) 

# Identify the 75th percentile of the combined MFE distributions of control and drug-treated samples
quantile_075_GSE118548_JQ1_norm_TX_counts_MFE_df <- quantile(GSE118548_JQ1_norm_TX_counts_MFE_df$Normalized_MFE, probs = c(0.75))

# Select all the transcripts with Normalized_MFE values above the 75th percentile
GSE118548_JQ1_high_MFE_TX <- dplyr::filter(GSE118548_JQ1_norm_TX_counts_MFE_df, Normalized_MFE > quantile_075_GSE118548_JQ1_norm_TX_counts_MFE_df)

# Count the number of transcripts in the significantly up- and down-regulated pools that have MFE values above this threshold.
GSE118548_JQ1_high_MFE_TX_in_UP <- dplyr::filter(MFE_res_GSE118548_JQ1_UP, ensembl_transcript_id_version %in% GSE118548_JQ1_high_MFE_TX$ensembl_transcript_id_version)
GSE118548_JQ1_high_MFE_TX_in_DOWN <- dplyr::filter(MFE_res_GSE118548_JQ1_DOWN, ensembl_transcript_id_version %in% GSE118548_JQ1_high_MFE_TX$ensembl_transcript_id_version)

# Count the number of high MFE transcripts in UP and DOWN groups
GSE118548_JQ1_total_UP <- nrow(MFE_res_GSE118548_JQ1_UP)
GSE118548_JQ1_total_DOWN <- nrow(MFE_res_GSE118548_JQ1_DOWN)
GSE118548_JQ1_count_high_MFE_UP <- nrow(GSE118548_JQ1_high_MFE_TX_in_UP)
GSE118548_JQ1_count_high_MFE_DOWN <- nrow(GSE118548_JQ1_high_MFE_TX_in_DOWN)

# Calculate proportions for UP and DOWN groups
prop_high_MFE_UP <- GSE118548_JQ1_count_high_MFE_UP / GSE118548_JQ1_total_UP
prop_high_MFE_DOWN <- GSE118548_JQ1_count_high_MFE_DOWN / GSE118548_JQ1_total_DOWN

# Calculate the pooled proportion for the two-proportion z-test
pooled_prop <- (GSE118548_JQ1_count_high_MFE_UP + GSE118548_JQ1_count_high_MFE_DOWN) /
  (GSE118548_JQ1_total_UP + GSE118548_JQ1_total_DOWN)

# Calculate the standard error for the difference between the proportions
se <- sqrt(pooled_prop * (1 - pooled_prop) * (1 / GSE118548_JQ1_total_UP + 1 / GSE118548_JQ1_total_DOWN))

# Calculate the z-score
z_score <- (prop_high_MFE_UP - prop_high_MFE_DOWN) / se

# Calculate the p-value for the two-tailed test
GSE118548_JQ1_z_test_MFE_p_value <- 2 * (1 - pnorm(abs(z_score)))  # Two-tailed test

# Output the results of the z-test
cat("Z-score for high MFE transcripts between UP-regulated and DOWN-regulated genes:", z_score, "\n")
cat("P-value for the two-proportion z-test:", GSE118548_JQ1_z_test_MFE_p_value, "\n")

# Look at the fractions
GSE118548_JQ1_high_MFE_in_UP_fraction <- prop_high_MFE_UP
GSE118548_JQ1_high_MFE_in_DOWN_fraction <- prop_high_MFE_DOWN

# Output the results
cat("Fraction of GSE118548_JQ1 high MFE TX in UP-regulated genes:", GSE118548_JQ1_high_MFE_in_UP_fraction, "\n") # This value goes in the summary table
cat("Fraction of GSE118548_JQ1 high MFE TX in DOWN-regulated genes:", GSE118548_JQ1_high_MFE_in_DOWN_fraction, "\n") # This value goes in the summary table
cat("Mean of GSE118548_JQ1 high MFE TX in UP-regulated genes:", mean(GSE118548_JQ1_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mean of GSE118548_JQ1 high MFE TX in DOWN-regulated genes:", mean(GSE118548_JQ1_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")
cat("Mode of GSE118548_JQ1 high MFE TX in UP-regulated genes:", calculate_mode(GSE118548_JQ1_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mode of GSE118548_JQ1 high MFE TX in DOWN-regulated genes:", calculate_mode(GSE118548_JQ1_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")





# Show data as violin plot
# Add a new column to indicate if the value is above the 75th percentile
MFE_res_GSE118548_JQ1$above_quantile_075 <- MFE_res_GSE118548_JQ1$Normalized_MFE > quantile_075_GSE118548_JQ1_norm_TX_counts_MFE_df

# Generate violin plot with conditional jitter coloring
Plot_MFE_GSE118548_JQ1 <- ggplot(MFE_res_GSE118548_JQ1, aes(x = factor(log2FoldChange > 0), y = Normalized_MFE)) +
  geom_violin(fill = "white", size = 1.5) +
  geom_jitter(aes(color = above_quantile_075), width = 0.1, size = 1, alpha = 1) +
  scale_color_manual(values = c("FALSE" = "black", "TRUE" = "dodgerblue3")) +
  theme_classic() +
  ylim(-0.6, 0) +
  theme(
    legend.position = "none", 
    axis.title = element_text(size = 20), 
    plot.title = element_text(size = 10),
    axis.text.x = element_text(size = 14, color = "black")
  ) +
  geom_vline(xintercept = 0, linewidth = 0.3) +
  labs(
    y = "Normalized_MFE", 
    x = NULL, 
    title = "GSE118548_JQ1_Log2_FC_adj.P<0.05"
  ) +
  scale_x_discrete(labels = c("log2_FC < 0", "log2_FC > 0"))

print(Plot_MFE_GSE118548_JQ1)



















