  dplyr::summarise(total_counts = sum(avg_counts))

GSE118548_Trametinib_JQ1_control_high_MFE_TX_counts <- dplyr::filter(GSE118548_Trametinib_JQ1_norm_TX_aggregated_data_avg_counts, condition == "Control") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE118548_Trametinib_JQ1_high_MFE_TX_total$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE118548_Trametinib_JQ1_control_high_MFE_TX_counts_fraction <- GSE118548_Trametinib_JQ1_control_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE118548_Trametinib_JQ1_control_total_counts$total_counts
print(GSE118548_Trametinib_JQ1_control_high_MFE_TX_counts_fraction) # This value goes in the summary table

GSE118548_Trametinib_JQ1_total_counts <- dplyr::filter(GSE118548_Trametinib_JQ1_norm_TX_aggregated_data_avg_counts, condition == "Trametinib_JQ1") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE118548_Trametinib_JQ1_high_MFE_TX_counts <- dplyr::filter(GSE118548_Trametinib_JQ1_norm_TX_aggregated_data_avg_counts, condition == "Trametinib_JQ1") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE118548_Trametinib_JQ1_high_MFE_TX_total$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE118548_Trametinib_JQ1_high_MFE_TX_counts_fraction <- GSE118548_Trametinib_JQ1_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE118548_Trametinib_JQ1_total_counts$total_counts
print(GSE118548_Trametinib_JQ1_high_MFE_TX_counts_fraction) # This value goes in the summary table

# Two-proportion z-test to compare the proportions of high MFE transcripts counts between the two groups
# Calculate the counts of high MFE transcripts in both groups
high_MFE_control_count <- GSE118548_Trametinib_JQ1_control_high_MFE_TX_counts$total_counts_high_MFE_TX
high_MFE_JQ1_count <- GSE118548_Trametinib_JQ1_high_MFE_TX_counts$total_counts_high_MFE_TX

# Calculate the total counts in each group
low_MFE_control_count <- GSE118548_Trametinib_JQ1_control_total_counts$total_counts - high_MFE_control_count
low_MFE_JQ1_count <- GSE118548_Trametinib_JQ1_total_counts$total_counts - high_MFE_JQ1_count

# Calculate proportions for both groups
prop_high_MFE_control <- high_MFE_control_count / GSE118548_Trametinib_JQ1_control_total_counts$total_counts
prop_high_MFE_JQ1 <- high_MFE_JQ1_count / GSE118548_Trametinib_JQ1_total_counts$total_counts

# Calculate the pooled proportion for the two-proportion z-test
pooled_prop <- (high_MFE_control_count + high_MFE_JQ1_count) / (GSE118548_Trametinib_JQ1_control_total_counts$total_counts + GSE118548_Trametinib_JQ1_total_counts$total_counts)

# Calculate the standard error for the difference between the proportions
se <- sqrt(pooled_prop * (1 - pooled_prop) * (1 / GSE118548_Trametinib_JQ1_control_total_counts$total_counts + 1 / GSE118548_Trametinib_JQ1_total_counts$total_counts))

# Calculate the z-score
z_score <- (prop_high_MFE_control - prop_high_MFE_JQ1) / se

# Calculate the p-value for the two-tailed test
GSE118548_Trametinib_JQ1_z_test_counts_75_p_value <- 2 * (1 - pnorm(abs(z_score)))  # Two-tailed test

# Output the results of the z-test
cat("Z-score for high MFE transcript counts between Control and Trametinib_JQ1 groups:", z_score, "\n")
cat("P-value for the two-proportion z-test:", GSE118548_Trametinib_JQ1_z_test_counts_75_p_value, "\n")

# Output the fractions and net change in high MFE transcript counts
cat("GSE118548_Trametinib_JQ1 control high MFE TX as fraction of total counts:", GSE118548_Trametinib_JQ1_control_high_MFE_TX_counts_fraction, "\n")
cat("GSE118548_Trametinib_JQ1 JQ1 high MFE TX as fraction of total counts:", GSE118548_Trametinib_JQ1_high_MFE_TX_counts_fraction, "\n")
cat("GSE118548_Trametinib_JQ1 net change counts high MFE TX drug vs control:", GSE118548_Trametinib_JQ1_high_MFE_TX_counts_fraction - GSE118548_Trametinib_JQ1_control_high_MFE_TX_counts_fraction, "\n")





