dds_GSE177054 <- dds_GSE177054[keep,]
table(keep) # This shows how many transcripts have been removed after the filtering
nrow(dds_GSE177054) # to confirm the filtered transcripts

# DIFFERENTIAL EXPRESSION ANALYSIS
dds_GSE177054 <- DESeq(dds_GSE177054) # The DESeq() function normalizes the read counts, estimates dispersions, and fits the linear model, all in one go
