## GSE177054 High MFE TX fraction changes ####
# Determine whether within the differentially expressed genes there is a significant up-regulation of high MFE transcripts:
# Define high MFE transcripts by taking the 75th percentile of the combined MFE distributions of control and drug-treated samples.
# Count the number of transcripts in the significantly up- and down-regulated genes that have MFE values above this threshold.
# Perform a Fisher’s exact test to compare the proportions of high MFE transcripts between the two groups. 


# Analysis GSE177054
# Extract the normalized count data
# The minimal pre-filtering has already been done in the previous steps
GSE177054_norm_TX_counts <- counts(dds_GSE177054, normalized=TRUE) # This object is already a matrix
GSE177054_norm_TX_counts_df <- as.data.frame(GSE177054_norm_TX_counts)
# Convert row names to column
GSE177054_norm_TX_counts_df$ensembl_transcript_id <- rownames(GSE177054_norm_TX_counts_df)
# Remove row names
rownames(GSE177054_norm_TX_counts_df) <- NULL

# Move ensembl_transcript_id column to the first position
GSE177054_norm_TX_counts_df <- GSE177054_norm_TX_counts_df[, c("ensembl_transcript_id", setdiff(names(GSE177054_norm_TX_counts_df), "ensembl_transcript_id"))]

# Remove everything after the dot (including the dot itself) in the ensembl_transcript_id column
GSE177054_norm_TX_counts_df$ensembl_transcript_id <- sub("\\..*", "", GSE177054_norm_TX_counts_df$ensembl_transcript_id)

# Join the counts with the Table_ANNOTATED containing MFE values and heat capacity values
GSE177054_norm_TX_counts_MFE_df <- dplyr::inner_join(Table_ANNOTATED, GSE177054_norm_TX_counts_df, by="ensembl_transcript_id") %>%
  dplyr::select(ensembl_transcript_id_version, ensembl_transcript_id, ensembl_gene_id, external_gene_name, transcript_is_canonical, Transcript_length, 
                GSM5373566, GSM5373567, GSM5373568, GSM5373569, GSM5373570, GSM5373571, GSM5373572, GSM5373573, GSM5373574, Normalized_MFE, Temperature, Specific_heat)








# GSE177054_Ribociclib
# Convert from wide to long format
GSE177054_Ribociclib_norm_TX_counts_MFE_df <- GSE177054_norm_TX_counts_MFE_df %>%
  dplyr::select(ensembl_transcript_id_version, ensembl_transcript_id, ensembl_gene_id, external_gene_name, transcript_is_canonical, Transcript_length, 
                GSM5373566, GSM5373567, GSM5373568, GSM5373569, GSM5373570, GSM5373571, 
                Normalized_MFE, Temperature, Specific_heat) %>%
  dplyr::filter(ensembl_transcript_id %in% MFE_res_GSE177054_Ribociclib$ensembl_transcript_id)

# Identify the 75th percentile of the combined MFE distributions of control and drug-treated samples
quantile_075_GSE177054_Ribociclib_norm_TX_counts_MFE_df <- quantile(GSE177054_Ribociclib_norm_TX_counts_MFE_df$Normalized_MFE, probs = c(0.75))

# Select all the transcripts with Normalized_MFE values above the 75th percentile
GSE177054_Ribociclib_high_MFE_TX <- dplyr::filter(GSE177054_Ribociclib_norm_TX_counts_MFE_df, Normalized_MFE > quantile_075_GSE177054_Ribociclib_norm_TX_counts_MFE_df)

# Count the number of transcripts in the significantly up- and down-regulated pools that have MFE values above this threshold.
GSE177054_Ribociclib_high_MFE_TX_in_UP <- dplyr::filter(MFE_res_GSE177054_Ribociclib_UP, ensembl_transcript_id_version %in% GSE177054_Ribociclib_high_MFE_TX$ensembl_transcript_id_version)
GSE177054_Ribociclib_high_MFE_TX_in_DOWN <- dplyr::filter(MFE_res_GSE177054_Ribociclib_DOWN, ensembl_transcript_id_version %in% GSE177054_Ribociclib_high_MFE_TX$ensembl_transcript_id_version)

# Calculate the proportions of high MFE transcripts in UP and DOWN groups
p_UP <- nrow(GSE177054_Ribociclib_high_MFE_TX_in_UP) / nrow(MFE_res_GSE177054_Ribociclib_UP)
p_DOWN <- nrow(GSE177054_Ribociclib_high_MFE_TX_in_DOWN) / nrow(MFE_res_GSE177054_Ribociclib_DOWN)


n_UP <- nrow(MFE_res_GSE177054_Ribociclib_UP)
n_DOWN <- nrow(MFE_res_GSE177054_Ribociclib_DOWN)


# Standard Error (SE) for the difference in proportions
SE <- sqrt((p_UP * (1 - p_UP)) / n_UP + (p_DOWN * (1 - p_DOWN)) / n_DOWN)

# Z-statistic
Z <- (p_UP - p_DOWN) / SE

# p-value (two-tailed test)
GSE177054_Ribociclib_z_test_MFE_p_value <- 2 * (1 - pnorm(abs(Z)))

# Output the results
cat("Z-statistic from two-proportion Z-test:", Z, "\n")
cat("P-value from two-proportion Z-test:", GSE177054_Ribociclib_z_test_MFE_p_value, "\n")

# Calculate the fractions of high MFE transcripts in UP and DOWN groups
GSE177054_Ribociclib_high_MFE_in_UP_fraction <- nrow(GSE177054_Ribociclib_high_MFE_TX_in_UP) / n_UP
GSE177054_Ribociclib_high_MFE_in_DOWN_fraction <- nrow(GSE177054_Ribociclib_high_MFE_TX_in_DOWN) / n_DOWN

# Output the fractions and other statistics
cat("Fraction of GSE177054_Ribociclib high MFE TX in UP-regulated genes:", GSE177054_Ribociclib_high_MFE_in_UP_fraction, "\n") # This value goes in the summary table
cat("Fraction of GSE177054_Ribociclib high MFE TX in DOWN-regulated genes:", GSE177054_Ribociclib_high_MFE_in_DOWN_fraction, "\n") # This value goes in the summary table
cat("Mean of GSE177054_Ribociclib high MFE TX in UP-regulated genes:", mean(GSE177054_Ribociclib_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mean of GSE177054_Ribociclib high MFE TX in DOWN-regulated genes:", mean(GSE177054_Ribociclib_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")
cat("Mode of GSE177054_Ribociclib high MFE TX in UP-regulated genes:", calculate_mode(GSE177054_Ribociclib_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mode of GSE177054_Ribociclib high MFE TX in DOWN-regulated genes:", calculate_mode(GSE177054_Ribociclib_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")




# Show data as violin plot
# Add a new column to indicate if the value is above the 75th percentile
MFE_res_GSE177054_Ribociclib$above_quantile_075 <- MFE_res_GSE177054_Ribociclib$Normalized_MFE > quantile_075_GSE177054_Ribociclib_norm_TX_counts_MFE_df

# Generate violin plot with conditional jitter coloring
ggplot(MFE_res_GSE177054_Ribociclib, aes(x = factor(log2FoldChange > 0), y = Normalized_MFE)) +
  geom_violin(fill = "white") +
  geom_jitter(aes(color = above_quantile_075), width = 0.1, size = 1, alpha = 0.1) +
  scale_color_manual(values = c("FALSE" = "black", "TRUE" = "blue")) +
  theme_classic() +
  theme(
    legend.position = "none", 
    axis.title = element_text(size = 20), 
    plot.title = element_text(size = 10),
    axis.text.x = element_text(size = 16, color = "black")
  ) +
  geom_vline(xintercept = 0, linewidth = 0.3) +
  labs(
    y = "Normalized_MFE", 
    x = NULL, 
    title = "GSE177054_Ribociclib_Log2_FC_adj.P<0.05"
  ) +
  scale_x_discrete(labels = c("log2FoldChange < 0", "log2FoldChange > 0"))














