# Select all the transcripts with Normalized_MFE values above the 75th percentile
GSE177054_Ribociclib_D4476_high_MFE_TX <- dplyr::filter(GSE177054_Ribociclib_D4476_norm_TX_counts_MFE_df, Normalized_MFE > quantile_075_GSE177054_Ribociclib_D4476_norm_TX_counts_MFE_df)

# Count the number of transcripts in the significantly up- and down-regulated pools that have MFE values above this threshold
GSE177054_Ribociclib_D4476_high_MFE_TX_in_UP <- dplyr::filter(MFE_res_GSE177054_Ribociclib_D4476_UP, ensembl_transcript_id_version %in% GSE177054_Ribociclib_D4476_high_MFE_TX$ensembl_transcript_id_version)
