GSE177054_Ribociclib_D4476_count_high_MFE_DOWN <- nrow(GSE177054_Ribociclib_D4476_high_MFE_TX_in_DOWN)

# Define the total number of UP and DOWN-regulated transcripts
GSE177054_Ribociclib_D4476_total_UP <- nrow(MFE_res_GSE177054_Ribociclib_D4476_UP)
GSE177054_Ribociclib_D4476_total_DOWN <- nrow(MFE_res_GSE177054_Ribociclib_D4476_DOWN)

# Calculate the fractions of high MFE transcripts in UP and DOWN-regulated genes
GSE177054_Ribociclib_D4476_high_MFE_in_UP_fraction <- GSE177054_Ribociclib_D4476_count_high_MFE_UP / GSE177054_Ribociclib_D4476_total_UP
