# Determine the impact of these changes in terms of fraction of total counts:
# Calculate the fraction of total counts of high MFE transcripts in control and drug-treated groups. 
# This is done by summing the counts of the high MFE transcripts and dividing by the total counts in each group.
# Fisher’s exact test to compare the proportions of high MFE transcripts counts between the two groups.


# Convert from wide to long format
GSE177054_Ribociclib_long_data <- GSE177054_Ribociclib_norm_TX_counts_MFE_df %>%
  pivot_longer(
    cols = starts_with("GSM"),      # Select all columns starting with "GSM"
    names_to = "replicate",         # Name of the new column for replicate identifiers
    values_to = "counts"            # Name of the new column for the counts
  )

# Add a condition column based on the replicate
GSE177054_Ribociclib_long_data <- GSE177054_Ribociclib_long_data %>%
  mutate(condition = ifelse(replicate %in% c("GSM5373566", "GSM5373567", "GSM5373568"), "Control", "Ribociclib"))

# Aggregate the replicates for each condition
GSE177054_Ribociclib_norm_TX_aggregated_data_avg_counts <- GSE177054_Ribociclib_long_data %>%
  group_by(ensembl_transcript_id_version, condition, Normalized_MFE, Specific_heat) %>%
  summarise(
    avg_counts = mean(counts),
    .groups = 'drop'
  )

# Define the 75th percentile of the entire distribution of MFE values for the GSE177054_Ribociclib data
GSE177054_Ribociclib_MFE_all_TX_75_percentile <- quantile(GSE177054_Ribociclib_norm_TX_aggregated_data_avg_counts$Normalized_MFE, 0.75)

# Identify all the transcripts with MFE values above the 75th percentile
GSE177054_Ribociclib_high_MFE_TX_total <- dplyr::filter(GSE177054_Ribociclib_norm_TX_counts_MFE_df, Normalized_MFE > GSE177054_Ribociclib_MFE_all_TX_75_percentile)

# Fraction of total high MFE transcripts counts in control and drug-treated groups
GSE177054_Ribociclib_control_total_counts <- dplyr::filter(GSE177054_Ribociclib_norm_TX_aggregated_data_avg_counts, condition == "Control") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE177054_Ribociclib_control_high_MFE_TX_counts <- dplyr::filter(GSE177054_Ribociclib_norm_TX_aggregated_data_avg_counts, condition == "Control") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE177054_Ribociclib_high_MFE_TX_total$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE177054_Ribociclib_control_high_MFE_TX_counts_fraction <- GSE177054_Ribociclib_control_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE177054_Ribociclib_control_total_counts$total_counts
print(GSE177054_Ribociclib_control_high_MFE_TX_counts_fraction) # This value goes in the summary table

GSE177054_Ribociclib_Ribociclib_total_counts <- dplyr::filter(GSE177054_Ribociclib_norm_TX_aggregated_data_avg_counts, condition == "Ribociclib") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE177054_Ribociclib_Ribociclib_high_MFE_TX_counts <- dplyr::filter(GSE177054_Ribociclib_norm_TX_aggregated_data_avg_counts, condition == "Ribociclib") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE177054_Ribociclib_high_MFE_TX_total$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE177054_Ribociclib_Ribociclib_high_MFE_TX_counts_fraction <- GSE177054_Ribociclib_Ribociclib_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE177054_Ribociclib_Ribociclib_total_counts$total_counts
print(GSE177054_Ribociclib_Ribociclib_high_MFE_TX_counts_fraction) # This value goes in the summary table

# Calculate standard error for the difference in proportions
p_control <- GSE177054_Ribociclib_control_high_MFE_TX_counts_fraction
p_ribociclib <- GSE177054_Ribociclib_Ribociclib_high_MFE_TX_counts_fraction

n_control <- GSE177054_Ribociclib_control_total_counts$total_counts
n_ribociclib <- GSE177054_Ribociclib_Ribociclib_total_counts$total_counts

SE <- sqrt((p_control * (1 - p_control)) / n_control + (p_ribociclib * (1 - p_ribociclib)) / n_ribociclib)

# Z-statistic for two-proportion Z-test
Z <- (p_control - p_ribociclib) / SE

# p-value from Z-statistic
GSE177054_Ribociclib_z_test_counts_75_p_value <- 2 * (1 - pnorm(abs(Z)))

# Output the results
cat("Z-statistic from two-proportion Z-test:", Z, "\n")
cat("P-value from two-proportion Z-test:", GSE177054_Ribociclib_z_test_counts_75_p_value, "\n")

cat("GSE177054_Ribociclib control high MFE TX as fraction of total counts:", GSE177054_Ribociclib_control_high_MFE_TX_counts_fraction, "\n")
cat("GSE177054_Ribociclib Ribociclib high MFE TX as fraction of total counts:", GSE177054_Ribociclib_Ribociclib_high_MFE_TX_counts_fraction, "\n")
cat("GSE177054_Ribociclib net change counts high MFE TX drug vs control:", GSE177054_Ribociclib_Ribociclib_high_MFE_TX_counts_fraction - GSE177054_Ribociclib_control_high_MFE_TX_counts_fraction, "\n")





