# Identify all the transcripts with MFE values above the 75th percentile
GSE177054_Ribociclib_D4476_high_MFE_TX_total <- dplyr::filter(GSE177054_Ribociclib_D4476_norm_TX_counts_MFE_df, Normalized_MFE > GSE177054_Ribociclib_D4476_MFE_all_TX_75_percentile)

# Fraction of total high MFE transcripts counts in control and drug-treated groups

# For control group
GSE177054_Ribociclib_D4476_control_total_counts <- dplyr::filter(GSE177054_Ribociclib_D4476_norm_TX_aggregated_data_avg_counts, condition == "Control") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

