# GSE99060 MDA-MB-453, MDA-MB-361 and MCF7 breast cancer cell lines treated with abemaciclib ####
# http://www.ilincs.org/apps/grein/?gse=GSE99060

# IMPORTANT
# Cells have been treated with abemaciclib for 7 days

Counts_GSE99060_GREIN <- read.delim("path_to/GSE99060/GSE99060_TranscriptLevel_Raw_data.csv", sep = ",", header = T, stringsAsFactors = F)
Counts_GSE99060_GREIN <- Counts_GSE99060_GREIN %>% remove_rownames %>% column_to_rownames(var="X") # Convert first column into row names in data frame
# Round counts down to the nearest integer
Counts_GSE99060_GREIN <- floor(Counts_GSE99060_GREIN)


# Access the Series Matrix
# Data_GSE99060 <- getGEO(GEO = "GSE99060")

# LOad the object
Data_GSE99060 <- readRDS("path_to/GREIN_series_matrices_data/Data_GSE99060.rds")



# Extract the phenotypic/clinical data matrix from the series matrix
Expdata_GSE99060 <- Data_GSE99060[["GSE99060_series_matrix.txt.gz"]]@phenoData@data


# Merge two columns
Expdata_GSE99060$condition <- paste(Expdata_GSE99060$`agent:ch1`, Expdata_GSE99060$`cell line:ch1`, sep = " ")

# Edit the descriptions of the conditions
Expdata_GSE99060$condition <- gsub("control MDA-MB-361 breast carcinoma cell line", "MDA_MB_361_DMSO", Expdata_GSE99060$condition)
Expdata_GSE99060$condition <- gsub("abemaciclib MDA-MB-361 breast carcinoma cell line", "MDA_MB_361_abemaciclib", Expdata_GSE99060$condition)
Expdata_GSE99060$condition <- gsub("control MDA-MB-453 breast carcinoma cell line", "MDA_MB_453_DMSO", Expdata_GSE99060$condition)
Expdata_GSE99060$condition <- gsub("abemaciclib MDA-MB-453 breast carcinoma cell line", "MDA_MB_453_abemaciclib", Expdata_GSE99060$condition)
Expdata_GSE99060$condition <- gsub("control MCF7 breast carcinoma cell line", "MCF7_DMSO", Expdata_GSE99060$condition)
Expdata_GSE99060$condition <- gsub("abemaciclib MCF7 breast carcinoma cell line", "MCF7_abemaciclib", Expdata_GSE99060$condition)





# IMPORTANT:
# It is absolutely critical that the columns of the count matrix and the rows of the column data (information about samples) are in the same order.

# Replace the row names of Expdata_GSE99060 (sampleID) with the same sample name [title] of [Counts_GSE182018]. 
# This will help to match sample names in both matrices.
# The outcome should be TRUE
all(rownames(Expdata_GSE99060) %in% colnames(Counts_GSE99060_GREIN))
all(colnames(Counts_GSE99060_GREIN) %in% rownames(Expdata_GSE99060))

# With the count matrix, Counts_GSE108308_GREIN, and the sample information, Expdata_GSE108308, we can construct a DESeqDataSet:
dds_GSE99060 <- DESeqDataSetFromMatrix(countData = Counts_GSE99060_GREIN,
                                        colData = Expdata_GSE99060,
                                        design = ~ condition)
dds_GSE99060




# DATA QUALITY ASSESSMENT COUNTS
# Before performing differential expression analysis, we perform data quality assessment by sample clustering and visualization
library("pheatmap")
# We log transform the counts
ntd <- normTransform(dds_GSE99060)
# Heat map of the count matrix
select <- order(rowMeans(counts(dds_GSE99060,normalized=FALSE)),
                decreasing=TRUE)[1:25]
df <- as.data.frame(colData(dds_GSE99060)[,c("condition","type")])
pheatmap(assay(ntd)[select,], cluster_rows=FALSE, show_rownames=FALSE,
         cluster_cols=FALSE, annotation_col=df)



# Heatmap of the sample-to-sample distances
# A heatmap of this distance matrix gives us an overview over similarities and dissimilarities between samples
# Transform the values
vsd <- vst(dds_GSE99060, blind=FALSE)
# rld <- rlog(dds_GSE99060, blind=FALSE)
head(assay(vsd), 3)

# Apply the dist function to the transpose of the transformed count matrix to get sample-to-sample distances
sampleDists <- dist(t(assay(vsd)))

# Condition
library("RColorBrewer")
sampleDistMatrix <- as.matrix(sampleDists)
rownames(sampleDistMatrix) <- paste(vsd$condition, vsd$type, sep="-")
colnames(sampleDistMatrix) <- NULL
colors <- colorRampPalette( rev(brewer.pal(9, "Blues")) )(255)
pheatmap(sampleDistMatrix,
         clustering_distance_rows=sampleDists,
         clustering_distance_cols=sampleDists,
         col=colors)

# Principal component plot of the samples
plotPCA(vsd, intgroup="condition")




# DIFFERENTIAL EXPRESSION ANALYSIS
# We perform a minimal pre-filtering to keep only rows that have at least 3 reads total
keep <- rowSums(counts(dds_GSE99060)) >= 3
dds_GSE99060 <- dds_GSE99060[keep,]
table(keep) # This shows how many transcripts have been removed after the filtering
nrow(dds_GSE99060) # to confirm the filtered transcripts

# DIFFERENTIAL EXPRESSION ANALYSIS
dds_GSE99060 <- DESeq(dds_GSE99060) # The DESeq() function normalizes the read counts, estimates dispersions, and fits the linear model, all in one go
# dds_GSE99060 <- DESeq(dds_GSE99060, betaPrior = T)  The betaPrior = T opton tells DESeq2 to squeeze the log Fold Changes of lowly expressed genes toward zero.

# If I want to see the normalized counts generated in the DESeq object:
# norm_dds_GSE99060 <- counts(dds_GSE99060, normalized=TRUE)

# resultsNames(dds_GSE99060) # lists the coefficients
# plotDispEsts(dds_GSE99060) # Plot the dispersions
# Each black dot in the plot represents the dispersion for one gene. The red line is fit to data (black bots),
# then the dispersions are squeezed toward the red line, resulting the final (blue) dispersion estimates. Usually,
# the dispersion is highest at the low counts and levels off at higher counts.



# Analysis GSE99060_MDA_MB_361_abemaciclib data
# Specify the conditions to contrast for differential expression analysis
res_GSE99060_MDA_MB_361_abemaciclib <- results(dds_GSE99060, contrast=c("condition","MDA_MB_361_abemaciclib","MDA_MB_361_DMSO")) # to specify the samples to contrast
res_GSE99060_MDA_MB_361_abemaciclib
# Get a summary of the results
summary(res_GSE99060_MDA_MB_361_abemaciclib)




# Plot the log2 Fold Changes as function of expression:
plotMA(res_GSE99060_MDA_MB_361_abemaciclib,alpha = 0.05)
abline(h=c(-2,2),col = "red")

# Transform the row names into a column
res_GSE99060_MDA_MB_361_abemaciclib_df <- data.frame(res_GSE99060_MDA_MB_361_abemaciclib)
