Mean_MFE_res_GSE99060_MDA_MB_361_abemaciclib_DOWN <- mean(MFE_res_GSE99060_MDA_MB_361_abemaciclib_DOWN$Normalized_MFE)

TTEST_MFE_res_GSE99060_MDA_MB_361_abemaciclib_all_UP_vs_DOWN <- t.test(MFE_res_GSE99060_MDA_MB_361_abemaciclib_DOWN$Normalized_MFE, MFE_res_GSE99060_MDA_MB_361_abemaciclib_UP$Normalized_MFE, paired=FALSE)

# Add K-S test to look at the differences between the up-regukated and down-regulated genes
ks_test_res_GSE99060_MDA_MB_361_abemaciclib_all_UP_vs_DOWN <- ks.test(MFE_res_GSE99060_MDA_MB_361_abemaciclib_DOWN$Normalized_MFE, MFE_res_GSE99060_MDA_MB_361_abemaciclib_UP$Normalized_MFE)


quantile_075_MFE_res_GSE99060_MDA_MB_361_abemaciclib_UP <- quantile(MFE_res_GSE99060_MDA_MB_361_abemaciclib_UP$Normalized_MFE, probs = c(0.75)) 
quantile_075_MFE_res_GSE99060_MDA_MB_361_abemaciclib_DOWN <- quantile(MFE_res_GSE99060_MDA_MB_361_abemaciclib_DOWN$Normalized_MFE, probs = c(0.75)) 
# Values above 0.75 quantile
ks_test_MFE_075_above <- ks.test(MFE_res_GSE99060_MDA_MB_361_abemaciclib_UP$Normalized_MFE[MFE_res_GSE99060_MDA_MB_361_abemaciclib_UP$Normalized_MFE >= quantile_075_MFE_res_GSE99060_MDA_MB_361_abemaciclib_UP],
                                 MFE_res_GSE99060_MDA_MB_361_abemaciclib_DOWN$Normalized_MFE[MFE_res_GSE99060_MDA_MB_361_abemaciclib_DOWN$Normalized_MFE >= quantile_075_MFE_res_GSE99060_MDA_MB_361_abemaciclib_DOWN])

# Look at the differences between the 0.25 quantile 
quantile_025_MFE_res_GSE99060_MDA_MB_361_abemaciclib_UP <- quantile(MFE_res_GSE99060_MDA_MB_361_abemaciclib_UP$Normalized_MFE, probs = c(0.25)) 
quantile_025_MFE_res_GSE99060_MDA_MB_361_abemaciclib_DOWN <- quantile(MFE_res_GSE99060_MDA_MB_361_abemaciclib_DOWN$Normalized_MFE, probs = c(0.25)) 
# Values below 0.25 quantile
ks_test_MFE_025_below <- ks.test(MFE_res_GSE99060_MDA_MB_361_abemaciclib_UP$Normalized_MFE[MFE_res_GSE99060_MDA_MB_361_abemaciclib_UP$Normalized_MFE <= quantile_025_MFE_res_GSE99060_MDA_MB_361_abemaciclib_UP],
                                 MFE_res_GSE99060_MDA_MB_361_abemaciclib_DOWN$Normalized_MFE[MFE_res_GSE99060_MDA_MB_361_abemaciclib_DOWN$Normalized_MFE <= quantile_025_MFE_res_GSE99060_MDA_MB_361_abemaciclib_DOWN])




# Permutation test MFE changes
# Combine the data into a single data frame with labels
upregulated <- data.frame(MFE = MFE_res_GSE99060_MDA_MB_361_abemaciclib_UP$Normalized_MFE, Group = "Up")
downregulated <- data.frame(MFE = MFE_res_GSE99060_MDA_MB_361_abemaciclib_DOWN$Normalized_MFE, Group = "Down")
combined_data <- bind_rows(upregulated, downregulated)

# Observed difference in means
GSE99060_MDA_MB_361_abemaciclib_observed_diff <- mean(MFE_res_GSE99060_MDA_MB_361_abemaciclib_UP$Normalized_MFE) - mean(MFE_res_GSE99060_MDA_MB_361_abemaciclib_DOWN$Normalized_MFE)

# Number of permutations
n_permutations <- 10000

# Initialize a vector to store the permuted differences
GSE99060_MDA_MB_361_abemaciclib_permuted_diffs <- numeric(n_permutations)

# Permutation test
set.seed(123)  # Set seed for reproducibility
for (i in 1:n_permutations) {
  # Permute the Group labels
  permuted_labels <- sample(combined_data$Group)
  
  # Calculate the mean MFE for each permuted group
  permuted_up_mean <- mean(combined_data$MFE[permuted_labels == "Up"])
  permuted_down_mean <- mean(combined_data$MFE[permuted_labels == "Down"])
  
  # Calculate the difference in means for the permuted groups
  GSE99060_MDA_MB_361_abemaciclib_permuted_diffs[i] <- permuted_up_mean - permuted_down_mean
}

# Calculate the p-value
GSE99060_MDA_MB_361_abemaciclib_p_value <- (sum(abs(GSE99060_MDA_MB_361_abemaciclib_permuted_diffs) >= abs(GSE99060_MDA_MB_361_abemaciclib_observed_diff)) + 1) / (n_permutations + 1)

# Output the results
cat("Observed difference in GSE99060_MDA_MB_361_abemaciclib means MFE_UP - MFE_DOWN:", GSE99060_MDA_MB_361_abemaciclib_observed_diff, "\n")
cat("GSE99060_MDA_MB_361_abemaciclib P-value from permutation test:", GSE99060_MDA_MB_361_abemaciclib_p_value, "\n")










