## GSE99060 High MFE TX fraction changes ####
# Determine whether within the differentially expressed genes there is a significant up-regulation of high MFE transcripts:
# Define high MFE transcripts by taking the 75th percentile of the combined MFE distributions of control and drug-treated samples.
# Count the number of transcripts in the significantly up- and down-regulated genes that have MFE values above this threshold.
# Perform a Fisher’s exact test to compare the proportions of high MFE transcripts between the two groups. 


# Analysis GSE99060_MDA_MB_361_abemaciclib
# Extract the normalized count data
# The minimal pre-filtering has already been done in the previous steps
GSE99060 <- counts(dds_GSE99060, normalized=TRUE) # This object is already a matrix
GSE99060_df <- as.data.frame(GSE99060)
# Convert row names to column
GSE99060_df$ensembl_transcript_id <- rownames(GSE99060_df)
# Remove row names
rownames(GSE99060_df) <- NULL

# Move ensembl_transcript_id column to the first position
GSE99060_df <- GSE99060_df[, c("ensembl_transcript_id", setdiff(names(GSE99060_df), "ensembl_transcript_id"))]

# Remove everything after the dot (including the dot itself) in the ensembl_transcript_id column
GSE99060_df$ensembl_transcript_id <- sub("\\..*", "", GSE99060_df$ensembl_transcript_id)

# Join the counts with the Table_ANNOTATED containing MFE values and heat capacity values
GSE99060_MFE_df <- dplyr::inner_join(Table_ANNOTATED, GSE99060_df, by="ensembl_transcript_id") %>%
  dplyr::select(ensembl_transcript_id_version, ensembl_transcript_id, ensembl_gene_id, external_gene_name, transcript_is_canonical, Transcript_length, 
                GSM2631688, GSM2631689, GSM2631690, GSM2631691, GSM2631692, GSM2631693, GSM2631694, GSM2631695, GSM2631696, GSM2631697, GSM2631698, GSM2631699,
                GSM2631700, GSM2631701, GSM2631702, GSM2631703, GSM2631704, GSM2631705,
                Normalized_MFE, Temperature, Specific_heat)






# GSE99060_MDA_MB_361_abemaciclib
# Convert from wide to long format
GSE99060_MDA_MB_361_abemaciclib_norm_TX_counts_MFE_df <- GSE99060_MFE_df %>%
  dplyr::select(ensembl_transcript_id_version, ensembl_transcript_id, ensembl_gene_id, external_gene_name, transcript_is_canonical, Transcript_length, 
                GSM2631688, GSM2631689, GSM2631690, GSM2631691, GSM2631692, GSM2631693, 
                Normalized_MFE, Temperature, Specific_heat) %>%
  dplyr::filter(ensembl_transcript_id %in% MFE_res_GSE99060_MDA_MB_361_abemaciclib$ensembl_transcript_id) 

# Identify the 75th percentile of the combined MFE distributions of control and drug-treated samples
quantile_075_GSE99060_MDA_MB_361_abemaciclib_norm_TX_counts_MFE_df <- quantile(GSE99060_MDA_MB_361_abemaciclib_norm_TX_counts_MFE_df$Normalized_MFE, probs = c(0.75))

# Select all the transcripts with Normalized_MFE values above the 75th percentile
GSE99060_MDA_MB_361_abemaciclib_high_MFE_TX <- dplyr::filter(GSE99060_MDA_MB_361_abemaciclib_norm_TX_counts_MFE_df, Normalized_MFE > quantile_075_GSE99060_MDA_MB_361_abemaciclib_norm_TX_counts_MFE_df)

# Count the number of transcripts in the significantly up- and down-regulated pools that have MFE values above this threshold
GSE99060_MDA_MB_361_abemaciclib_high_MFE_TX_in_UP <- dplyr::filter(MFE_res_GSE99060_MDA_MB_361_abemaciclib_UP, ensembl_transcript_id_version %in% GSE99060_MDA_MB_361_abemaciclib_high_MFE_TX$ensembl_transcript_id_version)
GSE99060_MDA_MB_361_abemaciclib_high_MFE_TX_in_DOWN <- dplyr::filter(MFE_res_GSE99060_MDA_MB_361_abemaciclib_DOWN, ensembl_transcript_id_version %in% GSE99060_MDA_MB_361_abemaciclib_high_MFE_TX$ensembl_transcript_id_version)

# Sample sizes and counts
GSE99060_MDA_MB_361_abemaciclib_total_UP <- nrow(MFE_res_GSE99060_MDA_MB_361_abemaciclib_UP)
GSE99060_MDA_MB_361_abemaciclib_total_DOWN <- nrow(MFE_res_GSE99060_MDA_MB_361_abemaciclib_DOWN)
GSE99060_MDA_MB_361_abemaciclib_count_high_MFE_UP <- nrow(GSE99060_MDA_MB_361_abemaciclib_high_MFE_TX_in_UP)
GSE99060_MDA_MB_361_abemaciclib_count_high_MFE_DOWN <- nrow(GSE99060_MDA_MB_361_abemaciclib_high_MFE_TX_in_DOWN)

# Calculate the proportions of high MFE transcripts
GSE99060_MDA_MB_361_abemaciclib_high_MFE_in_UP_fraction <- GSE99060_MDA_MB_361_abemaciclib_count_high_MFE_UP / GSE99060_MDA_MB_361_abemaciclib_total_UP
GSE99060_MDA_MB_361_abemaciclib_high_MFE_in_DOWN_fraction <- GSE99060_MDA_MB_361_abemaciclib_count_high_MFE_DOWN / GSE99060_MDA_MB_361_abemaciclib_total_DOWN

# Pooled proportion
p_pool <- (GSE99060_MDA_MB_361_abemaciclib_count_high_MFE_UP + GSE99060_MDA_MB_361_abemaciclib_count_high_MFE_DOWN) / 
  (GSE99060_MDA_MB_361_abemaciclib_total_UP + GSE99060_MDA_MB_361_abemaciclib_total_DOWN)

# Standard error
SE <- sqrt(p_pool * (1 - p_pool) * (1 / GSE99060_MDA_MB_361_abemaciclib_total_UP + 1 / GSE99060_MDA_MB_361_abemaciclib_total_DOWN))

# Z-test statistic
Z <- (GSE99060_MDA_MB_361_abemaciclib_high_MFE_in_UP_fraction - GSE99060_MDA_MB_361_abemaciclib_high_MFE_in_DOWN_fraction) / SE

# P-value (two-tailed)
GSE99060_MDA_MB_361_abemaciclib_z_test_MFE_p_value <- 2 * (1 - pnorm(abs(Z)))

# Output the results
cat("GSE99060_MDA_MB_361_abemaciclib Two-Proportion Z-Test Results:\n")
cat("Z-test statistic:", Z, "\n")
cat("P-value from Z-test:", GSE99060_MDA_MB_361_abemaciclib_z_test_MFE_p_value, "\n")

# Additional fractions and statistics
cat("Fraction of high MFE TX in UP-regulated genes:", GSE99060_MDA_MB_361_abemaciclib_high_MFE_in_UP_fraction, "\n")
cat("Fraction of high MFE TX in DOWN-regulated genes:", GSE99060_MDA_MB_361_abemaciclib_high_MFE_in_DOWN_fraction, "\n")
cat("Mean of high MFE TX in UP-regulated genes:", mean(GSE99060_MDA_MB_361_abemaciclib_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mean of high MFE TX in DOWN-regulated genes:", mean(GSE99060_MDA_MB_361_abemaciclib_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")
cat("Mode of high MFE TX in UP-regulated genes:", calculate_mode(GSE99060_MDA_MB_361_abemaciclib_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mode of high MFE TX in DOWN-regulated genes:", calculate_mode(GSE99060_MDA_MB_361_abemaciclib_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")




