# Determine the impact of these changes in terms of fraction of total counts:
# Calculate the fraction of total counts of high MFE transcripts in control and drug-treated groups. 
# This is done by summing the counts of the high MFE transcripts and dividing by the total counts in each group.
# Fisher’s exact test to compare the proportions of high MFE transcripts counts between the two groups.


# Convert from wide to long format
GSE99060_MDA_MB_453_abemaciclib_long_data <- GSE99060_MDA_MB_453_abemaciclib_norm_TX_counts_MFE_df %>%
  pivot_longer(
    cols = starts_with("GSM"),      # Select all columns starting with "GSM"
    names_to = "replicate",         # Name of the new column for replicate identifiers
    values_to = "counts"            # Name of the new column for the counts
  )

# Add a condition column based on the replicate
GSE99060_MDA_MB_453_abemaciclib_long_data <- GSE99060_MDA_MB_453_abemaciclib_long_data %>%
  mutate(condition = ifelse(replicate %in% c("GSM2631694", "GSM2631695", "GSM2631696"), "Control", "MDA_MB_453_abemaciclib"))

# Aggregate the replicates for each condition
GSE99060_MDA_MB_453_abemaciclib_norm_TX_aggregated_data_avg_counts <- GSE99060_MDA_MB_453_abemaciclib_long_data %>%
  group_by(ensembl_transcript_id_version, condition, Normalized_MFE, Specific_heat) %>%
  summarise(
    avg_counts = mean(counts),
    .groups = 'drop'
  )

# Define the 75th percentile of the entire distribution of MFE values
GSE99060_MDA_MB_453_abemaciclib_MFE_all_TX_75_percentile <- quantile(GSE99060_MDA_MB_453_abemaciclib_norm_TX_aggregated_data_avg_counts$Normalized_MFE, 0.75)

# Identify transcripts with MFE values above the 75th percentile
GSE99060_MDA_MB_453_abemaciclib_high_MFE_TX_total <- dplyr::filter(GSE99060_MDA_MB_453_abemaciclib_norm_TX_counts_MFE_df, Normalized_MFE > GSE99060_MDA_MB_453_abemaciclib_MFE_all_TX_75_percentile)

# Calculate fractions of high MFE transcripts for each condition
GSE99060_MDA_MB_453_abemaciclib_control_total_counts <- dplyr::filter(GSE99060_MDA_MB_453_abemaciclib_norm_TX_aggregated_data_avg_counts, condition == "Control") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE99060_MDA_MB_453_abemaciclib_control_high_MFE_TX_counts <- dplyr::filter(GSE99060_MDA_MB_453_abemaciclib_norm_TX_aggregated_data_avg_counts, condition == "Control") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE99060_MDA_MB_453_abemaciclib_high_MFE_TX_total$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE99060_MDA_MB_453_abemaciclib_control_high_MFE_TX_counts_fraction <- GSE99060_MDA_MB_453_abemaciclib_control_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE99060_MDA_MB_453_abemaciclib_control_total_counts$total_counts

GSE99060_MDA_MB_453_abemaciclib_MDA_MB_453_abemaciclib_total_counts <- dplyr::filter(GSE99060_MDA_MB_453_abemaciclib_norm_TX_aggregated_data_avg_counts, condition == "MDA_MB_453_abemaciclib") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE99060_MDA_MB_453_abemaciclib_MDA_MB_453_abemaciclib_high_MFE_TX_counts <- dplyr::filter(GSE99060_MDA_MB_453_abemaciclib_norm_TX_aggregated_data_avg_counts, condition == "MDA_MB_453_abemaciclib") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE99060_MDA_MB_453_abemaciclib_high_MFE_TX_total$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE99060_MDA_MB_453_abemaciclib_MDA_MB_453_abemaciclib_high_MFE_TX_counts_fraction <- GSE99060_MDA_MB_453_abemaciclib_MDA_MB_453_abemaciclib_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE99060_MDA_MB_453_abemaciclib_MDA_MB_453_abemaciclib_total_counts$total_counts

# Calculate counts for two-proportion Z-test
control_high <- GSE99060_MDA_MB_453_abemaciclib_control_high_MFE_TX_counts$total_counts_high_MFE_TX
control_total <- GSE99060_MDA_MB_453_abemaciclib_control_total_counts$total_counts
treated_high <- GSE99060_MDA_MB_453_abemaciclib_MDA_MB_453_abemaciclib_high_MFE_TX_counts$total_counts_high_MFE_TX
treated_total <- GSE99060_MDA_MB_453_abemaciclib_MDA_MB_453_abemaciclib_total_counts$total_counts

# Perform two-proportion Z-test
p_control <- control_high / control_total
p_treated <- treated_high / treated_total
p_pool <- (control_high + treated_high) / (control_total + treated_total)
z_score <- (p_treated - p_control) / sqrt(p_pool * (1 - p_pool) * (1 / control_total + 1 / treated_total))
GSE99060_MDA_MB_453_abemaciclib_z_test_counts_75_p_value <- 2 * pnorm(-abs(z_score))

# Output results
cat("Control high MFE TX fraction:", p_control, "\n")
cat("Treated high MFE TX fraction:", p_treated, "\n")
cat("Two-proportion Z-test Z-score:", z_score, "\n")
cat("Two-proportion Z-test P-value:", GSE99060_MDA_MB_453_abemaciclib_z_test_counts_75_p_value, "\n")





