# Determine the impact of these changes in terms of fraction of total counts:
# Calculate the fraction of total counts of high MFE transcripts in control and drug-treated groups. 
# This is done by summing the counts of the high MFE transcripts and dividing by the total counts in each group.
# Fisher’s exact test to compare the proportions of high MFE transcripts counts between the two groups.


# Convert from wide to long format
GSE99060_MCF7_abemaciclib_long_data <- GSE99060_MCF7_abemaciclib_norm_TX_counts_MFE_df %>%
  pivot_longer(
    cols = starts_with("GSM"),      # Select all columns starting with "GSM"
    names_to = "replicate",         # Name of the new column for replicate identifiers
    values_to = "counts"            # Name of the new column for the counts
  )

# Add a condition column based on the replicate
GSE99060_MCF7_abemaciclib_long_data <- GSE99060_MCF7_abemaciclib_long_data %>%
  mutate(condition = ifelse(replicate %in% c("GSM2631700", "GSM2631701", "GSM2631702"), "Control", "MCF7_abemaciclib"))

# Aggregate the replicates for each condition
GSE99060_MCF7_abemaciclib_norm_TX_aggregated_data_avg_counts <- GSE99060_MCF7_abemaciclib_long_data %>%
  group_by(ensembl_transcript_id_version, condition, Normalized_MFE, Specific_heat) %>%
  summarise(
    avg_counts = mean(counts),
    .groups = 'drop'
  )

# Define the 75th percentile of the entire distribution of MFE values
GSE99060_MCF7_abemaciclib_MFE_all_TX_75_percentile <- quantile(GSE99060_MCF7_abemaciclib_norm_TX_aggregated_data_avg_counts$Normalized_MFE, 0.75)

# Identify all transcripts with MFE values above the 75th percentile
GSE99060_MCF7_abemaciclib_high_MFE_TX_total <- dplyr::filter(GSE99060_MCF7_abemaciclib_norm_TX_counts_MFE_df, Normalized_MFE > GSE99060_MCF7_abemaciclib_MFE_all_TX_75_percentile)

# Fraction of total high MFE transcripts counts in control and drug-treated groups
GSE99060_MCF7_abemaciclib_control_total_counts <- dplyr::filter(GSE99060_MCF7_abemaciclib_norm_TX_aggregated_data_avg_counts, condition == "Control") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE99060_MCF7_abemaciclib_control_high_MFE_TX_counts <- dplyr::filter(GSE99060_MCF7_abemaciclib_norm_TX_aggregated_data_avg_counts, condition == "Control") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE99060_MCF7_abemaciclib_high_MFE_TX_total$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE99060_MCF7_abemaciclib_control_high_MFE_TX_counts_fraction <- GSE99060_MCF7_abemaciclib_control_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE99060_MCF7_abemaciclib_control_total_counts$total_counts

GSE99060_MCF7_abemaciclib_MCF7_abemaciclib_total_counts <- dplyr::filter(GSE99060_MCF7_abemaciclib_norm_TX_aggregated_data_avg_counts, condition == "MCF7_abemaciclib") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE99060_MCF7_abemaciclib_MCF7_abemaciclib_high_MFE_TX_counts <- dplyr::filter(GSE99060_MCF7_abemaciclib_norm_TX_aggregated_data_avg_counts, condition == "MCF7_abemaciclib") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE99060_MCF7_abemaciclib_high_MFE_TX_total$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE99060_MCF7_abemaciclib_MCF7_abemaciclib_high_MFE_TX_counts_fraction <- GSE99060_MCF7_abemaciclib_MCF7_abemaciclib_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE99060_MCF7_abemaciclib_MCF7_abemaciclib_total_counts$total_counts

# Two-proportion z-test
n1 <- GSE99060_MCF7_abemaciclib_control_total_counts$total_counts
n2 <- GSE99060_MCF7_abemaciclib_MCF7_abemaciclib_total_counts$total_counts
p1 <- GSE99060_MCF7_abemaciclib_control_high_MFE_TX_counts_fraction
p2 <- GSE99060_MCF7_abemaciclib_MCF7_abemaciclib_high_MFE_TX_counts_fraction

# Calculate pooled proportion and z-statistic
p_pool <- (p1 * n1 + p2 * n2) / (n1 + n2)
z_stat <- (p1 - p2) / sqrt(p_pool * (1 - p_pool) * (1/n1 + 1/n2))

# Calculate p-value
GSE99060_MCF7_abemaciclib_z_test_counts_75_p_value <- 2 * (1 - pnorm(abs(z_stat)))

# Output results
cat("Control high MFE TX fraction:", p1, "\n")
cat("MCF7_abemaciclib high MFE TX fraction:", p2, "\n")
cat("Two-proportion z-test statistic:", z_stat, "\n")
cat("Two-proportion z-test p-value:", GSE99060_MCF7_abemaciclib_z_test_counts_75_p_value, "\n")





