# Ensure the Gene_set column is a factor with the correct order
combined_df$Gene_set <- factor(combined_df$Gene_set, levels = c("Proliferation_Science", "Meta_PCNA", "Proliferation_GO", "Proliferation_STOP", "Proliferation_Carey", "G1_phase", "MTOR_POS", "MTOR_NEG", "Essential_cell_cycle", "Essential_S_Phase", "HR", "FA", "HF_POL"))


# Generate the box plot

Plot_GSE99060_MDA_MB_361_abemaciclib_proliferation <- ggplot(combined_df, aes(x=Gene_set, y=log2FoldChange)) +
  geom_boxplot(fill="lightgrey") + 
  stat_summary(fun.y=mean, geom="point", shape=20, size=4, color="blue") +
  # geom_jitter(width=0.2, alpha=0.5) +
