# LOad the object
Data_GSE93124 <- readRDS("path_to/GREIN_series_matrices_data/Data_GSE93124.rds")


# Extract the phenotypic/clinical data matrix from the series matrix
Expdata_GSE93124 <- Data_GSE93124[["GSE93124_series_matrix.txt.gz"]]@phenoData@data

colnames(Expdata_GSE93124)[colnames(Expdata_GSE93124) == "agent:ch1"] <- "condition" # Rename the column to have an easier identifier for the conditions

# Edit the descriptions of the conditions
Expdata_GSE93124$condition <- gsub("control", "DMSO", Expdata_GSE93124$condition)



# IMPORTANT:
# It is absolutely critical that the columns of the count matrix and the rows of the column data (information about samples) are in the same order.

# Replace the row names of Expdata_GSE93124 (sampleID) with the same sample name [title] of [Counts_GSE182018]. 
# This will help to match sample names in both matrices.
# The outcome should be TRUE
all(rownames(Expdata_GSE93124) %in% colnames(Counts_GSE93124_GREIN))
