# Join the expression change values with the Table_ANNOTATED containing MFE values
MFE_res_GSE93124_SW480_crizotinib <- dplyr::inner_join(Table_ANNOTATED, res_GSE93124_SW480_crizotinib, by="ensembl_transcript_id") %>% # The file 'Table' contains the Normalized_MFE values of all ANNOTATED transcripts
  dplyr::filter(padj < 0.05) 



# Generate a scatter plot Log2_FC vs Normalized_MFE

Plot_GSE93124_SW480_crizotinib <- ggplot(MFE_res_GSE93124_SW480_crizotinib, aes(y=Normalized_MFE, x=log2FoldChange)) +
