print(Plot_GSE93124_SW480_crizotinib)








# Look at the mean log2_FC
MFE_res_GSE93124_SW480_crizotinib_UP <- dplyr::filter(MFE_res_GSE93124_SW480_crizotinib, log2FoldChange > 0)
Mean_MFE_res_GSE93124_SW480_crizotinib_UP <- mean(MFE_res_GSE93124_SW480_crizotinib_UP$Normalized_MFE, na.rm = TRUE)

MFE_res_GSE93124_SW480_crizotinib_DOWN <- dplyr::filter(MFE_res_GSE93124_SW480_crizotinib, log2FoldChange < 0)
Mean_MFE_res_GSE93124_SW480_crizotinib_DOWN <- mean(MFE_res_GSE93124_SW480_crizotinib_DOWN$Normalized_MFE, na.rm = TRUE)

TTEST_MFE_res_GSE93124_SW480_crizotinib_all_UP_vs_DOWN <- t.test(MFE_res_GSE93124_SW480_crizotinib_DOWN$Normalized_MFE, MFE_res_GSE93124_SW480_crizotinib_UP$Normalized_MFE, paired=FALSE)

# Add K-S test to look at the differences between the up-regukated and down-regulated genes
ks_test_res_GSE93124_SW480_crizotinib_all_UP_vs_DOWN <- ks.test(MFE_res_GSE93124_SW480_crizotinib_DOWN$Normalized_MFE, MFE_res_GSE93124_SW480_crizotinib_UP$Normalized_MFE)


quantile_075_MFE_res_GSE93124_SW480_crizotinib_UP <- quantile(MFE_res_GSE93124_SW480_crizotinib_UP$Normalized_MFE, probs = c(0.75)) 
quantile_075_MFE_res_GSE93124_SW480_crizotinib_DOWN <- quantile(MFE_res_GSE93124_SW480_crizotinib_DOWN$Normalized_MFE, probs = c(0.75)) 
# Values above 0.75 quantile
ks_test_MFE_075_above <- ks.test(MFE_res_GSE93124_SW480_crizotinib_UP$Normalized_MFE[MFE_res_GSE93124_SW480_crizotinib_UP$Normalized_MFE >= quantile_075_MFE_res_GSE93124_SW480_crizotinib_UP],
                                 MFE_res_GSE93124_SW480_crizotinib_DOWN$Normalized_MFE[MFE_res_GSE93124_SW480_crizotinib_DOWN$Normalized_MFE >= quantile_075_MFE_res_GSE93124_SW480_crizotinib_DOWN])

# Look at the differences between the 0.25 quantile 
quantile_025_MFE_res_GSE93124_SW480_crizotinib_UP <- quantile(MFE_res_GSE93124_SW480_crizotinib_UP$Normalized_MFE, probs = c(0.25)) 
quantile_025_MFE_res_GSE93124_SW480_crizotinib_DOWN <- quantile(MFE_res_GSE93124_SW480_crizotinib_DOWN$Normalized_MFE, probs = c(0.25)) 
# Values below 0.25 quantile
ks_test_MFE_025_below <- ks.test(MFE_res_GSE93124_SW480_crizotinib_UP$Normalized_MFE[MFE_res_GSE93124_SW480_crizotinib_UP$Normalized_MFE <= quantile_025_MFE_res_GSE93124_SW480_crizotinib_UP],
                                 MFE_res_GSE93124_SW480_crizotinib_DOWN$Normalized_MFE[MFE_res_GSE93124_SW480_crizotinib_DOWN$Normalized_MFE <= quantile_025_MFE_res_GSE93124_SW480_crizotinib_DOWN])



# Permutation test MFE changes
# Combine the data into a single data frame with labels
upregulated <- data.frame(MFE = MFE_res_GSE93124_SW480_crizotinib_UP$Normalized_MFE, Group = "Up")
downregulated <- data.frame(MFE = MFE_res_GSE93124_SW480_crizotinib_DOWN$Normalized_MFE, Group = "Down")
combined_data <- bind_rows(upregulated, downregulated)

# Observed difference in means
GSE93124_SW480_crizotinib_observed_diff <- mean(MFE_res_GSE93124_SW480_crizotinib_UP$Normalized_MFE) - mean(MFE_res_GSE93124_SW480_crizotinib_DOWN$Normalized_MFE)

# Number of permutations
n_permutations <- 10000

# Initialize a vector to store the permuted differences
GSE93124_SW480_crizotinib_permuted_diffs <- numeric(n_permutations)

# Permutation test
set.seed(123)  # Set seed for reproducibility
for (i in 1:n_permutations) {
  # Permute the Group labels
  permuted_labels <- sample(combined_data$Group)
  
  # Calculate the mean MFE for each permuted group
  permuted_up_mean <- mean(combined_data$MFE[permuted_labels == "Up"])
  permuted_down_mean <- mean(combined_data$MFE[permuted_labels == "Down"])
  
  # Calculate the difference in means for the permuted groups
  GSE93124_SW480_crizotinib_permuted_diffs[i] <- permuted_up_mean - permuted_down_mean
}

# Calculate the p-value
GSE93124_SW480_crizotinib_p_value <- (sum(abs(GSE93124_SW480_crizotinib_permuted_diffs) >= abs(GSE93124_SW480_crizotinib_observed_diff)) + 1) / (n_permutations + 1)

# Output the results
cat("Observed difference in GSE93124_SW480_crizotinib means MFE_UP - MFE_DOWN:", GSE93124_SW480_crizotinib_observed_diff, "\n")
cat("GSE93124_SW480_crizotinib P-value from permutation test:", GSE93124_SW480_crizotinib_p_value, "\n")










## GSE93124 High MFE TX fraction changes ####
# Determine whether within the differentially expressed genes there is a significant up-regulation of high MFE transcripts:
# Define high MFE transcripts by taking the 75th percentile of the combined MFE distributions of control and drug-treated samples.
# Count the number of transcripts in the significantly up- and down-regulated genes that have MFE values above this threshold.
# Perform a Fisher’s exact test to compare the proportions of high MFE transcripts between the two groups.


# Analysis GSE93124_SW480_crizotinib
# Extract the normalized count data
# The minimal pre-filtering has already been done in the previous steps
GSE93124_SW480_crizotinib_norm_TX_counts <- counts(dds_GSE93124, normalized=TRUE) # This object is already a matrix
GSE93124_SW480_crizotinib_norm_TX_counts_df <- as.data.frame(GSE93124_SW480_crizotinib_norm_TX_counts)
# Convert row names to column
GSE93124_SW480_crizotinib_norm_TX_counts_df$ensembl_transcript_id <- rownames(GSE93124_SW480_crizotinib_norm_TX_counts_df)
# Remove row names
rownames(GSE93124_SW480_crizotinib_norm_TX_counts_df) <- NULL

# Move ensembl_transcript_id column to the first position
GSE93124_SW480_crizotinib_norm_TX_counts_df <- GSE93124_SW480_crizotinib_norm_TX_counts_df[, c("ensembl_transcript_id", setdiff(names(GSE93124_SW480_crizotinib_norm_TX_counts_df), "ensembl_transcript_id"))]

# Remove everything after the dot (including the dot itself) in the ensembl_transcript_id column
GSE93124_SW480_crizotinib_norm_TX_counts_df$ensembl_transcript_id <- sub("\\..*", "", GSE93124_SW480_crizotinib_norm_TX_counts_df$ensembl_transcript_id)

# Join the counts with the Table_ANNOTATED containing MFE values and heat capacity values
GSE93124_SW480_crizotinib_norm_TX_counts_MFE_df <- dplyr::inner_join(Table_ANNOTATED, GSE93124_SW480_crizotinib_norm_TX_counts_df, by="ensembl_transcript_id") %>%
  dplyr::select(ensembl_transcript_id_version, ensembl_transcript_id, ensembl_gene_id, external_gene_name, transcript_is_canonical, Transcript_length, 
                GSM2454872, GSM2454873, GSM2454874, GSM2454875, GSM2454876, GSM2454877,
                Normalized_MFE, Temperature, Specific_heat)  %>%
  dplyr::filter(ensembl_transcript_id %in% MFE_res_GSE93124_SW480_crizotinib$ensembl_transcript_id) 


# Identify the 75th percentile of the combined MFE distributions
quantile_075_GSE93124_SW480_crizotinib_norm_TX_counts_MFE_df <- quantile(GSE93124_SW480_crizotinib_norm_TX_counts_MFE_df$Normalized_MFE, probs = c(0.75))

# Select all the transcripts with Normalized_MFE values above the 75th percentile
GSE93124_SW480_crizotinib_high_MFE_TX <- dplyr::filter(GSE93124_SW480_crizotinib_norm_TX_counts_MFE_df, Normalized_MFE > quantile_075_GSE93124_SW480_crizotinib_norm_TX_counts_MFE_df)

# Count the number of transcripts in UP- and DOWN-regulated pools that have MFE values above the threshold
GSE93124_SW480_crizotinib_high_MFE_TX_in_UP <- dplyr::filter(MFE_res_GSE93124_SW480_crizotinib_UP, ensembl_transcript_id_version %in% GSE93124_SW480_crizotinib_high_MFE_TX$ensembl_transcript_id_version)
GSE93124_SW480_crizotinib_high_MFE_TX_in_DOWN <- dplyr::filter(MFE_res_GSE93124_SW480_crizotinib_DOWN, ensembl_transcript_id_version %in% GSE93124_SW480_crizotinib_high_MFE_TX$ensembl_transcript_id_version)

# Total counts in UP and DOWN groups
GSE93124_SW480_crizotinib_total_UP <- nrow(MFE_res_GSE93124_SW480_crizotinib_UP)
GSE93124_SW480_crizotinib_total_DOWN <- nrow(MFE_res_GSE93124_SW480_crizotinib_DOWN)

# High MFE counts in UP and DOWN groups
GSE93124_SW480_crizotinib_count_high_MFE_UP <- nrow(GSE93124_SW480_crizotinib_high_MFE_TX_in_UP)
GSE93124_SW480_crizotinib_count_high_MFE_DOWN <- nrow(GSE93124_SW480_crizotinib_high_MFE_TX_in_DOWN)

# Calculate proportions
GSE93124_SW480_crizotinib_high_MFE_in_UP_fraction <- GSE93124_SW480_crizotinib_count_high_MFE_UP / GSE93124_SW480_crizotinib_total_UP
GSE93124_SW480_crizotinib_high_MFE_in_DOWN_fraction <- GSE93124_SW480_crizotinib_count_high_MFE_DOWN / GSE93124_SW480_crizotinib_total_DOWN

# Perform a two-proportion z-test
n1 <- GSE93124_SW480_crizotinib_total_UP
n2 <- GSE93124_SW480_crizotinib_total_DOWN
p1 <- GSE93124_SW480_crizotinib_high_MFE_in_UP_fraction
p2 <- GSE93124_SW480_crizotinib_high_MFE_in_DOWN_fraction

# Calculate pooled proportion and z-statistic
p_pool <- (p1 * n1 + p2 * n2) / (n1 + n2)
z_stat <- (p1 - p2) / sqrt(p_pool * (1 - p_pool) * (1/n1 + 1/n2))

# Calculate p-value
GSE93124_SW480_crizotinib_z_test_MFE_p_value <- 2 * (1 - pnorm(abs(z_stat)))

# Output results
cat("Fraction of high MFE TX in UP-regulated genes:", p1, "\n")
cat("Fraction of high MFE TX in DOWN-regulated genes:", p2, "\n")
cat("Two-proportion z-test statistic:", z_stat, "\n")
cat("Two-proportion z-test p-value:", GSE93124_SW480_crizotinib_z_test_MFE_p_value, "\n")

# Additional descriptive statistics
cat("Mean of high MFE TX in UP-regulated genes:", mean(GSE93124_SW480_crizotinib_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mean of high MFE TX in DOWN-regulated genes:", mean(GSE93124_SW480_crizotinib_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")
cat("Mode of high MFE TX in UP-regulated genes:", calculate_mode(GSE93124_SW480_crizotinib_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mode of high MFE TX in DOWN-regulated genes:", calculate_mode(GSE93124_SW480_crizotinib_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")




# Show data as violin plot
# Add a new column to indicate if the value is above the 75th percentile
MFE_res_GSE93124_SW480_crizotinib$above_quantile_075 <- MFE_res_GSE93124_SW480_crizotinib$Normalized_MFE > quantile_075_GSE93124_SW480_crizotinib_norm_TX_counts_MFE_df

# Generate violin plot with conditional jitter coloring
ggplot(MFE_res_GSE93124_SW480_crizotinib, aes(x = factor(log2FoldChange > 0), y = Normalized_MFE)) +
  geom_violin(fill = "white") +
  geom_jitter(aes(color = above_quantile_075), width = 0.1, size = 1, alpha = 0.1) +
