    plot.title = element_text(size = 10),
    axis.text.x = element_text(size = 16, color = "black")
  ) +
  geom_vline(xintercept = 0, linewidth = 0.3) +
  labs(
    y = "Normalized_MFE", 
    x = NULL, 
    title = "GSE93124_SW480_crizotinib_Log2_FC_adj.P<0.05"
  ) +
  scale_x_discrete(labels = c("log2FoldChange < 0", "log2FoldChange > 0"))














# Determine the impact of these changes in terms of fraction of total counts:
# Calculate the fraction of total counts of high MFE transcripts in control and drug-treated groups. 
# This is done by summing the counts of the high MFE transcripts and dividing by the total counts in each group.
# Fisher’s exact test to compare the proportions of high MFE transcripts counts between the two groups.


# Convert from wide to long format
GSE93124_SW480_crizotinib_long_data <- GSE93124_SW480_crizotinib_norm_TX_counts_MFE_df %>%
  pivot_longer(
    cols = starts_with("GSM"),      # Select all columns starting with "GSM"
    names_to = "replicate",         # Name of the new column for replicate identifiers
    values_to = "counts"            # Name of the new column for the counts
  )

# Add a condition column based on the replicate
GSE93124_SW480_crizotinib_long_data <- GSE93124_SW480_crizotinib_long_data %>%
  mutate(condition = ifelse(replicate %in% c("GSM2454872", "GSM2454873", "GSM2454874"), "Control", "crizotinib"))

# Aggregate the replicates for each condition
GSE93124_SW480_crizotinib_norm_TX_aggregated_data_avg_counts <- GSE93124_SW480_crizotinib_long_data %>%
  group_by(ensembl_transcript_id_version, condition, Normalized_MFE, Specific_heat) %>%
  summarise(
    avg_counts = mean(counts),
    .groups = 'drop'
  )

# Define the 75th percentile of the entire distribution of MFE values
GSE93124_SW480_crizotinib_MFE_all_TX_75_percentile <- quantile(GSE93124_SW480_crizotinib_norm_TX_aggregated_data_avg_counts$Normalized_MFE, 0.75)

# Identify all transcripts with MFE values above the 75th percentile
# GSE93124_SW480_crizotinib_high_MFE_TX_total <- dplyr::filter(GSE93124_SW480_crizotinib_norm_TX_counts_MFE_df, Normalized_MFE > GSE93124_SW480_crizotinib_MFE_all_TX_75_percentile)
GSE93124_SW480_crizotinib_high_MFE_TX_total <- dplyr::filter(GSE93124_SW480_crizotinib_norm_TX_aggregated_data_avg_counts, Normalized_MFE > GSE93124_SW480_crizotinib_MFE_all_TX_75_percentile)


# Fraction of total high MFE transcripts counts in control and drug-treated groups
GSE93124_SW480_crizotinib_control_total_counts <- dplyr::filter(GSE93124_SW480_crizotinib_norm_TX_aggregated_data_avg_counts, condition == "Control") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE93124_SW480_crizotinib_control_high_MFE_TX_counts <- dplyr::filter(GSE93124_SW480_crizotinib_norm_TX_aggregated_data_avg_counts, condition == "Control") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE93124_SW480_crizotinib_high_MFE_TX_total$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE93124_SW480_crizotinib_control_high_MFE_TX_counts_fraction <- GSE93124_SW480_crizotinib_control_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE93124_SW480_crizotinib_control_total_counts$total_counts




GSE93124_SW480_crizotinib_total_counts <- dplyr::filter(GSE93124_SW480_crizotinib_norm_TX_aggregated_data_avg_counts, condition == "crizotinib") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE93124_SW480_crizotinib_high_MFE_TX_counts <- dplyr::filter(GSE93124_SW480_crizotinib_norm_TX_aggregated_data_avg_counts, condition == "crizotinib") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE93124_SW480_crizotinib_high_MFE_TX_total$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE93124_SW480_crizotinib_high_MFE_TX_counts_fraction <- GSE93124_SW480_crizotinib_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE93124_SW480_crizotinib_total_counts$total_counts



# Two-proportion z-test
n1 <- GSE93124_SW480_crizotinib_control_total_counts$total_counts
n2 <- GSE93124_SW480_crizotinib_total_counts$total_counts
p1 <- GSE93124_SW480_crizotinib_control_high_MFE_TX_counts_fraction
p2 <- GSE93124_SW480_crizotinib_high_MFE_TX_counts_fraction

# Calculate pooled proportion and z-statistic
p_pool <- (p1 * n1 + p2 * n2) / (n1 + n2)
z_stat <- (p1 - p2) / sqrt(p_pool * (1 - p_pool) * (1/n1 + 1/n2))

# Calculate p-value
GSE93124_SW480_crizotinib_z_test_counts_75_p_value <- 2 * (1 - pnorm(abs(z_stat)))

# Output results
cat("GSE93124_SW480_crizotinib_control high MFE TX fraction:", p1, "\n")
cat("SE93124_SW480_crizotinib high MFE TX fraction:", p2, "\n")
