# Define the 25th percentile of the entire distribution of MFE values for the GSE93124_SW480 data
GSE93124_SW480_MFE_all_TX_25_percentile <- quantile(GSE93124_SW480_crizotinib_norm_TX_aggregated_data_avg_counts$Normalized_MFE, 0.25)

# Identify all the transcripts with MFE values below the 25th percentile
GSE93124_SW480_low_MFE_TX_total <- dplyr::filter(GSE93124_SW480_crizotinib_norm_TX_counts_MFE_df, Normalized_MFE < GSE93124_SW480_MFE_all_TX_25_percentile)

# Fraction of total low MFE transcript counts in control and drug-treated groups (Control group)
GSE93124_SW480_control_total_counts <- dplyr::filter(GSE93124_SW480_crizotinib_norm_TX_aggregated_data_avg_counts, condition == "Control") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE93124_SW480_control_low_MFE_TX_counts <- dplyr::filter(GSE93124_SW480_crizotinib_norm_TX_aggregated_data_avg_counts, condition == "Control") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE93124_SW480_low_MFE_TX_total$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_low_MFE_TX = sum(avg_counts))

GSE93124_SW480_control_low_MFE_TX_counts_fraction <- GSE93124_SW480_control_low_MFE_TX_counts$total_counts_low_MFE_TX / GSE93124_SW480_control_total_counts$total_counts
print(GSE93124_SW480_control_low_MFE_TX_counts_fraction) # This value goes in the summary table




# Fraction of total low MFE transcript counts in crizotinib-treated group
GSE93124_SW480_crizotinib_total_counts <- dplyr::filter(GSE93124_SW480_crizotinib_norm_TX_aggregated_data_avg_counts, condition == "crizotinib") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE93124_SW480_crizotinib_low_MFE_TX_counts <- dplyr::filter(GSE93124_SW480_crizotinib_norm_TX_aggregated_data_avg_counts, condition == "crizotinib") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE93124_SW480_low_MFE_TX_total$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_low_MFE_TX = sum(avg_counts))

GSE93124_SW480_crizotinib_low_MFE_TX_counts_fraction <- GSE93124_SW480_crizotinib_low_MFE_TX_counts$total_counts_low_MFE_TX / GSE93124_SW480_crizotinib_total_counts$total_counts
print(GSE93124_SW480_crizotinib_low_MFE_TX_counts_fraction) # This value goes in the summary table




# Proportions of low MFE transcript counts in control and crizotinib-treated groups
p_control_low <- GSE93124_SW480_control_low_MFE_TX_counts_fraction
p_crizotinib_low <- GSE93124_SW480_crizotinib_low_MFE_TX_counts_fraction

# Calculate the pooled proportion for the two-proportion Z-test
pooled_prop_low <- (GSE93124_SW480_control_low_MFE_TX_counts$total_counts_low_MFE_TX + GSE93124_SW480_crizotinib_low_MFE_TX_counts$total_counts_low_MFE_TX) / 
  (GSE93124_SW480_control_total_counts$total_counts + GSE93124_SW480_crizotinib_total_counts$total_counts)

# Standard error for the difference in proportions
se_low <- sqrt(pooled_prop_low * (1 - pooled_prop_low) * 
                 (1 / GSE93124_SW480_control_total_counts$total_counts + 1 / GSE93124_SW480_crizotinib_total_counts$total_counts))

# Z-statistic for the difference in proportions
z_stat_low <- (p_control_low - p_crizotinib_low) / se_low

# p-value for the Z-test (two-tailed test)
GSE93124_SW480_z_test_counts_25_p_value <- 2 * pnorm(-abs(z_stat_low))

# Output the results of the two-proportion Z-test for low MFE transcript counts
cat("Two-proportion Z-test p-value for low MFE TX counts in Control vs crizotinib:", GSE93124_SW480_z_test_counts_25_p_value, "\n")
cat("Z-statistic for low MFE TX counts in Control vs crizotinib:", z_stat_low, "\n")




















