# GSE121105 Breast cancer cell line treated with trastuzumab +/- pertuzumab for 3 days ####
# http://www.ilincs.org/apps/grein/?gse=GSE121105

# IMPORTANT
# The data set includes resistant subpopulations. These samples are not necessary and have not been analyzed.

Counts_GSE121105_GREIN <- read.delim("path_to/GSE121105/GSE121105_TranscriptLevel_Raw_data.csv", sep = ",", header = T, stringsAsFactors = F)
Counts_GSE121105_GREIN <- Counts_GSE121105_GREIN %>% remove_rownames %>% column_to_rownames(var="X") # Convert first column into row names in data frame
# Round counts down to the nearest integer
Counts_GSE121105_GREIN <- floor(Counts_GSE121105_GREIN)

# Select only the samples of interest
Counts_GSE121105_GREIN <- dplyr::select(Counts_GSE121105_GREIN, -c("GSM3426221", "GSM3426222", "GSM3426223", "GSM3426224", "GSM3426225", "GSM3426226", "GSM3426227", "GSM3426228", "GSM3426229", "GSM3426230", "GSM3426231", "GSM3426232"))



# Access the Series Matrix
# Data_GSE121105 <- getGEO(GEO = "GSE121105")

# LOad the object
Data_GSE121105 <- readRDS("path_to/GREIN_series_matrices_data/Data_GSE121105.rds")


# Extract the phenotypic/clinical data matrix from the series matrix
Expdata_GSE121105 <- Data_GSE121105[["GSE121105_series_matrix.txt.gz"]]@phenoData@data

colnames(Expdata_GSE121105)[colnames(Expdata_GSE121105) == "treatment:ch1"] <- "condition" # Rename the column to have an easier identifier for the conditions

# Edit the descriptions of the conditions
Expdata_GSE121105$condition <- gsub("none", "DMSO", Expdata_GSE121105$condition)
Expdata_GSE121105$condition <- gsub("10 µg/mL trastuzumab for 3 days", "trastuzumab", Expdata_GSE121105$condition)
row_index <- 7:9
column_name <- "condition"
Expdata_GSE121105[row_index, column_name] <- "trastuzumab_pertuzumab"

# Select specific conditions
Expdata_GSE121105 <- Expdata_GSE121105[(1:9), ]




# IMPORTANT:
# It is absolutely critical that the columns of the count matrix and the rows of the column data (information about samples) are in the same order.

# Replace the row names of Expdata_GSE121105 (sampleID) with the same sample name [title] of [Counts_GSE182018]. 
# This will help to match sample names in both matrices.
# The outcome should be TRUE
all(rownames(Expdata_GSE121105) %in% colnames(Counts_GSE121105_GREIN))
all(colnames(Counts_GSE121105_GREIN) %in% rownames(Expdata_GSE121105))

# With the count matrix, Counts_GSE108308_GREIN, and the sample information, Expdata_GSE108308, we can construct a DESeqDataSet:
dds_GSE121105 <- DESeqDataSetFromMatrix(countData = Counts_GSE121105_GREIN,
                                       colData = Expdata_GSE121105,
                                       design = ~ condition)
dds_GSE121105




# DATA QUALITY ASSESSMENT COUNTS
# Before performing differential expression analysis, we perform data quality assessment by sample clustering and visualization
library("pheatmap")
# We log transform the counts
ntd <- normTransform(dds_GSE121105)
# Heat map of the count matrix
select <- order(rowMeans(counts(dds_GSE121105,normalized=FALSE)),
                decreasing=TRUE)[1:25]
df <- as.data.frame(colData(dds_GSE121105)[,c("condition","type")])
pheatmap(assay(ntd)[select,], cluster_rows=FALSE, show_rownames=FALSE,
         cluster_cols=FALSE, annotation_col=df)



# Heatmap of the sample-to-sample distances
# A heatmap of this distance matrix gives us an overview over similarities and dissimilarities between samples
# Transform the values
vsd <- vst(dds_GSE121105, blind=FALSE)
# rld <- rlog(dds_GSE121105, blind=FALSE)
head(assay(vsd), 3)

# Apply the dist function to the transpose of the transformed count matrix to get sample-to-sample distances
sampleDists <- dist(t(assay(vsd)))

# Condition
library("RColorBrewer")
sampleDistMatrix <- as.matrix(sampleDists)
rownames(sampleDistMatrix) <- paste(vsd$condition, vsd$type, sep="-")
colnames(sampleDistMatrix) <- NULL
colors <- colorRampPalette( rev(brewer.pal(9, "Blues")) )(255)
pheatmap(sampleDistMatrix,
         clustering_distance_rows=sampleDists,
         clustering_distance_cols=sampleDists,
         col=colors)

# Principal component plot of the samples
plotPCA(vsd, intgroup="condition")




# DIFFERENTIAL EXPRESSION ANALYSIS
# We perform a minimal pre-filtering to keep only rows that have at least 3 reads total
keep <- rowSums(counts(dds_GSE121105)) >= 3
dds_GSE121105 <- dds_GSE121105[keep,]
table(keep) # This shows how many transcripts have been removed after the filtering
nrow(dds_GSE121105) # to confirm the filtered transcripts

# DIFFERENTIAL EXPRESSION ANALYSIS
dds_GSE121105 <- DESeq(dds_GSE121105) # The DESeq() function normalizes the read counts, estimates dispersions, and fits the linear model, all in one go
# dds_GSE121105 <- DESeq(dds_GSE121105, betaPrior = T)  The betaPrior = T opton tells DESeq2 to squeeze the log Fold Changes of lowly expressed genes toward zero.

# If I want to see the normalized counts generated in the DESeq object:
# norm_dds_GSE121105 <- counts(dds_GSE121105, normalized=TRUE)

# resultsNames(dds_GSE121105) # lists the coefficients
# plotDispEsts(dds_GSE121105) # Plot the dispersions
# Each black dot in the plot represents the dispersion for one gene. The red line is fit to data (black bots),
# then the dispersions are squeezed toward the red line, resulting the final (blue) dispersion estimates. Usually,
# the dispersion is highest at the low counts and levels off at higher counts.



# Analysis GSE121105_trastuzumab data
# Specify the conditions to contrast for differential expression analysis
res_GSE121105_trastuzumab <- results(dds_GSE121105, contrast=c("condition","trastuzumab","DMSO")) # to specify the samples to contrast
res_GSE121105_trastuzumab
# Get a summary of the results
summary(res_GSE121105_trastuzumab)




# Plot the log2 Fold Changes as function of expression:
plotMA(res_GSE121105_trastuzumab,alpha = 0.05)
abline(h=c(-2,2),col = "red")

# Transform the row names into a column
res_GSE121105_trastuzumab_df <- data.frame(res_GSE121105_trastuzumab)
res_GSE121105_trastuzumab <- tibble::rownames_to_column(res_GSE121105_trastuzumab_df, "ensembl_transcript_id")



# Join the expression change values with the Table_ANNOTATED containing MFE values
MFE_res_GSE121105_trastuzumab <- dplyr::inner_join(Table_ANNOTATED, res_GSE121105_trastuzumab, by="ensembl_transcript_id") %>% # The file 'Table' contains the Normalized_MFE values of all ANNOTATED transcripts
  dplyr::filter(padj < 0.05) 



# Generate a scatter plot Log2_FC vs Normalized_MFE

Plot_GSE121105_trastuzumab <- ggplot(MFE_res_GSE121105_trastuzumab, aes(y=Normalized_MFE, x=log2FoldChange)) +
  geom_point(size=1.5, alpha=0.3)+
  theme_classic() +
  theme(legend.position="none") +
  geom_vline(xintercept = 0, size=0.3) +
  #xlim(-5.5,5.5) +
  theme(axis.title = element_text(size = 20)) +
  theme(plot.title = element_text(size = 15)) +
  labs(y="DGfold / nt (kcal/mol)",x="Log2_FC_expression",title="GSE121105_trastuzumab_Log2_FC_adj.P<0.05")
print(Plot_GSE121105_trastuzumab)






# Look at the mean log2_FC
MFE_res_GSE121105_trastuzumab_UP <- dplyr::filter(MFE_res_GSE121105_trastuzumab, log2FoldChange > 0)
Mean_MFE_res_GSE121105_trastuzumab_UP <- mean(MFE_res_GSE121105_trastuzumab_UP$Normalized_MFE)

MFE_res_GSE121105_trastuzumab_DOWN <- dplyr::filter(MFE_res_GSE121105_trastuzumab, log2FoldChange < 0)
Mean_MFE_res_GSE121105_trastuzumab_DOWN <- mean(MFE_res_GSE121105_trastuzumab_DOWN$Normalized_MFE)

TTEST_MFE_res_GSE121105_trastuzumab_all_UP_vs_DOWN <- t.test(MFE_res_GSE121105_trastuzumab_DOWN$Normalized_MFE, MFE_res_GSE121105_trastuzumab_UP$Normalized_MFE, paired=FALSE)

# Add K-S test to look at the differences between the up-regukated and down-regulated genes
ks_test_res_GSE121105_trastuzumab_all_UP_vs_DOWN <- ks.test(MFE_res_GSE121105_trastuzumab_DOWN$Normalized_MFE, MFE_res_GSE121105_trastuzumab_UP$Normalized_MFE)


quantile_075_MFE_res_GSE121105_trastuzumab_UP <- quantile(MFE_res_GSE121105_trastuzumab_UP$Normalized_MFE, probs = c(0.75)) 
quantile_075_MFE_res_GSE121105_trastuzumab_DOWN <- quantile(MFE_res_GSE121105_trastuzumab_DOWN$Normalized_MFE, probs = c(0.75)) 
# Values above 0.75 quantile
ks_test_MFE_075_above <- ks.test(MFE_res_GSE121105_trastuzumab_UP$Normalized_MFE[MFE_res_GSE121105_trastuzumab_UP$Normalized_MFE >= quantile_075_MFE_res_GSE121105_trastuzumab_UP],
                                 MFE_res_GSE121105_trastuzumab_DOWN$Normalized_MFE[MFE_res_GSE121105_trastuzumab_DOWN$Normalized_MFE >= quantile_075_MFE_res_GSE121105_trastuzumab_DOWN])

# Look at the differences between the 0.25 quantile 
quantile_025_MFE_res_GSE121105_trastuzumab_UP <- quantile(MFE_res_GSE121105_trastuzumab_UP$Normalized_MFE, probs = c(0.25)) 
quantile_025_MFE_res_GSE121105_trastuzumab_DOWN <- quantile(MFE_res_GSE121105_trastuzumab_DOWN$Normalized_MFE, probs = c(0.25)) 
# Values below 0.25 quantile
ks_test_MFE_025_below <- ks.test(MFE_res_GSE121105_trastuzumab_UP$Normalized_MFE[MFE_res_GSE121105_trastuzumab_UP$Normalized_MFE <= quantile_025_MFE_res_GSE121105_trastuzumab_UP],
                                 MFE_res_GSE121105_trastuzumab_DOWN$Normalized_MFE[MFE_res_GSE121105_trastuzumab_DOWN$Normalized_MFE <= quantile_025_MFE_res_GSE121105_trastuzumab_DOWN])



# Permutation test MFE changes
# Combine the data into a single data frame with labels
upregulated <- data.frame(MFE = MFE_res_GSE121105_trastuzumab_UP$Normalized_MFE, Group = "Up")
downregulated <- data.frame(MFE = MFE_res_GSE121105_trastuzumab_DOWN$Normalized_MFE, Group = "Down")
combined_data <- bind_rows(upregulated, downregulated)

# Observed difference in means
GSE121105_trastuzumab_observed_diff <- mean(MFE_res_GSE121105_trastuzumab_UP$Normalized_MFE) - mean(MFE_res_GSE121105_trastuzumab_DOWN$Normalized_MFE)

# Number of permutations
n_permutations <- 10000

# Initialize a vector to store the permuted differences
GSE121105_trastuzumab_permuted_diffs <- numeric(n_permutations)

# Permutation test
set.seed(123)  # Set seed for reproducibility
for (i in 1:n_permutations) {
  # Permute the Group labels
  permuted_labels <- sample(combined_data$Group)
  
  # Calculate the mean MFE for each permuted group
  permuted_up_mean <- mean(combined_data$MFE[permuted_labels == "Up"])
  permuted_down_mean <- mean(combined_data$MFE[permuted_labels == "Down"])
  
  # Calculate the difference in means for the permuted groups
  GSE121105_trastuzumab_permuted_diffs[i] <- permuted_up_mean - permuted_down_mean
}

# Calculate the p-value
GSE121105_trastuzumab_p_value <- (sum(abs(GSE121105_trastuzumab_permuted_diffs) >= abs(GSE121105_trastuzumab_observed_diff)) + 1) / (n_permutations + 1)

# Output the results
cat("Observed difference in GSE121105_trastuzumab means MFE_UP - MFE_DOWN:", GSE121105_trastuzumab_observed_diff, "\n")
cat("GSE121105_trastuzumab P-value from permutation test:", GSE121105_trastuzumab_p_value, "\n")









