## GSE121105 High MFE TX fraction changes ####
# Determine whether within the differentially expressed genes there is a significant up-regulation of high MFE transcripts:
# Define high MFE transcripts by taking the 75th percentile of the combined MFE distributions of control and drug-treated samples.
# Count the number of transcripts in the significantly up- and down-regulated genes that have MFE values above this threshold.
# Perform a Fisher’s exact test to compare the proportions of high MFE transcripts between the two groups.


# Analysis GSE121105
# Extract the normalized count data
# The minimal pre-filtering has already been done in the previous steps
GSE121105_norm_TX_counts <- counts(dds_GSE121105, normalized=TRUE) # This object is already a matrix
GSE121105_norm_TX_counts_df <- as.data.frame(GSE121105_norm_TX_counts)
# Convert row names to column
GSE121105_norm_TX_counts_df$ensembl_transcript_id <- rownames(GSE121105_norm_TX_counts_df)
# Remove row names
rownames(GSE121105_norm_TX_counts_df) <- NULL

# Move ensembl_transcript_id column to the first position
GSE121105_norm_TX_counts_df <- GSE121105_norm_TX_counts_df[, c("ensembl_transcript_id", setdiff(names(GSE121105_norm_TX_counts_df), "ensembl_transcript_id"))]

# Remove everything after the dot (including the dot itself) in the ensembl_transcript_id column
GSE121105_norm_TX_counts_df$ensembl_transcript_id <- sub("\\..*", "", GSE121105_norm_TX_counts_df$ensembl_transcript_id)

# Join the counts with the Table_ANNOTATED containing MFE values and heat capacity values
GSE121105_norm_TX_counts_MFE_df <- dplyr::inner_join(Table_ANNOTATED, GSE121105_norm_TX_counts_df, by="ensembl_transcript_id") %>%
  dplyr::select(ensembl_transcript_id_version, ensembl_transcript_id, ensembl_gene_id, external_gene_name, transcript_is_canonical, Transcript_length, 
                GSM3426212, GSM3426213, GSM3426214, GSM3426215, GSM3426216, GSM3426217, GSM3426218, GSM3426219, GSM3426220,
                Normalized_MFE, Temperature, Specific_heat)







# GSE121105_trastuzumab
# Convert from wide to long format
GSE121105_trastuzumab_norm_TX_counts_MFE_df <- GSE121105_norm_TX_counts_MFE_df %>%
  dplyr::select(ensembl_transcript_id_version, ensembl_transcript_id, ensembl_gene_id, external_gene_name, transcript_is_canonical, Transcript_length, 
                GSM3426212, GSM3426213, GSM3426214, GSM3426215, GSM3426216, GSM3426217, 
                Normalized_MFE, Temperature, Specific_heat) %>%
  dplyr::filter(ensembl_transcript_id %in% MFE_res_GSE121105_trastuzumab$ensembl_transcript_id) 

# Identify the 75th percentile of the combined MFE distributions of control and drug-treated samples
quantile_075_GSE121105_trastuzumab_norm_TX_counts_MFE_df <- quantile(GSE121105_trastuzumab_norm_TX_counts_MFE_df$Normalized_MFE, probs = c(0.75))

# Select all the transcripts with Normalized_MFE values above the 75th percentile
GSE121105_trastuzumab_high_MFE_TX <- dplyr::filter(GSE121105_trastuzumab_norm_TX_counts_MFE_df, Normalized_MFE > quantile_075_GSE121105_trastuzumab_norm_TX_counts_MFE_df)

# Count the number of transcripts in the significantly up- and down-regulated pools that have MFE values above this threshold.
GSE121105_trastuzumab_high_MFE_TX_in_UP <- dplyr::filter(MFE_res_GSE121105_trastuzumab_UP, ensembl_transcript_id_version %in% GSE121105_trastuzumab_high_MFE_TX$ensembl_transcript_id_version)
GSE121105_trastuzumab_high_MFE_TX_in_DOWN <- dplyr::filter(MFE_res_GSE121105_trastuzumab_DOWN, ensembl_transcript_id_version %in% GSE121105_trastuzumab_high_MFE_TX$ensembl_transcript_id_version)

# Calculate the proportions of high MFE transcripts in UP and DOWN-regulated groups
GSE121105_trastuzumab_total_UP <- nrow(MFE_res_GSE121105_trastuzumab_UP)
GSE121105_trastuzumab_total_DOWN <- nrow(MFE_res_GSE121105_trastuzumab_DOWN)
GSE121105_trastuzumab_count_high_MFE_UP <- nrow(GSE121105_trastuzumab_high_MFE_TX_in_UP)
GSE121105_trastuzumab_count_high_MFE_DOWN <- nrow(GSE121105_trastuzumab_high_MFE_TX_in_DOWN)

# Proportions of high MFE in each group
p_UP <- GSE121105_trastuzumab_count_high_MFE_UP / GSE121105_trastuzumab_total_UP
p_DOWN <- GSE121105_trastuzumab_count_high_MFE_DOWN / GSE121105_trastuzumab_total_DOWN

# Pooled proportion
P_pool <- (GSE121105_trastuzumab_count_high_MFE_UP + GSE121105_trastuzumab_count_high_MFE_DOWN) /
  (GSE121105_trastuzumab_total_UP + GSE121105_trastuzumab_total_DOWN)

# Two-proportion Z-test statistic
Z <- (p_UP - p_DOWN) / sqrt(P_pool * (1 - P_pool) * (1/GSE121105_trastuzumab_total_UP + 1/GSE121105_trastuzumab_total_DOWN))

# Calculate the p-value for the Z-test
GSE121105_trastuzumab_z_test_MFE_p_value <- 2 * (1 - pnorm(abs(Z)))

# Output the results
cat("Two-proportion Z-test statistic:", Z, "\n")
cat("Two-proportion Z-test p-value:", GSE121105_trastuzumab_z_test_MFE_p_value, "\n")

# Look at the fractions
GSE121105_trastuzumab_high_MFE_in_UP_fraction <- GSE121105_trastuzumab_count_high_MFE_UP / GSE121105_trastuzumab_total_UP
GSE121105_trastuzumab_high_MFE_in_DOWN_fraction <- GSE121105_trastuzumab_count_high_MFE_DOWN / GSE121105_trastuzumab_total_DOWN

# Output the fractions
cat("Fraction of GSE121105_trastuzumab high MFE TX in UP-regulated genes:", GSE121105_trastuzumab_high_MFE_in_UP_fraction, "\n")
cat("Fraction of GSE121105_trastuzumab high MFE TX in DOWN-regulated genes:", GSE121105_trastuzumab_high_MFE_in_DOWN_fraction, "\n")
cat("Mean of GSE121105_trastuzumab high MFE TX in UP-regulated genes:", mean(GSE121105_trastuzumab_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mean of GSE121105_trastuzumab high MFE TX in DOWN-regulated genes:", mean(GSE121105_trastuzumab_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")
cat("Mode of GSE121105_trastuzumab high MFE TX in UP-regulated genes:", calculate_mode(GSE121105_trastuzumab_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mode of GSE121105_trastuzumab high MFE TX in DOWN-regulated genes:", calculate_mode(GSE121105_trastuzumab_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")





# Show data as violin plot
# Add a new column to indicate if the value is above the 75th percentile
MFE_res_GSE121105_trastuzumab$above_quantile_075 <- MFE_res_GSE121105_trastuzumab$Normalized_MFE > quantile_075_GSE121105_trastuzumab_norm_TX_counts_MFE_df

# Generate violin plot with conditional jitter coloring
Plot_MFE_GSE121105 <- ggplot(MFE_res_GSE121105_trastuzumab, aes(x = factor(log2FoldChange > 0), y = Normalized_MFE)) +
  geom_violin(fill = "white", size = 1.5) +
  geom_jitter(aes(color = above_quantile_075), width = 0.1, size = 1, alpha = 1) +
  scale_color_manual(values = c("FALSE" = "black", "TRUE" = "dodgerblue3")) +
  theme_classic() +
  ylim(-0.6, 0) +
  theme(
    legend.position = "none", 
    axis.title = element_text(size = 20), 
    plot.title = element_text(size = 10),
    axis.text.x = element_text(size = 16, color = "black")
  ) +
  geom_vline(xintercept = 0, linewidth = 0.3) +
  labs(
    y = "Normalized_MFE", 
    x = NULL, 
    title = "GSE121105_trastuzumab_Log2_FC_adj.P<0.05"
  ) +
  scale_x_discrete(labels = c("log2_FC < 0", "log2_FC > 0"))

print(Plot_MFE_GSE121105)




















