# Determine the impact of these changes in terms of fraction of total counts:
# Calculate the fraction of total counts of high MFE transcripts in control and drug-treated groups. 
# This is done by summing the counts of the high MFE transcripts and dividing by the total counts in each group.
# Fisher’s exact test to compare the proportions of high MFE transcripts counts between the two groups.


# Convert from wide to long format
GSE121105_trastuzumab_long_data <- GSE121105_trastuzumab_norm_TX_counts_MFE_df %>%
  pivot_longer(
    cols = starts_with("GSM"),      # Select all columns starting with "GSM"
    names_to = "replicate",         # Name of the new column for replicate identifiers
    values_to = "counts"            # Name of the new column for the counts
  )

# Add a condition column based on the replicate
GSE121105_trastuzumab_long_data <- GSE121105_trastuzumab_long_data %>%
  mutate(condition = ifelse(replicate %in% c("GSM3426212", "GSM3426213", "GSM3426214"), "Control", "trastuzumab"))

# Aggregate the replicates for each condition
GSE121105_trastuzumab_norm_TX_aggregated_data_avg_counts <- GSE121105_trastuzumab_long_data %>%
  group_by(ensembl_transcript_id_version, condition, Normalized_MFE, Specific_heat) %>%
  summarise(
    avg_counts = mean(counts),
    .groups = 'drop'
  )

# Define the 75th percentile of the entire distribution of MFE values for the GSE121105_trastuzumab data
GSE121105_trastuzumab_MFE_all_TX_75_percentile <- quantile(GSE121105_trastuzumab_norm_TX_aggregated_data_avg_counts$Normalized_MFE, 0.75)

# Identify all the transcripts with MFE values above the 75th percentile
GSE121105_trastuzumab_high_MFE_TX_total <- dplyr::filter(GSE121105_trastuzumab_norm_TX_counts_MFE_df, Normalized_MFE > GSE121105_trastuzumab_MFE_all_TX_75_percentile)

# Fraction of total high MFE transcript counts in control and drug-treated groups
GSE121105_trastuzumab_control_total_counts <- dplyr::filter(GSE121105_trastuzumab_norm_TX_aggregated_data_avg_counts, condition == "Control") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE121105_trastuzumab_control_high_MFE_TX_counts <- dplyr::filter(GSE121105_trastuzumab_norm_TX_aggregated_data_avg_counts, condition == "Control") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE121105_trastuzumab_high_MFE_TX_total$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE121105_trastuzumab_control_high_MFE_TX_counts_fraction <- GSE121105_trastuzumab_control_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE121105_trastuzumab_control_total_counts$total_counts
print(GSE121105_trastuzumab_control_high_MFE_TX_counts_fraction) # This value goes in the summary table

GSE121105_trastuzumab_trastuzumab_total_counts <- dplyr::filter(GSE121105_trastuzumab_norm_TX_aggregated_data_avg_counts, condition == "trastuzumab") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE121105_trastuzumab_trastuzumab_high_MFE_TX_counts <- dplyr::filter(GSE121105_trastuzumab_norm_TX_aggregated_data_avg_counts, condition == "trastuzumab") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE121105_trastuzumab_high_MFE_TX_total$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE121105_trastuzumab_trastuzumab_high_MFE_TX_counts_fraction <- GSE121105_trastuzumab_trastuzumab_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE121105_trastuzumab_trastuzumab_total_counts$total_counts
print(GSE121105_trastuzumab_trastuzumab_high_MFE_TX_counts_fraction) # This value goes in the summary table

# Calculate proportions and apply two-proportion Z-test
p_control <- GSE121105_trastuzumab_control_high_MFE_TX_counts_fraction
p_trastuzumab <- GSE121105_trastuzumab_trastuzumab_high_MFE_TX_counts_fraction

# Pooled proportion
P_pool <- (GSE121105_trastuzumab_control_high_MFE_TX_counts$total_counts_high_MFE_TX + GSE121105_trastuzumab_trastuzumab_high_MFE_TX_counts$total_counts_high_MFE_TX) /
  (GSE121105_trastuzumab_control_total_counts$total_counts + GSE121105_trastuzumab_trastuzumab_total_counts$total_counts)

# Z-test statistic for two proportions
Z <- (p_control - p_trastuzumab) / sqrt(P_pool * (1 - P_pool) * (1/GSE121105_trastuzumab_control_total_counts$total_counts + 1/GSE121105_trastuzumab_trastuzumab_total_counts$total_counts))

# Calculate the p-value for the Z-test
GSE121105_trastuzumab_z_test_counts_75_p_value <- 2 * (1 - pnorm(abs(Z)))

# Output the results
cat("Two-proportion Z-test statistic:", Z, "\n")
cat("Two-proportion Z-test p-value:", GSE121105_trastuzumab_z_test_counts_75_p_value, "\n")

# Output the results of fractions and net change
cat("GSE121105_trastuzumab control high MFE TX as fraction of total counts:", GSE121105_trastuzumab_control_high_MFE_TX_counts_fraction, "\n")
cat("GSE121105_trastuzumab trastuzumab high MFE TX as fraction of total counts:", GSE121105_trastuzumab_trastuzumab_high_MFE_TX_counts_fraction, "\n")
cat("GSE121105_trastuzumab net change counts high MFE TX drug vs control:", GSE121105_trastuzumab_trastuzumab_high_MFE_TX_counts_fraction - GSE121105_trastuzumab_control_high_MFE_TX_counts_fraction, "\n")





