# Pooled proportion
P_pool <- (GSE121105_trastuzumab_control_low_MFE_TX_counts$total_counts_low_MFE_TX + GSE121105_trastuzumab_trastuzumab_low_MFE_TX_counts$total_counts_low_MFE_TX) /
  (GSE121105_trastuzumab_control_total_counts$total_counts + GSE121105_trastuzumab_trastuzumab_total_counts$total_counts)

# Z-test statistic for two proportions
Z <- (p_control - p_trastuzumab) / sqrt(P_pool * (1 - P_pool) * (1/GSE121105_trastuzumab_control_total_counts$total_counts + 1/GSE121105_trastuzumab_trastuzumab_total_counts$total_counts))

# Calculate the p-value for the Z-test
GSE121105_trastuzumab_z_test_counts_25_p_value <- 2 * (1 - pnorm(abs(Z)))

# Output the results
cat("Two-proportion Z-test statistic:", Z, "\n")
cat("Two-proportion Z-test p-value:", GSE121105_trastuzumab_z_test_counts_25_p_value, "\n")

# Output the results of fractions and net change
cat("GSE121105_trastuzumab control low MFE TX as fraction of total counts:", GSE121105_trastuzumab_control_low_MFE_TX_counts_fraction, "\n")
cat("GSE121105_trastuzumab trastuzumab low MFE TX as fraction of total counts:", GSE121105_trastuzumab_trastuzumab_low_MFE_TX_counts_fraction, "\n")
cat("GSE121105_trastuzumab net change counts low MFE TX drug vs control:", GSE121105_trastuzumab_trastuzumab_low_MFE_TX_counts_fraction - GSE121105_trastuzumab_control_low_MFE_TX_counts_fraction, "\n")
































