# Convert from wide to long format
GSE121105_trastuzumab_pertuzumab_long_data <- GSE121105_trastuzumab_pertuzumab_norm_TX_counts_MFE_df %>%
  pivot_longer(
    cols = starts_with("GSM"),      # Select all columns starting with "GSM"
    names_to = "replicate",         # Name of the new column for replicate identifiers
    values_to = "counts"            # Name of the new column for the counts
  )

# Add a condition column based on the replicate
GSE121105_trastuzumab_pertuzumab_long_data <- GSE121105_trastuzumab_pertuzumab_long_data %>%
  mutate(condition = ifelse(replicate %in% c("GSM3426212", "GSM3426213", "GSM3426214"), "Control", "trastuzumab_pertuzumab"))

# Aggregate the replicates for each condition
GSE121105_trastuzumab_pertuzumab_norm_TX_aggregated_data_avg_counts <- GSE121105_trastuzumab_pertuzumab_long_data %>%
  group_by(ensembl_transcript_id_version, condition, Normalized_MFE, Specific_heat) %>%
  summarise(
    avg_counts = mean(counts),
    .groups = 'drop'
  )

# Define the 75th percentile of the entire distribution of MFE values for the GSE182018 data
GSE121105_trastuzumab_pertuzumab_MFE_all_TX_75_percentile <- quantile(GSE121105_trastuzumab_pertuzumab_norm_TX_aggregated_data_avg_counts$Normalized_MFE, 0.75)

# Identify all the transcripts with MFE values above the 75th percentile
GSE121105_trastuzumab_pertuzumab_high_MFE_TX_total <- dplyr::filter(GSE121105_trastuzumab_pertuzumab_norm_TX_counts_MFE_df, Normalized_MFE > GSE121105_trastuzumab_pertuzumab_MFE_all_TX_75_percentile)

# Fraction of total high MFE transcript counts in control and drug-treated groups
GSE121105_trastuzumab_pertuzumab_control_total_counts <- dplyr::filter(GSE121105_trastuzumab_pertuzumab_norm_TX_aggregated_data_avg_counts, condition == "Control") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE121105_trastuzumab_pertuzumab_control_high_MFE_TX_counts <- dplyr::filter(GSE121105_trastuzumab_pertuzumab_norm_TX_aggregated_data_avg_counts, condition == "Control") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE121105_trastuzumab_pertuzumab_high_MFE_TX_total$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE121105_trastuzumab_pertuzumab_control_high_MFE_TX_counts_fraction <- GSE121105_trastuzumab_pertuzumab_control_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE121105_trastuzumab_pertuzumab_control_total_counts$total_counts
print(GSE121105_trastuzumab_pertuzumab_control_high_MFE_TX_counts_fraction) # This value goes in the summary table

GSE121105_trastuzumab_pertuzumab_trastuzumab_pertuzumab_total_counts <- dplyr::filter(GSE121105_trastuzumab_pertuzumab_norm_TX_aggregated_data_avg_counts, condition == "trastuzumab_pertuzumab") %>%
