GSE121105_trastuzumab_pertuzumab_trastuzumab_pertuzumab_high_MFE_TX_counts <- dplyr::filter(GSE121105_trastuzumab_pertuzumab_norm_TX_aggregated_data_avg_counts, condition == "trastuzumab_pertuzumab") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE121105_trastuzumab_pertuzumab_high_MFE_TX_total$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE121105_trastuzumab_pertuzumab_trastuzumab_pertuzumab_high_MFE_TX_counts_fraction <- GSE121105_trastuzumab_pertuzumab_trastuzumab_pertuzumab_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE121105_trastuzumab_pertuzumab_trastuzumab_pertuzumab_total_counts$total_counts
print(GSE121105_trastuzumab_pertuzumab_trastuzumab_pertuzumab_high_MFE_TX_counts_fraction) # This value goes in the summary table

# Calculate proportions and apply two-proportion Z-test
p_control <- GSE121105_trastuzumab_pertuzumab_control_high_MFE_TX_counts_fraction
p_trastuzumab_pertuzumab <- GSE121105_trastuzumab_pertuzumab_trastuzumab_pertuzumab_high_MFE_TX_counts_fraction

# Pooled proportion
P_pool <- (GSE121105_trastuzumab_pertuzumab_control_high_MFE_TX_counts$total_counts_high_MFE_TX + GSE121105_trastuzumab_pertuzumab_trastuzumab_pertuzumab_high_MFE_TX_counts$total_counts_high_MFE_TX) /
  (GSE121105_trastuzumab_pertuzumab_control_total_counts$total_counts + GSE121105_trastuzumab_pertuzumab_trastuzumab_pertuzumab_total_counts$total_counts)

# Z-test statistic for two proportions
Z <- (p_control - p_trastuzumab_pertuzumab) / sqrt(P_pool * (1 - P_pool) * (1/GSE121105_trastuzumab_pertuzumab_control_total_counts$total_counts + 1/GSE121105_trastuzumab_pertuzumab_trastuzumab_pertuzumab_total_counts$total_counts))

# Calculate the p-value for the Z-test
GSE121105_trastuzumab_pertuzumab_z_test_counts_75_p_value <- 2 * (1 - pnorm(abs(Z)))

# Output the results
cat("Two-proportion Z-test statistic:", Z, "\n")
cat("Two-proportion Z-test p-value:", GSE121105_trastuzumab_pertuzumab_z_test_counts_75_p_value, "\n")

# Output the results of fractions and net change
