# Select only the samples of interest
Counts_GSE121105_gene <- dplyr::select(Counts_GSE121105_gene, -c("X", "GSM3426221", "GSM3426222", "GSM3426223", "GSM3426224", "GSM3426225", "GSM3426226", "GSM3426227", "GSM3426228", "GSM3426229", "GSM3426230", "GSM3426231", "GSM3426232"))


