# In order to use the gene symbols as raw names, I need to remove the duplicates - I merge the counts of the same gene
Counts_GSE121105_gene <- Counts_GSE121105_gene %>% group_by(gene_symbol) %>%
  summarise (GSM3426212 = sum(GSM3426212),
             GSM3426213 = sum(GSM3426213),
             GSM3426214 = sum(GSM3426214),
             GSM3426215 = sum(GSM3426215),
