# Calculate proportions
p_control <- GSE73318_HCT_116_control_low_MFE_TX_counts_fraction
p_HCT_116 <- GSE73318_HCT_116_HCT_116_low_MFE_TX_counts_fraction

# Pooled proportion (weighted average of proportions)
P_pool <- (GSE73318_HCT_116_control_low_MFE_TX_counts$total_counts_low_MFE_TX + GSE73318_HCT_116_HCT_116_low_MFE_TX_counts$total_counts_low_MFE_TX) /
  (GSE73318_HCT_116_control_total_counts$total_counts + GSE73318_HCT_116_HCT_116_total_counts$total_counts)

# Calculate the variance for the two-proportion Z-test
var_control <- p_control * (1 - p_control) / GSE73318_HCT_116_control_total_counts$total_counts
var_HCT_116 <- p_HCT_116 * (1 - p_HCT_116) / GSE73318_HCT_116_HCT_116_total_counts$total_counts

# Combined variance for two proportions Z-test
P_pool_variance <- P_pool * (1 - P_pool) * (1 / GSE73318_HCT_116_control_total_counts$total_counts + 1 / GSE73318_HCT_116_HCT_116_total_counts$total_counts)

# Z-test statistic for two proportions
Z <- (p_control - p_HCT_116) / sqrt(P_pool_variance)

# Calculate the p-value for the Z-test (two-tailed)
GSE73318_HCT_116_z_test_counts_25_p_value <- 2 * (1 - pnorm(abs(Z)))

# Output the results
cat("Two-proportion Z-test statistic:", Z, "\n")
cat("Two-proportion Z-test p-value:", GSE73318_HCT_116_z_test_counts_25_p_value, "\n")

