cat("GSE73318_HCT_116 control low MFE TX as fraction of total counts:", GSE73318_HCT_116_control_low_MFE_TX_counts_fraction, "\n")
cat("GSE73318_HCT_116 HCT_116 low MFE TX as fraction of total counts:", GSE73318_HCT_116_HCT_116_low_MFE_TX_counts_fraction, "\n")
cat("GSE73318_HCT_116 net change counts low MFE TX drug vs control:", GSE73318_HCT_116_HCT_116_low_MFE_TX_counts_fraction - GSE73318_HCT_116_control_low_MFE_TX_counts_fraction, "\n")















