# Fraction of total low MFE transcript counts in control and drug-treated groups
GSE73318_SW_480_control_total_counts <- dplyr::filter(GSE73318_SW_480_norm_TX_aggregated_data_avg_counts, condition == "DMSO") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE73318_SW_480_control_low_MFE_TX_counts <- dplyr::filter(GSE73318_SW_480_norm_TX_aggregated_data_avg_counts, condition == "DMSO") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE73318_SW_480_low_MFE_TX_total$ensembl_transcript_id_version) %>%
