GSE73318_SW_480_control_low_MFE_TX_counts_fraction <- GSE73318_SW_480_control_low_MFE_TX_counts$total_counts_low_MFE_TX / GSE73318_SW_480_control_total_counts$total_counts
print(GSE73318_SW_480_control_low_MFE_TX_counts_fraction) # This value goes in the summary table

GSE73318_SW_480_SW_480_total_counts <- dplyr::filter(GSE73318_SW_480_norm_TX_aggregated_data_avg_counts, condition == "JQ1") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE73318_SW_480_SW_480_low_MFE_TX_counts <- dplyr::filter(GSE73318_SW_480_norm_TX_aggregated_data_avg_counts, condition == "JQ1") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE73318_SW_480_low_MFE_TX_total$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_low_MFE_TX = sum(avg_counts))

GSE73318_SW_480_SW_480_low_MFE_TX_counts_fraction <- GSE73318_SW_480_SW_480_low_MFE_TX_counts$total_counts_low_MFE_TX / GSE73318_SW_480_SW_480_total_counts$total_counts
print(GSE73318_SW_480_SW_480_low_MFE_TX_counts_fraction) # This value goes in the summary table

# Calculate proportions
p_control <- GSE73318_SW_480_control_low_MFE_TX_counts_fraction
p_SW_480 <- GSE73318_SW_480_SW_480_low_MFE_TX_counts_fraction

# Pooled proportion (weighted average of proportions)
P_pool <- (GSE73318_SW_480_control_low_MFE_TX_counts$total_counts_low_MFE_TX + GSE73318_SW_480_SW_480_low_MFE_TX_counts$total_counts_low_MFE_TX) /
  (GSE73318_SW_480_control_total_counts$total_counts + GSE73318_SW_480_SW_480_total_counts$total_counts)

# Calculate the variance for the two-proportion Z-test
var_control <- p_control * (1 - p_control) / GSE73318_SW_480_control_total_counts$total_counts
var_SW_480 <- p_SW_480 * (1 - p_SW_480) / GSE73318_SW_480_SW_480_total_counts$total_counts

# Combined variance for two proportions Z-test
P_pool_variance <- P_pool * (1 - P_pool) * (1 / GSE73318_SW_480_control_total_counts$total_counts + 1 / GSE73318_SW_480_SW_480_total_counts$total_counts)

# Z-test statistic for two proportions
Z <- (p_control - p_SW_480) / sqrt(P_pool_variance)

# Calculate the p-value for the Z-test (two-tailed)
GSE73318_SW_480_z_test_counts_25_p_value <- 2 * (1 - pnorm(abs(Z)))

# Output the results
cat("Two-proportion Z-test statistic:", Z, "\n")
cat("Two-proportion Z-test p-value:", GSE73318_SW_480_z_test_counts_25_p_value, "\n")

# Output the results of fractions and net change
cat("GSE73318_SW_480 control low MFE TX as fraction of total counts:", GSE73318_SW_480_control_low_MFE_TX_counts_fraction, "\n")
cat("GSE73318_SW_480 SW_480 low MFE TX as fraction of total counts:", GSE73318_SW_480_SW_480_low_MFE_TX_counts_fraction, "\n")
cat("GSE73318_SW_480 net change counts low MFE TX drug vs control:", GSE73318_SW_480_SW_480_low_MFE_TX_counts_fraction - GSE73318_SW_480_control_low_MFE_TX_counts_fraction, "\n")















