## GSE73318_SW_480 gene-level expression changes ####

# 1. Download from GREIN the row counts at the gene level 
# 2. Normalize the counts with DESeq
# 3. Log2 transform the counts
Counts_GSE73318_SW_480_gene <- read.delim("path_to/GSE73318/GSE73318_GeneLevel_Raw_data.csv", sep = ",", header = T, stringsAsFactors = F)
# Select only the columns of the counts that are necessary for the analysis
Counts_GSE73318_SW_480_gene <- dplyr::select(Counts_GSE73318_SW_480_gene, c("X", "gene_symbol", "GSM1890700", "GSM1890701", "GSM1890702", "GSM1890703", "GSM1890704", "GSM1890705"))

# In order to use the gene symbols as raw names, I need to remove the duplicates - I merge the transcript-level counts of the same gene
Counts_GSE73318_SW_480_gene <- Counts_GSE73318_SW_480_gene %>% group_by(gene_symbol) %>%
  summarise (GSM1890700 = sum(GSM1890700),
             GSM1890701 = sum(GSM1890701),
             GSM1890702 = sum(GSM1890702),
             GSM1890703 = sum(GSM1890703),
             GSM1890704 = sum(GSM1890704),
             GSM1890705 = sum(GSM1890705))

Counts_GSE73318_SW_480_gene <- Counts_GSE73318_SW_480_gene %>% remove_rownames %>% column_to_rownames(var="gene_symbol") # Convert first column into row names in data frame
Counts_GSE73318_SW_480_gene <- floor(Counts_GSE73318_SW_480_gene)

Counts_GSE73318_SW_480_gene <- as.matrix(Counts_GSE73318_SW_480_gene)


# Access the metadata table
Expdata_GSE73318_SW_480_gene <- dplyr::filter(Expdata_GSE73318, geo_accession %in% c("GSM1890700", "GSM1890701", "GSM1890702", "GSM1890703", "GSM1890704", "GSM1890705"))

# Check whether the gene-level counts and the metadata table have the same selected samples
all(rownames(Expdata_GSE73318_SW_480_gene) %in% colnames(Counts_GSE73318_SW_480_gene))
all(colnames(Counts_GSE73318_SW_480_gene) %in% rownames(Expdata_GSE73318_SW_480_gene))

# Construct a DESeqDataSet:
dds_GSE73318_SW_480_gene <- DESeqDataSetFromMatrix(countData = Counts_GSE73318_SW_480_gene,
                                                    colData = Expdata_GSE73318_SW_480_gene,
                                                    design = ~ condition)
dds_GSE73318_SW_480_gene

# Perform differential expression analysis with DESeq2
dds_GSE73318_SW_480_gene <- DESeq(dds_GSE73318_SW_480_gene)

# Check the global change of different proliferation gene sets
dds_proliferation_GSE73318_SW_480_gene <- dds_GSE73318_SW_480_gene

# DIFFERENTIAL EXPRESSION ANALYSIS
res_GSE73318_SW_480_gene <- results(dds_proliferation_GSE73318_SW_480_gene, contrast=c("condition","SW_480_JQ1","SW_480_DMSO")) # to specify the samples to contrast
res_GSE73318_SW_480_gene

# Gene names are as raw names. Transform to first column for the filtering
res_GSE73318_SW_480_gene_df <- as.data.frame(res_GSE73318_SW_480_gene)
res_GSE73318_SW_480_gene_df <- dplyr::filter(res_GSE73318_SW_480_gene_df, !is.na(padj)) # Remove NA
res_GSE73318_SW_480_gene_df <- tibble::rownames_to_column(res_GSE73318_SW_480_gene_df, "Gene_symbol")
















