# Determine the impact of these changes in terms of fraction of total counts:
# Calculate the fraction of total counts of high MFE transcripts in control and drug-treated groups. 
# This is done by summing the counts of the high MFE transcripts and dividing by the total counts in each group.
# Fisher’s exact test to compare the proportions of high MFE transcripts counts between the two groups.


# Convert from wide to long format
GSE73318_HT_29_long_data <- GSE73318_HT_29_norm_TX_counts_MFE_df %>%
  pivot_longer(
    cols = starts_with("GSM"),      # Select all columns starting with "GSM"
    names_to = "replicate",         # Name of the new column for replicate identifiers
    values_to = "counts"            # Name of the new column for the counts
  )

# Add a condition column based on the replicate
GSE73318_HT_29_long_data <- GSE73318_HT_29_long_data %>%
  dplyr::mutate(condition = ifelse(replicate %in% c("GSM1890706", "GSM1890707", "GSM1890708"), "DMSO", "JQ1")) 

# Aggregate the replicates for each condition
GSE73318_HT_29_norm_TX_aggregated_data_avg_counts <- GSE73318_HT_29_long_data %>%
  group_by(ensembl_transcript_id_version, condition, Normalized_MFE, Specific_heat) %>%
  summarise(
    avg_counts = mean(counts, na.rm = TRUE),
    .groups = 'drop'
  )

# Define the 75th percentile of the entire distribution of MFE values for the GSE73318_HT_29 data
GSE73318_HT_29_MFE_all_TX_75_percentile <- quantile(GSE73318_HT_29_norm_TX_aggregated_data_avg_counts$Normalized_MFE, 0.75)

# Identify all the transcripts with MFE values above the 75th percentile
GSE73318_HT_29_high_MFE_TX_total <- dplyr::filter(GSE73318_HT_29_norm_TX_counts_MFE_df, Normalized_MFE > GSE73318_HT_29_MFE_all_TX_75_percentile)

# Fraction of total high MFE transcript counts in control and drug-treated groups
GSE73318_HT_29_control_total_counts <- dplyr::filter(GSE73318_HT_29_norm_TX_aggregated_data_avg_counts, condition == "DMSO") %>%
  dplyr::summarise(total_counts = sum(avg_counts, na.rm = TRUE))

GSE73318_HT_29_control_high_MFE_TX_counts <- dplyr::filter(GSE73318_HT_29_norm_TX_aggregated_data_avg_counts, condition == "DMSO") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE73318_HT_29_high_MFE_TX_total$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE73318_HT_29_control_high_MFE_TX_counts_fraction <- GSE73318_HT_29_control_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE73318_HT_29_control_total_counts$total_counts
print(GSE73318_HT_29_control_high_MFE_TX_counts_fraction) # This value goes in the summary table

GSE73318_HT_29_HT_29_total_counts <- dplyr::filter(GSE73318_HT_29_norm_TX_aggregated_data_avg_counts, condition == "JQ1") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE73318_HT_29_HT_29_high_MFE_TX_counts <- dplyr::filter(GSE73318_HT_29_norm_TX_aggregated_data_avg_counts, condition == "JQ1") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE73318_HT_29_high_MFE_TX_total$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE73318_HT_29_HT_29_high_MFE_TX_counts_fraction <- GSE73318_HT_29_HT_29_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE73318_HT_29_HT_29_total_counts$total_counts
print(GSE73318_HT_29_HT_29_high_MFE_TX_counts_fraction) # This value goes in the summary table

# Calculate proportions and apply two-proportion Z-test
p_control <- GSE73318_HT_29_control_high_MFE_TX_counts_fraction
p_HT_29 <- GSE73318_HT_29_HT_29_high_MFE_TX_counts_fraction

# Pooled proportion
P_pool <- (GSE73318_HT_29_control_high_MFE_TX_counts$total_counts_high_MFE_TX + GSE73318_HT_29_HT_29_high_MFE_TX_counts$total_counts_high_MFE_TX) /
  (GSE73318_HT_29_control_total_counts$total_counts + GSE73318_HT_29_HT_29_total_counts$total_counts)

# Z-test statistic for two proportions
if (GSE73318_HT_29_control_total_counts$total_counts > 0 & GSE73318_HT_29_HT_29_total_counts$total_counts > 0) {
  Z <- (p_control - p_HT_29) / sqrt(P_pool * (1 - P_pool) * (1/GSE73318_HT_29_control_total_counts$total_counts + 1/GSE73318_HT_29_HT_29_total_counts$total_counts))
  GSE73318_HT_29_z_test_counts_75_p_value <- 2 * (1 - pnorm(abs(Z)))
} else {
  Z <- NA
  GSE73318_HT_29_z_test_counts_75_p_value <- NA
}

# Calculate the p-value for the Z-test
GSE73318_HT_29_z_test_counts_75_p_value <- 2 * (1 - pnorm(abs(Z)))

# Output the results
cat("Two-proportion Z-test statistic:", Z, "\n")
cat("Two-proportion Z-test p-value:", GSE73318_HT_29_z_test_counts_75_p_value, "\n")

# Output the results of fractions and net change
cat("GSE73318_HT_29 control high MFE TX as fraction of total counts:", GSE73318_HT_29_control_high_MFE_TX_counts_fraction, "\n")
cat("GSE73318_HT_29 HT_29 high MFE TX as fraction of total counts:", GSE73318_HT_29_HT_29_high_MFE_TX_counts_fraction, "\n")
cat("GSE73318_HT_29 net change counts high MFE TX drug vs control:", GSE73318_HT_29_HT_29_high_MFE_TX_counts_fraction - GSE73318_HT_29_control_high_MFE_TX_counts_fraction, "\n")





