# Permutation test MFE changes
# Combine the data into a single data frame with labels
upregulated <- data.frame(MFE = MFE_res_GSE73318_COLO_205_UP$Normalized_MFE, Group = "Up")
downregulated <- data.frame(MFE = MFE_res_GSE73318_COLO_205_DOWN$Normalized_MFE, Group = "Down")
combined_data <- bind_rows(upregulated, downregulated)

# Observed difference in means
GSE73318_COLO_205_observed_diff <- mean(MFE_res_GSE73318_COLO_205_UP$Normalized_MFE, na.rm = TRUE) - mean(MFE_res_GSE73318_COLO_205_DOWN$Normalized_MFE, na.rm = TRUE)

# Number of permutations
n_permutations <- 10000

# Initialize a vector to store the permuted differences
GSE73318_COLO_205_permuted_diffs <- numeric(n_permutations)

# Permutation test
set.seed(123)  # Set seed for reproducibility
for (i in 1:n_permutations) {
  # Permute the Group labels
  combined_data <- combined_data %>%
    mutate(Permuted_Group = sample(Group))
  
  permuted_up_mean <- mean(combined_data$MFE[combined_data$Permuted_Group == "Up"], na.rm = TRUE)
  permuted_down_mean <- mean(combined_data$MFE[combined_data$Permuted_Group == "Down"], na.rm = TRUE)
  
  # Calculate the difference in means for the permuted groups
  GSE73318_COLO_205_permuted_diffs[i] <- permuted_up_mean - permuted_down_mean
}

# Calculate the p-value
GSE73318_COLO_205_p_value <- (sum(abs(GSE73318_COLO_205_permuted_diffs) >= abs(GSE73318_COLO_205_observed_diff)) + 1) / (n_permutations + 1)

# Output the results
cat("Observed difference in GSE73318_COLO_205 means MFE_UP - MFE_DOWN:", GSE73318_COLO_205_observed_diff, "\n")
cat("GSE73318_COLO_205 P-value from permutation test:", GSE73318_COLO_205_p_value, "\n")













## GSE73318 High MFE TX fraction changes
# Determine whether within the differentially expressed genes there is a significant up-regulation of high MFE transcripts:
# Define high MFE transcripts by taking the 75th percentile of the combined MFE distributions of control and drug-treated samples.
# Count the number of transcripts in the significantly up- and down-regulated genes that have MFE values above this threshold.
# Perform a Fisher’s exact test to compare the proportions of high MFE transcripts between the two groups.


# Analysis GSE73318
# Extract the normalized count data
# The minimal pre-filtering has already been done in the previous steps
GSE73318_norm_TX_counts <- counts(dds_GSE73318, normalized=TRUE) # This object is already a matrix
GSE73318_norm_TX_counts_df <- as.data.frame(GSE73318_norm_TX_counts)
# Convert row names to column
GSE73318_norm_TX_counts_df$ensembl_transcript_id <- rownames(GSE73318_norm_TX_counts_df)
# Remove row names
rownames(GSE73318_norm_TX_counts_df) <- NULL

# Move ensembl_transcript_id column to the first position
GSE73318_norm_TX_counts_df <- GSE73318_norm_TX_counts_df[, c("ensembl_transcript_id", setdiff(names(GSE73318_norm_TX_counts_df), "ensembl_transcript_id"))]

# Remove everything after the dot (including the dot itself) in the ensembl_transcript_id column
GSE73318_norm_TX_counts_df$ensembl_transcript_id <- sub("\\..*", "", GSE73318_norm_TX_counts_df$ensembl_transcript_id)

# Join the counts with the Table_ANNOTATED containing MFE values and heat capacity values
GSE73318_norm_TX_counts_MFE_df <- dplyr::inner_join(Table_ANNOTATED, GSE73318_norm_TX_counts_df, by="ensembl_transcript_id") %>%
  dplyr::select(ensembl_transcript_id_version, ensembl_transcript_id, ensembl_gene_id, external_gene_name, transcript_is_canonical, Transcript_length, 
                GSM1890712, GSM1890713, GSM1890714, GSM1890715, GSM1890716, GSM1890717,
                Normalized_MFE, Temperature, Specific_heat)







# GSE73318_COLO_205
# Convert from wide to long format
GSE73318_COLO_205_norm_TX_counts_MFE_df <- GSE73318_norm_TX_counts_MFE_df %>%
  dplyr::select(ensembl_transcript_id_version, ensembl_transcript_id, ensembl_gene_id, external_gene_name, transcript_is_canonical, Transcript_length, 
                GSM1890712, GSM1890713, GSM1890714, GSM1890715, GSM1890716, GSM1890717, 
                Normalized_MFE, Temperature, Specific_heat) %>%
  dplyr::filter(ensembl_transcript_id %in% MFE_res_GSE73318_COLO_205$ensembl_transcript_id) 

# Identify the 75th percentile of the combined MFE distributions of control and drug-treated samples
quantile_075_GSE73318_COLO_205_norm_TX_counts_MFE_df <- quantile(GSE73318_COLO_205_norm_TX_counts_MFE_df$Normalized_MFE, probs = c(0.75))

# Select all the transcripts with Normalized_MFE values above the 75th percentile
GSE73318_COLO_205_high_MFE_TX <- dplyr::filter(GSE73318_COLO_205_norm_TX_counts_MFE_df, Normalized_MFE > quantile_075_GSE73318_COLO_205_norm_TX_counts_MFE_df)

# Count the number of transcripts in the significantly up- and down-regulated pools that have MFE values above this threshold.
GSE73318_COLO_205_high_MFE_TX_in_UP <- dplyr::filter(MFE_res_GSE73318_COLO_205_UP, ensembl_transcript_id_version %in% GSE73318_COLO_205_high_MFE_TX$ensembl_transcript_id_version)
GSE73318_COLO_205_high_MFE_TX_in_DOWN <- dplyr::filter(MFE_res_GSE73318_COLO_205_DOWN, ensembl_transcript_id_version %in% GSE73318_COLO_205_high_MFE_TX$ensembl_transcript_id_version)

# Calculate the proportions of high MFE transcripts in UP and DOWN-regulated groups
GSE73318_COLO_205_total_UP <- nrow(MFE_res_GSE73318_COLO_205_UP)
GSE73318_COLO_205_total_DOWN <- nrow(MFE_res_GSE73318_COLO_205_DOWN)
GSE73318_COLO_205_count_high_MFE_UP <- nrow(GSE73318_COLO_205_high_MFE_TX_in_UP)
GSE73318_COLO_205_count_high_MFE_DOWN <- nrow(GSE73318_COLO_205_high_MFE_TX_in_DOWN)

# Proportions of high MFE in each group
p_UP <- GSE73318_COLO_205_count_high_MFE_UP / GSE73318_COLO_205_total_UP
p_DOWN <- GSE73318_COLO_205_count_high_MFE_DOWN / GSE73318_COLO_205_total_DOWN

# Pooled proportion
P_pool <- (GSE73318_COLO_205_count_high_MFE_UP + GSE73318_COLO_205_count_high_MFE_DOWN) /
  (GSE73318_COLO_205_total_UP + GSE73318_COLO_205_total_DOWN)

# Two-proportion Z-test statistic
Z <- (p_UP - p_DOWN) / sqrt(P_pool * (1 - P_pool) * (1/GSE73318_COLO_205_total_UP + 1/GSE73318_COLO_205_total_DOWN))

# Calculate the p-value for the Z-test
GSE73318_COLO_205_z_test_MFE_p_value <- 2 * (1 - pnorm(abs(Z)))

# Output the results
cat("Two-proportion Z-test statistic:", Z, "\n")
cat("Two-proportion Z-test p-value:", GSE73318_COLO_205_z_test_MFE_p_value, "\n")

# Look at the fractions
GSE73318_COLO_205_high_MFE_in_UP_fraction <- GSE73318_COLO_205_count_high_MFE_UP / GSE73318_COLO_205_total_UP
GSE73318_COLO_205_high_MFE_in_DOWN_fraction <- GSE73318_COLO_205_count_high_MFE_DOWN / GSE73318_COLO_205_total_DOWN

# Output the fractions
cat("Fraction of GSE73318_COLO_205 high MFE TX in UP-regulated genes:", GSE73318_COLO_205_high_MFE_in_UP_fraction, "\n")
cat("Fraction of GSE73318_COLO_205 high MFE TX in DOWN-regulated genes:", GSE73318_COLO_205_high_MFE_in_DOWN_fraction, "\n")
cat("Mean of GSE73318_COLO_205 high MFE TX in UP-regulated genes:", mean(GSE73318_COLO_205_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mean of GSE73318_COLO_205 high MFE TX in DOWN-regulated genes:", mean(GSE73318_COLO_205_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")
cat("Mode of GSE73318_COLO_205 high MFE TX in UP-regulated genes:", calculate_mode(GSE73318_COLO_205_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mode of GSE73318_COLO_205 high MFE TX in DOWN-regulated genes:", calculate_mode(GSE73318_COLO_205_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")





