GSE73318_HCT_15_HCT_15_low_MFE_TX_counts <- dplyr::filter(GSE73318_HCT_15_norm_TX_aggregated_data_avg_counts, condition == "JQ1") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE73318_HCT_15_low_MFE_TX_total$ensembl_transcript_id_version) %>%
