## GSE73318_HCT_15 gene-level expression changes ####

# 1. Download from GREIN the row counts at the gene level 
# 2. Normalize the counts with DESeq
# 3. Log2 transform the counts
Counts_GSE73318_HCT_15_gene <- read.delim("path_to/GSE73318/GSE73318_GeneLevel_Raw_data.csv", sep = ",", header = T, stringsAsFactors = F)
# Select only the columns of the counts that are necessary for the analysis
Counts_GSE73318_HCT_15_gene <- dplyr::select(Counts_GSE73318_HCT_15_gene, c("X", "gene_symbol", "GSM1890718", "GSM1890719", "GSM1890720", "GSM1890721", "GSM1890722", "GSM1890723"))

# In order to use the gene symbols as raw names, I need to remove the duplicates - I merge the transcript-level counts of the same gene
Counts_GSE73318_HCT_15_gene <- Counts_GSE73318_HCT_15_gene %>% group_by(gene_symbol) %>%
  summarise (GSM1890718 = sum(GSM1890718),
             GSM1890719 = sum(GSM1890719),
             GSM1890720 = sum(GSM1890720),
             GSM1890721 = sum(GSM1890721),
             GSM1890722 = sum(GSM1890722),
             GSM1890723 = sum(GSM1890723))

Counts_GSE73318_HCT_15_gene <- Counts_GSE73318_HCT_15_gene %>% remove_rownames %>% column_to_rownames(var="gene_symbol") # Convert first column into row names in data frame
Counts_GSE73318_HCT_15_gene <- floor(Counts_GSE73318_HCT_15_gene)

Counts_GSE73318_HCT_15_gene <- as.matrix(Counts_GSE73318_HCT_15_gene)


# Access the metadata table
Expdata_GSE73318_HCT_15_gene <- dplyr::filter(Expdata_GSE73318, geo_accession %in% c("GSM1890718", "GSM1890719", "GSM1890720", "GSM1890721", "GSM1890722", "GSM1890723"))

# Check whether the gene-level counts and the metadata table have the same selected samples
all(rownames(Expdata_GSE73318_HCT_15_gene) %in% colnames(Counts_GSE73318_HCT_15_gene))
all(colnames(Counts_GSE73318_HCT_15_gene) %in% rownames(Expdata_GSE73318_HCT_15_gene))

# Construct a DESeqDataSet:
dds_GSE73318_HCT_15_gene <- DESeqDataSetFromMatrix(countData = Counts_GSE73318_HCT_15_gene,
                                                    colData = Expdata_GSE73318_HCT_15_gene,
                                                    design = ~ condition)
dds_GSE73318_HCT_15_gene

# Perform differential expression analysis with DESeq2
dds_GSE73318_HCT_15_gene <- DESeq(dds_GSE73318_HCT_15_gene)

# Check the global change of different proliferation gene sets
dds_proliferation_GSE73318_HCT_15_gene <- dds_GSE73318_HCT_15_gene

# DIFFERENTIAL EXPRESSION ANALYSIS
res_GSE73318_HCT_15_gene <- results(dds_proliferation_GSE73318_HCT_15_gene, contrast=c("condition","HCT_15_JQ1","HCT_15_DMSO")) # to specify the samples to contrast
res_GSE73318_HCT_15_gene

# Gene names are as raw names. Transform to first column for the filtering
res_GSE73318_HCT_15_gene_df <- as.data.frame(res_GSE73318_HCT_15_gene)
res_GSE73318_HCT_15_gene_df <- dplyr::filter(res_GSE73318_HCT_15_gene_df, !is.na(padj)) # Remove NA
res_GSE73318_HCT_15_gene_df <- tibble::rownames_to_column(res_GSE73318_HCT_15_gene_df, "Gene_symbol")


















