Mean_MFE_res_GSE73318_COLO_320_DOWN <- mean(MFE_res_GSE73318_COLO_320_DOWN$Normalized_MFE, na.rm = TRUE)

TTEST_MFE_res_GSE73318_COLO_320_all_UP_vs_DOWN <- t.test(MFE_res_GSE73318_COLO_320_DOWN$Normalized_MFE, MFE_res_GSE73318_COLO_320_UP$Normalized_MFE, paired=FALSE)
print(TTEST_MFE_res_GSE73318_COLO_320_all_UP_vs_DOWN)

# Add K-S test to look at the differences between the up-regukated and down-regulated genes
ks_test_res_GSE73318_COLO_320_all_UP_vs_DOWN <- ks.test(MFE_res_GSE73318_COLO_320_DOWN$Normalized_MFE, MFE_res_GSE73318_COLO_320_UP$Normalized_MFE)
print(ks_test_res_GSE73318_COLO_320_all_UP_vs_DOWN)


