# Values above 0.75 quantile
ks_test_MFE_075_above <- ks.test(MFE_res_GSE73318_COLO_320_UP$Normalized_MFE[MFE_res_GSE73318_COLO_320_UP$Normalized_MFE >= quantile_075_MFE_res_GSE73318_COLO_320_UP],
                                 MFE_res_GSE73318_COLO_320_DOWN$Normalized_MFE[MFE_res_GSE73318_COLO_320_DOWN$Normalized_MFE >= quantile_075_MFE_res_GSE73318_COLO_320_DOWN])
