# Permutation test MFE changes
# Combine the data into a single data frame with labels
upregulated <- data.frame(MFE = MFE_res_GSE63582_UP$Normalized_MFE, Group = "Up")
downregulated <- data.frame(MFE = MFE_res_GSE63582_DOWN$Normalized_MFE, Group = "Down")
combined_data <- bind_rows(upregulated, downregulated)

# Observed difference in means
GSE63582_observed_diff <- mean(MFE_res_GSE63582_UP$Normalized_MFE, na.rm = TRUE) - mean(MFE_res_GSE63582_DOWN$Normalized_MFE, na.rm = TRUE)

# Number of permutations
n_permutations <- 10000

# Initialize a vector to store the permuted differences
GSE63582_permuted_diffs <- numeric(n_permutations)

# Permutation test
set.seed(123)  # Set seed for reproducibility
for (i in 1:n_permutations) {
  # Permute the Group labels
  combined_data <- combined_data %>%
    mutate(Permuted_Group = sample(Group))
  
  permuted_up_mean <- mean(combined_data$MFE[combined_data$Permuted_Group == "Up"], na.rm = TRUE)
  permuted_down_mean <- mean(combined_data$MFE[combined_data$Permuted_Group == "Down"], na.rm = TRUE)
  
  # Calculate the difference in means for the permuted groups
  GSE63582_permuted_diffs[i] <- permuted_up_mean - permuted_down_mean
}

# Calculate the p-value
GSE63582_p_value <- (sum(abs(GSE63582_permuted_diffs) >= abs(GSE63582_observed_diff)) + 1) / (n_permutations + 1)

# Output the results
cat("Observed difference in GSE63582 means MFE_UP - MFE_DOWN:", GSE63582_observed_diff, "\n")
cat("GSE63582 P-value from permutation test:", GSE63582_p_value, "\n")















## GSE63582 High MFE TX fraction changes
# Determine whether within the differentially expressed genes there is a significant up-regulation of high MFE transcripts:
# Define high MFE transcripts by taking the 75th percentile of the combined MFE distributions of control and drug-treated samples.
# Count the number of transcripts in the significantly up- and down-regulated genes that have MFE values above this threshold.
# Perform a Fisher’s exact test to compare the proportions of high MFE transcripts between the two groups.


# Analysis GSE63582
# Extract the normalized count data
# The minimal pre-filtering has already been done in the previous steps
GSE63582_norm_TX_counts <- counts(dds_GSE63582, normalized=TRUE) # This object is already a matrix
GSE63582_norm_TX_counts_df <- as.data.frame(GSE63582_norm_TX_counts)
# Convert row names to column
GSE63582_norm_TX_counts_df$ensembl_transcript_id <- rownames(GSE63582_norm_TX_counts_df)
# Remove row names
rownames(GSE63582_norm_TX_counts_df) <- NULL

# Move ensembl_transcript_id column to the first position
GSE63582_norm_TX_counts_df <- GSE63582_norm_TX_counts_df[, c("ensembl_transcript_id", setdiff(names(GSE63582_norm_TX_counts_df), "ensembl_transcript_id"))]

# Remove everything after the dot (including the dot itself) in the ensembl_transcript_id column
GSE63582_norm_TX_counts_df$ensembl_transcript_id <- sub("\\..*", "", GSE63582_norm_TX_counts_df$ensembl_transcript_id)

# Join the counts with the Table_ANNOTATED containing MFE values and heat capacity values
GSE63582_norm_TX_counts_MFE_df <- dplyr::inner_join(Table_ANNOTATED, GSE63582_norm_TX_counts_df, by="ensembl_transcript_id") %>%
  dplyr::select(ensembl_transcript_id_version, ensembl_transcript_id, ensembl_gene_id, external_gene_name, transcript_is_canonical, Transcript_length, 
                GSM1553154, GSM1553155, GSM1553160, GSM1553161,
                Normalized_MFE, Temperature, Specific_heat)







# GSE63582
# Convert from wide to long format
GSE63582_norm_TX_counts_MFE_df <- GSE63582_norm_TX_counts_MFE_df %>%
  dplyr::select(ensembl_transcript_id_version, ensembl_transcript_id, ensembl_gene_id, external_gene_name, transcript_is_canonical, Transcript_length, 
                GSM1553154, GSM1553155, GSM1553160, GSM1553161, 
                Normalized_MFE, Temperature, Specific_heat) %>%
  dplyr::filter(ensembl_transcript_id %in% MFE_res_GSE63582$ensembl_transcript_id) 

# Identify the 75th percentile of the combined MFE distributions of control and drug-treated samples
quantile_075_GSE63582_norm_TX_counts_MFE_df <- quantile(GSE63582_norm_TX_counts_MFE_df$Normalized_MFE, probs = c(0.75))

# Select all the transcripts with Normalized_MFE values above the 75th percentile
GSE63582_high_MFE_TX <- dplyr::filter(GSE63582_norm_TX_counts_MFE_df, Normalized_MFE > quantile_075_GSE63582_norm_TX_counts_MFE_df)

# Count the number of transcripts in the significantly up- and down-regulated pools that have MFE values above this threshold.
GSE63582_high_MFE_TX_in_UP <- dplyr::filter(MFE_res_GSE63582_UP, ensembl_transcript_id_version %in% GSE63582_high_MFE_TX$ensembl_transcript_id_version)
GSE63582_high_MFE_TX_in_DOWN <- dplyr::filter(MFE_res_GSE63582_DOWN, ensembl_transcript_id_version %in% GSE63582_high_MFE_TX$ensembl_transcript_id_version)

# Calculate the proportions of high MFE transcripts in UP and DOWN-regulated groups
GSE63582_total_UP <- nrow(MFE_res_GSE63582_UP)
GSE63582_total_DOWN <- nrow(MFE_res_GSE63582_DOWN)
GSE63582_count_high_MFE_UP <- nrow(GSE63582_high_MFE_TX_in_UP)
GSE63582_count_high_MFE_DOWN <- nrow(GSE63582_high_MFE_TX_in_DOWN)

# Proportions of high MFE in each group
p_UP <- GSE63582_count_high_MFE_UP / GSE63582_total_UP
p_DOWN <- GSE63582_count_high_MFE_DOWN / GSE63582_total_DOWN

# Pooled proportion
P_pool <- (GSE63582_count_high_MFE_UP + GSE63582_count_high_MFE_DOWN) /
  (GSE63582_total_UP + GSE63582_total_DOWN)

# Two-proportion Z-test statistic
Z <- (p_UP - p_DOWN) / sqrt(P_pool * (1 - P_pool) * (1/GSE63582_total_UP + 1/GSE63582_total_DOWN))

# Calculate the p-value for the Z-test
GSE63582_z_test_MFE_p_value <- 2 * (1 - pnorm(abs(Z)))

# Output the results
cat("Two-proportion Z-test statistic:", Z, "\n")
cat("Two-proportion Z-test p-value:", GSE63582_z_test_MFE_p_value, "\n")

# Look at the fractions
GSE63582_high_MFE_in_UP_fraction <- GSE63582_count_high_MFE_UP / GSE63582_total_UP
GSE63582_high_MFE_in_DOWN_fraction <- GSE63582_count_high_MFE_DOWN / GSE63582_total_DOWN

# Output the fractions
cat("Fraction of GSE63582 high MFE TX in UP-regulated genes:", GSE63582_high_MFE_in_UP_fraction, "\n")
cat("Fraction of GSE63582 high MFE TX in DOWN-regulated genes:", GSE63582_high_MFE_in_DOWN_fraction, "\n")
cat("Mean of GSE63582 high MFE TX in UP-regulated genes:", mean(GSE63582_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mean of GSE63582 high MFE TX in DOWN-regulated genes:", mean(GSE63582_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")
cat("Mode of GSE63582 high MFE TX in UP-regulated genes:", calculate_mode(GSE63582_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mode of GSE63582 high MFE TX in DOWN-regulated genes:", calculate_mode(GSE63582_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")





# Show data as violin plot
# Add a new column to indicate if the value is above the 75th percentile
MFE_res_GSE63582$above_quantile_075 <- MFE_res_GSE63582$Normalized_MFE > quantile_075_GSE63582_norm_TX_counts_MFE_df

# Generate violin plot with conditional jitter coloring
Plot_MFE_GSE63582 <- ggplot(MFE_res_GSE63582, aes(x = factor(log2FoldChange > 0), y = Normalized_MFE)) +
  geom_violin(fill = "white", size = 1.5) +
  geom_jitter(aes(color = above_quantile_075), width = 0.1, size = 1, alpha = 1) +
  scale_color_manual(values = c("FALSE" = "black", "TRUE" = "dodgerblue3")) +
