GSE126779_DU145_DU145_low_MFE_TX_counts_fraction <- GSE126779_DU145_DU145_low_MFE_TX_counts$total_counts_low_MFE_TX / GSE126779_DU145_DU145_total_counts$total_counts
print(GSE126779_DU145_DU145_low_MFE_TX_counts_fraction) # This value goes in the summary table

# Calculate proportions
p_control <- GSE126779_DU145_control_low_MFE_TX_counts_fraction
p_DU145 <- GSE126779_DU145_DU145_low_MFE_TX_counts_fraction

# Pooled proportion (weighted average of proportions)
P_pool <- (GSE126779_DU145_control_low_MFE_TX_counts$total_counts_low_MFE_TX + GSE126779_DU145_DU145_low_MFE_TX_counts$total_counts_low_MFE_TX) /
  (GSE126779_DU145_control_total_counts$total_counts + GSE126779_DU145_DU145_total_counts$total_counts)

# Calculate the variance for the two-proportion Z-test
var_control <- p_control * (1 - p_control) / GSE126779_DU145_control_total_counts$total_counts
var_DU145 <- p_DU145 * (1 - p_DU145) / GSE126779_DU145_DU145_total_counts$total_counts

# Combined variance for two proportions Z-test
P_pool_variance <- P_pool * (1 - P_pool) * (1 / GSE126779_DU145_control_total_counts$total_counts + 1 / GSE126779_DU145_DU145_total_counts$total_counts)

# Z-test statistic for two proportions
Z <- (p_control - p_DU145) / sqrt(P_pool_variance)

# Calculate the p-value for the Z-test (two-tailed)
GSE126779_DU145_z_test_counts_25_p_value <- 2 * (1 - pnorm(abs(Z)))

# Output the results
cat("Two-proportion Z-test statistic:", Z, "\n")
cat("Two-proportion Z-test p-value:", GSE126779_DU145_z_test_counts_25_p_value, "\n")

# Output the results of fractions and net change
cat("GSE126779_DU145 control low MFE TX as fraction of total counts:", GSE126779_DU145_control_low_MFE_TX_counts_fraction, "\n")
cat("GSE126779_DU145 DU145 low MFE TX as fraction of total counts:", GSE126779_DU145_DU145_low_MFE_TX_counts_fraction, "\n")
cat("GSE126779_DU145 net change counts low MFE TX drug vs control:", GSE126779_DU145_DU145_low_MFE_TX_counts_fraction - GSE126779_DU145_control_low_MFE_TX_counts_fraction, "\n")















