# Permutation test MFE changes
# Combine the data into a single data frame with labels
upregulated <- data.frame(MFE = MFE_res_GSE126779_PC3_UP$Normalized_MFE, Group = "Up")
downregulated <- data.frame(MFE = MFE_res_GSE126779_PC3_DOWN$Normalized_MFE, Group = "Down")
combined_data <- bind_rows(upregulated, downregulated)

# Observed difference in means
GSE126779_PC3_observed_diff <- mean(MFE_res_GSE126779_PC3_UP$Normalized_MFE, na.rm = TRUE) - mean(MFE_res_GSE126779_PC3_DOWN$Normalized_MFE, na.rm = TRUE)

# Number of permutations
n_permutations <- 10000

# Initialize a vector to store the permuted differences
GSE126779_PC3_permuted_diffs <- numeric(n_permutations)

# Permutation test
set.seed(123)  # Set seed for reproducibility
for (i in 1:n_permutations) {
  # Permute the Group labels
  combined_data <- combined_data %>%
    mutate(Permuted_Group = sample(Group))
  
  permuted_up_mean <- mean(combined_data$MFE[combined_data$Permuted_Group == "Up"], na.rm = TRUE)
  permuted_down_mean <- mean(combined_data$MFE[combined_data$Permuted_Group == "Down"], na.rm = TRUE)
  
  # Calculate the difference in means for the permuted groups
  GSE126779_PC3_permuted_diffs[i] <- permuted_up_mean - permuted_down_mean
}

# Calculate the p-value
GSE126779_PC3_p_value <- (sum(abs(GSE126779_PC3_permuted_diffs) >= abs(GSE126779_PC3_observed_diff)) + 1) / (n_permutations + 1)

# Output the results
cat("Observed difference in GSE126779_PC3 means MFE_UP - MFE_DOWN:", GSE126779_PC3_observed_diff, "\n")
cat("GSE126779_PC3 P-value from permutation test:", GSE126779_PC3_p_value, "\n")















## GSE126779 High MFE TX fraction changes
# Determine whether within the differentially expressed genes there is a significant up-regulation of high MFE transcripts:
# Define high MFE transcripts by taking the 75th percentile of the combined MFE distributions of control and drug-treated samples.
# Count the number of transcripts in the significantly up- and down-regulated genes that have MFE values above this threshold.
# Perform a Fisher’s exact test to compare the proportions of high MFE transcripts between the two groups.


# Analysis GSE126779
# Extract the normalized count data
# The minimal pre-filtering has already been done in the previous steps
GSE126779_norm_TX_counts <- counts(dds_GSE126779, normalized=TRUE) # This object is already a matrix
GSE126779_norm_TX_counts_df <- as.data.frame(GSE126779_norm_TX_counts)
# Convert row names to column
GSE126779_norm_TX_counts_df$ensembl_transcript_id <- rownames(GSE126779_norm_TX_counts_df)
# Remove row names
rownames(GSE126779_norm_TX_counts_df) <- NULL

# Move ensembl_transcript_id column to the first position
GSE126779_norm_TX_counts_df <- GSE126779_norm_TX_counts_df[, c("ensembl_transcript_id", setdiff(names(GSE126779_norm_TX_counts_df), "ensembl_transcript_id"))]

# Remove everything after the dot (including the dot itself) in the ensembl_transcript_id column
GSE126779_norm_TX_counts_df$ensembl_transcript_id <- sub("\\..*", "", GSE126779_norm_TX_counts_df$ensembl_transcript_id)

# Join the counts with the Table_ANNOTATED containing MFE values and heat capacity values
GSE126779_norm_TX_counts_MFE_df <- dplyr::inner_join(Table_ANNOTATED, GSE126779_norm_TX_counts_df, by="ensembl_transcript_id") %>%
  dplyr::select(ensembl_transcript_id_version, ensembl_transcript_id, ensembl_gene_id, external_gene_name, transcript_is_canonical, Transcript_length, 
                GSM3612783, GSM3612784, GSM3612786, GSM3612787,
                Normalized_MFE, Temperature, Specific_heat)







# GSE126779_PC3
# Convert from wide to long format
GSE126779_PC3_norm_TX_counts_MFE_df <- GSE126779_norm_TX_counts_MFE_df %>%
  dplyr::select(ensembl_transcript_id_version, ensembl_transcript_id, ensembl_gene_id, external_gene_name, transcript_is_canonical, Transcript_length, 
                GSM3612783, GSM3612784, GSM3612786, GSM3612787,
                Normalized_MFE, Temperature, Specific_heat) %>%
  dplyr::filter(ensembl_transcript_id %in% MFE_res_GSE126779_PC3$ensembl_transcript_id) 

# Identify the 75th percentile of the combined MFE distributions of control and drug-treated samples
quantile_075_GSE126779_PC3_norm_TX_counts_MFE_df <- quantile(GSE126779_PC3_norm_TX_counts_MFE_df$Normalized_MFE, probs = c(0.75))

# Select all the transcripts with Normalized_MFE values above the 75th percentile
GSE126779_PC3_high_MFE_TX <- dplyr::filter(GSE126779_PC3_norm_TX_counts_MFE_df, Normalized_MFE > quantile_075_GSE126779_PC3_norm_TX_counts_MFE_df)

# Count the number of transcripts in the significantly up- and down-regulated pools that have MFE values above this threshold.
GSE126779_PC3_high_MFE_TX_in_UP <- dplyr::filter(MFE_res_GSE126779_PC3_UP, ensembl_transcript_id_version %in% GSE126779_PC3_high_MFE_TX$ensembl_transcript_id_version)
GSE126779_PC3_high_MFE_TX_in_DOWN <- dplyr::filter(MFE_res_GSE126779_PC3_DOWN, ensembl_transcript_id_version %in% GSE126779_PC3_high_MFE_TX$ensembl_transcript_id_version)

# Calculate the proportions of high MFE transcripts in UP and DOWN-regulated groups
GSE126779_PC3_total_UP <- nrow(MFE_res_GSE126779_PC3_UP)
GSE126779_PC3_total_DOWN <- nrow(MFE_res_GSE126779_PC3_DOWN)
GSE126779_PC3_count_high_MFE_UP <- nrow(GSE126779_PC3_high_MFE_TX_in_UP)
GSE126779_PC3_count_high_MFE_DOWN <- nrow(GSE126779_PC3_high_MFE_TX_in_DOWN)

# Proportions of high MFE in each group
p_UP <- GSE126779_PC3_count_high_MFE_UP / GSE126779_PC3_total_UP
p_DOWN <- GSE126779_PC3_count_high_MFE_DOWN / GSE126779_PC3_total_DOWN

# Pooled proportion
P_pool <- (GSE126779_PC3_count_high_MFE_UP + GSE126779_PC3_count_high_MFE_DOWN) /
  (GSE126779_PC3_total_UP + GSE126779_PC3_total_DOWN)

# Two-proportion Z-test statistic
Z <- (p_UP - p_DOWN) / sqrt(P_pool * (1 - P_pool) * (1/GSE126779_PC3_total_UP + 1/GSE126779_PC3_total_DOWN))

# Calculate the p-value for the Z-test
GSE126779_PC3_z_test_MFE_p_value <- 2 * (1 - pnorm(abs(Z)))

# Output the results
cat("Two-proportion Z-test statistic:", Z, "\n")
cat("Two-proportion Z-test p-value:", GSE126779_PC3_z_test_MFE_p_value, "\n")

# Look at the fractions
GSE126779_PC3_high_MFE_in_UP_fraction <- GSE126779_PC3_count_high_MFE_UP / GSE126779_PC3_total_UP
GSE126779_PC3_high_MFE_in_DOWN_fraction <- GSE126779_PC3_count_high_MFE_DOWN / GSE126779_PC3_total_DOWN

# Output the fractions
cat("Fraction of GSE126779_PC3 high MFE TX in UP-regulated genes:", GSE126779_PC3_high_MFE_in_UP_fraction, "\n")
cat("Fraction of GSE126779_PC3 high MFE TX in DOWN-regulated genes:", GSE126779_PC3_high_MFE_in_DOWN_fraction, "\n")
cat("Mean of GSE126779_PC3 high MFE TX in UP-regulated genes:", mean(GSE126779_PC3_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mean of GSE126779_PC3 high MFE TX in DOWN-regulated genes:", mean(GSE126779_PC3_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")
cat("Mode of GSE126779_PC3 high MFE TX in UP-regulated genes:", calculate_mode(GSE126779_PC3_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mode of GSE126779_PC3 high MFE TX in DOWN-regulated genes:", calculate_mode(GSE126779_PC3_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")





# Show data as violin plot
# Add a new column to indicate if the value is above the 75th percentile
MFE_res_GSE126779_PC3$above_quantile_075 <- MFE_res_GSE126779_PC3$Normalized_MFE > quantile_075_GSE126779_PC3_norm_TX_counts_MFE_df

# Generate violin plot with conditional jitter coloring
Plot_MFE_GSE126779 <- ggplot(MFE_res_GSE126779_PC3, aes(x = factor(log2FoldChange > 0), y = Normalized_MFE)) +
  geom_violin(fill = "white", size = 1.5) +
  geom_jitter(aes(color = above_quantile_075), width = 0.1, size = 1, alpha = 1) +
  scale_color_manual(values = c("FALSE" = "black", "TRUE" = "dodgerblue3")) +
  theme_classic() +
  ylim(-0.6, 0) +
  theme(
    legend.position = "none", 
    axis.title = element_text(size = 20), 
    plot.title = element_text(size = 10),
    axis.text.x = element_text(size = 16, color = "black")
  ) +
  geom_vline(xintercept = 0, linewidth = 0.3) +
  labs(
    y = "Normalized_MFE", 
    x = NULL, 
    title = "GSE126779_PC3_Log2_FC_adj.P<0.05"
  ) +
  scale_x_discrete(labels = c("log2_FC < 0", "log2_FC > 0"))

print(Plot_MFE_GSE126779)
















# Determine the impact of these changes in terms of fraction of total counts:
# Calculate the fraction of total counts of high MFE transcripts in control and drug-treated groups. 
# This is done by summing the counts of the high MFE transcripts and dividing by the total counts in each group.
# Fisher’s exact test to compare the proportions of high MFE transcripts counts between the two groups.


# Convert from wide to long format
GSE126779_PC3_long_data <- GSE126779_PC3_norm_TX_counts_MFE_df %>%
  pivot_longer(
    cols = starts_with("GSM"),      # Select all columns starting with "GSM"
    names_to = "replicate",         # Name of the new column for replicate identifiers
    values_to = "counts"            # Name of the new column for the counts
  )

# Add a condition column based on the replicate
GSE126779_PC3_long_data <- GSE126779_PC3_long_data %>%
  dplyr::mutate(condition = ifelse(replicate %in% c("GSM3612783", "GSM3612784"), "DMSO", "0.1_uM_JQ1")) # this code assigns the "GSM3612783", "GSM3612784" GSMs to the control DMSO condition, the other GSMs will be automatically assigned to JQ1.

# Aggregate the replicates for each condition
GSE126779_PC3_norm_TX_aggregated_data_avg_counts <- GSE126779_PC3_long_data %>%
  group_by(ensembl_transcript_id_version, condition, Normalized_MFE, Specific_heat) %>%
  summarise(
    avg_counts = mean(counts, na.rm = TRUE),
    .groups = 'drop'
  )

# Define the 75th percentile of the entire distribution of MFE values for the GSE126779_PC3 data
GSE126779_PC3_MFE_all_TX_75_percentile <- quantile(GSE126779_PC3_norm_TX_aggregated_data_avg_counts$Normalized_MFE, 0.75)

# Identify all the transcripts with MFE values above the 75th percentile
GSE126779_PC3_high_MFE_TX_total <- dplyr::filter(GSE126779_PC3_norm_TX_counts_MFE_df, Normalized_MFE > GSE126779_PC3_MFE_all_TX_75_percentile)

# Fraction of total high MFE transcript counts in control and drug-treated groups
GSE126779_PC3_control_total_counts <- dplyr::filter(GSE126779_PC3_norm_TX_aggregated_data_avg_counts, condition == "DMSO") %>%
  dplyr::summarise(total_counts = sum(avg_counts, na.rm = TRUE))

GSE126779_PC3_control_high_MFE_TX_counts <- dplyr::filter(GSE126779_PC3_norm_TX_aggregated_data_avg_counts, condition == "DMSO") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE126779_PC3_high_MFE_TX_total$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE126779_PC3_control_high_MFE_TX_counts_fraction <- GSE126779_PC3_control_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE126779_PC3_control_total_counts$total_counts
print(GSE126779_PC3_control_high_MFE_TX_counts_fraction) # This value goes in the summary table

GSE126779_PC3_PC3_total_counts <- dplyr::filter(GSE126779_PC3_norm_TX_aggregated_data_avg_counts, condition == "0.1_uM_JQ1") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE126779_PC3_PC3_high_MFE_TX_counts <- dplyr::filter(GSE126779_PC3_norm_TX_aggregated_data_avg_counts, condition == "0.1_uM_JQ1") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE126779_PC3_high_MFE_TX_total$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE126779_PC3_PC3_high_MFE_TX_counts_fraction <- GSE126779_PC3_PC3_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE126779_PC3_PC3_total_counts$total_counts
print(GSE126779_PC3_PC3_high_MFE_TX_counts_fraction) # This value goes in the summary table

# Calculate proportions and apply two-proportion Z-test
p_control <- GSE126779_PC3_control_high_MFE_TX_counts_fraction
p_PC3 <- GSE126779_PC3_PC3_high_MFE_TX_counts_fraction

# Pooled proportion
P_pool <- (GSE126779_PC3_control_high_MFE_TX_counts$total_counts_high_MFE_TX + GSE126779_PC3_PC3_high_MFE_TX_counts$total_counts_high_MFE_TX) /
  (GSE126779_PC3_control_total_counts$total_counts + GSE126779_PC3_PC3_total_counts$total_counts)

# Z-test statistic for two proportions
if (GSE126779_PC3_control_total_counts$total_counts > 0 & GSE126779_PC3_PC3_total_counts$total_counts > 0) {
  Z <- (p_control - p_PC3) / sqrt(P_pool * (1 - P_pool) * (1/GSE126779_PC3_control_total_counts$total_counts + 1/GSE126779_PC3_PC3_total_counts$total_counts))
  GSE126779_PC3_z_test_counts_75_p_value <- 2 * (1 - pnorm(abs(Z)))
} else {
  Z <- NA
  GSE126779_PC3_z_test_counts_75_p_value <- NA
}

# Calculate the p-value for the Z-test
GSE126779_PC3_z_test_counts_75_p_value <- 2 * (1 - pnorm(abs(Z)))

# Output the results
cat("Two-proportion Z-test statistic:", Z, "\n")
cat("Two-proportion Z-test p-value:", GSE126779_PC3_z_test_counts_75_p_value, "\n")

# Output the results of fractions and net change
cat("GSE126779_PC3 control high MFE TX as fraction of total counts:", GSE126779_PC3_control_high_MFE_TX_counts_fraction, "\n")
cat("GSE126779_PC3 PC3 high MFE TX as fraction of total counts:", GSE126779_PC3_PC3_high_MFE_TX_counts_fraction, "\n")
cat("GSE126779_PC3 net change counts high MFE TX drug vs control:", GSE126779_PC3_PC3_high_MFE_TX_counts_fraction - GSE126779_PC3_control_high_MFE_TX_counts_fraction, "\n")





