# Permutation test MFE changes
# Combine the data into a single data frame with labels
upregulated <- data.frame(MFE = MFE_res_GSE115550_JQ1_50_nM_UP$Normalized_MFE, Group = "Up")
downregulated <- data.frame(MFE = MFE_res_GSE115550_JQ1_50_nM_DOWN$Normalized_MFE, Group = "Down")
combined_data <- bind_rows(upregulated, downregulated)

# Observed difference in means
GSE115550_JQ1_50_nM_observed_diff <- mean(MFE_res_GSE115550_JQ1_50_nM_UP$Normalized_MFE, na.rm = TRUE) - mean(MFE_res_GSE115550_JQ1_50_nM_DOWN$Normalized_MFE, na.rm = TRUE)

# Number of permutations
n_permutations <- 10000

# Initialize a vector to store the permuted differences
GSE115550_JQ1_50_nM_permuted_diffs <- numeric(n_permutations)

# Permutation test
set.seed(123)  # Set seed for reproducibility
for (i in 1:n_permutations) {
  # Permute the Group labels
  combined_data <- combined_data %>%
    mutate(Permuted_Group = sample(Group))
  
  permuted_up_mean <- mean(combined_data$MFE[combined_data$Permuted_Group == "Up"], na.rm = TRUE)
  permuted_down_mean <- mean(combined_data$MFE[combined_data$Permuted_Group == "Down"], na.rm = TRUE)
  
  # Calculate the difference in means for the permuted groups
  GSE115550_JQ1_50_nM_permuted_diffs[i] <- permuted_up_mean - permuted_down_mean
}

# Calculate the p-value
GSE115550_JQ1_50_nM_p_value <- (sum(abs(GSE115550_JQ1_50_nM_permuted_diffs) >= abs(GSE115550_JQ1_50_nM_observed_diff)) + 1) / (n_permutations + 1)

# Output the results
cat("Observed difference in GSE115550_JQ1_50_nM means MFE_UP - MFE_DOWN:", GSE115550_JQ1_50_nM_observed_diff, "\n")
cat("GSE115550_JQ1_50_nM P-value from permutation test:", GSE115550_JQ1_50_nM_p_value, "\n")


















## GSE115550 High MFE TX fraction changes
# Determine whether within the differentially expressed genes there is a significant up-regulation of high MFE transcripts:
# Define high MFE transcripts by taking the 75th percentile of the combined MFE distributions of control and drug-treated samples.
# Count the number of transcripts in the significantly up- and down-regulated genes that have MFE values above this threshold.
# Perform a Fisher’s exact test to compare the proportions of high MFE transcripts between the two groups.


# Analysis GSE115550
# Extract the normalized count data
# The minimal pre-filtering has already been done in the previous steps
GSE115550_norm_TX_counts <- counts(dds_GSE115550, normalized=TRUE) # This object is already a matrix
GSE115550_norm_TX_counts_df <- as.data.frame(GSE115550_norm_TX_counts)
# Convert row names to column
GSE115550_norm_TX_counts_df$ensembl_transcript_id <- rownames(GSE115550_norm_TX_counts_df)
# Remove row names
rownames(GSE115550_norm_TX_counts_df) <- NULL

# Move ensembl_transcript_id column to the first position
GSE115550_norm_TX_counts_df <- GSE115550_norm_TX_counts_df[, c("ensembl_transcript_id", setdiff(names(GSE115550_norm_TX_counts_df), "ensembl_transcript_id"))]

# Remove everything after the dot (including the dot itself) in the ensembl_transcript_id column
GSE115550_norm_TX_counts_df$ensembl_transcript_id <- sub("\\..*", "", GSE115550_norm_TX_counts_df$ensembl_transcript_id)

# Join the counts with the Table_ANNOTATED containing MFE values and heat capacity values
GSE115550_norm_TX_counts_MFE_df <- dplyr::inner_join(Table_ANNOTATED, GSE115550_norm_TX_counts_df, by="ensembl_transcript_id") %>%
  dplyr::select(ensembl_transcript_id_version, ensembl_transcript_id, ensembl_gene_id, external_gene_name, transcript_is_canonical, Transcript_length, 
                GSM3181856, GSM3181861, GSM3181866, GSM3181857, GSM3181862, GSM3181867,
                Normalized_MFE, Temperature, Specific_heat)







# GSE115550_JQ1_50_nM
# Convert from wide to long format
GSE115550_JQ1_50_nM_norm_TX_counts_MFE_df <- GSE115550_norm_TX_counts_MFE_df %>%
  dplyr::select(ensembl_transcript_id_version, ensembl_transcript_id, ensembl_gene_id, external_gene_name, transcript_is_canonical, Transcript_length, 
                GSM3181856, GSM3181861, GSM3181866, GSM3181857, GSM3181862, GSM3181867,
                Normalized_MFE, Temperature, Specific_heat) %>%
  dplyr::filter(ensembl_transcript_id %in% MFE_res_GSE115550_JQ1_50_nM$ensembl_transcript_id) 

# Identify the 75th percentile of the combined MFE distributions of control and drug-treated samples
quantile_075_GSE115550_JQ1_50_nM_norm_TX_counts_MFE_df <- quantile(GSE115550_JQ1_50_nM_norm_TX_counts_MFE_df$Normalized_MFE, probs = c(0.75))

# Select all the transcripts with Normalized_MFE values above the 75th percentile
GSE115550_JQ1_50_nM_high_MFE_TX <- dplyr::filter(GSE115550_JQ1_50_nM_norm_TX_counts_MFE_df, Normalized_MFE > quantile_075_GSE115550_JQ1_50_nM_norm_TX_counts_MFE_df)

# Count the number of transcripts in the significantly up- and down-regulated pools that have MFE values above this threshold.
GSE115550_JQ1_50_nM_high_MFE_TX_in_UP <- dplyr::filter(MFE_res_GSE115550_JQ1_50_nM_UP, ensembl_transcript_id_version %in% GSE115550_JQ1_50_nM_high_MFE_TX$ensembl_transcript_id_version)
GSE115550_JQ1_50_nM_high_MFE_TX_in_DOWN <- dplyr::filter(MFE_res_GSE115550_JQ1_50_nM_DOWN, ensembl_transcript_id_version %in% GSE115550_JQ1_50_nM_high_MFE_TX$ensembl_transcript_id_version)

# Calculate the proportions of high MFE transcripts in UP and DOWN-regulated groups
GSE115550_JQ1_50_nM_total_UP <- nrow(MFE_res_GSE115550_JQ1_50_nM_UP)
GSE115550_JQ1_50_nM_total_DOWN <- nrow(MFE_res_GSE115550_JQ1_50_nM_DOWN)
GSE115550_JQ1_50_nM_count_high_MFE_UP <- nrow(GSE115550_JQ1_50_nM_high_MFE_TX_in_UP)
GSE115550_JQ1_50_nM_count_high_MFE_DOWN <- nrow(GSE115550_JQ1_50_nM_high_MFE_TX_in_DOWN)

# Proportions of high MFE in each group
p_UP <- GSE115550_JQ1_50_nM_count_high_MFE_UP / GSE115550_JQ1_50_nM_total_UP
p_DOWN <- GSE115550_JQ1_50_nM_count_high_MFE_DOWN / GSE115550_JQ1_50_nM_total_DOWN

# Pooled proportion
P_pool <- (GSE115550_JQ1_50_nM_count_high_MFE_UP + GSE115550_JQ1_50_nM_count_high_MFE_DOWN) /
  (GSE115550_JQ1_50_nM_total_UP + GSE115550_JQ1_50_nM_total_DOWN)

# Two-proportion Z-test statistic
Z <- (p_UP - p_DOWN) / sqrt(P_pool * (1 - P_pool) * (1/GSE115550_JQ1_50_nM_total_UP + 1/GSE115550_JQ1_50_nM_total_DOWN))

# Calculate the p-value for the Z-test
GSE115550_JQ1_50_nM_z_test_MFE_p_value <- 2 * (1 - pnorm(abs(Z)))

# Output the results
cat("Two-proportion Z-test statistic:", Z, "\n")
cat("Two-proportion Z-test p-value:", GSE115550_JQ1_50_nM_z_test_MFE_p_value, "\n")

# Look at the fractions
GSE115550_JQ1_50_nM_high_MFE_in_UP_fraction <- GSE115550_JQ1_50_nM_count_high_MFE_UP / GSE115550_JQ1_50_nM_total_UP
GSE115550_JQ1_50_nM_high_MFE_in_DOWN_fraction <- GSE115550_JQ1_50_nM_count_high_MFE_DOWN / GSE115550_JQ1_50_nM_total_DOWN

# Output the fractions
cat("Fraction of GSE115550_JQ1_50_nM high MFE TX in UP-regulated genes:", GSE115550_JQ1_50_nM_high_MFE_in_UP_fraction, "\n")
cat("Fraction of GSE115550_JQ1_50_nM high MFE TX in DOWN-regulated genes:", GSE115550_JQ1_50_nM_high_MFE_in_DOWN_fraction, "\n")
cat("Mean of GSE115550_JQ1_50_nM high MFE TX in UP-regulated genes:", mean(GSE115550_JQ1_50_nM_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mean of GSE115550_JQ1_50_nM high MFE TX in DOWN-regulated genes:", mean(GSE115550_JQ1_50_nM_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")
cat("Mode of GSE115550_JQ1_50_nM high MFE TX in UP-regulated genes:", calculate_mode(GSE115550_JQ1_50_nM_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mode of GSE115550_JQ1_50_nM high MFE TX in DOWN-regulated genes:", calculate_mode(GSE115550_JQ1_50_nM_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")





# Show data as violin plot
# Add a new column to indicate if the value is above the 75th percentile
MFE_res_GSE115550_JQ1_50_nM$above_quantile_075 <- MFE_res_GSE115550_JQ1_50_nM$Normalized_MFE > quantile_075_GSE115550_JQ1_50_nM_norm_TX_counts_MFE_df

# Generate violin plot with conditional jitter coloring
Plot_MFE_GSE115550 <- ggplot(MFE_res_GSE115550_JQ1_50_nM, aes(x = factor(log2FoldChange > 0), y = Normalized_MFE)) +
  geom_violin(fill = "white", size = 1.5) +
  geom_jitter(aes(color = above_quantile_075), width = 0.1, size = 1, alpha = 1) +
  scale_color_manual(values = c("FALSE" = "black", "TRUE" = "dodgerblue3")) +
  theme_classic() +
  ylim(-0.6, 0) +
  theme(
    legend.position = "none", 
    axis.title = element_text(size = 20), 
    plot.title = element_text(size = 10),
    axis.text.x = element_text(size = 16, color = "black")
  ) +
  geom_vline(xintercept = 0, linewidth = 0.3) +
  labs(
    y = "Normalized_MFE", 
    x = NULL, 
    title = "GSE115550_JQ1_50_nM_Log2_FC_adj.P<0.05"
  ) +
  scale_x_discrete(labels = c("log2_FC < 0", "log2_FC > 0"))

print(Plot_MFE_GSE115550)

