# Determine the impact of these changes in terms of fraction of total counts:
# Calculate the fraction of total counts of high MFE transcripts in control and drug-treated groups. 
# This is done by summing the counts of the high MFE transcripts and dividing by the total counts in each group.
# Fisher’s exact test to compare the proportions of high MFE transcripts counts between the two groups.


# Convert from wide to long format
GSE115550_JQ1_50_nM_long_data <- GSE115550_JQ1_50_nM_norm_TX_counts_MFE_df %>%
  pivot_longer(
    cols = starts_with("GSM"),      # Select all columns starting with "GSM"
    names_to = "replicate",         # Name of the new column for replicate identifiers
    values_to = "counts"            # Name of the new column for the counts
  )

# Add a condition column based on the replicate
GSE115550_JQ1_50_nM_long_data <- GSE115550_JQ1_50_nM_long_data %>%
  dplyr::mutate(condition = ifelse(replicate %in% c("GSM3181856", "GSM3181861", "GSM3181866"), "DMSO_control", "JQ1_50_nM")) # this code assigns the "GSM3181856", "GSM3181861", "GSM3181866" GSMs to the control DMSO condition, the other GSMs will be automatically assigned to JQ1.

# Aggregate the replicates for each condition
GSE115550_JQ1_50_nM_norm_TX_aggregated_data_avg_counts <- GSE115550_JQ1_50_nM_long_data %>%
  group_by(ensembl_transcript_id_version, condition, Normalized_MFE, Specific_heat) %>%
  summarise(
    avg_counts = mean(counts, na.rm = TRUE),
    .groups = 'drop'
  )

# Define the 75th percentile of the entire distribution of MFE values for the GSE115550_JQ1_50_nM data
GSE115550_JQ1_50_nM_MFE_all_TX_75_percentile <- quantile(GSE115550_JQ1_50_nM_norm_TX_aggregated_data_avg_counts$Normalized_MFE, 0.75)

# Identify all the transcripts with MFE values above the 75th percentile
GSE115550_JQ1_50_nM_high_MFE_TX_total <- dplyr::filter(GSE115550_JQ1_50_nM_norm_TX_counts_MFE_df, Normalized_MFE > GSE115550_JQ1_50_nM_MFE_all_TX_75_percentile)

# Fraction of total high MFE transcript counts in control and drug-treated groups
GSE115550_JQ1_50_nM_control_total_counts <- dplyr::filter(GSE115550_JQ1_50_nM_norm_TX_aggregated_data_avg_counts, condition == "DMSO_control") %>%
  dplyr::summarise(total_counts = sum(avg_counts, na.rm = TRUE))

GSE115550_JQ1_50_nM_control_high_MFE_TX_counts <- dplyr::filter(GSE115550_JQ1_50_nM_norm_TX_aggregated_data_avg_counts, condition == "DMSO_control") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE115550_JQ1_50_nM_high_MFE_TX_total$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE115550_JQ1_50_nM_control_high_MFE_TX_counts_fraction <- GSE115550_JQ1_50_nM_control_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE115550_JQ1_50_nM_control_total_counts$total_counts
print(GSE115550_JQ1_50_nM_control_high_MFE_TX_counts_fraction) # This value goes in the summary table

GSE115550_JQ1_50_nM_JQ1_50_nM_total_counts <- dplyr::filter(GSE115550_JQ1_50_nM_norm_TX_aggregated_data_avg_counts, condition == "JQ1_50_nM") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE115550_JQ1_50_nM_JQ1_50_nM_high_MFE_TX_counts <- dplyr::filter(GSE115550_JQ1_50_nM_norm_TX_aggregated_data_avg_counts, condition == "JQ1_50_nM") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE115550_JQ1_50_nM_high_MFE_TX_total$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE115550_JQ1_50_nM_JQ1_50_nM_high_MFE_TX_counts_fraction <- GSE115550_JQ1_50_nM_JQ1_50_nM_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE115550_JQ1_50_nM_JQ1_50_nM_total_counts$total_counts
print(GSE115550_JQ1_50_nM_JQ1_50_nM_high_MFE_TX_counts_fraction) # This value goes in the summary table

# Calculate proportions and apply two-proportion Z-test
p_control <- GSE115550_JQ1_50_nM_control_high_MFE_TX_counts_fraction
p_JQ1_50_nM <- GSE115550_JQ1_50_nM_JQ1_50_nM_high_MFE_TX_counts_fraction

# Pooled proportion
P_pool <- (GSE115550_JQ1_50_nM_control_high_MFE_TX_counts$total_counts_high_MFE_TX + GSE115550_JQ1_50_nM_JQ1_50_nM_high_MFE_TX_counts$total_counts_high_MFE_TX) /
  (GSE115550_JQ1_50_nM_control_total_counts$total_counts + GSE115550_JQ1_50_nM_JQ1_50_nM_total_counts$total_counts)

# Z-test statistic for two proportions
if (GSE115550_JQ1_50_nM_control_total_counts$total_counts > 0 & GSE115550_JQ1_50_nM_JQ1_50_nM_total_counts$total_counts > 0) {
  Z <- (p_control - p_JQ1_50_nM) / sqrt(P_pool * (1 - P_pool) * (1/GSE115550_JQ1_50_nM_control_total_counts$total_counts + 1/GSE115550_JQ1_50_nM_JQ1_50_nM_total_counts$total_counts))
  GSE115550_JQ1_50_nM_z_test_counts_75_p_value <- 2 * (1 - pnorm(abs(Z)))
} else {
  Z <- NA
  GSE115550_JQ1_50_nM_z_test_counts_75_p_value <- NA
}

# Calculate the p-value for the Z-test
GSE115550_JQ1_50_nM_z_test_counts_75_p_value <- 2 * (1 - pnorm(abs(Z)))

# Output the results
cat("Two-proportion Z-test statistic:", Z, "\n")
cat("Two-proportion Z-test p-value:", GSE115550_JQ1_50_nM_z_test_counts_75_p_value, "\n")

# Output the results of fractions and net change
cat("GSE115550_JQ1_50_nM control high MFE TX as fraction of total counts:", GSE115550_JQ1_50_nM_control_high_MFE_TX_counts_fraction, "\n")
cat("GSE115550_JQ1_50_nM DU145 high MFE TX as fraction of total counts:", GSE115550_JQ1_50_nM_JQ1_50_nM_high_MFE_TX_counts_fraction, "\n")
cat("GSE115550_JQ1_50_nM net change counts high MFE TX drug vs control:", GSE115550_JQ1_50_nM_JQ1_50_nM_high_MFE_TX_counts_fraction - GSE115550_JQ1_50_nM_control_high_MFE_TX_counts_fraction, "\n")





