print(GSE115550_JQ1_50_nM_JQ1_50_nM_low_MFE_TX_counts_fraction) # This value goes in the summary table

# Calculate proportions
p_control <- GSE115550_JQ1_50_nM_control_low_MFE_TX_counts_fraction
p_JQ1_50_nM <- GSE115550_JQ1_50_nM_JQ1_50_nM_low_MFE_TX_counts_fraction

# Pooled proportion (weighted average of proportions)
P_pool <- (GSE115550_JQ1_50_nM_control_low_MFE_TX_counts$total_counts_low_MFE_TX + GSE115550_JQ1_50_nM_JQ1_50_nM_low_MFE_TX_counts$total_counts_low_MFE_TX) /
  (GSE115550_JQ1_50_nM_control_total_counts$total_counts + GSE115550_JQ1_50_nM_JQ1_50_nM_total_counts$total_counts)

# Calculate the variance for the two-proportion Z-test
var_control <- p_control * (1 - p_control) / GSE115550_JQ1_50_nM_control_total_counts$total_counts
var_JQ1_50_nM <- p_JQ1_50_nM * (1 - p_JQ1_50_nM) / GSE115550_JQ1_50_nM_JQ1_50_nM_total_counts$total_counts

# Combined variance for two proportions Z-test
P_pool_variance <- P_pool * (1 - P_pool) * (1 / GSE115550_JQ1_50_nM_control_total_counts$total_counts + 1 / GSE115550_JQ1_50_nM_JQ1_50_nM_total_counts$total_counts)

# Z-test statistic for two proportions
Z <- (p_control - p_JQ1_50_nM) / sqrt(P_pool_variance)

# Calculate the p-value for the Z-test (two-tailed)
GSE115550_JQ1_50_nM_z_test_counts_25_p_value <- 2 * (1 - pnorm(abs(Z)))

# Output the results
cat("Two-proportion Z-test statistic:", Z, "\n")
cat("Two-proportion Z-test p-value:", GSE115550_JQ1_50_nM_z_test_counts_25_p_value, "\n")

# Output the results of fractions and net change
cat("GSE115550_JQ1_50_nM control low MFE TX as fraction of total counts:", GSE115550_JQ1_50_nM_control_low_MFE_TX_counts_fraction, "\n")
cat("GSE115550_JQ1_50_nM DU145 low MFE TX as fraction of total counts:", GSE115550_JQ1_50_nM_JQ1_50_nM_low_MFE_TX_counts_fraction, "\n")
cat("GSE115550_JQ1_50_nM net change counts low MFE TX drug vs control:", GSE115550_JQ1_50_nM_JQ1_50_nM_low_MFE_TX_counts_fraction - GSE115550_JQ1_50_nM_control_low_MFE_TX_counts_fraction, "\n")















