rownames(GSE115550_norm_TX_counts_df) <- NULL

# Move ensembl_transcript_id column to the first position
GSE115550_norm_TX_counts_df <- GSE115550_norm_TX_counts_df[, c("ensembl_transcript_id", setdiff(names(GSE115550_norm_TX_counts_df), "ensembl_transcript_id"))]

# Remove everything after the dot (including the dot itself) in the ensembl_transcript_id column
GSE115550_norm_TX_counts_df$ensembl_transcript_id <- sub("\\..*", "", GSE115550_norm_TX_counts_df$ensembl_transcript_id)

# Join the counts with the Table_ANNOTATED containing MFE values and heat capacity values
GSE115550_norm_TX_counts_MFE_df <- dplyr::inner_join(Table_ANNOTATED, GSE115550_norm_TX_counts_df, by="ensembl_transcript_id") %>%
  dplyr::select(ensembl_transcript_id_version, ensembl_transcript_id, ensembl_gene_id, external_gene_name, transcript_is_canonical, Transcript_length, 
                GSM3181856, GSM3181861, GSM3181866, GSM3181858, GSM3181863, GSM3181868,
                Normalized_MFE, Temperature, Specific_heat)







# GSE115550_JQ1_500_nM
# Convert from wide to long format
GSE115550_JQ1_500_nM_norm_TX_counts_MFE_df <- GSE115550_norm_TX_counts_MFE_df %>%
  dplyr::select(ensembl_transcript_id_version, ensembl_transcript_id, ensembl_gene_id, external_gene_name, transcript_is_canonical, Transcript_length, 
                GSM3181856, GSM3181861, GSM3181866, GSM3181858, GSM3181863, GSM3181868,
                Normalized_MFE, Temperature, Specific_heat) %>%
  dplyr::filter(ensembl_transcript_id %in% MFE_res_GSE115550_JQ1_500_nM$ensembl_transcript_id) 

# Identify the 75th percentile of the combined MFE distributions of control and drug-treated samples
quantile_075_GSE115550_JQ1_500_nM_norm_TX_counts_MFE_df <- quantile(GSE115550_JQ1_500_nM_norm_TX_counts_MFE_df$Normalized_MFE, probs = c(0.75))

# Select all the transcripts with Normalized_MFE values above the 75th percentile
GSE115550_JQ1_500_nM_high_MFE_TX <- dplyr::filter(GSE115550_JQ1_500_nM_norm_TX_counts_MFE_df, Normalized_MFE > quantile_075_GSE115550_JQ1_500_nM_norm_TX_counts_MFE_df)

# Count the number of transcripts in the significantly up- and down-regulated pools that have MFE values above this threshold.
GSE115550_JQ1_500_nM_high_MFE_TX_in_UP <- dplyr::filter(MFE_res_GSE115550_JQ1_500_nM_UP, ensembl_transcript_id_version %in% GSE115550_JQ1_500_nM_high_MFE_TX$ensembl_transcript_id_version)
GSE115550_JQ1_500_nM_high_MFE_TX_in_DOWN <- dplyr::filter(MFE_res_GSE115550_JQ1_500_nM_DOWN, ensembl_transcript_id_version %in% GSE115550_JQ1_500_nM_high_MFE_TX$ensembl_transcript_id_version)

# Calculate the proportions of high MFE transcripts in UP and DOWN-regulated groups
GSE115550_JQ1_500_nM_total_UP <- nrow(MFE_res_GSE115550_JQ1_500_nM_UP)
GSE115550_JQ1_500_nM_total_DOWN <- nrow(MFE_res_GSE115550_JQ1_500_nM_DOWN)
GSE115550_JQ1_500_nM_count_high_MFE_UP <- nrow(GSE115550_JQ1_500_nM_high_MFE_TX_in_UP)
GSE115550_JQ1_500_nM_count_high_MFE_DOWN <- nrow(GSE115550_JQ1_500_nM_high_MFE_TX_in_DOWN)

# Proportions of high MFE in each group
p_UP <- GSE115550_JQ1_500_nM_count_high_MFE_UP / GSE115550_JQ1_500_nM_total_UP
p_DOWN <- GSE115550_JQ1_500_nM_count_high_MFE_DOWN / GSE115550_JQ1_500_nM_total_DOWN

# Pooled proportion
P_pool <- (GSE115550_JQ1_500_nM_count_high_MFE_UP + GSE115550_JQ1_500_nM_count_high_MFE_DOWN) /
  (GSE115550_JQ1_500_nM_total_UP + GSE115550_JQ1_500_nM_total_DOWN)

# Two-proportion Z-test statistic
Z <- (p_UP - p_DOWN) / sqrt(P_pool * (1 - P_pool) * (1/GSE115550_JQ1_500_nM_total_UP + 1/GSE115550_JQ1_500_nM_total_DOWN))

# Calculate the p-value for the Z-test
GSE115550_JQ1_500_nM_z_test_MFE_p_value <- 2 * (1 - pnorm(abs(Z)))

# Output the results
cat("Two-proportion Z-test statistic:", Z, "\n")
cat("Two-proportion Z-test p-value:", GSE115550_JQ1_500_nM_z_test_MFE_p_value, "\n")

# Look at the fractions
GSE115550_JQ1_500_nM_high_MFE_in_UP_fraction <- GSE115550_JQ1_500_nM_count_high_MFE_UP / GSE115550_JQ1_500_nM_total_UP
GSE115550_JQ1_500_nM_high_MFE_in_DOWN_fraction <- GSE115550_JQ1_500_nM_count_high_MFE_DOWN / GSE115550_JQ1_500_nM_total_DOWN

# Output the fractions
cat("Fraction of GSE115550_JQ1_500_nM high MFE TX in UP-regulated genes:", GSE115550_JQ1_500_nM_high_MFE_in_UP_fraction, "\n")
cat("Fraction of GSE115550_JQ1_500_nM high MFE TX in DOWN-regulated genes:", GSE115550_JQ1_500_nM_high_MFE_in_DOWN_fraction, "\n")
cat("Mean of GSE115550_JQ1_500_nM high MFE TX in UP-regulated genes:", mean(GSE115550_JQ1_500_nM_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mean of GSE115550_JQ1_500_nM high MFE TX in DOWN-regulated genes:", mean(GSE115550_JQ1_500_nM_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")
cat("Mode of GSE115550_JQ1_500_nM high MFE TX in UP-regulated genes:", calculate_mode(GSE115550_JQ1_500_nM_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mode of GSE115550_JQ1_500_nM high MFE TX in DOWN-regulated genes:", calculate_mode(GSE115550_JQ1_500_nM_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")





# Show data as violin plot
