MFE_res_GSE115550_JQ1_500_nM$above_quantile_075 <- MFE_res_GSE115550_JQ1_500_nM$Normalized_MFE > quantile_075_GSE115550_JQ1_500_nM_norm_TX_counts_MFE_df

