GSE115550_MS645_50_nM_MS645_50_nM_low_MFE_TX_counts <- dplyr::filter(GSE115550_MS645_50_nM_norm_TX_aggregated_data_avg_counts, condition == "MS645_50_nM") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE115550_MS645_50_nM_low_MFE_TX_total$ensembl_transcript_id_version) %>%
