                                 MFE_res_GSE115550_MS645_500_nM_DOWN$Normalized_MFE[MFE_res_GSE115550_MS645_500_nM_DOWN$Normalized_MFE <= quantile_025_MFE_res_GSE115550_MS645_500_nM_DOWN])
print(ks_test_MFE_025_below)



# Permutation test MFE changes
# Combine the data into a single data frame with labels
upregulated <- data.frame(MFE = MFE_res_GSE115550_MS645_500_nM_UP$Normalized_MFE, Group = "Up")
downregulated <- data.frame(MFE = MFE_res_GSE115550_MS645_500_nM_DOWN$Normalized_MFE, Group = "Down")
combined_data <- bind_rows(upregulated, downregulated)

# Observed difference in means
GSE115550_MS645_500_nM_observed_diff <- mean(MFE_res_GSE115550_MS645_500_nM_UP$Normalized_MFE, na.rm = TRUE) - mean(MFE_res_GSE115550_MS645_500_nM_DOWN$Normalized_MFE, na.rm = TRUE)

# Number of permutations
n_permutations <- 10000

# Initialize a vector to store the permuted differences
GSE115550_MS645_500_nM_permuted_diffs <- numeric(n_permutations)

# Permutation test
set.seed(123)  # Set seed for reproducibility
for (i in 1:n_permutations) {
  # Permute the Group labels
  combined_data <- combined_data %>%
    mutate(Permuted_Group = sample(Group))
  
  permuted_up_mean <- mean(combined_data$MFE[combined_data$Permuted_Group == "Up"], na.rm = TRUE)
  permuted_down_mean <- mean(combined_data$MFE[combined_data$Permuted_Group == "Down"], na.rm = TRUE)
  
  # Calculate the difference in means for the permuted groups
  GSE115550_MS645_500_nM_permuted_diffs[i] <- permuted_up_mean - permuted_down_mean
}

# Calculate the p-value
GSE115550_MS645_500_nM_p_value <- (sum(abs(GSE115550_MS645_500_nM_permuted_diffs) >= abs(GSE115550_MS645_500_nM_observed_diff)) + 1) / (n_permutations + 1)

# Output the results
cat("Observed difference in GSE115550_MS645_500_nM means MFE_UP - MFE_DOWN:", GSE115550_MS645_500_nM_observed_diff, "\n")
cat("GSE115550_MS645_500_nM P-value from permutation test:", GSE115550_MS645_500_nM_p_value, "\n")


















## GSE115550 High MFE TX fraction changes
# Determine whether within the differentially expressed genes there is a significant up-regulation of high MFE transcripts:
# Define high MFE transcripts by taking the 75th percentile of the combined MFE distributions of control and drug-treated samples.
# Count the number of transcripts in the significantly up- and down-regulated genes that have MFE values above this threshold.
# Perform a Fisher’s exact test to compare the proportions of high MFE transcripts between the two groups.


# Analysis GSE115550
# Extract the normalized count data
# The minimal pre-filtering has already been done in the previous steps
GSE115550_norm_TX_counts <- counts(dds_GSE115550, normalized=TRUE) # This object is already a matrix
GSE115550_norm_TX_counts_df <- as.data.frame(GSE115550_norm_TX_counts)
# Convert row names to column
GSE115550_norm_TX_counts_df$ensembl_transcript_id <- rownames(GSE115550_norm_TX_counts_df)
# Remove row names
rownames(GSE115550_norm_TX_counts_df) <- NULL

# Move ensembl_transcript_id column to the first position
GSE115550_norm_TX_counts_df <- GSE115550_norm_TX_counts_df[, c("ensembl_transcript_id", setdiff(names(GSE115550_norm_TX_counts_df), "ensembl_transcript_id"))]

# Remove everything after the dot (including the dot itself) in the ensembl_transcript_id column
GSE115550_norm_TX_counts_df$ensembl_transcript_id <- sub("\\..*", "", GSE115550_norm_TX_counts_df$ensembl_transcript_id)

# Join the counts with the Table_ANNOTATED containing MFE values and heat capacity values
GSE115550_norm_TX_counts_MFE_df <- dplyr::inner_join(Table_ANNOTATED, GSE115550_norm_TX_counts_df, by="ensembl_transcript_id") %>%
  dplyr::select(ensembl_transcript_id_version, ensembl_transcript_id, ensembl_gene_id, external_gene_name, transcript_is_canonical, Transcript_length, 
                GSM3181856, GSM3181861, GSM3181866, GSM3181860, GSM3181865, GSM3181870,
                Normalized_MFE, Temperature, Specific_heat)







# GSE115550_MS645_500_nM
# Convert from wide to long format
GSE115550_MS645_500_nM_norm_TX_counts_MFE_df <- GSE115550_norm_TX_counts_MFE_df %>%
  dplyr::select(ensembl_transcript_id_version, ensembl_transcript_id, ensembl_gene_id, external_gene_name, transcript_is_canonical, Transcript_length, 
                GSM3181856, GSM3181861, GSM3181866, GSM3181860, GSM3181865, GSM3181870,
                Normalized_MFE, Temperature, Specific_heat) %>%
  dplyr::filter(ensembl_transcript_id %in% MFE_res_GSE115550_MS645_500_nM$ensembl_transcript_id) 

# Identify the 75th percentile of the combined MFE distributions of control and drug-treated samples
quantile_075_GSE115550_MS645_500_nM_norm_TX_counts_MFE_df <- quantile(GSE115550_MS645_500_nM_norm_TX_counts_MFE_df$Normalized_MFE, probs = c(0.75))

# Select all the transcripts with Normalized_MFE values above the 75th percentile
GSE115550_MS645_500_nM_high_MFE_TX <- dplyr::filter(GSE115550_MS645_500_nM_norm_TX_counts_MFE_df, Normalized_MFE > quantile_075_GSE115550_MS645_500_nM_norm_TX_counts_MFE_df)

# Count the number of transcripts in the significantly up- and down-regulated pools that have MFE values above this threshold.
GSE115550_MS645_500_nM_high_MFE_TX_in_UP <- dplyr::filter(MFE_res_GSE115550_MS645_500_nM_UP, ensembl_transcript_id_version %in% GSE115550_MS645_500_nM_high_MFE_TX$ensembl_transcript_id_version)
GSE115550_MS645_500_nM_high_MFE_TX_in_DOWN <- dplyr::filter(MFE_res_GSE115550_MS645_500_nM_DOWN, ensembl_transcript_id_version %in% GSE115550_MS645_500_nM_high_MFE_TX$ensembl_transcript_id_version)

# Calculate the proportions of high MFE transcripts in UP and DOWN-regulated groups
GSE115550_MS645_500_nM_total_UP <- nrow(MFE_res_GSE115550_MS645_500_nM_UP)
GSE115550_MS645_500_nM_total_DOWN <- nrow(MFE_res_GSE115550_MS645_500_nM_DOWN)
GSE115550_MS645_500_nM_count_high_MFE_UP <- nrow(GSE115550_MS645_500_nM_high_MFE_TX_in_UP)
GSE115550_MS645_500_nM_count_high_MFE_DOWN <- nrow(GSE115550_MS645_500_nM_high_MFE_TX_in_DOWN)

# Proportions of high MFE in each group
p_UP <- GSE115550_MS645_500_nM_count_high_MFE_UP / GSE115550_MS645_500_nM_total_UP
p_DOWN <- GSE115550_MS645_500_nM_count_high_MFE_DOWN / GSE115550_MS645_500_nM_total_DOWN

# Pooled proportion
P_pool <- (GSE115550_MS645_500_nM_count_high_MFE_UP + GSE115550_MS645_500_nM_count_high_MFE_DOWN) /
  (GSE115550_MS645_500_nM_total_UP + GSE115550_MS645_500_nM_total_DOWN)

# Two-proportion Z-test statistic
Z <- (p_UP - p_DOWN) / sqrt(P_pool * (1 - P_pool) * (1/GSE115550_MS645_500_nM_total_UP + 1/GSE115550_MS645_500_nM_total_DOWN))

# Calculate the p-value for the Z-test
GSE115550_MS645_500_nM_z_test_MFE_p_value <- 2 * (1 - pnorm(abs(Z)))

# Output the results
cat("Two-proportion Z-test statistic:", Z, "\n")
cat("Two-proportion Z-test p-value:", GSE115550_MS645_500_nM_z_test_MFE_p_value, "\n")

# Look at the fractions
GSE115550_MS645_500_nM_high_MFE_in_UP_fraction <- GSE115550_MS645_500_nM_count_high_MFE_UP / GSE115550_MS645_500_nM_total_UP
GSE115550_MS645_500_nM_high_MFE_in_DOWN_fraction <- GSE115550_MS645_500_nM_count_high_MFE_DOWN / GSE115550_MS645_500_nM_total_DOWN

# Output the fractions
cat("Fraction of GSE115550_MS645_500_nM high MFE TX in UP-regulated genes:", GSE115550_MS645_500_nM_high_MFE_in_UP_fraction, "\n")
cat("Fraction of GSE115550_MS645_500_nM high MFE TX in DOWN-regulated genes:", GSE115550_MS645_500_nM_high_MFE_in_DOWN_fraction, "\n")
cat("Mean of GSE115550_MS645_500_nM high MFE TX in UP-regulated genes:", mean(GSE115550_MS645_500_nM_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mean of GSE115550_MS645_500_nM high MFE TX in DOWN-regulated genes:", mean(GSE115550_MS645_500_nM_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")
cat("Mode of GSE115550_MS645_500_nM high MFE TX in UP-regulated genes:", calculate_mode(GSE115550_MS645_500_nM_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mode of GSE115550_MS645_500_nM high MFE TX in DOWN-regulated genes:", calculate_mode(GSE115550_MS645_500_nM_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")





# Show data as violin plot
# Add a new column to indicate if the value is above the 75th percentile
MFE_res_GSE115550_MS645_500_nM$above_quantile_075 <- MFE_res_GSE115550_MS645_500_nM$Normalized_MFE > quantile_075_GSE115550_MS645_500_nM_norm_TX_counts_MFE_df

# Generate violin plot with conditional jitter coloring
Plot_MFE_GSE115550 <- ggplot(MFE_res_GSE115550_MS645_500_nM, aes(x = factor(log2FoldChange > 0), y = Normalized_MFE)) +
  geom_violin(fill = "white", size = 1.5) +
  geom_jitter(aes(color = above_quantile_075), width = 0.1, size = 1, alpha = 1) +
  scale_color_manual(values = c("FALSE" = "black", "TRUE" = "dodgerblue3")) +
  theme_classic() +
  ylim(-0.6, 0) +
  theme(
    legend.position = "none", 
    axis.title = element_text(size = 20), 
    plot.title = element_text(size = 10),
    axis.text.x = element_text(size = 16, color = "black")
  ) +
  geom_vline(xintercept = 0, linewidth = 0.3) +
  labs(
    y = "Normalized_MFE", 
    x = NULL, 
    title = "GSE115550_MS645_500_nM_Log2_FC_adj.P<0.05"
  ) +
  scale_x_discrete(labels = c("log2_FC < 0", "log2_FC > 0"))

print(Plot_MFE_GSE115550)

















# Determine the impact of these changes in terms of fraction of total counts:
# Calculate the fraction of total counts of high MFE transcripts in control and drug-treated groups. 
# This is done by summing the counts of the high MFE transcripts and dividing by the total counts in each group.
# Fisher’s exact test to compare the proportions of high MFE transcripts counts between the two groups.


# Convert from wide to long format
GSE115550_MS645_500_nM_long_data <- GSE115550_MS645_500_nM_norm_TX_counts_MFE_df %>%
  pivot_longer(
    cols = starts_with("GSM"),      # Select all columns starting with "GSM"
    names_to = "replicate",         # Name of the new column for replicate identifiers
    values_to = "counts"            # Name of the new column for the counts
  )

# Add a condition column based on the replicate
GSE115550_MS645_500_nM_long_data <- GSE115550_MS645_500_nM_long_data %>%
  dplyr::mutate(condition = ifelse(replicate %in% c("GSM3181856", "GSM3181861", "GSM3181866"), "DMSO_control", "MS645_500_nM")) # this code assigns the "GSM3181856", "GSM3181861", "GSM3181866" GSMs to the control DMSO condition, the other GSMs will be automatically assigned to MS645.

# Aggregate the replicates for each condition
GSE115550_MS645_500_nM_norm_TX_aggregated_data_avg_counts <- GSE115550_MS645_500_nM_long_data %>%
  group_by(ensembl_transcript_id_version, condition, Normalized_MFE, Specific_heat) %>%
  summarise(
    avg_counts = mean(counts, na.rm = TRUE),
    .groups = 'drop'
  )

# Define the 75th percentile of the entire distribution of MFE values for the GSE115550_MS645_500_nM data
GSE115550_MS645_500_nM_MFE_all_TX_75_percentile <- quantile(GSE115550_MS645_500_nM_norm_TX_aggregated_data_avg_counts$Normalized_MFE, 0.75)

# Identify all the transcripts with MFE values above the 75th percentile
GSE115550_MS645_500_nM_high_MFE_TX_total <- dplyr::filter(GSE115550_MS645_500_nM_norm_TX_counts_MFE_df, Normalized_MFE > GSE115550_MS645_500_nM_MFE_all_TX_75_percentile)

# Fraction of total high MFE transcript counts in control and drug-treated groups
GSE115550_MS645_500_nM_control_total_counts <- dplyr::filter(GSE115550_MS645_500_nM_norm_TX_aggregated_data_avg_counts, condition == "DMSO_control") %>%
  dplyr::summarise(total_counts = sum(avg_counts, na.rm = TRUE))

GSE115550_MS645_500_nM_control_high_MFE_TX_counts <- dplyr::filter(GSE115550_MS645_500_nM_norm_TX_aggregated_data_avg_counts, condition == "DMSO_control") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE115550_MS645_500_nM_high_MFE_TX_total$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE115550_MS645_500_nM_control_high_MFE_TX_counts_fraction <- GSE115550_MS645_500_nM_control_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE115550_MS645_500_nM_control_total_counts$total_counts
print(GSE115550_MS645_500_nM_control_high_MFE_TX_counts_fraction) # This value goes in the summary table

GSE115550_MS645_500_nM_MS645_500_nM_total_counts <- dplyr::filter(GSE115550_MS645_500_nM_norm_TX_aggregated_data_avg_counts, condition == "MS645_500_nM") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE115550_MS645_500_nM_MS645_500_nM_high_MFE_TX_counts <- dplyr::filter(GSE115550_MS645_500_nM_norm_TX_aggregated_data_avg_counts, condition == "MS645_500_nM") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE115550_MS645_500_nM_high_MFE_TX_total$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE115550_MS645_500_nM_MS645_500_nM_high_MFE_TX_counts_fraction <- GSE115550_MS645_500_nM_MS645_500_nM_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE115550_MS645_500_nM_MS645_500_nM_total_counts$total_counts
print(GSE115550_MS645_500_nM_MS645_500_nM_high_MFE_TX_counts_fraction) # This value goes in the summary table

# Calculate proportions and apply two-proportion Z-test
p_control <- GSE115550_MS645_500_nM_control_high_MFE_TX_counts_fraction
p_MS645_500_nM <- GSE115550_MS645_500_nM_MS645_500_nM_high_MFE_TX_counts_fraction

# Pooled proportion
P_pool <- (GSE115550_MS645_500_nM_control_high_MFE_TX_counts$total_counts_high_MFE_TX + GSE115550_MS645_500_nM_MS645_500_nM_high_MFE_TX_counts$total_counts_high_MFE_TX) /
  (GSE115550_MS645_500_nM_control_total_counts$total_counts + GSE115550_MS645_500_nM_MS645_500_nM_total_counts$total_counts)

# Z-test statistic for two proportions
if (GSE115550_MS645_500_nM_control_total_counts$total_counts > 0 & GSE115550_MS645_500_nM_MS645_500_nM_total_counts$total_counts > 0) {
  Z <- (p_control - p_MS645_500_nM) / sqrt(P_pool * (1 - P_pool) * (1/GSE115550_MS645_500_nM_control_total_counts$total_counts + 1/GSE115550_MS645_500_nM_MS645_500_nM_total_counts$total_counts))
  GSE115550_MS645_500_nM_z_test_counts_75_p_value <- 2 * (1 - pnorm(abs(Z)))
} else {
  Z <- NA
  GSE115550_MS645_500_nM_z_test_counts_75_p_value <- NA
}

# Calculate the p-value for the Z-test
GSE115550_MS645_500_nM_z_test_counts_75_p_value <- 2 * (1 - pnorm(abs(Z)))

# Output the results
cat("Two-proportion Z-test statistic:", Z, "\n")
cat("Two-proportion Z-test p-value:", GSE115550_MS645_500_nM_z_test_counts_75_p_value, "\n")

# Output the results of fractions and net change
cat("GSE115550_MS645_500_nM control high MFE TX as fraction of total counts:", GSE115550_MS645_500_nM_control_high_MFE_TX_counts_fraction, "\n")
cat("GSE115550_MS645_500_nM DU145 high MFE TX as fraction of total counts:", GSE115550_MS645_500_nM_MS645_500_nM_high_MFE_TX_counts_fraction, "\n")
cat("GSE115550_MS645_500_nM net change counts high MFE TX drug vs control:", GSE115550_MS645_500_nM_MS645_500_nM_high_MFE_TX_counts_fraction - GSE115550_MS645_500_nM_control_high_MFE_TX_counts_fraction, "\n")





