# Permutation test MFE changes
# Combine the data into a single data frame with labels
upregulated <- data.frame(MFE = MFE_res_GSE241600_MG132_24H_UP$Normalized_MFE, Group = "Up")
downregulated <- data.frame(MFE = MFE_res_GSE241600_MG132_24H_DOWN$Normalized_MFE, Group = "Down")
combined_data <- bind_rows(upregulated, downregulated)

# Observed difference in means
GSE241600_MG132_24H_observed_diff <- mean(MFE_res_GSE241600_MG132_24H_UP$Normalized_MFE, na.rm = TRUE) - mean(MFE_res_GSE241600_MG132_24H_DOWN$Normalized_MFE, na.rm = TRUE)

# Number of permutations
n_permutations <- 10000

# Initialize a vector to store the permuted differences
GSE241600_MG132_24H_permuted_diffs <- numeric(n_permutations)

# Permutation test
set.seed(123)  # Set seed for reproducibility
for (i in 1:n_permutations) {
  # Permute the Group labels
  combined_data <- combined_data %>%
    mutate(Permuted_Group = sample(Group))
  
  permuted_up_mean <- mean(combined_data$MFE[combined_data$Permuted_Group == "Up"], na.rm = TRUE)
  permuted_down_mean <- mean(combined_data$MFE[combined_data$Permuted_Group == "Down"], na.rm = TRUE)
  
  # Calculate the difference in means for the permuted groups
  GSE241600_MG132_24H_permuted_diffs[i] <- permuted_up_mean - permuted_down_mean
}

# Calculate the p-value
GSE241600_MG132_24H_p_value <- (sum(abs(GSE241600_MG132_24H_permuted_diffs) >= abs(GSE241600_MG132_24H_observed_diff)) + 1) / (n_permutations + 1)

# Output the results
cat("Observed difference in GSE241600_MG132_24H means MFE_UP - MFE_DOWN:", GSE241600_MG132_24H_observed_diff, "\n")
cat("GSE241600_MG132_24H P-value from permutation test:", GSE241600_MG132_24H_p_value, "\n")






















## GSE241600 High MFE TX fraction changes
# Determine whether within the differentially expressed genes there is a significant up-regulation of high MFE transcripts:
# Define high MFE transcripts by taking the 75th percentile of the combined MFE distributions of control and drug-treated samples.
# Count the number of transcripts in the significantly up- and down-regulated genes that have MFE values above this threshold.
# Perform a Fisher’s exact test to compare the proportions of high MFE transcripts between the two groups.


# Analysis GSE241600
# Extract the normalized count data
# The minimal pre-filtering has already been done in the previous steps
GSE241600_norm_TX_counts <- counts(dds_GSE241600, normalized=TRUE) # This object is already a matrix
GSE241600_norm_TX_counts_df <- as.data.frame(GSE241600_norm_TX_counts)
# Convert row names to column
GSE241600_norm_TX_counts_df$ensembl_transcript_id <- rownames(GSE241600_norm_TX_counts_df)
# Remove row names
rownames(GSE241600_norm_TX_counts_df) <- NULL

# Move ensembl_transcript_id column to the first position
GSE241600_norm_TX_counts_df <- GSE241600_norm_TX_counts_df[, c("ensembl_transcript_id", setdiff(names(GSE241600_norm_TX_counts_df), "ensembl_transcript_id"))]

# Remove everything after the dot (including the dot itself) in the ensembl_transcript_id column
GSE241600_norm_TX_counts_df$ensembl_transcript_id <- sub("\\..*", "", GSE241600_norm_TX_counts_df$ensembl_transcript_id)

# Join the counts with the Table_ANNOTATED containing MFE values and heat capacity values
GSE241600_norm_TX_counts_MFE_df <- dplyr::inner_join(Table_ANNOTATED, GSE241600_norm_TX_counts_df, by="ensembl_transcript_id") %>%
  dplyr::select(ensembl_transcript_id_version, ensembl_transcript_id, ensembl_gene_id, external_gene_name, transcript_is_canonical, Transcript_length, 
                GSM7731540, GSM7731541, GSM7731542, GSM7731546, GSM7731547, GSM7731548,
                Normalized_MFE, Temperature, Specific_heat)







# GSE241600_MG132_24H
# Convert from wide to long format
GSE241600_MG132_24H_norm_TX_counts_MFE_df <- GSE241600_norm_TX_counts_MFE_df %>%
  dplyr::select(ensembl_transcript_id_version, ensembl_transcript_id, ensembl_gene_id, external_gene_name, transcript_is_canonical, Transcript_length, 
                GSM7731540, GSM7731541, GSM7731542, GSM7731546, GSM7731547, GSM7731548,
                Normalized_MFE, Temperature, Specific_heat) %>%
  dplyr::filter(ensembl_transcript_id %in% MFE_res_GSE241600_MG132_24H$ensembl_transcript_id) 

# Identify the 75th percentile of the combined MFE distributions of control and drug-treated samples
quantile_075_GSE241600_MG132_24H_norm_TX_counts_MFE_df <- quantile(GSE241600_MG132_24H_norm_TX_counts_MFE_df$Normalized_MFE, probs = c(0.75))

# Select all the transcripts with Normalized_MFE values above the 75th percentile
GSE241600_MG132_24H_high_MFE_TX <- dplyr::filter(GSE241600_MG132_24H_norm_TX_counts_MFE_df, Normalized_MFE > quantile_075_GSE241600_MG132_24H_norm_TX_counts_MFE_df)

# Count the number of transcripts in the significantly up- and down-regulated pools that have MFE values above this threshold.
GSE241600_MG132_24H_high_MFE_TX_in_UP <- dplyr::filter(MFE_res_GSE241600_MG132_24H_UP, ensembl_transcript_id_version %in% GSE241600_MG132_24H_high_MFE_TX$ensembl_transcript_id_version)
GSE241600_MG132_24H_high_MFE_TX_in_DOWN <- dplyr::filter(MFE_res_GSE241600_MG132_24H_DOWN, ensembl_transcript_id_version %in% GSE241600_MG132_24H_high_MFE_TX$ensembl_transcript_id_version)

# Calculate the proportions of high MFE transcripts in UP and DOWN-regulated groups
GSE241600_MG132_24H_total_UP <- nrow(MFE_res_GSE241600_MG132_24H_UP)
GSE241600_MG132_24H_total_DOWN <- nrow(MFE_res_GSE241600_MG132_24H_DOWN)
GSE241600_MG132_24H_count_high_MFE_UP <- nrow(GSE241600_MG132_24H_high_MFE_TX_in_UP)
GSE241600_MG132_24H_count_high_MFE_DOWN <- nrow(GSE241600_MG132_24H_high_MFE_TX_in_DOWN)

# Proportions of high MFE in each group
p_UP <- GSE241600_MG132_24H_count_high_MFE_UP / GSE241600_MG132_24H_total_UP
p_DOWN <- GSE241600_MG132_24H_count_high_MFE_DOWN / GSE241600_MG132_24H_total_DOWN

# Pooled proportion
P_pool <- (GSE241600_MG132_24H_count_high_MFE_UP + GSE241600_MG132_24H_count_high_MFE_DOWN) /
  (GSE241600_MG132_24H_total_UP + GSE241600_MG132_24H_total_DOWN)

# Two-proportion Z-test statistic
Z <- (p_UP - p_DOWN) / sqrt(P_pool * (1 - P_pool) * (1/GSE241600_MG132_24H_total_UP + 1/GSE241600_MG132_24H_total_DOWN))

# Calculate the p-value for the Z-test
GSE241600_MG132_24H_z_test_MFE_p_value <- 2 * (1 - pnorm(abs(Z)))

# Output the results
cat("Two-proportion Z-test statistic:", Z, "\n")
cat("Two-proportion Z-test p-value:", GSE241600_MG132_24H_z_test_MFE_p_value, "\n")

# Look at the fractions
GSE241600_MG132_24H_high_MFE_in_UP_fraction <- GSE241600_MG132_24H_count_high_MFE_UP / GSE241600_MG132_24H_total_UP
GSE241600_MG132_24H_high_MFE_in_DOWN_fraction <- GSE241600_MG132_24H_count_high_MFE_DOWN / GSE241600_MG132_24H_total_DOWN

# Output the fractions
cat("Fraction of GSE241600_MG132_24H high MFE TX in UP-regulated genes:", GSE241600_MG132_24H_high_MFE_in_UP_fraction, "\n")
cat("Fraction of GSE241600_MG132_24H high MFE TX in DOWN-regulated genes:", GSE241600_MG132_24H_high_MFE_in_DOWN_fraction, "\n")
cat("Mean of GSE241600_MG132_24H high MFE TX in UP-regulated genes:", mean(GSE241600_MG132_24H_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mean of GSE241600_MG132_24H high MFE TX in DOWN-regulated genes:", mean(GSE241600_MG132_24H_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")
cat("Mode of GSE241600_MG132_24H high MFE TX in UP-regulated genes:", calculate_mode(GSE241600_MG132_24H_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mode of GSE241600_MG132_24H high MFE TX in DOWN-regulated genes:", calculate_mode(GSE241600_MG132_24H_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")





# Show data as violin plot
# Add a new column to indicate if the value is above the 75th percentile
MFE_res_GSE241600_MG132_24H$above_quantile_075 <- MFE_res_GSE241600_MG132_24H$Normalized_MFE > quantile_075_GSE241600_MG132_24H_norm_TX_counts_MFE_df

# Generate violin plot with conditional jitter coloring
Plot_MFE_GSE241600 <- ggplot(MFE_res_GSE241600_MG132_24H, aes(x = factor(log2FoldChange > 0), y = Normalized_MFE)) +
  geom_violin(fill = "white", size = 1.5) +
  geom_jitter(aes(color = above_quantile_075), width = 0.1, size = 1, alpha = 1) +
  scale_color_manual(values = c("FALSE" = "black", "TRUE" = "dodgerblue3")) +
  theme_classic() +
  ylim(-0.6, 0) +
  theme(
    legend.position = "none", 
    axis.title = element_text(size = 20), 
    plot.title = element_text(size = 10),
    axis.text.x = element_text(size = 16, color = "black")
  ) +
  geom_vline(xintercept = 0, linewidth = 0.3) +
  labs(
    y = "Normalized_MFE", 
    x = NULL, 
    title = "GSE241600_MG132_24H_Log2_FC_adj.P<0.05"
  ) +
  scale_x_discrete(labels = c("log2_FC < 0", "log2_FC > 0"))

print(Plot_MFE_GSE241600)


















# Determine the impact of these changes in terms of fraction of total counts:
# Calculate the fraction of total counts of high MFE transcripts in control and drug-treated groups. 
# This is done by summing the counts of the high MFE transcripts and dividing by the total counts in each group.
# Fisher’s exact test to compare the proportions of high MFE transcripts counts between the two groups.


# Convert from wide to long format
GSE241600_MG132_24H_long_data <- GSE241600_MG132_24H_norm_TX_counts_MFE_df %>%
  pivot_longer(
    cols = starts_with("GSM"),      # Select all columns starting with "GSM"
    names_to = "replicate",         # Name of the new column for replicate identifiers
    values_to = "counts"            # Name of the new column for the counts
  )

# Add a condition column based on the replicate
GSE241600_MG132_24H_long_data <- GSE241600_MG132_24H_long_data %>%
  dplyr::mutate(condition = ifelse(replicate %in% c("GSM7731540", "GSM7731541", "GSM7731542"), "Control", "MG132_24H")) # this code assigns the "GSM7731540", "GSM7731541", "GSM7731542" GSMs to the control DMSO condition, the other GSMs will be automatically assigned to MG132.

# Aggregate the replicates for each condition
GSE241600_MG132_24H_norm_TX_aggregated_data_avg_counts <- GSE241600_MG132_24H_long_data %>%
  group_by(ensembl_transcript_id_version, condition, Normalized_MFE, Specific_heat) %>%
  summarise(
    avg_counts = mean(counts, na.rm = TRUE),
    .groups = 'drop'
  )

# There is a transcript which is always detected at very high counts in both controll and drug treated samples. I remove it.
GSE241600_MG132_24H_norm_TX_aggregated_data_avg_counts <- dplyr::filter(GSE241600_MG132_24H_norm_TX_aggregated_data_avg_counts, ensembl_transcript_id_version != "ENST00000636484.1")

# Define the 75th percentile of the entire distribution of MFE values for the GSE241600_MG132_24H data
GSE241600_MG132_24H_MFE_all_TX_75_percentile <- quantile(GSE241600_MG132_24H_norm_TX_aggregated_data_avg_counts$Normalized_MFE, 0.75)

# Identify all the transcripts with MFE values above the 75th percentile
GSE241600_MG132_24H_high_MFE_TX_total <- dplyr::filter(GSE241600_MG132_24H_norm_TX_counts_MFE_df, Normalized_MFE > GSE241600_MG132_24H_MFE_all_TX_75_percentile)

# Fraction of total high MFE transcript counts in control and drug-treated groups
GSE241600_MG132_24H_control_total_counts <- dplyr::filter(GSE241600_MG132_24H_norm_TX_aggregated_data_avg_counts, condition == "Control") %>%
  dplyr::summarise(total_counts = sum(avg_counts, na.rm = TRUE))

GSE241600_MG132_24H_control_high_MFE_TX_counts <- dplyr::filter(GSE241600_MG132_24H_norm_TX_aggregated_data_avg_counts, condition == "Control") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE241600_MG132_24H_high_MFE_TX_total$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE241600_MG132_24H_control_high_MFE_TX_counts_fraction <- GSE241600_MG132_24H_control_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE241600_MG132_24H_control_total_counts$total_counts
print(GSE241600_MG132_24H_control_high_MFE_TX_counts_fraction) # This value goes in the summary table

GSE241600_MG132_24H_MG132_24H_total_counts <- dplyr::filter(GSE241600_MG132_24H_norm_TX_aggregated_data_avg_counts, condition == "MG132_24H") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE241600_MG132_24H_MG132_24H_high_MFE_TX_counts <- dplyr::filter(GSE241600_MG132_24H_norm_TX_aggregated_data_avg_counts, condition == "MG132_24H") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE241600_MG132_24H_high_MFE_TX_total$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE241600_MG132_24H_MG132_24H_high_MFE_TX_counts_fraction <- GSE241600_MG132_24H_MG132_24H_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE241600_MG132_24H_MG132_24H_total_counts$total_counts
print(GSE241600_MG132_24H_MG132_24H_high_MFE_TX_counts_fraction) # This value goes in the summary table

# Calculate proportions and apply two-proportion Z-test
p_control <- GSE241600_MG132_24H_control_high_MFE_TX_counts_fraction
p_MG132_24H <- GSE241600_MG132_24H_MG132_24H_high_MFE_TX_counts_fraction

# Pooled proportion
P_pool <- (GSE241600_MG132_24H_control_high_MFE_TX_counts$total_counts_high_MFE_TX + GSE241600_MG132_24H_MG132_24H_high_MFE_TX_counts$total_counts_high_MFE_TX) /
  (GSE241600_MG132_24H_control_total_counts$total_counts + GSE241600_MG132_24H_MG132_24H_total_counts$total_counts)

# Z-test statistic for two proportions
if (GSE241600_MG132_24H_control_total_counts$total_counts > 0 & GSE241600_MG132_24H_MG132_24H_total_counts$total_counts > 0) {
  Z <- (p_control - p_MG132_24H) / sqrt(P_pool * (1 - P_pool) * (1/GSE241600_MG132_24H_control_total_counts$total_counts + 1/GSE241600_MG132_24H_MG132_24H_total_counts$total_counts))
  GSE241600_MG132_24H_z_test_counts_75_p_value <- 2 * (1 - pnorm(abs(Z)))
} else {
  Z <- NA
  GSE241600_MG132_24H_z_test_counts_75_p_value <- NA
}

# Calculate the p-value for the Z-test
GSE241600_MG132_24H_z_test_counts_75_p_value <- 2 * (1 - pnorm(abs(Z)))

# Output the results
cat("Two-proportion Z-test statistic:", Z, "\n")
cat("Two-proportion Z-test p-value:", GSE241600_MG132_24H_z_test_counts_75_p_value, "\n")

# Output the results of fractions and net change
cat("GSE241600_MG132_24H control high MFE TX as fraction of total counts:", GSE241600_MG132_24H_control_high_MFE_TX_counts_fraction, "\n")
cat("GSE241600_MG132_24H high MFE TX as fraction of total counts:", GSE241600_MG132_24H_MG132_24H_high_MFE_TX_counts_fraction, "\n")
cat("GSE241600_MG132_24H net change counts high MFE TX drug vs control:", GSE241600_MG132_24H_MG132_24H_high_MFE_TX_counts_fraction - GSE241600_MG132_24H_control_high_MFE_TX_counts_fraction, "\n")





