# Define the 25th percentile of the entire distribution of MFE values for the GSE241600_MG132_24H data
GSE241600_MG132_24H_MFE_all_TX_25_percentile <- quantile(GSE241600_MG132_24H_norm_TX_aggregated_data_avg_counts$Normalized_MFE, 0.25)

# Identify all the transcripts with MFE values below the 25th percentile
GSE241600_MG132_24H_low_MFE_TX_total <- dplyr::filter(GSE241600_MG132_24H_norm_TX_counts_MFE_df, Normalized_MFE < GSE241600_MG132_24H_MFE_all_TX_25_percentile)

# Fraction of total low MFE transcript counts in control and drug-treated groups
GSE241600_MG132_24H_control_total_counts <- dplyr::filter(GSE241600_MG132_24H_norm_TX_aggregated_data_avg_counts, condition == "Control") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE241600_MG132_24H_control_low_MFE_TX_counts <- dplyr::filter(GSE241600_MG132_24H_norm_TX_aggregated_data_avg_counts, condition == "Control") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE241600_MG132_24H_low_MFE_TX_total$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_low_MFE_TX = sum(avg_counts))

GSE241600_MG132_24H_control_low_MFE_TX_counts_fraction <- GSE241600_MG132_24H_control_low_MFE_TX_counts$total_counts_low_MFE_TX / GSE241600_MG132_24H_control_total_counts$total_counts
print(GSE241600_MG132_24H_control_low_MFE_TX_counts_fraction) # This value goes in the summary table

GSE241600_MG132_24H_MG132_24H_total_counts <- dplyr::filter(GSE241600_MG132_24H_norm_TX_aggregated_data_avg_counts, condition == "MG132_24H") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE241600_MG132_24H_MG132_24H_low_MFE_TX_counts <- dplyr::filter(GSE241600_MG132_24H_norm_TX_aggregated_data_avg_counts, condition == "MG132_24H") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE241600_MG132_24H_low_MFE_TX_total$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_low_MFE_TX = sum(avg_counts))

GSE241600_MG132_24H_MG132_24H_low_MFE_TX_counts_fraction <- GSE241600_MG132_24H_MG132_24H_low_MFE_TX_counts$total_counts_low_MFE_TX / GSE241600_MG132_24H_MG132_24H_total_counts$total_counts
print(GSE241600_MG132_24H_MG132_24H_low_MFE_TX_counts_fraction) # This value goes in the summary table

# Calculate proportions
p_control <- GSE241600_MG132_24H_control_low_MFE_TX_counts_fraction
p_MG132_24H <- GSE241600_MG132_24H_MG132_24H_low_MFE_TX_counts_fraction

# Pooled proportion (weighted average of proportions)
P_pool <- (GSE241600_MG132_24H_control_low_MFE_TX_counts$total_counts_low_MFE_TX + GSE241600_MG132_24H_MG132_24H_low_MFE_TX_counts$total_counts_low_MFE_TX) /
  (GSE241600_MG132_24H_control_total_counts$total_counts + GSE241600_MG132_24H_MG132_24H_total_counts$total_counts)

# Calculate the variance for the two-proportion Z-test
var_control <- p_control * (1 - p_control) / GSE241600_MG132_24H_control_total_counts$total_counts
var_MG132_24H <- p_MG132_24H * (1 - p_MG132_24H) / GSE241600_MG132_24H_MG132_24H_total_counts$total_counts

# Combined variance for two proportions Z-test
P_pool_variance <- P_pool * (1 - P_pool) * (1 / GSE241600_MG132_24H_control_total_counts$total_counts + 1 / GSE241600_MG132_24H_MG132_24H_total_counts$total_counts)

# Z-test statistic for two proportions
Z <- (p_control - p_MG132_24H) / sqrt(P_pool_variance)

# Calculate the p-value for the Z-test (two-tailed)
GSE241600_MG132_24H_z_test_counts_25_p_value <- 2 * (1 - pnorm(abs(Z)))

# Output the results
cat("Two-proportion Z-test statistic:", Z, "\n")
cat("Two-proportion Z-test p-value:", GSE241600_MG132_24H_z_test_counts_25_p_value, "\n")

# Output the results of fractions and net change
cat("GSE241600_MG132_24H control low MFE TX as fraction of total counts:", GSE241600_MG132_24H_control_low_MFE_TX_counts_fraction, "\n")
cat("GSE241600_MG132_24H low MFE TX as fraction of total counts:", GSE241600_MG132_24H_MG132_24H_low_MFE_TX_counts_fraction, "\n")
cat("GSE241600_MG132_24H net change counts low MFE TX drug vs control:", GSE241600_MG132_24H_MG132_24H_low_MFE_TX_counts_fraction - GSE241600_MG132_24H_control_low_MFE_TX_counts_fraction, "\n")















