# Look at the mean log2_FC
MFE_res_GSE129944_Belinostat_UP <- dplyr::filter(MFE_res_GSE129944_Belinostat, log2FoldChange > 0)
Mean_MFE_res_GSE129944_Belinostat_UP <- mean(MFE_res_GSE129944_Belinostat_UP$Normalized_MFE, na.rm = TRUE)

MFE_res_GSE129944_Belinostat_DOWN <- dplyr::filter(MFE_res_GSE129944_Belinostat, log2FoldChange < 0)
Mean_MFE_res_GSE129944_Belinostat_DOWN <- mean(MFE_res_GSE129944_Belinostat_DOWN$Normalized_MFE, na.rm = TRUE)

TTEST_MFE_res_GSE129944_Belinostat_all_UP_vs_DOWN <- t.test(MFE_res_GSE129944_Belinostat_DOWN$Normalized_MFE, MFE_res_GSE129944_Belinostat_UP$Normalized_MFE, paired=FALSE)
print(TTEST_MFE_res_GSE129944_Belinostat_all_UP_vs_DOWN)

# Add K-S test to look at the differences between the up-regukated and down-regulated genes
ks_test_res_GSE129944_Belinostat_all_UP_vs_DOWN <- ks.test(MFE_res_GSE129944_Belinostat_DOWN$Normalized_MFE, MFE_res_GSE129944_Belinostat_UP$Normalized_MFE)
print(ks_test_res_GSE129944_Belinostat_all_UP_vs_DOWN)


