# Values above 0.75 quantile
ks_test_MFE_075_above <- ks.test(MFE_res_GSE129944_Belinostat_UP$Normalized_MFE[MFE_res_GSE129944_Belinostat_UP$Normalized_MFE >= quantile_075_MFE_res_GSE129944_Belinostat_UP],
                                 MFE_res_GSE129944_Belinostat_DOWN$Normalized_MFE[MFE_res_GSE129944_Belinostat_DOWN$Normalized_MFE >= quantile_075_MFE_res_GSE129944_Belinostat_DOWN])
print(ks_test_MFE_075_above)

# Look at the differences between the 0.25 quantile 
