# Values below 0.25 quantile
ks_test_MFE_025_below <- ks.test(MFE_res_GSE129944_Belinostat_UP$Normalized_MFE[MFE_res_GSE129944_Belinostat_UP$Normalized_MFE <= quantile_025_MFE_res_GSE129944_Belinostat_UP],
                                 MFE_res_GSE129944_Belinostat_DOWN$Normalized_MFE[MFE_res_GSE129944_Belinostat_DOWN$Normalized_MFE <= quantile_025_MFE_res_GSE129944_Belinostat_DOWN])
print(ks_test_MFE_025_below)



# Permutation test MFE changes
# Combine the data into a single data frame with labels
upregulated <- data.frame(MFE = MFE_res_GSE129944_Belinostat_UP$Normalized_MFE, Group = "Up")
downregulated <- data.frame(MFE = MFE_res_GSE129944_Belinostat_DOWN$Normalized_MFE, Group = "Down")
combined_data <- bind_rows(upregulated, downregulated)

# Observed difference in means
GSE129944_Belinostat_observed_diff <- mean(MFE_res_GSE129944_Belinostat_UP$Normalized_MFE, na.rm = TRUE) - mean(MFE_res_GSE129944_Belinostat_DOWN$Normalized_MFE, na.rm = TRUE)

# Number of permutations
n_permutations <- 10000

# Initialize a vector to store the permuted differences
GSE129944_Belinostat_permuted_diffs <- numeric(n_permutations)

# Permutation test
set.seed(123)  # Set seed for reproducibility
for (i in 1:n_permutations) {
  # Permute the Group labels
  combined_data <- combined_data %>%
    mutate(Permuted_Group = sample(Group))
  
  permuted_up_mean <- mean(combined_data$MFE[combined_data$Permuted_Group == "Up"], na.rm = TRUE)
  permuted_down_mean <- mean(combined_data$MFE[combined_data$Permuted_Group == "Down"], na.rm = TRUE)
  
  # Calculate the difference in means for the permuted groups
  GSE129944_Belinostat_permuted_diffs[i] <- permuted_up_mean - permuted_down_mean
}

# Calculate the p-value
GSE129944_Belinostat_p_value <- (sum(abs(GSE129944_Belinostat_permuted_diffs) >= abs(GSE129944_Belinostat_observed_diff)) + 1) / (n_permutations + 1)

# Output the results
cat("Observed difference in GSE129944_Belinostat means MFE_UP - MFE_DOWN:", GSE129944_Belinostat_observed_diff, "\n")
cat("GSE129944_Belinostat P-value from permutation test:", GSE129944_Belinostat_p_value, "\n")





















## GSE129944 High MFE TX fraction changes
# Determine whether within the differentially expressed genes there is a significant up-regulation of high MFE transcripts:
# Define high MFE transcripts by taking the 75th percentile of the combined MFE distributions of control and drug-treated samples.
# Count the number of transcripts in the significantly up- and down-regulated genes that have MFE values above this threshold.
# Perform a Fisher’s exact test to compare the proportions of high MFE transcripts between the two groups.


# Analysis GSE129944
# Extract the normalized count data
# The minimal pre-filtering has already been done in the previous steps
GSE129944_norm_TX_counts <- counts(dds_GSE129944, normalized=TRUE) # This object is already a matrix
GSE129944_norm_TX_counts_df <- as.data.frame(GSE129944_norm_TX_counts)
# Convert row names to column
GSE129944_norm_TX_counts_df$ensembl_transcript_id <- rownames(GSE129944_norm_TX_counts_df)
# Remove row names
rownames(GSE129944_norm_TX_counts_df) <- NULL

# Move ensembl_transcript_id column to the first position
GSE129944_norm_TX_counts_df <- GSE129944_norm_TX_counts_df[, c("ensembl_transcript_id", setdiff(names(GSE129944_norm_TX_counts_df), "ensembl_transcript_id"))]

# Remove everything after the dot (including the dot itself) in the ensembl_transcript_id column
GSE129944_norm_TX_counts_df$ensembl_transcript_id <- sub("\\..*", "", GSE129944_norm_TX_counts_df$ensembl_transcript_id)

# Join the counts with the Table_ANNOTATED containing MFE values and heat capacity values
GSE129944_norm_TX_counts_MFE_df <- dplyr::inner_join(Table_ANNOTATED, GSE129944_norm_TX_counts_df, by="ensembl_transcript_id") %>%
  dplyr::select(ensembl_transcript_id_version, ensembl_transcript_id, ensembl_gene_id, external_gene_name, transcript_is_canonical, Transcript_length, 
                GSM3728402, GSM3728403, GSM3728406, GSM3728407,
                Normalized_MFE, Temperature, Specific_heat)







# GSE129944_Belinostat
# Convert from wide to long format
GSE129944_Belinostat_norm_TX_counts_MFE_df <- GSE129944_norm_TX_counts_MFE_df %>%
  dplyr::select(ensembl_transcript_id_version, ensembl_transcript_id, ensembl_gene_id, external_gene_name, transcript_is_canonical, Transcript_length, 
                GSM3728402, GSM3728403, GSM3728406, GSM3728407,
                Normalized_MFE, Temperature, Specific_heat) %>%
  dplyr::filter(ensembl_transcript_id %in% MFE_res_GSE129944_Belinostat$ensembl_transcript_id) 

# Identify the 75th percentile of the combined MFE distributions of control and drug-treated samples
quantile_075_GSE129944_Belinostat_norm_TX_counts_MFE_df <- quantile(GSE129944_Belinostat_norm_TX_counts_MFE_df$Normalized_MFE, probs = c(0.75))

# Select all the transcripts with Normalized_MFE values above the 75th percentile
GSE129944_Belinostat_high_MFE_TX <- dplyr::filter(GSE129944_Belinostat_norm_TX_counts_MFE_df, Normalized_MFE > quantile_075_GSE129944_Belinostat_norm_TX_counts_MFE_df)

# Count the number of transcripts in the significantly up- and down-regulated pools that have MFE values above this threshold.
GSE129944_Belinostat_high_MFE_TX_in_UP <- dplyr::filter(MFE_res_GSE129944_Belinostat_UP, ensembl_transcript_id_version %in% GSE129944_Belinostat_high_MFE_TX$ensembl_transcript_id_version)
GSE129944_Belinostat_high_MFE_TX_in_DOWN <- dplyr::filter(MFE_res_GSE129944_Belinostat_DOWN, ensembl_transcript_id_version %in% GSE129944_Belinostat_high_MFE_TX$ensembl_transcript_id_version)

# Calculate the proportions of high MFE transcripts in UP and DOWN-regulated groups
GSE129944_Belinostat_total_UP <- nrow(MFE_res_GSE129944_Belinostat_UP)
GSE129944_Belinostat_total_DOWN <- nrow(MFE_res_GSE129944_Belinostat_DOWN)
GSE129944_Belinostat_count_high_MFE_UP <- nrow(GSE129944_Belinostat_high_MFE_TX_in_UP)
GSE129944_Belinostat_count_high_MFE_DOWN <- nrow(GSE129944_Belinostat_high_MFE_TX_in_DOWN)

# Proportions of high MFE in each group
p_UP <- GSE129944_Belinostat_count_high_MFE_UP / GSE129944_Belinostat_total_UP
p_DOWN <- GSE129944_Belinostat_count_high_MFE_DOWN / GSE129944_Belinostat_total_DOWN

# Pooled proportion
P_pool <- (GSE129944_Belinostat_count_high_MFE_UP + GSE129944_Belinostat_count_high_MFE_DOWN) /
  (GSE129944_Belinostat_total_UP + GSE129944_Belinostat_total_DOWN)

# Two-proportion Z-test statistic
Z <- (p_UP - p_DOWN) / sqrt(P_pool * (1 - P_pool) * (1/GSE129944_Belinostat_total_UP + 1/GSE129944_Belinostat_total_DOWN))

# Calculate the p-value for the Z-test
GSE129944_Belinostat_z_test_MFE_p_value <- 2 * (1 - pnorm(abs(Z)))

# Output the results
cat("Two-proportion Z-test statistic:", Z, "\n")
cat("Two-proportion Z-test p-value:", GSE129944_Belinostat_z_test_MFE_p_value, "\n")

# Look at the fractions
GSE129944_Belinostat_high_MFE_in_UP_fraction <- GSE129944_Belinostat_count_high_MFE_UP / GSE129944_Belinostat_total_UP
GSE129944_Belinostat_high_MFE_in_DOWN_fraction <- GSE129944_Belinostat_count_high_MFE_DOWN / GSE129944_Belinostat_total_DOWN

# Output the fractions
cat("Fraction of GSE129944_Belinostat high MFE TX in UP-regulated genes:", GSE129944_Belinostat_high_MFE_in_UP_fraction, "\n")
cat("Fraction of GSE129944_Belinostat high MFE TX in DOWN-regulated genes:", GSE129944_Belinostat_high_MFE_in_DOWN_fraction, "\n")
cat("Mean of GSE129944_Belinostat high MFE TX in UP-regulated genes:", mean(GSE129944_Belinostat_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mean of GSE129944_Belinostat high MFE TX in DOWN-regulated genes:", mean(GSE129944_Belinostat_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")
cat("Mode of GSE129944_Belinostat high MFE TX in UP-regulated genes:", calculate_mode(GSE129944_Belinostat_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mode of GSE129944_Belinostat high MFE TX in DOWN-regulated genes:", calculate_mode(GSE129944_Belinostat_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")





# Show data as violin plot
# Add a new column to indicate if the value is above the 75th percentile
MFE_res_GSE129944_Belinostat$above_quantile_075 <- MFE_res_GSE129944_Belinostat$Normalized_MFE > quantile_075_GSE129944_Belinostat_norm_TX_counts_MFE_df

# Generate violin plot with conditional jitter coloring
Plot_MFE_GSE129944 <- ggplot(MFE_res_GSE129944_Belinostat, aes(x = factor(log2FoldChange > 0), y = Normalized_MFE)) +
  geom_violin(fill = "white", size = 1.5) +
  geom_jitter(aes(color = above_quantile_075), width = 0.1, size = 1, alpha = 1) +
  scale_color_manual(values = c("FALSE" = "black", "TRUE" = "dodgerblue3")) +
  theme_classic() +
  ylim(-0.6, 0) +
  theme(
    legend.position = "none", 
    axis.title = element_text(size = 20), 
    plot.title = element_text(size = 10),
    axis.text.x = element_text(size = 16, color = "black")
  ) +
  geom_vline(xintercept = 0, linewidth = 0.3) +
  labs(
    y = "Normalized_MFE", 
    x = NULL, 
    title = "GSE129944_Belinostat_Log2_FC_adj.P<0.05"
  ) +
  scale_x_discrete(labels = c("log2_FC < 0", "log2_FC > 0"))

print(Plot_MFE_GSE129944)

















# Determine the impact of these changes in terms of fraction of total counts:
# Calculate the fraction of total counts of high MFE transcripts in DMSO and drug-treated groups. 
# This is done by summing the counts of the high MFE transcripts and dividing by the total counts in each group.
# Fisher’s exact test to compare the proportions of high MFE transcripts counts between the two groups.


# Convert from wide to long format
GSE129944_Belinostat_long_data <- GSE129944_Belinostat_norm_TX_counts_MFE_df %>%
  pivot_longer(
    cols = starts_with("GSM"),      # Select all columns starting with "GSM"
    names_to = "replicate",         # Name of the new column for replicate identifiers
    values_to = "counts"            # Name of the new column for the counts
  )

# Add a condition column based on the replicate
GSE129944_Belinostat_long_data <- GSE129944_Belinostat_long_data %>%
  dplyr::mutate(condition = ifelse(replicate %in% c("GSM3728402", "GSM3728403"), "DMSO", "Belinostat")) # this code assigns the "GSM3728402", "GSM3728403", "GSM7731542" GSMs to the DMSO DMSO condition, the other GSMs will be automatically assigned to Belinostat

# Aggregate the replicates for each condition
GSE129944_Belinostat_norm_TX_aggregated_data_avg_counts <- GSE129944_Belinostat_long_data %>%
  group_by(ensembl_transcript_id_version, condition, Normalized_MFE, Specific_heat) %>%
  summarise(
    avg_counts = mean(counts, na.rm = TRUE),
    .groups = 'drop'
  )

# There is a transcript which is always detected at very high counts in both DMSOl and drug treated samples. I remove it.
#GSE129944_Belinostat_norm_TX_aggregated_data_avg_counts <- dplyr::filter(GSE129944_Belinostat_norm_TX_aggregated_data_avg_counts, ensembl_transcript_id_version != "ENST00000636484.1")

# Define the 75th percentile of the entire distribution of MFE values for the GSE129944_Belinostat data
GSE129944_Belinostat_MFE_all_TX_75_percentile <- quantile(GSE129944_Belinostat_norm_TX_aggregated_data_avg_counts$Normalized_MFE, 0.75)

# Identify all the transcripts with MFE values above the 75th percentile
GSE129944_Belinostat_high_MFE_TX_total <- dplyr::filter(GSE129944_Belinostat_norm_TX_counts_MFE_df, Normalized_MFE > GSE129944_Belinostat_MFE_all_TX_75_percentile)

# Fraction of total high MFE transcript counts in DMSO and drug-treated groups
GSE129944_Belinostat_DMSO_total_counts <- dplyr::filter(GSE129944_Belinostat_norm_TX_aggregated_data_avg_counts, condition == "DMSO") %>%
  dplyr::summarise(total_counts = sum(avg_counts, na.rm = TRUE))

GSE129944_Belinostat_DMSO_high_MFE_TX_counts <- dplyr::filter(GSE129944_Belinostat_norm_TX_aggregated_data_avg_counts, condition == "DMSO") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE129944_Belinostat_high_MFE_TX_total$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE129944_Belinostat_DMSO_high_MFE_TX_counts_fraction <- GSE129944_Belinostat_DMSO_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE129944_Belinostat_DMSO_total_counts$total_counts
print(GSE129944_Belinostat_DMSO_high_MFE_TX_counts_fraction) # This value goes in the summary table

GSE129944_Belinostat_Belinostat_total_counts <- dplyr::filter(GSE129944_Belinostat_norm_TX_aggregated_data_avg_counts, condition == "Belinostat") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE129944_Belinostat_Belinostat_high_MFE_TX_counts <- dplyr::filter(GSE129944_Belinostat_norm_TX_aggregated_data_avg_counts, condition == "Belinostat") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE129944_Belinostat_high_MFE_TX_total$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE129944_Belinostat_Belinostat_high_MFE_TX_counts_fraction <- GSE129944_Belinostat_Belinostat_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE129944_Belinostat_Belinostat_total_counts$total_counts
print(GSE129944_Belinostat_Belinostat_high_MFE_TX_counts_fraction) # This value goes in the summary table

# Calculate proportions and apply two-proportion Z-test
p_DMSO <- GSE129944_Belinostat_DMSO_high_MFE_TX_counts_fraction
p_Belinostat <- GSE129944_Belinostat_Belinostat_high_MFE_TX_counts_fraction

# Pooled proportion
P_pool <- (GSE129944_Belinostat_DMSO_high_MFE_TX_counts$total_counts_high_MFE_TX + GSE129944_Belinostat_Belinostat_high_MFE_TX_counts$total_counts_high_MFE_TX) /
  (GSE129944_Belinostat_DMSO_total_counts$total_counts + GSE129944_Belinostat_Belinostat_total_counts$total_counts)

# Z-test statistic for two proportions
if (GSE129944_Belinostat_DMSO_total_counts$total_counts > 0 & GSE129944_Belinostat_Belinostat_total_counts$total_counts > 0) {
  Z <- (p_DMSO - p_Belinostat) / sqrt(P_pool * (1 - P_pool) * (1/GSE129944_Belinostat_DMSO_total_counts$total_counts + 1/GSE129944_Belinostat_Belinostat_total_counts$total_counts))
  GSE129944_Belinostat_z_test_counts_75_p_value <- 2 * (1 - pnorm(abs(Z)))
} else {
  Z <- NA
  GSE129944_Belinostat_z_test_counts_75_p_value <- NA
}

# Calculate the p-value for the Z-test
GSE129944_Belinostat_z_test_counts_75_p_value <- 2 * (1 - pnorm(abs(Z)))

# Output the results
cat("Two-proportion Z-test statistic:", Z, "\n")
cat("Two-proportion Z-test p-value:", GSE129944_Belinostat_z_test_counts_75_p_value, "\n")

# Output the results of fractions and net change
cat("GSE129944_Belinostat DMSO high MFE TX as fraction of total counts:", GSE129944_Belinostat_DMSO_high_MFE_TX_counts_fraction, "\n")
cat("GSE129944_Belinostat high MFE TX as fraction of total counts:", GSE129944_Belinostat_Belinostat_high_MFE_TX_counts_fraction, "\n")
cat("GSE129944_Belinostat net change counts high MFE TX drug vs DMSO:", GSE129944_Belinostat_Belinostat_high_MFE_TX_counts_fraction - GSE129944_Belinostat_DMSO_high_MFE_TX_counts_fraction, "\n")





