GSE129944_Belinostat_combined_plots





# Define the 25th percentile of the entire distribution of MFE values for the GSE129944_Belinostat data
GSE129944_Belinostat_MFE_all_TX_25_percentile <- quantile(GSE129944_Belinostat_norm_TX_aggregated_data_avg_counts$Normalized_MFE, 0.25)

# Identify all the transcripts with MFE values below the 25th percentile
GSE129944_Belinostat_low_MFE_TX_total <- dplyr::filter(GSE129944_Belinostat_norm_TX_counts_MFE_df, Normalized_MFE < GSE129944_Belinostat_MFE_all_TX_25_percentile)

# Fraction of total low MFE transcript counts in DMSO and drug-treated groups
GSE129944_Belinostat_DMSO_total_counts <- dplyr::filter(GSE129944_Belinostat_norm_TX_aggregated_data_avg_counts, condition == "DMSO") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE129944_Belinostat_DMSO_low_MFE_TX_counts <- dplyr::filter(GSE129944_Belinostat_norm_TX_aggregated_data_avg_counts, condition == "DMSO") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE129944_Belinostat_low_MFE_TX_total$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_low_MFE_TX = sum(avg_counts))

GSE129944_Belinostat_DMSO_low_MFE_TX_counts_fraction <- GSE129944_Belinostat_DMSO_low_MFE_TX_counts$total_counts_low_MFE_TX / GSE129944_Belinostat_DMSO_total_counts$total_counts
print(GSE129944_Belinostat_DMSO_low_MFE_TX_counts_fraction) # This value goes in the summary table

GSE129944_Belinostat_Belinostat_total_counts <- dplyr::filter(GSE129944_Belinostat_norm_TX_aggregated_data_avg_counts, condition == "Belinostat") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE129944_Belinostat_Belinostat_low_MFE_TX_counts <- dplyr::filter(GSE129944_Belinostat_norm_TX_aggregated_data_avg_counts, condition == "Belinostat") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE129944_Belinostat_low_MFE_TX_total$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_low_MFE_TX = sum(avg_counts))

GSE129944_Belinostat_Belinostat_low_MFE_TX_counts_fraction <- GSE129944_Belinostat_Belinostat_low_MFE_TX_counts$total_counts_low_MFE_TX / GSE129944_Belinostat_Belinostat_total_counts$total_counts
print(GSE129944_Belinostat_Belinostat_low_MFE_TX_counts_fraction) # This value goes in the summary table

# Calculate proportions
p_DMSO <- GSE129944_Belinostat_DMSO_low_MFE_TX_counts_fraction
p_Belinostat <- GSE129944_Belinostat_Belinostat_low_MFE_TX_counts_fraction

# Pooled proportion (weighted average of proportions)
P_pool <- (GSE129944_Belinostat_DMSO_low_MFE_TX_counts$total_counts_low_MFE_TX + GSE129944_Belinostat_Belinostat_low_MFE_TX_counts$total_counts_low_MFE_TX) /
  (GSE129944_Belinostat_DMSO_total_counts$total_counts + GSE129944_Belinostat_Belinostat_total_counts$total_counts)

# Calculate the variance for the two-proportion Z-test
var_DMSO <- p_DMSO * (1 - p_DMSO) / GSE129944_Belinostat_DMSO_total_counts$total_counts
var_Belinostat <- p_Belinostat * (1 - p_Belinostat) / GSE129944_Belinostat_Belinostat_total_counts$total_counts

# Combined variance for two proportions Z-test
P_pool_variance <- P_pool * (1 - P_pool) * (1 / GSE129944_Belinostat_DMSO_total_counts$total_counts + 1 / GSE129944_Belinostat_Belinostat_total_counts$total_counts)

# Z-test statistic for two proportions
Z <- (p_DMSO - p_Belinostat) / sqrt(P_pool_variance)

# Calculate the p-value for the Z-test (two-tailed)
GSE129944_Belinostat_z_test_counts_25_p_value <- 2 * (1 - pnorm(abs(Z)))

# Output the results
cat("Two-proportion Z-test statistic:", Z, "\n")
cat("Two-proportion Z-test p-value:", GSE129944_Belinostat_z_test_counts_25_p_value, "\n")

# Output the results of fractions and net change
cat("GSE129944_Belinostat DMSO low MFE TX as fraction of total counts:", GSE129944_Belinostat_DMSO_low_MFE_TX_counts_fraction, "\n")
cat("GSE129944_Belinostat low MFE TX as fraction of total counts:", GSE129944_Belinostat_Belinostat_low_MFE_TX_counts_fraction, "\n")
cat("GSE129944_Belinostat net change counts low MFE TX drug vs DMSO:", GSE129944_Belinostat_Belinostat_low_MFE_TX_counts_fraction - GSE129944_Belinostat_DMSO_low_MFE_TX_counts_fraction, "\n")










