# Permutation test MFE changes
# Combine the data into a single data frame with labels
upregulated <- data.frame(MFE = MFE_res_GSE129944_17_AAG_UP$Normalized_MFE, Group = "Up")
downregulated <- data.frame(MFE = MFE_res_GSE129944_17_AAG_DOWN$Normalized_MFE, Group = "Down")
combined_data <- bind_rows(upregulated, downregulated)

# Observed difference in means
GSE129944_17_AAG_observed_diff <- mean(MFE_res_GSE129944_17_AAG_UP$Normalized_MFE, na.rm = TRUE) - mean(MFE_res_GSE129944_17_AAG_DOWN$Normalized_MFE, na.rm = TRUE)

# Number of permutations
n_permutations <- 10000

# Initialize a vector to store the permuted differences
GSE129944_17_AAG_permuted_diffs <- numeric(n_permutations)

# Permutation test
set.seed(123)  # Set seed for reproducibility
for (i in 1:n_permutations) {
  # Permute the Group labels
  combined_data <- combined_data %>%
    mutate(Permuted_Group = sample(Group))
  
  permuted_up_mean <- mean(combined_data$MFE[combined_data$Permuted_Group == "Up"], na.rm = TRUE)
  permuted_down_mean <- mean(combined_data$MFE[combined_data$Permuted_Group == "Down"], na.rm = TRUE)
  
  # Calculate the difference in means for the permuted groups
  GSE129944_17_AAG_permuted_diffs[i] <- permuted_up_mean - permuted_down_mean
}

# Calculate the p-value
GSE129944_17_AAG_p_value <- (sum(abs(GSE129944_17_AAG_permuted_diffs) >= abs(GSE129944_17_AAG_observed_diff)) + 1) / (n_permutations + 1)

# Output the results
cat("Observed difference in GSE129944_17_AAG means MFE_UP - MFE_DOWN:", GSE129944_17_AAG_observed_diff, "\n")
cat("GSE129944_17_AAG P-value from permutation test:", GSE129944_17_AAG_p_value, "\n")





















## GSE129944 High MFE TX fraction changes
# Determine whether within the differentially expressed genes there is a significant up-regulation of high MFE transcripts:
# Define high MFE transcripts by taking the 75th percentile of the combined MFE distributions of control and drug-treated samples.
# Count the number of transcripts in the significantly up- and down-regulated genes that have MFE values above this threshold.
# Perform a Fisher’s exact test to compare the proportions of high MFE transcripts between the two groups.


# Analysis GSE129944
# Extract the normalized count data
# The minimal pre-filtering has already been done in the previous steps
GSE129944_norm_TX_counts <- counts(dds_GSE129944, normalized=TRUE) # This object is already a matrix
GSE129944_norm_TX_counts_df <- as.data.frame(GSE129944_norm_TX_counts)
# Convert row names to column
GSE129944_norm_TX_counts_df$ensembl_transcript_id <- rownames(GSE129944_norm_TX_counts_df)
# Remove row names
rownames(GSE129944_norm_TX_counts_df) <- NULL

# Move ensembl_transcript_id column to the first position
GSE129944_norm_TX_counts_df <- GSE129944_norm_TX_counts_df[, c("ensembl_transcript_id", setdiff(names(GSE129944_norm_TX_counts_df), "ensembl_transcript_id"))]

# Remove everything after the dot (including the dot itself) in the ensembl_transcript_id column
GSE129944_norm_TX_counts_df$ensembl_transcript_id <- sub("\\..*", "", GSE129944_norm_TX_counts_df$ensembl_transcript_id)

# Join the counts with the Table_ANNOTATED containing MFE values and heat capacity values
GSE129944_norm_TX_counts_MFE_df <- dplyr::inner_join(Table_ANNOTATED, GSE129944_norm_TX_counts_df, by="ensembl_transcript_id") %>%
  dplyr::select(ensembl_transcript_id_version, ensembl_transcript_id, ensembl_gene_id, external_gene_name, transcript_is_canonical, Transcript_length, 
                GSM3728402, GSM3728403, GSM3728404, GSM3728405,
                Normalized_MFE, Temperature, Specific_heat)







# GSE129944_17_AAG
# Convert from wide to long format
GSE129944_17_AAG_norm_TX_counts_MFE_df <- GSE129944_norm_TX_counts_MFE_df %>%
  dplyr::select(ensembl_transcript_id_version, ensembl_transcript_id, ensembl_gene_id, external_gene_name, transcript_is_canonical, Transcript_length, 
                GSM3728402, GSM3728403, GSM3728404, GSM3728405,
                Normalized_MFE, Temperature, Specific_heat) %>%
  dplyr::filter(ensembl_transcript_id %in% MFE_res_GSE129944_17_AAG$ensembl_transcript_id) 

# Identify the 75th percentile of the combined MFE distributions of control and drug-treated samples
quantile_075_GSE129944_17_AAG_norm_TX_counts_MFE_df <- quantile(GSE129944_17_AAG_norm_TX_counts_MFE_df$Normalized_MFE, probs = c(0.75))

# Select all the transcripts with Normalized_MFE values above the 75th percentile
GSE129944_17_AAG_high_MFE_TX <- dplyr::filter(GSE129944_17_AAG_norm_TX_counts_MFE_df, Normalized_MFE > quantile_075_GSE129944_17_AAG_norm_TX_counts_MFE_df)

# Count the number of transcripts in the significantly up- and down-regulated pools that have MFE values above this threshold.
GSE129944_17_AAG_high_MFE_TX_in_UP <- dplyr::filter(MFE_res_GSE129944_17_AAG_UP, ensembl_transcript_id_version %in% GSE129944_17_AAG_high_MFE_TX$ensembl_transcript_id_version)
GSE129944_17_AAG_high_MFE_TX_in_DOWN <- dplyr::filter(MFE_res_GSE129944_17_AAG_DOWN, ensembl_transcript_id_version %in% GSE129944_17_AAG_high_MFE_TX$ensembl_transcript_id_version)

# Calculate the proportions of high MFE transcripts in UP and DOWN-regulated groups
GSE129944_17_AAG_total_UP <- nrow(MFE_res_GSE129944_17_AAG_UP)
GSE129944_17_AAG_total_DOWN <- nrow(MFE_res_GSE129944_17_AAG_DOWN)
GSE129944_17_AAG_count_high_MFE_UP <- nrow(GSE129944_17_AAG_high_MFE_TX_in_UP)
GSE129944_17_AAG_count_high_MFE_DOWN <- nrow(GSE129944_17_AAG_high_MFE_TX_in_DOWN)

# Proportions of high MFE in each group
p_UP <- GSE129944_17_AAG_count_high_MFE_UP / GSE129944_17_AAG_total_UP
p_DOWN <- GSE129944_17_AAG_count_high_MFE_DOWN / GSE129944_17_AAG_total_DOWN

# Pooled proportion
P_pool <- (GSE129944_17_AAG_count_high_MFE_UP + GSE129944_17_AAG_count_high_MFE_DOWN) /
  (GSE129944_17_AAG_total_UP + GSE129944_17_AAG_total_DOWN)

# Two-proportion Z-test statistic
Z <- (p_UP - p_DOWN) / sqrt(P_pool * (1 - P_pool) * (1/GSE129944_17_AAG_total_UP + 1/GSE129944_17_AAG_total_DOWN))

# Calculate the p-value for the Z-test
GSE129944_17_AAG_z_test_MFE_p_value <- 2 * (1 - pnorm(abs(Z)))

# Output the results
cat("Two-proportion Z-test statistic:", Z, "\n")
cat("Two-proportion Z-test p-value:", GSE129944_17_AAG_z_test_MFE_p_value, "\n")

# Look at the fractions
GSE129944_17_AAG_high_MFE_in_UP_fraction <- GSE129944_17_AAG_count_high_MFE_UP / GSE129944_17_AAG_total_UP
GSE129944_17_AAG_high_MFE_in_DOWN_fraction <- GSE129944_17_AAG_count_high_MFE_DOWN / GSE129944_17_AAG_total_DOWN

# Output the fractions
cat("Fraction of GSE129944_17_AAG high MFE TX in UP-regulated genes:", GSE129944_17_AAG_high_MFE_in_UP_fraction, "\n")
cat("Fraction of GSE129944_17_AAG high MFE TX in DOWN-regulated genes:", GSE129944_17_AAG_high_MFE_in_DOWN_fraction, "\n")
cat("Mean of GSE129944_17_AAG high MFE TX in UP-regulated genes:", mean(GSE129944_17_AAG_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mean of GSE129944_17_AAG high MFE TX in DOWN-regulated genes:", mean(GSE129944_17_AAG_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")
cat("Mode of GSE129944_17_AAG high MFE TX in UP-regulated genes:", calculate_mode(GSE129944_17_AAG_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mode of GSE129944_17_AAG high MFE TX in DOWN-regulated genes:", calculate_mode(GSE129944_17_AAG_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")





