# Determine the impact of these changes in terms of fraction of total counts:
# Calculate the fraction of total counts of high MFE transcripts in DMSO and drug-treated groups. 
# This is done by summing the counts of the high MFE transcripts and dividing by the total counts in each group.
# Fisher’s exact test to compare the proportions of high MFE transcripts counts between the two groups.


# Convert from wide to long format
GSE129944_17_AAG_long_data <- GSE129944_17_AAG_norm_TX_counts_MFE_df %>%
  pivot_longer(
    cols = starts_with("GSM"),      # Select all columns starting with "GSM"
    names_to = "replicate",         # Name of the new column for replicate identifiers
    values_to = "counts"            # Name of the new column for the counts
  )

# Add a condition column based on the replicate
GSE129944_17_AAG_long_data <- GSE129944_17_AAG_long_data %>%
  dplyr::mutate(condition = ifelse(replicate %in% c("GSM3728402", "GSM3728403"), "DMSO", "17_AAG")) # this code assigns the "GSM3728402", "GSM3728403", "GSM7731542" GSMs to the DMSO DMSO condition, the other GSMs will be automatically assigned to 17_AAG

# Aggregate the replicates for each condition
GSE129944_17_AAG_norm_TX_aggregated_data_avg_counts <- GSE129944_17_AAG_long_data %>%
  group_by(ensembl_transcript_id_version, condition, Normalized_MFE, Specific_heat) %>%
  summarise(
    avg_counts = mean(counts, na.rm = TRUE),
    .groups = 'drop'
  )

# There is a transcript which is always detected at very high counts in both DMSOl and drug treated samples. I remove it.
#GSE129944_17_AAG_norm_TX_aggregated_data_avg_counts <- dplyr::filter(GSE129944_17_AAG_norm_TX_aggregated_data_avg_counts, ensembl_transcript_id_version != "ENST00000636484.1")

# Define the 75th percentile of the entire distribution of MFE values for the GSE129944_17_AAG data
GSE129944_17_AAG_MFE_all_TX_75_percentile <- quantile(GSE129944_17_AAG_norm_TX_aggregated_data_avg_counts$Normalized_MFE, 0.75)

# Identify all the transcripts with MFE values above the 75th percentile
GSE129944_17_AAG_high_MFE_TX_total <- dplyr::filter(GSE129944_17_AAG_norm_TX_counts_MFE_df, Normalized_MFE > GSE129944_17_AAG_MFE_all_TX_75_percentile)

# Fraction of total high MFE transcript counts in DMSO and drug-treated groups
GSE129944_17_AAG_DMSO_total_counts <- dplyr::filter(GSE129944_17_AAG_norm_TX_aggregated_data_avg_counts, condition == "DMSO") %>%
  dplyr::summarise(total_counts = sum(avg_counts, na.rm = TRUE))

GSE129944_17_AAG_DMSO_high_MFE_TX_counts <- dplyr::filter(GSE129944_17_AAG_norm_TX_aggregated_data_avg_counts, condition == "DMSO") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE129944_17_AAG_high_MFE_TX_total$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE129944_17_AAG_DMSO_high_MFE_TX_counts_fraction <- GSE129944_17_AAG_DMSO_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE129944_17_AAG_DMSO_total_counts$total_counts
print(GSE129944_17_AAG_DMSO_high_MFE_TX_counts_fraction) # This value goes in the summary table

GSE129944_17_AAG_17_AAG_total_counts <- dplyr::filter(GSE129944_17_AAG_norm_TX_aggregated_data_avg_counts, condition == "17_AAG") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE129944_17_AAG_17_AAG_high_MFE_TX_counts <- dplyr::filter(GSE129944_17_AAG_norm_TX_aggregated_data_avg_counts, condition == "17_AAG") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE129944_17_AAG_high_MFE_TX_total$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE129944_17_AAG_17_AAG_high_MFE_TX_counts_fraction <- GSE129944_17_AAG_17_AAG_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE129944_17_AAG_17_AAG_total_counts$total_counts
print(GSE129944_17_AAG_17_AAG_high_MFE_TX_counts_fraction) # This value goes in the summary table

# Calculate proportions and apply two-proportion Z-test
p_DMSO <- GSE129944_17_AAG_DMSO_high_MFE_TX_counts_fraction
p_17_AAG <- GSE129944_17_AAG_17_AAG_high_MFE_TX_counts_fraction

# Pooled proportion
P_pool <- (GSE129944_17_AAG_DMSO_high_MFE_TX_counts$total_counts_high_MFE_TX + GSE129944_17_AAG_17_AAG_high_MFE_TX_counts$total_counts_high_MFE_TX) /
  (GSE129944_17_AAG_DMSO_total_counts$total_counts + GSE129944_17_AAG_17_AAG_total_counts$total_counts)

# Z-test statistic for two proportions
if (GSE129944_17_AAG_DMSO_total_counts$total_counts > 0 & GSE129944_17_AAG_17_AAG_total_counts$total_counts > 0) {
  Z <- (p_DMSO - p_17_AAG) / sqrt(P_pool * (1 - P_pool) * (1/GSE129944_17_AAG_DMSO_total_counts$total_counts + 1/GSE129944_17_AAG_17_AAG_total_counts$total_counts))
  GSE129944_17_AAG_z_test_counts_75_p_value <- 2 * (1 - pnorm(abs(Z)))
} else {
  Z <- NA
  GSE129944_17_AAG_z_test_counts_75_p_value <- NA
}

# Calculate the p-value for the Z-test
GSE129944_17_AAG_z_test_counts_75_p_value <- 2 * (1 - pnorm(abs(Z)))

# Output the results
cat("Two-proportion Z-test statistic:", Z, "\n")
cat("Two-proportion Z-test p-value:", GSE129944_17_AAG_z_test_counts_75_p_value, "\n")

# Output the results of fractions and net change
cat("GSE129944_17_AAG DMSO high MFE TX as fraction of total counts:", GSE129944_17_AAG_DMSO_high_MFE_TX_counts_fraction, "\n")
cat("GSE129944_17_AAG high MFE TX as fraction of total counts:", GSE129944_17_AAG_17_AAG_high_MFE_TX_counts_fraction, "\n")
cat("GSE129944_17_AAG net change counts high MFE TX drug vs DMSO:", GSE129944_17_AAG_17_AAG_high_MFE_TX_counts_fraction - GSE129944_17_AAG_DMSO_high_MFE_TX_counts_fraction, "\n")





