print(GSE129944_17_AAG_17_AAG_low_MFE_TX_counts_fraction) # This value goes in the summary table

# Calculate proportions
p_DMSO <- GSE129944_17_AAG_DMSO_low_MFE_TX_counts_fraction
p_17_AAG <- GSE129944_17_AAG_17_AAG_low_MFE_TX_counts_fraction

# Pooled proportion (weighted average of proportions)
P_pool <- (GSE129944_17_AAG_DMSO_low_MFE_TX_counts$total_counts_low_MFE_TX + GSE129944_17_AAG_17_AAG_low_MFE_TX_counts$total_counts_low_MFE_TX) /
  (GSE129944_17_AAG_DMSO_total_counts$total_counts + GSE129944_17_AAG_17_AAG_total_counts$total_counts)

# Calculate the variance for the two-proportion Z-test
var_DMSO <- p_DMSO * (1 - p_DMSO) / GSE129944_17_AAG_DMSO_total_counts$total_counts
var_17_AAG <- p_17_AAG * (1 - p_17_AAG) / GSE129944_17_AAG_17_AAG_total_counts$total_counts

# Combined variance for two proportions Z-test
P_pool_variance <- P_pool * (1 - P_pool) * (1 / GSE129944_17_AAG_DMSO_total_counts$total_counts + 1 / GSE129944_17_AAG_17_AAG_total_counts$total_counts)

# Z-test statistic for two proportions
Z <- (p_DMSO - p_17_AAG) / sqrt(P_pool_variance)

# Calculate the p-value for the Z-test (two-tailed)
GSE129944_17_AAG_z_test_counts_25_p_value <- 2 * (1 - pnorm(abs(Z)))

# Output the results
cat("Two-proportion Z-test statistic:", Z, "\n")
cat("Two-proportion Z-test p-value:", GSE129944_17_AAG_z_test_counts_25_p_value, "\n")

# Output the results of fractions and net change
cat("GSE129944_17_AAG DMSO low MFE TX as fraction of total counts:", GSE129944_17_AAG_DMSO_low_MFE_TX_counts_fraction, "\n")
cat("GSE129944_17_AAG low MFE TX as fraction of total counts:", GSE129944_17_AAG_17_AAG_low_MFE_TX_counts_fraction, "\n")
cat("GSE129944_17_AAG net change counts low MFE TX drug vs DMSO:", GSE129944_17_AAG_17_AAG_low_MFE_TX_counts_fraction - GSE129944_17_AAG_DMSO_low_MFE_TX_counts_fraction, "\n")















