# Values above 0.75 quantile
ks_test_MFE_075_above <- ks.test(MFE_res_GSE163249_Vorinostat_UP$Normalized_MFE[MFE_res_GSE163249_Vorinostat_UP$Normalized_MFE >= quantile_075_MFE_res_GSE163249_Vorinostat_UP],
                                 MFE_res_GSE163249_Vorinostat_DOWN$Normalized_MFE[MFE_res_GSE163249_Vorinostat_DOWN$Normalized_MFE >= quantile_075_MFE_res_GSE163249_Vorinostat_DOWN])
print(ks_test_MFE_075_above)

# Look at the differences between the 0.25 quantile 
quantile_025_MFE_res_GSE163249_Vorinostat_UP <- quantile(MFE_res_GSE163249_Vorinostat_UP$Normalized_MFE, probs = c(0.25)) 
quantile_025_MFE_res_GSE163249_Vorinostat_DOWN <- quantile(MFE_res_GSE163249_Vorinostat_DOWN$Normalized_MFE, probs = c(0.25)) 
# Values below 0.25 quantile
ks_test_MFE_025_below <- ks.test(MFE_res_GSE163249_Vorinostat_UP$Normalized_MFE[MFE_res_GSE163249_Vorinostat_UP$Normalized_MFE <= quantile_025_MFE_res_GSE163249_Vorinostat_UP],
                                 MFE_res_GSE163249_Vorinostat_DOWN$Normalized_MFE[MFE_res_GSE163249_Vorinostat_DOWN$Normalized_MFE <= quantile_025_MFE_res_GSE163249_Vorinostat_DOWN])
print(ks_test_MFE_025_below)



# Permutation test MFE changes
# Combine the data into a single data frame with labels
upregulated <- data.frame(MFE = MFE_res_GSE163249_Vorinostat_UP$Normalized_MFE, Group = "Up")
downregulated <- data.frame(MFE = MFE_res_GSE163249_Vorinostat_DOWN$Normalized_MFE, Group = "Down")
combined_data <- bind_rows(upregulated, downregulated)

# Observed difference in means
GSE163249_Vorinostat_observed_diff <- mean(MFE_res_GSE163249_Vorinostat_UP$Normalized_MFE, na.rm = TRUE) - mean(MFE_res_GSE163249_Vorinostat_DOWN$Normalized_MFE, na.rm = TRUE)

# Number of permutations
n_permutations <- 10000

# Initialize a vector to store the permuted differences
GSE163249_Vorinostat_permuted_diffs <- numeric(n_permutations)

# Permutation test
set.seed(123)  # Set seed for reproducibility
for (i in 1:n_permutations) {
  # Permute the Group labels
  combined_data <- combined_data %>%
    mutate(Permuted_Group = sample(Group))
  
  permuted_up_mean <- mean(combined_data$MFE[combined_data$Permuted_Group == "Up"], na.rm = TRUE)
  permuted_down_mean <- mean(combined_data$MFE[combined_data$Permuted_Group == "Down"], na.rm = TRUE)
  
  # Calculate the difference in means for the permuted groups
  GSE163249_Vorinostat_permuted_diffs[i] <- permuted_up_mean - permuted_down_mean
}

# Calculate the p-value
GSE163249_Vorinostat_p_value <- (sum(abs(GSE163249_Vorinostat_permuted_diffs) >= abs(GSE163249_Vorinostat_observed_diff)) + 1) / (n_permutations + 1)

# Output the results
cat("Observed difference in GSE163249_Vorinostat means MFE_UP - MFE_DOWN:", GSE163249_Vorinostat_observed_diff, "\n")
cat("GSE163249_Vorinostat P-value from permutation test:", GSE163249_Vorinostat_p_value, "\n")





















## GSE163249 High MFE TX fraction changes
# Determine whether within the differentially expressed genes there is a significant up-regulation of high MFE transcripts:
# Define high MFE transcripts by taking the 75th percentile of the combined MFE distributions of control and drug-treated samples.
# Count the number of transcripts in the significantly up- and down-regulated genes that have MFE values above this threshold.
# Perform a Fisher’s exact test to compare the proportions of high MFE transcripts between the two groups.


# Analysis GSE163249
# Extract the normalized count data
# The minimal pre-filtering has already been done in the previous steps
GSE163249_norm_TX_counts <- counts(dds_GSE163249, normalized=TRUE) # This object is already a matrix
GSE163249_norm_TX_counts_df <- as.data.frame(GSE163249_norm_TX_counts)
# Convert row names to column
GSE163249_norm_TX_counts_df$ensembl_transcript_id <- rownames(GSE163249_norm_TX_counts_df)
# Remove row names
rownames(GSE163249_norm_TX_counts_df) <- NULL

# Move ensembl_transcript_id column to the first position
GSE163249_norm_TX_counts_df <- GSE163249_norm_TX_counts_df[, c("ensembl_transcript_id", setdiff(names(GSE163249_norm_TX_counts_df), "ensembl_transcript_id"))]

# Remove everything after the dot (including the dot itself) in the ensembl_transcript_id column
GSE163249_norm_TX_counts_df$ensembl_transcript_id <- sub("\\..*", "", GSE163249_norm_TX_counts_df$ensembl_transcript_id)

# Join the counts with the Table_ANNOTATED containing MFE values and heat capacity values
GSE163249_norm_TX_counts_MFE_df <- dplyr::inner_join(Table_ANNOTATED, GSE163249_norm_TX_counts_df, by="ensembl_transcript_id") %>%
  dplyr::select(ensembl_transcript_id_version, ensembl_transcript_id, ensembl_gene_id, external_gene_name, transcript_is_canonical, Transcript_length, 
                GSM4975597, GSM4975599, GSM4975611, GSM4975613,
                Normalized_MFE, Temperature, Specific_heat)







# GSE163249_Vorinostat
# Convert from wide to long format
GSE163249_Vorinostat_norm_TX_counts_MFE_df <- GSE163249_norm_TX_counts_MFE_df %>%
  dplyr::select(ensembl_transcript_id_version, ensembl_transcript_id, ensembl_gene_id, external_gene_name, transcript_is_canonical, Transcript_length, 
                GSM4975597, GSM4975599, GSM4975611, GSM4975613,
                Normalized_MFE, Temperature, Specific_heat) %>%
  dplyr::filter(ensembl_transcript_id %in% MFE_res_GSE163249_Vorinostat$ensembl_transcript_id) 

# Identify the 75th percentile of the combined MFE distributions of control and drug-treated samples
quantile_075_GSE163249_Vorinostat_norm_TX_counts_MFE_df <- quantile(GSE163249_Vorinostat_norm_TX_counts_MFE_df$Normalized_MFE, probs = c(0.75))

# Select all the transcripts with Normalized_MFE values above the 75th percentile
GSE163249_Vorinostat_high_MFE_TX <- dplyr::filter(GSE163249_Vorinostat_norm_TX_counts_MFE_df, Normalized_MFE > quantile_075_GSE163249_Vorinostat_norm_TX_counts_MFE_df)

# Count the number of transcripts in the significantly up- and down-regulated pools that have MFE values above this threshold.
GSE163249_Vorinostat_high_MFE_TX_in_UP <- dplyr::filter(MFE_res_GSE163249_Vorinostat_UP, ensembl_transcript_id_version %in% GSE163249_Vorinostat_high_MFE_TX$ensembl_transcript_id_version)
GSE163249_Vorinostat_high_MFE_TX_in_DOWN <- dplyr::filter(MFE_res_GSE163249_Vorinostat_DOWN, ensembl_transcript_id_version %in% GSE163249_Vorinostat_high_MFE_TX$ensembl_transcript_id_version)

# Calculate the proportions of high MFE transcripts in UP and DOWN-regulated groups
GSE163249_Vorinostat_total_UP <- nrow(MFE_res_GSE163249_Vorinostat_UP)
GSE163249_Vorinostat_total_DOWN <- nrow(MFE_res_GSE163249_Vorinostat_DOWN)
GSE163249_Vorinostat_count_high_MFE_UP <- nrow(GSE163249_Vorinostat_high_MFE_TX_in_UP)
GSE163249_Vorinostat_count_high_MFE_DOWN <- nrow(GSE163249_Vorinostat_high_MFE_TX_in_DOWN)

# Proportions of high MFE in each group
p_UP <- GSE163249_Vorinostat_count_high_MFE_UP / GSE163249_Vorinostat_total_UP
p_DOWN <- GSE163249_Vorinostat_count_high_MFE_DOWN / GSE163249_Vorinostat_total_DOWN

# Pooled proportion
P_pool <- (GSE163249_Vorinostat_count_high_MFE_UP + GSE163249_Vorinostat_count_high_MFE_DOWN) /
  (GSE163249_Vorinostat_total_UP + GSE163249_Vorinostat_total_DOWN)

# Two-proportion Z-test statistic
Z <- (p_UP - p_DOWN) / sqrt(P_pool * (1 - P_pool) * (1/GSE163249_Vorinostat_total_UP + 1/GSE163249_Vorinostat_total_DOWN))

# Calculate the p-value for the Z-test
GSE163249_Vorinostat_z_test_MFE_p_value <- 2 * (1 - pnorm(abs(Z)))

# Output the results
cat("Two-proportion Z-test statistic:", Z, "\n")
cat("Two-proportion Z-test p-value:", GSE163249_Vorinostat_z_test_MFE_p_value, "\n")

# Look at the fractions
GSE163249_Vorinostat_high_MFE_in_UP_fraction <- GSE163249_Vorinostat_count_high_MFE_UP / GSE163249_Vorinostat_total_UP
GSE163249_Vorinostat_high_MFE_in_DOWN_fraction <- GSE163249_Vorinostat_count_high_MFE_DOWN / GSE163249_Vorinostat_total_DOWN

# Output the fractions
cat("Fraction of GSE163249_Vorinostat high MFE TX in UP-regulated genes:", GSE163249_Vorinostat_high_MFE_in_UP_fraction, "\n")
cat("Fraction of GSE163249_Vorinostat high MFE TX in DOWN-regulated genes:", GSE163249_Vorinostat_high_MFE_in_DOWN_fraction, "\n")
cat("Mean of GSE163249_Vorinostat high MFE TX in UP-regulated genes:", mean(GSE163249_Vorinostat_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mean of GSE163249_Vorinostat high MFE TX in DOWN-regulated genes:", mean(GSE163249_Vorinostat_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")
cat("Mode of GSE163249_Vorinostat high MFE TX in UP-regulated genes:", calculate_mode(GSE163249_Vorinostat_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mode of GSE163249_Vorinostat high MFE TX in DOWN-regulated genes:", calculate_mode(GSE163249_Vorinostat_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")





