# Identify all the transcripts with MFE values below the 25th percentile
GSE163249_Vorinostat_low_MFE_TX_total <- dplyr::filter(GSE163249_Vorinostat_norm_TX_counts_MFE_df, Normalized_MFE < GSE163249_Vorinostat_MFE_all_TX_25_percentile)

# Fraction of total low MFE transcript counts in DMSO and drug-treated groups
GSE163249_Vorinostat_DMSO_total_counts <- dplyr::filter(GSE163249_Vorinostat_norm_TX_aggregated_data_avg_counts, condition == "DMSO") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

