## GSE163249_Vorinostat gene-level expression changes ####

# 1. Download from GREIN the row counts at the gene level 
# 2. Normalize the counts with DESeq
# 3. Log2 transform the counts
Counts_GSE163249_Vorinostat_gene <- read.delim("path_to/GSE163249/GSE163249_GeneLevel_Raw_data.csv", sep = ",", header = T, stringsAsFactors = F)
# Select only the columns of the counts that are necessary for the analysis
Counts_GSE163249_Vorinostat_gene <- dplyr::select(Counts_GSE163249_Vorinostat_gene, c("X", "gene_symbol", "GSM4975597", "GSM4975599", "GSM4975611", "GSM4975613"))

# In order to use the gene symbols as raw names, I need to remove the duplicates - I merge the transcript-level counts of the same gene
Counts_GSE163249_Vorinostat_gene <- Counts_GSE163249_Vorinostat_gene %>% group_by(gene_symbol) %>%
  summarise (GSM4975597 = sum(GSM4975597),
             GSM4975599 = sum(GSM4975599),
             GSM4975611 = sum(GSM4975611),
             GSM4975613 = sum(GSM4975613))

Counts_GSE163249_Vorinostat_gene <- Counts_GSE163249_Vorinostat_gene %>% remove_rownames %>% column_to_rownames(var="gene_symbol") # Convert first column into row names in data frame
Counts_GSE163249_Vorinostat_gene <- floor(Counts_GSE163249_Vorinostat_gene)

Counts_GSE163249_Vorinostat_gene <- as.matrix(Counts_GSE163249_Vorinostat_gene)


# Access the metadata table
Expdata_GSE163249_Vorinostat_gene <- dplyr::filter(Expdata_GSE163249, geo_accession %in% c("GSM4975597", "GSM4975599", "GSM4975611", "GSM4975613"))

# Check whether the gene-level counts and the metadata table have the same selected samples
all(rownames(Expdata_GSE163249_Vorinostat_gene) %in% colnames(Counts_GSE163249_Vorinostat_gene))
all(colnames(Counts_GSE163249_Vorinostat_gene) %in% rownames(Expdata_GSE163249_Vorinostat_gene))

# Construct a DESeqDataSet:
dds_GSE163249_Vorinostat_gene <- DESeqDataSetFromMatrix(countData = Counts_GSE163249_Vorinostat_gene,
                                                    colData = Expdata_GSE163249_Vorinostat_gene,
                                                    design = ~ condition)
dds_GSE163249_Vorinostat_gene

# Perform differential expression analysis with DESeq2
dds_GSE163249_Vorinostat_gene <- DESeq(dds_GSE163249_Vorinostat_gene)

# Check the global change of different proliferation gene sets
dds_proliferation_GSE163249_Vorinostat_gene <- dds_GSE163249_Vorinostat_gene

# DIFFERENTIAL EXPRESSION ANALYSIS
res_GSE163249_Vorinostat_gene <- results(dds_proliferation_GSE163249_Vorinostat_gene, contrast=c("condition","Vorinostat","DMSO")) # to specify the samples to contrast
res_GSE163249_Vorinostat_gene

# Gene names are as raw names. Transform to first column for the filtering
res_GSE163249_Vorinostat_gene_df <- as.data.frame(res_GSE163249_Vorinostat_gene)
res_GSE163249_Vorinostat_gene_df <- dplyr::filter(res_GSE163249_Vorinostat_gene_df, !is.na(padj)) # Remove NA
res_GSE163249_Vorinostat_gene_df <- tibble::rownames_to_column(res_GSE163249_Vorinostat_gene_df, "Gene_symbol")











# Save the environment
save.image(file = "path_to/Cross_validation_MFE_AC_environment.RData")
















